pub(crate) fn read_existing_project_identity(
    project_org: &FsPath,
) -> Result<ExistingProjectIdentity, ApiError> {
    let source = std::fs::read_to_string(project_org).map_err(|e| {
        tracing::warn!(path = %project_org.display(), error = %e, "project.org read failed");
        ApiError::bad_request("failed to read project.org")
    })?;
    let file = OrgFile::parse(source, project_org.to_string_lossy()).map_err(|e| {
        tracing::warn!(path = %project_org.display(), error = %e, "project.org parse failed");
        ApiError::bad_request("project file is not valid orgasmic markup")
    })?;
    let project = ProjectFile::from_org(&file, project_org.to_string_lossy().as_ref()).map_err(|e| {
        tracing::warn!(path = %project_org.display(), error = %e, "project.org schema validation failed");
        ApiError::bad_request("project file is not valid orgasmic markup")
    })?;
    Ok(ExistingProjectIdentity {
        project_id: project.id.to_string(),
    })
}

fn git_default_branch(project_root: &FsPath) -> Option<String> {
    let origin_head = git_output(
        project_root,
        &["symbolic-ref", "--short", "refs/remotes/origin/HEAD"],
    )
    .map(|value| value.strip_prefix("origin/").unwrap_or(&value).to_string());
    origin_head.or_else(|| {
        git_output(project_root, &["rev-parse", "--abbrev-ref", "HEAD"])
            .filter(|value| value != "HEAD")
    })
}

fn git_output(project_root: &FsPath, args: &[&str]) -> Option<String> {
    let output = Command::new("git")
        .args(args)
        .current_dir(project_root)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
        .filter(|value| !value.is_empty())
}

fn init_project_error(error: anyhow::Error) -> ApiError {
    let message = error.to_string();
    if is_project_input_error(&message) {
        return ApiError::bad_request(message);
    }
    tracing::warn!(error = %error, "project scaffold failed");
    if message.contains("did not parse as an app-owned Org file") {
        ApiError::bad_request("project file is not valid orgasmic markup")
    } else {
        ApiError::bad_request("failed to initialize project scaffold")
    }
}

fn register_project_error(error: anyhow::Error) -> ApiError {
    let message = error.to_string();
    if message.contains("already on the board") {
        ApiError::conflict(message)
    } else if is_project_input_error(&message) {
        ApiError::bad_request(message)
    } else if message.contains("parse") || message.contains("valid orgasmic markup") {
        tracing::warn!(error = %error, "project board parse failed during registration");
        ApiError::internal("project board is not valid orgasmic markup")
    } else {
        tracing::warn!(error = %error, "project board update failed");
        ApiError::internal("failed to update project board")
    }
}

fn is_project_input_error(message: &str) -> bool {
    message.starts_with("project_id must ")
        || message.starts_with("default_branch ")
        || message.starts_with("project_root ")
        || message.starts_with("project_name ")
}

async fn get_project(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path(id): Path<String>,
) -> Result<Json<crate::index::ProjectIndex>, ApiError> {
    let (_, snap) =
        resolve_authorized_project(&state, &identity, Some(&id), Action::ProjectRead).await?;
    let supervisor = state.supervisor.snapshot().await;
    let project = snap
        .project(&id)
        .cloned()
        .ok_or_else(|| ApiError::internal("project load published no projection"))?;
    Ok(Json(apply_task_owners(project, &supervisor.runs)))
}

async fn get_project_tasks(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path(id): Path<String>,
) -> Result<Json<Vec<crate::index::TaskSummary>>, ApiError> {
    let (_, snap) =
        resolve_authorized_project(&state, &identity, Some(&id), Action::TasksRead).await?;
    let supervisor = state.supervisor.snapshot().await;
    let project = snap
        .project(&id)
        .ok_or_else(|| ApiError::internal("project load published no projection"))?;
    Ok(Json(
        apply_task_owners(project.clone(), &supervisor.runs).tasks,
    ))
}

async fn get_task(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path((project_id, task_id)): Path<(String, String)>,
) -> Result<Json<crate::index::TaskDetail>, ApiError> {
    let (_, snap) =
        resolve_authorized_project(&state, &identity, Some(&project_id), Action::TasksRead).await?;
    let project = snap
        .project(&project_id)
        .ok_or_else(|| ApiError::internal("project load published no projection"))?;
    if !project.tasks.iter().any(|task| task.id == task_id) {
        tracing::warn!(project_id = %project_id, task_id = %task_id, "task not found");
        return Err(ApiError::not_found("task not found"));
    }
    let supervisor = state.supervisor.snapshot().await;
    let project = apply_task_owners(project.clone(), &supervisor.runs);
    let task = project
        .tasks
        .iter()
        .find(|t| t.id == task_id)
        .cloned()
        .expect("task index membership checked above");
    let body = project.task_bodies.get(&task_id).cloned();
    Ok(Json(crate::index::TaskDetail::from_indexed_body(
        task, body,
    )))
}

fn apply_task_owners(
    mut project: crate::index::ProjectIndex,
    runs: &[crate::supervisor::RunSummary],
) -> crate::index::ProjectIndex {
    let mut owners = BTreeMap::<String, (String, String)>::new();
    for run in runs {
        if run
            .project_id
            .as_deref()
            .map(|id| id == project.project_id)
            .unwrap_or(true)
        {
            owners.insert(run.task_id.clone(), (run.role.clone(), run.run_id.clone()));
        }
    }
    for task in &mut project.tasks {
        if let Some((owner, run_id)) = owners.get(&task.id) {
            task.owner = TaskOwner::Agent(owner.clone());
            task.run_id = Some(run_id.clone());
        } else {
            task.owner = TaskOwner::Human;
            task.run_id = None;
        }
    }
    project
}

/// Shared persisted terminal contract for boot auto-reattach AND every manual
/// recovery entry (recover / resume_native_fork / start_recovery_run).
/// orgasmic:TASK-ARZGD
#[derive(Debug, Clone)]
struct PersistedTerminalContract {
    role: String,
    requires_worker_finalize: bool,
    last_path: Option<PathBuf>,
    stdout_path: Option<PathBuf>,
    harness: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PersistedContractError {
    message: String,
}

impl fmt::Display for PersistedContractError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

/// Restore role/requires_worker_finalize from persisted RunMeta, deriving from
/// harness for pre-upgrade records. Unknown non-terminal historical agent
/// roles fail closed; the only exemption is a custom bare terminal proved
/// from the recorded harness (dec_WDR5K item 6 seventh amendment).
// orgasmic:TASK-ARZGD,dec_WDR5K
#[allow(clippy::too_many_arguments)]
fn resolve_persisted_terminal_contract(
    _home: &Home,
    worker_id: &str,
    _kind: RunKind,
    harness: Option<&str>,
    last_path: Option<PathBuf>,
    stdout_path: Option<PathBuf>,
    meta_role: Option<String>,
    meta_requires: Option<bool>,
) -> Result<PersistedTerminalContract, PersistedContractError> {
    let custom_terminal = harness.map(manager_terminal_harness).unwrap_or(false);
    let role = match meta_role {
        Some(role) => role,
        None => {
            if worker_id == "manager" {
                if custom_terminal {
                    "terminal".into()
                } else {
                    "manager".into()
                }
            } else {
                return Err(PersistedContractError {
                    message: format!(
                        "recovery requires persisted run_meta.role; worker_id={worker_id} has none and worker templates are not consulted"
                    ),
                });
            }
        }
    };
    let persisted_bare_terminal = custom_terminal && role == "terminal";
    let requires_worker_finalize = match meta_requires {
        Some(false) if persisted_bare_terminal => false,
        // Round-2 recovery runs could persist `false` for agent roles solely
        // because they had no last_path. That is not a terminal-shape proof:
        // fail closed under the universal contract and let fresh recovery
        // provision the missing path below (TASK-Y5K2C).
        Some(false) => true,
        Some(true) => true,
        None if persisted_bare_terminal => false,
        None => crate::supervisor::run_requires_worker_finalize(&last_path, &role),
    };
    Ok(PersistedTerminalContract {
        role,
        requires_worker_finalize,
        last_path,
        stdout_path,
        harness: harness.map(str::to_string),
    })
}

/// Compatibility wrapper used by boot reattach call sites / unit tests.
fn boot_reattach_terminal_contract(
    home: &Home,
    worker_id: &str,
    kind: RunKind,
    harness: Option<&str>,
    last_path: &Option<PathBuf>,
    meta_role: Option<String>,
    meta_requires: Option<bool>,
) -> Result<(String, bool), PersistedContractError> {
    let contract = resolve_persisted_terminal_contract(
        home,
        worker_id,
        kind,
        harness,
        last_path.clone(),
        None,
        meta_role,
        meta_requires,
    )?;
    Ok((contract.role, contract.requires_worker_finalize))
}

/// Parse the shared terminal contract from a recovered session's envelopes.
fn persisted_terminal_contract_from_session(
    home: &Home,
    envelopes: &[SessionEnvelope],
) -> Result<PersistedTerminalContract, PersistedContractError> {
    let meta = session_acquire_meta(envelopes);
    let worker_id = meta
        .as_ref()
        .map(|m| m.worker_id.clone())
        .unwrap_or_else(|| "manager".to_string());
    let kind = meta.as_ref().map(|m| m.kind).unwrap_or(RunKind::Worker);
    let mut harness = None;
    let mut last_path = None;
    let mut stdout_path = None;
    let mut meta_role = None;
    let mut meta_requires = None;
    for env in envelopes {
        if env.kind != SessionEventKind::Lifecycle {
            continue;
        }
        if let Ok(Lifecycle::RunMeta {
            harness: h,
            last_path: lp,
            stdout_path: sp,
            role,
            requires_worker_finalize,
            ..
        }) = serde_json::from_value::<Lifecycle>(env.event.clone())
        {
            harness = h.or(harness);
            last_path = lp.or(last_path);
            stdout_path = sp.or(stdout_path);
            meta_role = role.or(meta_role);
            meta_requires = requires_worker_finalize.or(meta_requires);
        }
    }
    if harness.is_none() {
        harness = session_native_runtime(envelopes).map(|n| n.provider);
    }
    resolve_persisted_terminal_contract(
        home,
        &worker_id,
        kind,
        harness.as_deref(),
        last_path,
        stdout_path,
        meta_role,
        meta_requires,
    )
}

/// Provision a last_path for a fresh manager-authorized recovery run that
/// inherits a required terminal contract (OQ1 / TASK-ARZGD). Not an
/// auto-continuation path (TASK-QPKCD).
fn provision_recovery_last_path(session_path: &FsPath, prior_run_id: &str) -> PathBuf {
    session_path
        .parent()
        .map(|dir| dir.join(format!("{prior_run_id}.recovery.last.txt")))
        .unwrap_or_else(|| PathBuf::from(format!("{prior_run_id}.recovery.last.txt")))
}

#[derive(Debug, Deserialize)]
pub struct TaskCommentRequest {
    #[serde(default)]
    pub actor: Option<String>,
    pub body: String,
    #[serde(default)]
    pub run_id: Option<String>,
    #[serde(default)]
    pub artifacts: Vec<String>,
    #[serde(default)]
    pub in_reply_to: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct TaskCommentResponse {
    pub tx_id: String,
}

async fn post_task_comment(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path(task_id): Path<String>,
    Query(q): Query<GraphQuery>,
    Json(req): Json<TaskCommentRequest>,
) -> Result<Json<TaskCommentResponse>, ApiError> {
    if req.body.trim().is_empty() {
        return Err(ApiError::bad_request("comment body is required"));
    }
    let (located, _) = resolve_authorized_task(
        &state,
        &identity,
        &task_id,
        q.project.as_deref(),
        Action::TasksComment,
    )
    .await?;
    // Mirror artifact comments: member attribution comes from the authenticated
    // session and cannot be spoofed by a request body. Admin scripts may still
    // provide an explicit actor; omitting it falls back to the daemon actor.
    let actor = match identity.member_name() {
        Some(name) => Some(name.to_string()),
        None => req.actor.filter(|value| !value.trim().is_empty()),
    };
    let mut extra = vec![("BODY".to_string(), escape_property_value(&req.body))];
    if let Some(run_id) = req.run_id.filter(|value| !value.trim().is_empty()) {
        extra.push(("RUN_ID".to_string(), run_id));
    }
    if !req.artifacts.is_empty() {
        extra.push(("ARTIFACTS".to_string(), req.artifacts.join(" ")));
    }
    if let Some(in_reply_to) = req.in_reply_to.filter(|value| !value.trim().is_empty()) {
        extra.push(("IN_REPLY_TO".to_string(), in_reply_to));
    }
    let tx_id = record_api_tx(
        &state,
        ApiTxRequest {
            ty: "comment".to_string(),
            actor,
            project: Some(located.project_id),
            task: Some(task_id),
            target: None,
            reason: "comment".to_string(),
            request_id: req.request_id,
            extra,
        },
    )
    .await?;
    Ok(Json(TaskCommentResponse { tx_id }))
}

async fn get_task_activity(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path(task_id): Path<String>,
    Query(q): Query<GraphQuery>,
) -> Result<Json<Vec<crate::index::ActivityEntry>>, ApiError> {
    let (located, snap) = resolve_authorized_task(
        &state,
        &identity,
        &task_id,
        q.project.as_deref(),
        Action::TasksRead,
    )
    .await?;
    let entries = snap
        .projects
        .get(&located.project_id)
        .and_then(|project| project.activity_index.get(&task_id))
        .cloned()
        .unwrap_or_default();
    Ok(Json(entries))
}

#[derive(Debug, Deserialize)]
pub struct CreateSubtaskRequest {
    pub title: String,
    #[serde(default)]
    pub description: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct CreateSubtaskResponse {
    pub id: String,
    pub heading: String,
    pub tx_id: String,
}

async fn post_task_subtask(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Path(parent_id): Path<String>,
    Query(q): Query<GraphQuery>,
    Json(req): Json<CreateSubtaskRequest>,
) -> Result<Json<CreateSubtaskResponse>, ApiError> {
    if !orgasmic_core::is_valid_task_path_id(&parent_id) {
        return Err(ApiError::bad_request(format!(
            "parent task id must match TASK-<stem>(.<n>)* with legacy numeric or minted stem: {parent_id}"
        )));
    }
    if req.title.trim().is_empty() {
        return Err(ApiError::bad_request("subtask title is required"));
    }
    let (located, snap) = resolve_authorized_task(
        &state,
        &identity,
        &parent_id,
        q.project.as_deref(),
        Action::TasksRead,
    )
    .await?;
    let project = snap
        .projects
        .get(&located.project_id)
        .ok_or_else(|| ApiError::not_found(format!("project {}", located.project_id)))?;
    if !project.tasks.iter().any(|task| task.id == parent_id) {
        return Err(ApiError::not_found(format!("parent task {parent_id}")));
    }
    let subtask_id = next_subtask_id(project, &parent_id);
    let heading = render_subtask_heading(
        &subtask_id,
        &parent_id,
        &req.title,
        req.description.as_deref(),
    );
    // New subtasks are born BACKLOG, and file membership is canonical state
    // (dec_QQYXM) — they land in backlog.org regardless of where the parent
    // currently lives; the file and the heading keyword may never disagree.
    let target_path = task_create_target_path(&project.root);
    let target_rel = task_file_rel(task_create_target_file_name());
    let source = if target_path.exists() {
        read_artifact(&target_path, "task file")?
    } else {
        empty_task_file_header(task_create_target_file_name())
    };
    let new_contents = append_heading_to_task_file(&source, &heading);

    let prepared = prepare_api_tx(
        &state,
        ApiTxRequest {
            ty: "task.created".to_string(),
            actor: None,
            project: Some(located.project_id.clone()),
            task: Some(subtask_id.clone()),
            target: Some(target_rel.clone()),
            reason: format!("created subtask {subtask_id} under {parent_id}"),
            request_id: req.request_id.clone().map(|id| format!("{id}/tx")),
            extra: Vec::new(),
        },
    )
    .await?;
    let project_tx = prepared.project_tx;
    let tx_id = state
        .writer
        .transaction(
            vec![FileRewrite {
                path: target_path,
                new_contents: new_contents.into_bytes(),
            }],
            prepared.tx,
        )
        .await
        .map_err(writer_transaction_error)?;
    refresh_after_project_mutation(&state, &located.project_id, project_tx, &tx_id).await?;
    state.events.publish(
        Topic::Task,
        EventPayload::TaskUpdated {
            project_id: located.project_id,
            task_id: subtask_id.clone(),
        },
    );
    Ok(Json(CreateSubtaskResponse {
        id: subtask_id,
        heading,
        tx_id,
    }))
}

#[derive(Debug, Clone)]
struct LocatedTask {
    project_id: String,
}

fn locate_task(
    snap: &IndexSnapshot,
    task_id: &str,
    project_ids: &[String],
) -> Result<LocatedTask, ApiError> {
    let mut matches = snap
        .projects
        .iter()
        .filter(|(project_id, project)| {
            project_ids.contains(project_id) && project.tasks.iter().any(|task| task.id == task_id)
        })
        .map(|(project_id, _)| project_id.clone())
        .collect::<Vec<_>>();
    matches.sort();
    match matches.len() {
        0 => {
            tracing::warn!(task_id = %task_id, "task not found");
            Err(ApiError::not_found("task not found"))
        }
        1 => Ok(LocatedTask {
            project_id: matches.remove(0),
        }),
        _ => Err(ApiError::bad_request(format!(
            "task {task_id} exists in multiple projects; use a project-scoped route"
        ))),
    }
}

fn next_subtask_id(project: &crate::index::ProjectIndex, parent_id: &str) -> String {
    let max_suffix = project
        .subtasks
        .get(parent_id)
        .into_iter()
        .flat_map(|children| children.iter())
        .filter_map(|child| child.strip_prefix(parent_id))
        .filter_map(|suffix| suffix.strip_prefix('.'))
        .filter_map(|suffix| suffix.split('.').next())
        .filter_map(|suffix| suffix.parse::<u32>().ok())
        .max()
        .unwrap_or(0);
    format!("{}.{}", parent_id, max_suffix + 1)
}

fn render_subtask_heading(
    id: &str,
    _parent_id: &str,
    title: &str,
    description: Option<&str>,
) -> String {
    let clean_title = title
        .chars()
        .map(|ch| if ch == '\n' || ch == '\r' { ' ' } else { ch })
        .collect::<String>();
    let mut heading = format!(
        "* BACKLOG {id} {}\n:PROPERTIES:\n:ID:               {id}\n:END:\n",
        clean_title.trim(),
    );
    if let Some(description) = description {
        if !description.trim().is_empty() {
            heading.push_str("\n** Description\n");
            heading.push_str(description.trim_end());
            heading.push('\n');
        }
    }
    heading
}

fn worker_kind_name(kind: WorkerKind) -> &'static str {
    match kind {
        WorkerKind::Implementer => "implementer",
        WorkerKind::Reviewer => "reviewer",
        WorkerKind::Planner => "planner",
        WorkerKind::Analyzer => "analyzer",
        WorkerKind::Griller => "griller",
        WorkerKind::Glossarist => "glossarist",
        WorkerKind::Manager => "manager",
        WorkerKind::Artifactor => "artifactor",
    }
}

fn escape_property_value(value: &str) -> String {
    value.replace('\\', "\\\\").replace('\n', "\\n")
}

