fn tx_time_string_utc(now: &chrono::DateTime<Utc>) -> String {
    now.format("[%Y-%m-%d %a %H:%M:%S]").to_string()
}

fn tx_preserve_id_timestamp_utc(now: &chrono::DateTime<Utc>) -> String {
    now.format("%Y%m%d%H%M%S").to_string()
}

fn tx_project_date_utc(now: &chrono::DateTime<Utc>) -> String {
    now.format("%Y%m%d").to_string()
}

fn tx_file_month_utc(now: &chrono::DateTime<Utc>) -> String {
    now.format("%Y-%m").to_string()
}

async fn post_tx(
    State(state): State<ApiState>,
    Json(req): Json<TxAppendRequest>,
) -> Result<Json<TxAppendResponse>, ApiError> {
    append_tx_request(&state, req).await.map(Json)
}

/// The body of `POST /tx`, callable from other handlers so a tx emitted as
/// part of a larger daemon-side operation is byte-identical to one a client
/// POSTs itself. `/runs/:id/release` uses it for the worker's terminal tx
/// (TASK-WGXKD).
async fn append_tx_request(
    state: &ApiState,
    req: TxAppendRequest,
) -> Result<TxAppendResponse, ApiError> {
    let (tx, project_tx, destination_project_id, time) =
        prepare_tx_append_request(state, req).await?;
    let res = state
        .writer
        .append_tx(tx, None)
        .await
        .map_err(writer_append_error)?;
    refresh_after_tx(state, project_tx, destination_project_id, &res.tx_id).await?;
    Ok(TxAppendResponse {
        tx_id: res.tx_id,
        tx_path: res.tx_path,
        time,
    })
}

async fn prepare_tx_append_request(
    state: &ApiState,
    req: TxAppendRequest,
) -> Result<(TxAppend, bool, Option<String>, String), ApiError> {
    let now = Utc::now();
    if let Some(project_id) = req.project.as_deref() {
        let registered = state
            .index
            .snapshot()
            .await
            .board
            .iter()
            .any(|entry| entry.id == project_id);
        if registered {
            state
                .index
                .ensure_project_loaded(project_id)
                .await
                .map_err(|error| {
                    ApiError::unavailable(format!("project {project_id} failed to load: {error}"))
                })?;
        }
    }
    let snap = state.index.snapshot().await;
    let project_entry = req
        .project
        .as_deref()
        .and_then(|id| snap.board.iter().find(|entry| entry.id == id))
        .cloned();
    let destination = tx_destination(state, &req, project_entry.as_ref(), &now)?;
    let tx_id = match &destination.tx_id_policy {
        TxIdPolicy::Preserve => format!(
            "tx-{}-{}",
            tx_preserve_id_timestamp_utc(&now),
            &uuid::Uuid::new_v4().to_string()[..8]
        ),
        TxIdPolicy::ProjectSequence { .. } => "pending-project-sequence".to_string(),
    };
    let time_str = tx_time_string_utc(&now);
    let mut entry = TxEntry::new(
        &tx_id,
        &req.r#type,
        &time_str,
        choose_actor(&req, project_entry.as_ref(), state),
        req.machine.clone().unwrap_or_else(|| state.machine.clone()),
    );
    entry.project = req.project.clone();
    entry.task = req.task;
    entry.target = req.target;
    entry.reason = req.reason;
    entry.extra = req.extra;
    // orgasmic:task_HQ970
    // Refuse at the boundary, before anything is queued to the writer: a value
    // the drawer cannot carry (a multi-line `reason`, most of all) used to be
    // accepted, appended verbatim, and reported back with a tx_id, leaving the
    // append-only ledger unreadable for every subsequent verb. The writer
    // repeats this check as its own last line of defence.
    tx_entry_write_error(&entry)?;

    Ok((
        TxAppend {
            tx_path: destination.tx_path,
            entry,
            project_id: destination.project_id.clone(),
            tx_id_policy: destination.tx_id_policy,
            request_id: req.request_id,
        },
        destination.project_tx,
        destination.project_id,
        time_str,
    ))
}

