/// Whether a manager launch is really a bare terminal. `custom` is the
/// pseudo-harness meaning "PTY with no agent CLI": the run gets the manager's
/// interactive treatment without being the project's manager.
fn manager_terminal_harness(harness: &str) -> bool {
    harness.trim().eq_ignore_ascii_case("custom")
}

fn manager_external_harness(harness: &str) -> bool {
    harness.trim().eq_ignore_ascii_case("external")
}

fn chat_access_supported(provider: &str, access: &str) -> bool {
    match provider {
        "codex" => matches!(access, "auto-accept-edits" | "auto" | "full-access"),
        "claude" => matches!(access, "auto" | "full-access"),
        "opencode" => access == "full-access",
        _ => false,
    }
}

struct ManagerLaunchIds {
    task_id: String,
    session_file: String,
}

/// Identity for one manager-namespace launch.
///
/// The project's manager is a singleton, and its stable task id is what makes
/// that true: the supervisor leases on (task_id, kind), so a second launch is
/// refused. A terminal is not the manager — it is a bare PTY, and the operator
/// may keep several open — so each terminal launch gets its own discriminator
/// and therefore its own lease. The `manager.launch:` prefix stays in front of
/// it because it is load-bearing beyond identity: it is how the supervisor
/// recognises an operator-paced session and holds back the stall and
/// max-duration detectors.
fn manager_launch_ids(
    project_id: &str,
    harness: &str,
    now: chrono::DateTime<Utc>,
) -> ManagerLaunchIds {
    let stamp = now.format("%Y%m%dT%H%M%S");
    if harness.trim().to_ascii_lowercase().starts_with("chat-") {
        let id = uuid::Uuid::new_v4().simple().to_string();
        return ManagerLaunchIds {
            // Chat providers still contend on the project's one manager lease.
            task_id: format!("manager.launch:{project_id}"),
            // A released chat is immediately restartable. The UUID prevents a
            // same-second restart from appending a new run at sequence zero to
            // the previous conversation's JSONL.
            session_file: format!("manager-{project_id}-{stamp}-chat-{id}.jsonl"),
        };
    }
    if !manager_terminal_harness(harness) {
        let session_file = if manager_external_harness(harness) {
            // External presence runs share the real manager lease, but never
            // its transcript: End-external followed by app-launch in the same
            // second must not append two run identities to one recovery file.
            let id = uuid::Uuid::new_v4().simple().to_string();
            format!("manager-{project_id}-{stamp}-external-{id}.jsonl")
        } else {
            format!("manager-{project_id}-{stamp}.jsonl")
        };
        return ManagerLaunchIds {
            task_id: format!("manager.launch:{project_id}"),
            session_file,
        };
    }
    // The discriminator lands in the session file name too: a second-granularity
    // stamp alone collides between two terminals opened in the same second.
    let id = uuid::Uuid::new_v4().simple().to_string();
    ManagerLaunchIds {
        task_id: format!("manager.launch:{project_id}#terminal-{id}"),
        session_file: format!("manager-{project_id}-{stamp}-{id}.jsonl"),
    }
}

async fn post_manager_launch(
    State(state): State<ApiState>,
    Json(req): Json<ManagerLaunchRequest>,
) -> Result<Json<ManagerLaunchResponse>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&req.project_id)).await?;
    let project = snap
        .projects
        .get(&req.project_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("project {}", req.project_id)))?;
    drop(snap);

    validate_address_harness_args(&req.harness, &req.harness_args)
        .map_err(ApiError::bad_request)?;

    let driver = resolve_launch_driver(&req.mode, &req.harness).ok_or_else(|| {
        ApiError::bad_request(format!(
            "unsupported manager driver {}/{}",
            req.mode, req.harness
        ))
    })?;
    let driver_config = DriverConfig::from_value(json!({
        "cwd": project.root.clone(),
        "auto_start_turn": false,
        // Launch-time runtime overrides: the PTY modes append `--model` to the
        // harness argv, so the choice stays pinned to this session instead of
        // rewriting the operator's saved harness default (an in-session
        // `/model` does the latter).
        // One value, one key. This used to be written under `effort` as well,
        // and one value under two names is what turned an ordinary
        // `#[serde(alias = "effort")]` in an adapter into a dispatch-killing
        // `duplicate field` (TASK-4YC8E). Every reader of this key takes
        // `reasoning_effort`: the adapters read only that name, and the tmux
        // mode config falls back to it.
        // orgasmic:TASK-4YC8E
        "model": req.model,
        "reasoning_effort": req.effort,
        "harness_args": req.harness_args,
    }));
    let driver_config = apply_driver_defaults(
        driver_config,
        &req.mode,
        &req.harness,
        &state.driver_defaults,
    );

    let ids = manager_launch_ids(&req.project_id, &req.harness, Utc::now());
    let session_path = project_sessions_dir(&project.root).join(ids.session_file);
    let task_id = ids.task_id;
    let manager_role = if manager_terminal_harness(&req.harness) {
        // Custom bare terminals are not agent runs (dec_WDR5K item 6 seventh
        // amendment / TASK-TZJFF): exempt from manager terminal-declaration.
        "terminal".into()
    } else {
        "manager".into()
    };
    let acquire = state
        .supervisor
        .acquire(
            driver.as_ref(),
            AcquireRequest {
                task_id,
                kind: RunKind::Worker,
                worker_id: "manager".into(),
                role: manager_role,
                project_id: Some(req.project_id.clone()),
                worktree: Some(project.root),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                session_path,
                driver_config,
                // The manager is interactive and operator-paced: it idles at a
                // prompt waiting for a human, which must never read as a
                // stalled worker. 0 disables both detectors.
                stall_timeout_secs: Some(0),
                max_run_duration_secs: Some(0),
                idle_timeout_secs: None,
                applicable_states: Vec::new(),
                max_iterations: None,
                planned_identity: None,
            },
        )
        .await
        .map_err(|e| supervisor_acquire_error("manager launch", e))?;

    Ok(Json(ManagerLaunchResponse {
        run_id: acquire.run_id,
    }))
}

/// Launch a reusable RunDock Chat conversation without changing the worker
/// driver registry. Claude uses the Agent SDK host, OpenCode its HTTP/SSE SDK,
/// and Codex the existing app-server client wrapped in the same canonical
/// provider-event vocabulary.
async fn post_manager_chat_launch(
    State(state): State<ApiState>,
    Json(req): Json<ManagerChatLaunchRequest>,
) -> Result<Json<ManagerLaunchResponse>, ApiError> {
    let provider = req.provider.trim().to_ascii_lowercase();
    let driver = orgasmic_drivers::chat_driver(&provider).ok_or_else(|| {
        ApiError::bad_request(format!(
            "unsupported Chat provider '{}'; expected codex, claude, or opencode",
            req.provider
        ))
    })?;
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&req.project_id)).await?;
    let project = snap
        .projects
        .get(&req.project_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("project {}", req.project_id)))?;
    drop(snap);

    let access = match req.access.as_deref().unwrap_or("full-access") {
        "supervised" | "auto-accept-edits" | "auto" | "full-access" => {
            req.access.unwrap_or_else(|| "full-access".into())
        }
        value => {
            return Err(ApiError::bad_request(format!(
                "unsupported Chat access mode '{value}'"
            )));
        }
    };
    if !chat_access_supported(&provider, &access) {
        return Err(ApiError::bad_request(format!(
            "Chat access mode '{access}' is not supported by the {provider} runtime"
        )));
    }
    let service_tier = match req.service_tier.as_deref() {
        None | Some("") | Some("standard") => None,
        Some("fast") => Some("fast".to_string()),
        Some(value) => {
            return Err(ApiError::bad_request(format!(
                "unsupported Chat service tier '{value}'"
            )));
        }
    };
    let sandbox_permissions = match access.as_str() {
        "supervised" => {
            "allow_exec=false,allow_patch=false,allow_network=false,allow_writes_outside_cwd=false"
        }
        "auto-accept-edits" => {
            "allow_exec=false,allow_patch=true,allow_network=false,allow_writes_outside_cwd=false"
        }
        "auto" => {
            "allow_exec=true,allow_patch=true,allow_network=true,allow_writes_outside_cwd=false"
        }
        _ => "allow_exec=true,allow_patch=true,allow_network=true,allow_writes_outside_cwd=true",
    };
    let speed = service_tier.as_ref().map(|_| "fast");

    let driver_config = DriverConfig::from_value(json!({
        "cwd": project.root.clone(),
        "auto_start_turn": false,
        "model": verbatim_optional(req.model),
        "reasoning_effort": verbatim_optional(req.effort),
        "access": access,
        "service_tier": service_tier,
        "speed": speed,
        "sandbox_permissions": sandbox_permissions,
    }));
    driver
        .validate(&driver_config)
        .map_err(|error| driver_validate_error("chat", &provider, error))?;

    let ids = manager_launch_ids(&req.project_id, &format!("chat-{provider}"), Utc::now());
    let session_path = project_sessions_dir(&project.root).join(ids.session_file);
    let acquire = state
        .supervisor
        .acquire(
            driver.as_ref(),
            AcquireRequest {
                task_id: ids.task_id,
                kind: RunKind::Worker,
                worker_id: "manager".into(),
                role: "manager".into(),
                project_id: Some(req.project_id),
                worktree: Some(project.root),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                session_path,
                driver_config,
                stall_timeout_secs: Some(0),
                max_run_duration_secs: Some(0),
                idle_timeout_secs: None,
                applicable_states: Vec::new(),
                max_iterations: None,
                planned_identity: None,
            },
        )
        .await
        .map_err(|error| supervisor_acquire_error("Chat launch", error))?;

    Ok(Json(ManagerLaunchResponse {
        run_id: acquire.run_id,
    }))
}

/// External manager self-registration (dec_3Y2E1, TASK-VKP5T): a manager
/// session started outside the app registers here so it appears in Running
/// Agents as a supervised run, on the same `manager.launch:<project>` lease
/// the app's own manager launch uses.
#[derive(Debug, Deserialize, Serialize)]
pub struct ManagerRegisterRequest {
    pub project_id: String,
    /// Terminal session-leader PID (`getsid(0)`), when the registrant could
    /// capture one. Absent falls back to a TTL that re-registering refreshes.
    #[serde(default)]
    pub pid: Option<i64>,
    /// Opaque token returned for the PID-less fallback. The CLI persists it
    /// per terminal session and presents it on refresh.
    #[serde(default)]
    pub holder_token: Option<String>,
    // Compatibility-only test fields. They are absent from production builds
    // and skipped even by direct-handler test serialization; capabilities are
    // the sole production claim authority.
    #[cfg(test)]
    #[serde(skip)]
    pub caller_identity: Option<RuntimeIdentity>,
    #[cfg(test)]
    #[serde(skip)]
    pub provider: Option<String>,
}

const MANAGER_TERMINAL_CAPABILITY_HEADER: &str = "x-orgasmic-manager-terminal-capability";

#[derive(Debug, Serialize)]
pub struct ManagerRegisterResponse {
    /// "registered" | "refreshed" | "refused".
    pub status: String,
    pub run_id: Option<String>,
    pub message: Option<String>,
    pub holder_token: Option<String>,
}

fn normalize_manager_registration_pid(pid: Option<i64>) -> Option<u32> {
    #[cfg(unix)]
    {
        let pid = pid
            .and_then(|pid| u32::try_from(pid).ok())
            .filter(|pid| *pid > 0)?;
        libc::pid_t::try_from(pid).ok()?;
        Some(pid)
    }
    #[cfg(not(unix))]
    {
        // The daemon deliberately performs no process probing on non-Unix.
        // Treat even a supplied PID as absent so registration gets a holder
        // token and the refreshable TTL fallback.
        let _ = pid;
        None
    }
}

/// HTTP adapter for the public registration endpoint. The run-scoped
/// capability deliberately lives in a header, not JSON: a client cannot name
/// a run/identity/provider in a body and request that it be claimed.
async fn post_manager_register_http(
    State(state): State<ApiState>,
    headers: HeaderMap,
    Json(req): Json<ManagerRegisterRequest>,
) -> Result<Json<ManagerRegisterResponse>, ApiError> {
    let capability = headers
        .get(MANAGER_TERMINAL_CAPABILITY_HEADER)
        .map(|value| value.to_str().unwrap_or(""));
    post_manager_register_inner(state, req, capability).await
}

/// Test/direct-call adapter for the body-only external registration surface.
/// It intentionally has no capability channel; claim tests use
/// [`post_manager_register_inner`] with a daemon-minted value.
#[cfg(test)]
async fn post_manager_register(
    State(state): State<ApiState>,
    Json(req): Json<ManagerRegisterRequest>,
) -> Result<Json<ManagerRegisterResponse>, ApiError> {
    post_manager_register_inner(state, req, None).await
}

async fn post_manager_register_inner(
    state: ApiState,
    req: ManagerRegisterRequest,
    capability: Option<&str>,
) -> Result<Json<ManagerRegisterResponse>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&req.project_id)).await?;
    let project = snap
        .projects
        .get(&req.project_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("project {}", req.project_id)))?;
    drop(snap);

    if let Some(capability) = capability.filter(|value| !value.trim().is_empty()) {
        return Ok(Json(
            match state
                .supervisor
                .claim_manager_terminal(&req.project_id, capability)
                .await
            {
                Ok(run_id) => ManagerRegisterResponse {
                    status: "claimed".into(),
                    run_id: Some(run_id),
                    message: None,
                    holder_token: None,
                },
                Err(error) => ManagerRegisterResponse {
                    status: "refused".into(),
                    run_id: None,
                    message: Some(error.to_string()),
                    holder_token: None,
                },
            },
        ));
    }

    let ids = manager_launch_ids(&req.project_id, "external", Utc::now());
    let session_path = project_sessions_dir(&project.root).join(ids.session_file);
    let outcome = state
        .manager_registry
        .register(
            &state.supervisor,
            &req.project_id,
            project.root,
            session_path,
            normalize_manager_registration_pid(req.pid),
            req.holder_token,
        )
        .await
        .map_err(|e| supervisor_acquire_error("manager register", e))?;

    Ok(Json(match outcome {
        crate::manager_registration::RegisterOutcome::Registered {
            run_id,
            holder_token,
        } => ManagerRegisterResponse {
            status: "registered".to_string(),
            run_id: Some(run_id),
            message: None,
            holder_token,
        },
        crate::manager_registration::RegisterOutcome::Refreshed {
            run_id,
            holder_token,
        } => ManagerRegisterResponse {
            status: "refreshed".to_string(),
            run_id: Some(run_id),
            message: None,
            holder_token,
        },
        crate::manager_registration::RegisterOutcome::Refused { message } => {
            ManagerRegisterResponse {
                status: "refused".to_string(),
                run_id: None,
                message: Some(message),
                holder_token: None,
            }
        }
    }))
}

#[derive(Debug, Deserialize)]
pub struct ManagerWakeRequest {
    pub project_id: String,
}

#[derive(Debug, Serialize)]
pub struct ManagerWakeResponse {
    /// accepted | busy | unavailable | mismatch | unsupported
    pub status: String,
    pub run_id: Option<String>,
    pub message: Option<String>,
}

async fn post_manager_wake(
    State(state): State<ApiState>,
    Json(req): Json<ManagerWakeRequest>,
) -> Result<Json<ManagerWakeResponse>, ApiError> {
    let snapshot = state.supervisor.snapshot().await;
    let Some(run) = snapshot
        .runs
        .iter()
        .find(|run| {
            run.project_id.as_deref() == Some(req.project_id.as_str()) && run.claimed_manager
        })
        .cloned()
    else {
        return Ok(Json(ManagerWakeResponse {
            status: "unavailable".into(),
            run_id: None,
            message: Some("no live claimed manager terminal".into()),
        }));
    };
    match state
        .supervisor
        .send_manager_wake(&run.run_id, &run.identity)
        .await
    {
        Ok(ack) if ack.accepted => Ok(Json(ManagerWakeResponse {
            status: "accepted".into(),
            run_id: Some(run.run_id),
            message: ack.message,
        })),
        Ok(ack) => Ok(Json(ManagerWakeResponse {
            status: "busy".into(),
            run_id: Some(run.run_id),
            message: ack.message,
        })),
        Err(crate::supervisor::SupervisorError::Driver(
            orgasmic_drivers::DriverError::Unsupported(_),
        )) => Ok(Json(ManagerWakeResponse {
            status: "unsupported".into(),
            run_id: Some(run.run_id),
            message: Some("claimed terminal transport cannot prove safe automated input".into()),
        })),
        Err(crate::supervisor::SupervisorError::RunNotFound(_)) => Ok(Json(ManagerWakeResponse {
            status: "unavailable".into(),
            run_id: Some(run.run_id),
            message: Some("claimed terminal is no longer live".into()),
        })),
        Err(crate::supervisor::SupervisorError::Driver(
            orgasmic_drivers::DriverError::ManagerWakeUnavailable,
        )) => Ok(Json(ManagerWakeResponse {
            status: "unavailable".into(),
            run_id: Some(run.run_id),
            message: Some("claimed terminal pane is unavailable".into()),
        })),
        Err(crate::supervisor::SupervisorError::Driver(
            orgasmic_drivers::DriverError::ManagerWakeProviderMismatch,
        )) => Ok(Json(ManagerWakeResponse {
            status: "mismatch".into(),
            run_id: Some(run.run_id),
            message: Some("claimed provider is not the foreground provider".into()),
        })),
        Err(error) => Err(supervisor_control_error("manager wake", error)),
    }
}

/// One daemon-owned answer for a dispatch generation. The CLI never combines
/// an on-disk tx scan with a separately timed live-run scan: a release already
/// admitted by this daemon remains `waiting` until its terminal tx settles.
#[derive(Debug, Deserialize)]
pub struct ManagerDispatchWaitRequest {
    pub project_id: String,
    pub started_tx: Vec<String>,
}

#[derive(Debug, Serialize)]
pub struct ManagerDispatchWaitResponse {
    pub generations: Vec<ManagerDispatchGenerationState>,
}

#[derive(Debug, Serialize)]
pub struct ManagerDispatchGenerationState {
    pub started_tx: String,
    /// waiting | reported | died | unknown
    pub status: String,
    pub run_id: Option<String>,
}

fn tx_extra<'a>(entry: &'a TxEntry, key: &str) -> Option<&'a str> {
    entry
        .extra
        .iter()
        .find(|(candidate, _)| candidate == key)
        .map(|(_, value)| value.as_str())
}

fn project_tx_entries(project_root: &FsPath) -> Result<Vec<TxEntry>, ApiError> {
    let tx_dir = project_root.join(".orgasmic/tx");
    let entries = std::fs::read_dir(&tx_dir).map_err(|error| {
        ApiError::internal(format!(
            "read dispatch tx directory {}: {error}",
            tx_dir.display()
        ))
    })?;
    let mut paths = Vec::new();
    for entry in entries {
        let path = entry
            .map_err(|error| ApiError::internal(format!("read dispatch tx entry: {error}")))?
            .path();
        if path.extension().and_then(|ext| ext.to_str()) == Some("org") {
            paths.push(path);
        }
    }
    paths.sort();
    let mut parsed = Vec::new();
    for path in paths {
        let source = std::fs::read_to_string(&path).map_err(|error| {
            ApiError::internal(format!("read dispatch tx file {}: {error}", path.display()))
        })?;
        let mut file = parse_tx_file(&source, &path.display().to_string()).map_err(|error| {
            ApiError::internal(format!(
                "parse dispatch tx file {}: {error}",
                path.display()
            ))
        })?;
        parsed.append(&mut file);
    }
    Ok(parsed)
}

/// The durable run lineage for one `manager.dispatch_started` generation.
///
/// A recovery is a replacement run, not a new dispatch. Keep every id because
/// a report from either the original or any replacement settles the one
/// generation, while `addressed_run_id` follows the newest replacement for
/// diagnostics and live checks. This deliberately mirrors the CLI dispatch
/// fold rather than trusting only the first `cli_dispatch` run.
#[derive(Debug, Default)]
struct DispatchGenerationLedger {
    run_ids: BTreeSet<String>,
    addressed_run_id: Option<String>,
    reported: bool,
}

fn dispatch_generation_ledgers(
    entries: &[TxEntry],
    project_id: &str,
) -> BTreeMap<String, DispatchGenerationLedger> {
    let mut generations: BTreeMap<String, DispatchGenerationLedger> = BTreeMap::new();
    for entry in entries {
        if entry.ty == "manager.dispatch_started" && entry.project.as_deref() == Some(project_id) {
            generations.entry(entry.tx_id.clone()).or_default();
        }
    }

    for entry in entries {
        if entry.ty != "run.created" || tx_extra(entry, "ORIGIN") != Some("cli_dispatch") {
            continue;
        }
        let (Some(started_tx), Some(run_id)) =
            (tx_extra(entry, "DISPATCH_TX"), tx_extra(entry, "RUN_ID"))
        else {
            continue;
        };
        if let Some(generation) = generations.get_mut(started_tx) {
            generation.run_ids.insert(run_id.to_string());
            generation.addressed_run_id = Some(run_id.to_string());
        }
    }

    // Recovery edges can arrive in either lineage order in a globbed tx
    // directory. Fixed-point folding handles A->B->C even if B->C sorts
    // before A->B, and is robust across daemon restart/reattach records.
    loop {
        let mut changed = false;
        for entry in entries {
            if entry.ty != "run.created" || tx_extra(entry, "ORIGIN") != Some("recovery") {
                continue;
            }
            let (Some(origin_run_id), Some(replacement_run_id)) =
                (tx_extra(entry, "ORIGIN_RUN_ID"), tx_extra(entry, "RUN_ID"))
            else {
                continue;
            };
            for generation in generations.values_mut() {
                if generation.run_ids.contains(origin_run_id)
                    && generation.run_ids.insert(replacement_run_id.to_string())
                {
                    generation.addressed_run_id = Some(replacement_run_id.to_string());
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }

    for entry in entries {
        if !entry.ty.ends_with(".reported") {
            continue;
        }
        // A present-but-unmatched RUN_ID is intentionally ignored. Falling
        // back to task names here could report a later dispatch generation.
        let Some(run_id) = tx_extra(entry, "RUN_ID") else {
            continue;
        };
        for generation in generations.values_mut() {
            if generation.run_ids.contains(run_id) {
                generation.reported = true;
            }
        }
    }
    generations
}

/// Recover the one crash-durable wait authority that the tx ledger cannot yet
/// see: a signed pending recovery claim whose replacement was already spawned
/// but whose later `ORIGIN=recovery` association was not appended before the
/// daemon died. The claim is written before spawn and binds the old lineage id
/// to the planned replacement; only a currently live planned tmux handle makes
/// it a waiting state. A missing pane is a stale intent, so it deliberately
/// contributes nothing and cannot keep `dispatch-wait` hanging forever.
fn dispatch_pending_recovery_intents(
    state: &ApiState,
    project_id: &str,
    generations: &BTreeMap<String, DispatchGenerationLedger>,
) -> Result<BTreeMap<String, String>, ApiError> {
    let mut intents = BTreeMap::new();
    for origin_run_id in generations
        .values()
        .flat_map(|generation| generation.run_ids.iter())
    {
        let claim = load_recovery_claim(&state.home, project_id, origin_run_id)
            .map_err(|error| recovery_claim_load_error(origin_run_id, error))?;
        let Some(claim) = claim else {
            continue;
        };
        // `load_recovery_claim` verifies the claim's daemon MAC and complete
        // plan. The claim may retain its original worktree path across a
        // daemon restart, so do not compare it to a freshly-indexed root here:
        // that would turn a valid durable intent into a false death. Liveness
        // remains narrow: only its exact planned tmux handle can wait.
        // An unobserved tmux probe is a retryable wait, never false evidence
        // that a crash-durable replacement died. The CLI's bounded wait still
        // terminates with its timeout contract if this persists.
        if pending_recovery_claim_planned_handle_observation(&claim)
            != orgasmic_drivers::modes::tmux::TmuxSessionObservation::Absent
        {
            intents.insert(origin_run_id.clone(), claim.replacement_run_id);
        }
    }
    Ok(intents)
}

async fn post_manager_dispatch_wait(
    State(state): State<ApiState>,
    Json(req): Json<ManagerDispatchWaitRequest>,
) -> Result<Json<ManagerDispatchWaitResponse>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&req.project_id)).await?;
    let project = snap
        .projects
        .get(&req.project_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("project {}", req.project_id)))?;
    // The release admission marker spans removal from `Supervisor::snapshot`
    // through terminal-tx append. Read its epoch on both sides of the durable
    // ledger/live scan and retry whenever a finalize/release/report transition
    // crossed the observation. This removes the old stale-ledger + fresh-live
    // false `died` verdict without holding a daemon mutex across filesystem IO.
    let (
        generations,
        live_run_ids,
        releasing_run_ids,
        recovering_origin_run_ids,
        pending_recovery_intents,
    ) = loop {
        let release_before = state.release_tasks.snapshot();
        let recovery_before = state.recovery_generation_transitions.snapshot();
        let entries = project_tx_entries(&project.root)?;
        let live = state.supervisor.snapshot().await;
        let release_after = state.release_tasks.snapshot();
        let recovery_after = state.recovery_generation_transitions.snapshot();
        if release_before.revision != release_after.revision
            || recovery_before.revision != recovery_after.revision
        {
            continue;
        }
        let generations = dispatch_generation_ledgers(&entries, &req.project_id);
        let pending_recovery_intents =
            dispatch_pending_recovery_intents(&state, &req.project_id, &generations)?;
        // Claim inspection touches disk, so the recovery epoch must enclose it
        // too. Otherwise a recovery could be accepted between the first epoch
        // read and its durable pending-claim write, leaving this response with
        // neither the in-memory transition nor the crash authority and a
        // false `died` verdict.
        let recovery_final = state.recovery_generation_transitions.snapshot();
        if recovery_after.revision != recovery_final.revision {
            continue;
        }
        break (
            generations,
            live.runs
                .into_iter()
                .map(|run| run.run_id)
                .collect::<BTreeSet<_>>(),
            release_after.active_run_ids,
            recovery_final.active_origin_run_ids,
            pending_recovery_intents,
        );
    };
    let states = req
        .started_tx
        .into_iter()
        .map(|started_tx| match generations.get(&started_tx) {
            None => ManagerDispatchGenerationState {
                started_tx,
                status: "unknown".into(),
                run_id: None,
            },
            Some(DispatchGenerationLedger {
                reported: true,
                addressed_run_id,
                ..
            }) => ManagerDispatchGenerationState {
                started_tx,
                status: "reported".into(),
                run_id: addressed_run_id.clone(),
            },
            Some(generation) => {
                let pending_replacement = generation
                    .run_ids
                    .iter()
                    .find_map(|run_id| pending_recovery_intents.get(run_id));
                if generation.run_ids.iter().any(|run_id| {
                    live_run_ids.contains(run_id)
                        || releasing_run_ids.contains(run_id)
                        || recovering_origin_run_ids.contains(run_id)
                }) || pending_replacement.is_some()
                {
                    ManagerDispatchGenerationState {
                        started_tx,
                        status: "waiting".into(),
                        run_id: pending_replacement
                            .cloned()
                            .or_else(|| generation.addressed_run_id.clone()),
                    }
                } else {
                    ManagerDispatchGenerationState {
                        started_tx,
                        status: "died".into(),
                        run_id: generation.addressed_run_id.clone(),
                    }
                }
            }
        })
        .collect();
    Ok(Json(ManagerDispatchWaitResponse {
        generations: states,
    }))
}

#[derive(Debug, Deserialize)]
pub struct ManagerReleaseRegistrationRequest {
    pub project_id: String,
    /// App-launched manager run id exported as `ORGASMIC_RUN_ID` into the
    /// pane. Used when the external-registration map does not own the run
    /// (TASK-TZJFF / TASK-S52X9).
    #[serde(default)]
    pub run_id: Option<String>,
    #[cfg(test)]
    #[serde(skip)]
    pub caller_identity: Option<RuntimeIdentity>,
}

#[derive(Debug, Serialize)]
pub struct ManagerReleaseRegistrationResponse {
    /// "released" | "not_registered".
    pub status: String,
    pub run_id: Option<String>,
}

async fn post_manager_release_http(
    State(state): State<ApiState>,
    headers: HeaderMap,
    Json(req): Json<ManagerReleaseRegistrationRequest>,
) -> Result<Json<ManagerReleaseRegistrationResponse>, ApiError> {
    let capability = headers
        .get(MANAGER_TERMINAL_CAPABILITY_HEADER)
        // Header presence is authority selection. A malformed/non-UTF-8
        // value is an invalid capability, not the absence of one: erasing it
        // here would let a caller fall through to registry/run-id release.
        .map(|value| value.to_str().unwrap_or(""));
    post_manager_release_inner(state, req, capability).await
}

#[cfg(test)]
async fn post_manager_release(
    State(state): State<ApiState>,
    Json(req): Json<ManagerReleaseRegistrationRequest>,
) -> Result<Json<ManagerReleaseRegistrationResponse>, ApiError> {
    post_manager_release_inner(state, req, None).await
}

async fn post_manager_release_inner(
    state: ApiState,
    req: ManagerReleaseRegistrationRequest,
    capability: Option<&str>,
) -> Result<Json<ManagerReleaseRegistrationResponse>, ApiError> {
    if let Some(capability) = capability {
        if capability.trim().is_empty() {
            return Err(ApiError::forbidden(
                "manager terminal capability is required for terminal release",
            ));
        }
        match state
            .supervisor
            .unclaim_manager_terminal(&req.project_id, capability)
            .await
        {
            Ok(Some(run_id)) => {
                return Ok(Json(ManagerReleaseRegistrationResponse {
                    status: "released".to_string(),
                    run_id: Some(run_id),
                }));
            }
            // A terminal capability is the authority for this request. Never
            // reinterpret an invalid/rotated/corrupt token as permission to
            // release an unrelated external or app manager by registry/run id.
            Ok(None) => {
                return Err(ApiError::forbidden(
                    "manager terminal capability does not name a claimed terminal",
                ));
            }
            Err(error) => return Err(supervisor_control_error("manager release", error)),
        }
    }
    let outcome = state
        .manager_registry
        .release(&state.supervisor, &req.project_id)
        .await;
    if let crate::manager_registration::ManagerReleaseOutcome::Released { run_id } = outcome {
        return Ok(Json(ManagerReleaseRegistrationResponse {
            status: "released".to_string(),
            run_id: Some(run_id),
        }));
    }
    if let Some(run_id) = req.run_id.as_deref().filter(|id| !id.trim().is_empty()) {
        if let Some(response) =
            release_app_manager_run(&state, &req.project_id, run_id.trim()).await
        {
            return Ok(Json(response));
        }
    }
    Ok(Json(ManagerReleaseRegistrationResponse {
        status: "not_registered".to_string(),
        run_id: None,
    }))
}

async fn release_app_manager_run(
    state: &ApiState,
    project_id: &str,
    run_id: &str,
) -> Option<ManagerReleaseRegistrationResponse> {
    let snapshot = state.supervisor.snapshot().await;
    let run = snapshot.runs.iter().find(|run| run.run_id == run_id)?;
    if run.project_id.as_deref() != Some(project_id) {
        return None;
    }
    if !run.task_id.starts_with("manager.launch:") {
        return None;
    }
    state
        .supervisor
        .release_with_finalization(
            run_id,
            "manager_released",
            ReleaseOutcome::Completed,
            true,
            None,
        )
        .await
        .ok()?;
    Some(ManagerReleaseRegistrationResponse {
        status: "released".to_string(),
        run_id: Some(run_id.to_string()),
    })
}

async fn post_manager_action(
    State(state): State<ApiState>,
    Json(req): Json<ManagerActionRequest>,
) -> Result<Json<ManagerActionResponse>, ApiError> {
    let mut extra = req.extra;
    if let Some(ty) = req.ty {
        extra.push(("ACTION_TYPE".to_string(), ty));
    }
    let tx_id = record_api_tx(
        &state,
        ApiTxRequest {
            ty: "manager.action".to_string(),
            actor: None,
            project: req.project.or_else(|| Some("orgasmic".to_string())),
            task: req.task,
            target: req
                .target
                .or_else(|| Some(DEFAULT_TASK_FILE_REL.to_string())),
            reason: req
                .reason
                .unwrap_or_else(|| "manager action recorded".to_string()),
            request_id: req.request_id,
            extra,
        },
    )
    .await?;
    Ok(Json(ManagerActionResponse {
        status: "recorded".to_string(),
        tx_id,
    }))
}

async fn get_manager_state(
    State(state): State<ApiState>,
) -> Json<crate::supervisor::SupervisorSnapshot> {
    Json(state.supervisor.snapshot().await)
}

// orgasmic:TASK-3CM0Q
/// The tx type a tier declaration lands under. Its own type rather than a
/// `manager.action` variant, because the acceptance is that the *absence* of a
/// declaration is detectable — and an absent type is greppable in a way an
/// absent property of a generic entry is not.
pub const MANAGER_TIER_TX_TYPE: &str = "manager.tier";

// orgasmic:TASK-3CM0Q
/// The three process tiers `shipped/workflows/default.org` computes, cheapest
/// first. The order is load-bearing: a re-declaration may raise the tier and
/// may not lower it, which is that workflow's "the floor is a floor" made
/// mechanical.
pub const MANAGER_TIERS: &[&str] = &["trivial", "ordinary", "risky"];

// orgasmic:TASK-3CM0Q
/// The four countable triggers the workflow's floor rule adds up (TASK-YGB1R),
/// spelled as the wire and the CLI take them.
pub const MANAGER_TIER_TRIGGERS: &[&str] = &["priority", "blast_radius", "breadth", "coupling"];

fn manager_tier_rank(tier: &str) -> Option<usize> {
    MANAGER_TIERS.iter().position(|known| *known == tier)
}

#[derive(Debug, Deserialize)]
pub struct ManagerTierRequest {
    /// Project whose ledger records the declaration.
    pub project: String,
    /// Task the declaration is about.
    pub task: String,
    /// One of [`MANAGER_TIERS`].
    pub tier: String,
    /// Triggers that fired, each one of [`MANAGER_TIER_TRIGGERS`].
    #[serde(default)]
    pub triggers: Vec<String>,
    #[serde(default)]
    pub reason: Option<String>,
    /// Accept a downgrade of an existing declaration, recording it as a
    /// correction rather than a recomputation.
    #[serde(default)]
    pub lower: bool,
    #[serde(default)]
    pub request_id: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct ManagerTierResponse {
    /// `declared` on the first declaration for a task, `redeclared` after.
    pub status: String,
    pub tx_id: String,
    pub tier: String,
    pub triggers: Vec<String>,
    pub previous_tier: Option<String>,
    /// True when this entry records a downgrade of an earlier declaration.
    pub lowered: bool,
}

#[derive(Debug, Deserialize)]
pub struct ManagerTierQuery {
    pub project: String,
    pub task: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct ManagerTierDeclaration {
    pub tier: String,
    pub triggers: Vec<String>,
    pub reason: Option<String>,
    pub tx_id: String,
    pub time: String,
    pub actor: String,
    pub lowered: bool,
}

#[derive(Debug, Serialize)]
pub struct ManagerTierStatusResponse {
    pub task: String,
    pub project: String,
    /// False when nothing has ever declared a tier for this task — the state
    /// in which manager-direct source editing is out of policy.
    pub declared: bool,
    pub current: Option<ManagerTierDeclaration>,
    /// How many declarations the ledger holds for this task, so a reader can
    /// see a mid-task raise happened without pulling the whole ledger.
    pub declarations: usize,
}

/// Every tier declaration recorded for `task`, oldest first.
///
/// Reads the tx index rather than a cache: the ledger is the record, and a
/// declaration that is not on it did not happen as far as this policy is
/// concerned.
async fn manager_tier_declarations(
    state: &ApiState,
    project: &str,
    task: &str,
) -> Result<Vec<ManagerTierDeclaration>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(state, Some(project)).await?;
    let mut found: Vec<_> = snap
        .tx
        .iter()
        .filter(|record| {
            record.project_id.as_deref() == Some(project)
                && record.entry.ty == MANAGER_TIER_TX_TYPE
                && record.entry.task.as_deref() == Some(task)
        })
        .map(|record| {
            let extra = |key: &str| {
                record
                    .entry
                    .extra
                    .iter()
                    .find(|(k, _)| k == key)
                    .map(|(_, v)| v.trim().to_string())
            };
            let triggers = extra("TRIGGERS")
                .filter(|value| value != "none")
                .map(|value| {
                    value
                        .split(',')
                        .map(str::trim)
                        .filter(|part| !part.is_empty())
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default();
            ManagerTierDeclaration {
                tier: extra("TIER").unwrap_or_default(),
                triggers,
                reason: record.entry.reason.clone(),
                tx_id: record.entry.tx_id.clone(),
                time: record.entry.time.clone(),
                actor: record.entry.actor.clone(),
                lowered: extra("LOWERED").as_deref() == Some("yes"),
            }
        })
        .collect();
    // Org timestamps are fixed-width and zero-padded, so lexical order is
    // chronological order.
    found.sort_by(|a, b| a.time.cmp(&b.time));
    Ok(found)
}

// orgasmic:TASK-3CM0Q
/// Record the manager's computed process tier for a task (TASK-3CM0Q).
///
/// The workflow already tells a manager to compute the tier before its first
/// source edit, but that is a *reading* obligation, and an agent under
/// execution momentum skims one without noticing. This is the writing
/// obligation: it costs one command, it lands on the append-only ledger, and
/// its absence is therefore detectable after the run.
///
/// It is a statement, not a question. Nothing here waits on an operator and
/// nothing asks one — the tier is computed from countable triggers, so there is
/// no decision to escalate (TASK-4YX1K).
async fn post_manager_tier(
    State(state): State<ApiState>,
    Json(req): Json<ManagerTierRequest>,
) -> Result<Json<ManagerTierResponse>, ApiError> {
    let project = req.project.trim().to_string();
    if project.is_empty() {
        return Err(ApiError::bad_request(
            "a tier declaration lands on a project ledger; `project` is required",
        ));
    }
    let task = req.task.trim().to_string();
    if task.is_empty() {
        return Err(ApiError::bad_request(
            "a tier declaration names the task it is about; `task` is required",
        ));
    }
    let tier = req.tier.trim().to_ascii_lowercase();
    let rank = manager_tier_rank(&tier).ok_or_else(|| {
        ApiError::bad_request(format!(
            "unknown tier `{tier}`; the workflow computes one of: {}",
            MANAGER_TIERS.join(", ")
        ))
    })?;

    let mut triggers: Vec<String> = Vec::new();
    for raw in &req.triggers {
        for part in raw.split(',') {
            let trigger = part.trim().to_ascii_lowercase();
            if trigger.is_empty() {
                continue;
            }
            if !MANAGER_TIER_TRIGGERS.contains(&trigger.as_str()) {
                return Err(ApiError::bad_request(format!(
                    "unknown trigger `{trigger}`; the workflow counts: {}",
                    MANAGER_TIER_TRIGGERS.join(", ")
                )));
            }
            if !triggers.contains(&trigger) {
                triggers.push(trigger);
            }
        }
    }
    let reason = req
        .reason
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);

    // The floor rule, checked rather than trusted: the tier only rises when a
    // trigger fires, so a tier above `trivial` that names none is arithmetic a
    // reader cannot check — which is the acceptance this verb exists to meet.
    if rank > 0 && triggers.is_empty() {
        return Err(ApiError::bad_request(format!(
            "tier `{tier}` is above the floor, and the floor only rises when a trigger fires — \
             name the ones that did with `triggers` (one or more of: {}), so a reader can check \
             the arithmetic instead of taking the tier on trust",
            MANAGER_TIER_TRIGGERS.join(", ")
        )));
    }
    // `trivial` with a trigger fired is reachable, but only through the
    // workflow's no-tracked-source exemption. Naming it costs a sentence and
    // separates the exemption from a miscount.
    if rank == 0 && !triggers.is_empty() && reason.is_none() {
        return Err(ApiError::bad_request(
            "trivial with a trigger fired is the workflow's exemption for a task that changes no \
             tracked source, not the floor — pass `reason` saying so, or drop the triggers if none \
             really fired",
        ));
    }

    let prior = manager_tier_declarations(&state, &project, &task).await?;
    let previous = prior.last().cloned();
    let previous_rank = previous
        .as_ref()
        .and_then(|declaration| manager_tier_rank(&declaration.tier));
    let lowering = matches!(previous_rank, Some(prev) if rank < prev);
    if lowering {
        let prev_tier = previous
            .as_ref()
            .map(|declaration| declaration.tier.clone())
            .unwrap_or_default();
        if !req.lower {
            return Err(ApiError::bad_request(format!(
                "{task} is already declared `{prev_tier}`, and the floor is a floor: a \
                 re-declaration may raise the tier and not lower it. Scope that grew mid-task \
                 re-declares upward and needs no flag. If the first declaration was simply wrong, \
                 pass `lower` with a `reason`, which records the downgrade as a correction rather \
                 than hiding it"
            )));
        }
        if reason.is_none() {
            return Err(ApiError::bad_request(
                "`lower` records a correction, so it needs a `reason` saying what the earlier \
                 declaration got wrong",
            ));
        }
    }

    let trigger_summary = if triggers.is_empty() {
        "none".to_string()
    } else {
        triggers.join(", ")
    };
    let tx_reason = reason.clone().unwrap_or_else(|| {
        if triggers.is_empty() {
            format!("tier {tier}; no trigger fired")
        } else {
            format!("tier {tier}; triggers fired: {trigger_summary}")
        }
    });

    let mut extra = vec![
        ("TIER".to_string(), tier.clone()),
        ("TRIGGERS".to_string(), trigger_summary),
    ];
    if let Some(declaration) = &previous {
        extra.push(("PREVIOUS_TIER".to_string(), declaration.tier.clone()));
    }
    if lowering {
        extra.push(("LOWERED".to_string(), "yes".to_string()));
    }

    let tx_id = record_api_tx(
        &state,
        ApiTxRequest {
            ty: MANAGER_TIER_TX_TYPE.to_string(),
            actor: None,
            project: Some(project),
            task: Some(task),
            target: None,
            reason: tx_reason,
            request_id: req.request_id,
            extra,
        },
    )
    .await?;

    Ok(Json(ManagerTierResponse {
        status: if previous.is_some() {
            "redeclared".to_string()
        } else {
            "declared".to_string()
        },
        tx_id,
        tier,
        triggers,
        previous_tier: previous.map(|declaration| declaration.tier),
        lowered: lowering,
    }))
}

// orgasmic:TASK-3CM0Q
/// Read back the tier declared for a task, so the omission this verb exists to
/// make detectable can actually be detected without reading the raw ledger.
async fn get_manager_tier(
    State(state): State<ApiState>,
    Query(q): Query<ManagerTierQuery>,
) -> Result<Json<ManagerTierStatusResponse>, ApiError> {
    let project = q.project.trim().to_string();
    let task = q.task.trim().to_string();
    if project.is_empty() || task.is_empty() {
        return Err(ApiError::bad_request(
            "`project` and `task` are both required to read a tier declaration",
        ));
    }
    let declarations = manager_tier_declarations(&state, &project, &task).await?;
    Ok(Json(ManagerTierStatusResponse {
        task,
        project,
        declared: !declarations.is_empty(),
        declarations: declarations.len(),
        current: declarations.last().cloned(),
    }))
}

