/// Reserve the dispatch worktree for a destructive `dispatch-close`, and
/// answer whether a live worker occupies it (TASK-1T3FZ).
///
/// This is the authority boundary the close was missing. The CLI cannot decide
/// this for itself: a competing `POST /runs/:origin/recover` acquires in
/// another process, so only the daemon — holding the supervisor lock the
/// acquire path also takes — can install a fence and read liveness as one
/// indivisible step. The reservation stays installed after this handler
/// returns and is released by `.../close-guard/finish`, so it spans the
/// caller's worktree and branch cleanup.
async fn post_task_dispatch_close_guard(
    State(state): State<ApiState>,
    Path((project_id, task_id)): Path<(String, String)>,
    Json(req): Json<DispatchCloseGuardRequest>,
) -> Result<Json<DispatchCloseGuardResponse>, ApiError> {
    // Absolute, and never a symlink — but unlike the rollback cleanup endpoint
    // this one does NOT require the directory to exist. A close whose worktree
    // is already gone still has to reach its ledger write and record the
    // cleanup outcome; refusing it here would turn "nothing to remove" into a
    // hard failure. Reserving a path that does not exist costs nothing and
    // still fences an acquire that would recreate it.
    if !req.worktree_path.is_absolute() {
        return Err(ApiError::bad_request("worktree_path must be absolute"));
    }
    if std::fs::symlink_metadata(&req.worktree_path).is_ok_and(|meta| meta.file_type().is_symlink())
    {
        return Err(ApiError::bad_request("worktree path must not be a symlink"));
    }

    let (_, snap) = ensure_loaded_snapshot(&state, Some(&project_id)).await?;
    debug_assert!(snap.projects.contains_key(&project_id));
    drop(snap);

    let params = DispatchCloseGuardParams {
        project_id: project_id.clone(),
        task_id: task_id.clone(),
        // Every dispatch shape — implementer, reviewer, and the stage kinds —
        // is a `RunKind::Worker` run in the supervisor, so this is the lease
        // and reservation identity for all of them.
        kind: RunKind::Worker,
        branch: req.branch.clone().unwrap_or_default(),
        worktree_path: req.worktree_path.clone(),
        dispatch_attempt_token: req.dispatch_attempt_token.clone(),
        last_path: req.last_path.clone(),
        stdout_path: req.stdout_path.clone(),
        owner_pid: req.owner_pid,
        releasing_run_id: req.releasing_run_id.clone(),
        owned_run_ids: req.owned_run_ids.clone(),
    };

    let response = match state.supervisor.reserve_dispatch_close(&params).await {
        DispatchCloseGuardOutcome::Reserved {
            guard_id,
            renew_within,
        } => DispatchCloseGuardResponse {
            status: "reserved".into(),
            guard_id: Some(guard_id),
            renew_within_secs: Some(renew_within.as_secs()),
            blocking_run_id: None,
            blocking_worktree: None,
        },
        DispatchCloseGuardOutcome::ReservationHeld => DispatchCloseGuardResponse {
            status: "reservation_held".into(),
            guard_id: None,
            renew_within_secs: None,
            blocking_run_id: None,
            blocking_worktree: None,
        },
        DispatchCloseGuardOutcome::BootReattachPending => DispatchCloseGuardResponse {
            status: "boot_reattach_pending".into(),
            guard_id: None,
            renew_within_secs: None,
            blocking_run_id: None,
            blocking_worktree: None,
        },
        DispatchCloseGuardOutcome::BlockedByLiveRun { run_id, worktree } => {
            DispatchCloseGuardResponse {
                status: "blocked".into(),
                guard_id: None,
                renew_within_secs: None,
                blocking_run_id: Some(run_id),
                blocking_worktree: worktree,
            }
        }
    };

    // Test-only rendezvous occupying the window between the liveness verdict
    // and the caller's removal — the interleaving no in-process reasoning can
    // rule out. No-op unless a test registered a gate for this task.
    if response.status == "reserved" {
        test_hooks::dispatch_close_guard_reserved(&task_id).await;
    }
    Ok(Json(response))
}

async fn post_task_dispatch_close_guard_finish(
    State(state): State<ApiState>,
    Path((_project_id, _task_id)): Path<(String, String)>,
    Json(req): Json<DispatchCloseGuardFinishRequest>,
) -> Result<Json<DispatchCloseGuardFinishResponse>, ApiError> {
    state.supervisor.finish_dispatch_close(&req.guard_id).await;
    Ok(Json(DispatchCloseGuardFinishResponse {
        status: "released".into(),
    }))
}

/// Extend the holder lease on a close guard (TASK-AK6EM).
///
/// This is the reclamation identity that works on every platform: the daemon
/// cannot probe a pid on non-Unix targets, so a holder proves it is still there
/// by renewing. `unknown` means the guard is no longer held — the caller has
/// lost its fence and is deleting files nobody is protecting.
async fn post_task_dispatch_close_guard_renew(
    State(state): State<ApiState>,
    Path((_project_id, _task_id)): Path<(String, String)>,
    Json(req): Json<DispatchCloseGuardRenewRequest>,
) -> Result<Json<DispatchCloseGuardRenewResponse>, ApiError> {
    let renewed = state.supervisor.renew_dispatch_close(&req.guard_id).await;
    Ok(Json(DispatchCloseGuardRenewResponse {
        status: if renewed { "renewed" } else { "unknown" }.into(),
        renew_within_secs: renewed.then(|| crate::supervisor::CLOSE_GUARD_RENEW_WITHIN.as_secs()),
    }))
}

/// Daemon-executed rollback for a failed or timed-out CLI dispatch. Per the
/// fencing invariant: kill any live worker (driver release / PGID reap), wait
/// for confirmed death, salvage dirty output, then remove the worktree. A
/// clean rollback deletes its branch; salvaged output remains reachable from
/// the named refs/orgasmic/salvage ref even when branch cleanup is requested.
async fn post_task_dispatch_cleanup(
    State(state): State<ApiState>,
    Path((project_id, task_id)): Path<(String, String)>,
    Json(req): Json<DispatchCleanupRequest>,
) -> Result<Json<DispatchCleanupResponse>, ApiError> {
    let kind = DispatchEndpointKind::from_str(&req.kind)?;
    validate_dispatch_path("worktree_path", &req.worktree_path)?;
    if req.branch.trim().is_empty() {
        return Err(ApiError::bad_request("branch must be non-empty"));
    }

    let (_, snap) = ensure_loaded_snapshot(&state, Some(&project_id)).await?;
    let project = snap
        .projects
        .get(&project_id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("project {project_id}")))?;
    drop(snap);

    let cleanup_params = DispatchCleanupParams {
        project_id: project_id.clone(),
        task_id: task_id.clone(),
        kind: kind.run_kind(),
        branch: req.branch.clone(),
        worktree_path: req.worktree_path.clone(),
        dispatch_attempt_token: req.dispatch_attempt_token.clone(),
        last_path: req.last_path.clone(),
        stdout_path: req.stdout_path.clone(),
    };

    // Validate the entire mutation plan before changing anything (TASK-NW4WV).
    let validated_artifacts = match orgasmic_core::validate_dispatch_cleanup_targets(
        &project.root,
        &req.worktree_path,
        req.last_path.as_deref(),
        req.stdout_path.as_deref(),
    ) {
        Ok(artifacts) => artifacts,
        Err(err) => {
            return Ok(Json(DispatchCleanupResponse {
                status: "failed".into(),
                released_run_id: None,
                worktree_removed: false,
                branch_deleted: false,
                salvage_sha: None,
                salvage_ref: None,
                salvage_file_count: None,
                error: Some(format!("validation: {err}")),
            }));
        }
    };
    let expected_branch_oid = match resolve_dispatch_branch_oid(&project.root, &req.branch) {
        Ok(oid) => oid,
        Err(err) => {
            return Ok(Json(DispatchCleanupResponse {
                status: "failed".into(),
                released_run_id: None,
                worktree_removed: false,
                branch_deleted: false,
                salvage_sha: None,
                salvage_ref: None,
                salvage_file_count: None,
                error: Some(format!("validation: {err}")),
            }));
        }
    };

    let cleanup = match state
        .supervisor
        .prepare_dispatch_cleanup(
            &orgasmic_core::project_sessions_dir(&project.root),
            &cleanup_params,
        )
        .await
    {
        Ok(DispatchCleanupOutcome::Conflict) => {
            return Ok(Json(DispatchCleanupResponse {
                status: "conflict".into(),
                released_run_id: None,
                worktree_removed: false,
                branch_deleted: false,
                salvage_sha: None,
                salvage_ref: None,
                salvage_file_count: None,
                error: Some("cleanup identity mismatch with live or newer tokened attempt".into()),
            }));
        }
        Ok(DispatchCleanupOutcome::Proceed {
            released_run_id,
            cleanup_guard_id,
        }) => (released_run_id, cleanup_guard_id),
        Err(error) => return Err(ApiError::internal(error.to_string())),
    };

    let (released_run_id, cleanup_guard_id) = cleanup;

    let mut errors = Vec::new();
    let worktree_removal = match remove_dispatch_worktree(
        &project.root,
        &req.worktree_path,
        &validated_artifacts,
        &task_id,
        &req.branch,
        expected_branch_oid.as_deref(),
    ) {
        Ok(removal) => removal,
        Err(err) => {
            errors.push(format!("worktree: {err}"));
            state
                .supervisor
                .finish_dispatch_cleanup(&cleanup_guard_id)
                .await;
            return Ok(Json(DispatchCleanupResponse {
                status: "failed".into(),
                released_run_id,
                worktree_removed: false,
                branch_deleted: false,
                salvage_sha: None,
                salvage_ref: None,
                salvage_file_count: None,
                error: Some(errors.join("; ")),
            }));
        }
    };
    let worktree_removed = worktree_removal.removed;
    if let Some(err) = &worktree_removal.error {
        errors.push(format!("worktree: {err}"));
    }
    let branch_deleted = if worktree_removal.error.is_some() || !worktree_removed {
        false
    } else {
        match delete_dispatch_branch_after_removal(
            &project.root,
            &req.branch,
            expected_branch_oid.as_deref(),
            worktree_removal.salvage.as_ref(),
        ) {
            Ok(deleted) => deleted,
            Err(err) => {
                errors.push(format!("branch: {err}"));
                false
            }
        }
    };

    state
        .supervisor
        .finish_dispatch_cleanup(&cleanup_guard_id)
        .await;

    let status = match (
        worktree_removed,
        branch_deleted,
        worktree_removal.salvage.is_some(),
        errors.is_empty(),
    ) {
        (true, false, true, true) | (true, true, true, true) => "ok",
        (true, true, false, true) => "ok",
        (false, false, false, true) => "noop",
        (true, false, false, _) | (false, true, false, _) => "partial",
        _ => "failed",
    };

    let (salvage_sha, salvage_ref, salvage_file_count) = worktree_removal
        .salvage
        .map(|salvage| {
            (
                Some(salvage.sha),
                Some(salvage.ref_name),
                Some(salvage.file_count),
            )
        })
        .unwrap_or((None, None, None));
    Ok(Json(DispatchCleanupResponse {
        status: status.into(),
        released_run_id,
        worktree_removed,
        branch_deleted,
        salvage_sha,
        salvage_ref,
        salvage_file_count,
        error: if errors.is_empty() {
            None
        } else {
            Some(errors.join("; "))
        },
    }))
}

#[derive(Debug, Eq, PartialEq)]
struct DispatchSalvageCommit {
    sha: String,
    ref_name: String,
    file_count: usize,
}

#[derive(Debug, Eq, PartialEq)]
struct DispatchWorktreeRemoval {
    removed: bool,
    salvage: Option<DispatchSalvageCommit>,
    error: Option<String>,
}

fn dispatch_worktree_status_porcelain(path: &FsPath) -> Result<Vec<u8>, String> {
    let output = Command::new("git")
        .args(["status", "--porcelain=v1", "-z", "--untracked-files=all"])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !output.status.success() {
        return Err(format!(
            "git status --porcelain=v1 -z --untracked-files=all failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    Ok(output.stdout)
}

fn dispatch_changed_file_count_between(
    path: &FsPath,
    parent: &str,
    commit: &str,
) -> Result<usize, String> {
    let output = Command::new("git")
        .args([
            "diff-tree",
            "--no-commit-id",
            "--name-only",
            "-r",
            "-z",
            parent,
            commit,
        ])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !output.status.success() {
        return Err(format!(
            "git diff-tree for salvage file count failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    Ok(output
        .stdout
        .split(|byte| *byte == b'\0')
        .filter(|path| !path.is_empty())
        .count())
}

fn anchor_dispatch_salvage_ref(project_root: &FsPath, sha: &str) -> Result<String, String> {
    let ref_name = format!("refs/orgasmic/salvage/{sha}");
    let existing = Command::new("git")
        .args(["rev-parse", "--verify", "--quiet", &ref_name])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if existing.status.success() {
        let existing = String::from_utf8_lossy(&existing.stdout).trim().to_string();
        if existing == sha {
            return Ok(ref_name);
        }
        return Err(format!(
            "salvage ref {ref_name} unexpectedly resolves to {existing}"
        ));
    }

    let zero_oid = "0".repeat(sha.len());
    let update = Command::new("git")
        .args(["update-ref", &ref_name, sha, &zero_oid])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if !update.status.success() {
        return Err(format!(
            "git update-ref failed for salvage ref {ref_name}: {}{}",
            String::from_utf8_lossy(&update.stderr),
            String::from_utf8_lossy(&update.stdout)
        ));
    }
    Ok(ref_name)
}

fn salvage_dispatch_worktree_if_dirty(
    project_root: &FsPath,
    path: &FsPath,
    task_id: &str,
    expected_branch: &str,
    expected_branch_oid: &str,
) -> Result<Option<DispatchSalvageCommit>, String> {
    let status = dispatch_worktree_status_porcelain(path)?;
    if status.is_empty() {
        return Ok(None);
    }

    let current_branch_oid = resolve_dispatch_branch_oid(project_root, expected_branch)?;
    if current_branch_oid.as_deref() != Some(expected_branch_oid) {
        return Err(format!(
            "recorded dispatch branch {expected_branch} moved before salvage (expected {expected_branch_oid}, found {})",
            current_branch_oid.as_deref().unwrap_or("<missing>")
        ));
    }

    let add = Command::new("git")
        .args(["add", "-A"])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !add.status.success() {
        return Err(format!(
            "git add -A failed: {}",
            String::from_utf8_lossy(&add.stderr)
        ));
    }
    let tree = Command::new("git")
        .args(["write-tree"])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !tree.status.success() {
        return Err(format!(
            "git write-tree failed: {}",
            String::from_utf8_lossy(&tree.stderr)
        ));
    }
    let tree = String::from_utf8_lossy(&tree.stdout).trim().to_string();
    let commit = Command::new("git")
        .args([
            "commit-tree",
            &tree,
            "-p",
            expected_branch_oid,
            "-m",
            &format!("{task_id}: manager-salvaged uncommitted worker output"),
        ])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !commit.status.success() {
        return Err(format!(
            "git commit-tree failed: {}",
            String::from_utf8_lossy(&commit.stderr)
        ));
    }
    let sha = String::from_utf8_lossy(&commit.stdout).trim().to_string();
    let file_count = dispatch_changed_file_count_between(path, expected_branch_oid, &sha)?;

    let checkout = Command::new("git")
        .args(["checkout", "--detach", &sha])
        .current_dir(path)
        .output()
        .map_err(|err| err.to_string())?;
    if !checkout.status.success() {
        return Err(format!(
            "git checkout --detach salvage commit failed: {}{}",
            String::from_utf8_lossy(&checkout.stderr),
            String::from_utf8_lossy(&checkout.stdout)
        ));
    }
    if !dispatch_worktree_status_porcelain(path)?.is_empty() {
        return Err("git checkout left uncommitted changes in the worktree".to_string());
    }
    let ref_name = anchor_dispatch_salvage_ref(project_root, &sha)?;

    Ok(Some(DispatchSalvageCommit {
        sha,
        ref_name,
        file_count,
    }))
}

struct DispatchCleanupLock(std::fs::File);

impl Drop for DispatchCleanupLock {
    fn drop(&mut self) {
        let _ = fs2::FileExt::unlock(&self.0);
    }
}

fn acquire_dispatch_cleanup_lock(project_root: &FsPath) -> Result<DispatchCleanupLock, String> {
    let output = Command::new("git")
        .args(["rev-parse", "--git-common-dir"])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if !output.status.success() {
        return Err(format!(
            "git rev-parse --git-common-dir failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    let common_dir = PathBuf::from(String::from_utf8_lossy(&output.stdout).trim().to_string());
    let common_dir = if common_dir.is_absolute() {
        common_dir
    } else {
        project_root.join(common_dir)
    };
    let path = common_dir.join("orgasmic-dispatch-cleanup.lock");
    let file = std::fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(&path)
        .map_err(|err| format!("open cleanup lock {}: {err}", path.display()))?;
    fs2::FileExt::lock_exclusive(&file)
        .map_err(|err| format!("lock dispatch cleanup {}: {err}", path.display()))?;
    Ok(DispatchCleanupLock(file))
}

fn remove_dispatch_worktree(
    project_root: &FsPath,
    path: &FsPath,
    artifacts: &orgasmic_core::DispatchAttemptArtifacts,
    task_id: &str,
    expected_branch: &str,
    expected_branch_oid: Option<&str>,
) -> Result<DispatchWorktreeRemoval, String> {
    remove_dispatch_worktree_with_hook(
        project_root,
        path,
        artifacts,
        task_id,
        expected_branch,
        expected_branch_oid,
        |_| {},
    )
}

#[allow(clippy::too_many_arguments)]
fn remove_dispatch_worktree_with_hook(
    project_root: &FsPath,
    path: &FsPath,
    artifacts: &orgasmic_core::DispatchAttemptArtifacts,
    task_id: &str,
    expected_branch: &str,
    expected_branch_oid: Option<&str>,
    before_remove: impl FnOnce(&FsPath),
) -> Result<DispatchWorktreeRemoval, String> {
    let _cleanup_lock = acquire_dispatch_cleanup_lock(project_root)?;
    if !path.exists() {
        return Ok(DispatchWorktreeRemoval {
            removed: false,
            salvage: None,
            error: None,
        });
    }
    orgasmic_core::verify_dispatch_worktree_identity(artifacts, path)?;
    let salvage = if dispatch_worktree_status_porcelain(path)?.is_empty() {
        None
    } else {
        let expected_branch_oid = expected_branch_oid
            .ok_or_else(|| format!("recorded dispatch branch {expected_branch} does not exist"))?;
        salvage_dispatch_worktree_if_dirty(
            project_root,
            path,
            task_id,
            expected_branch,
            expected_branch_oid,
        )?
    };
    before_remove(path);
    let output = match Command::new("git")
        .args(["worktree", "remove"])
        .arg(path)
        .current_dir(project_root)
        .output()
    {
        Ok(output) => output,
        Err(err) => {
            return Ok(DispatchWorktreeRemoval {
                removed: false,
                salvage,
                error: Some(err.to_string()),
            });
        }
    };
    if output.status.success() {
        let error = orgasmic_core::prune_validated_dispatch_attempt(artifacts).err();
        Ok(DispatchWorktreeRemoval {
            removed: true,
            salvage,
            error,
        })
    } else {
        Ok(DispatchWorktreeRemoval {
            removed: false,
            salvage,
            error: Some(format!(
                "{}{}",
                String::from_utf8_lossy(&output.stderr),
                String::from_utf8_lossy(&output.stdout)
            )),
        })
    }
}

fn resolve_dispatch_branch_oid(
    project_root: &FsPath,
    branch: &str,
) -> Result<Option<String>, String> {
    let valid = Command::new("git")
        .args(["check-ref-format", "--branch", branch])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if !valid.status.success() {
        return Err(format!("invalid branch name {branch}"));
    }
    let branch_ref = format!("refs/heads/{branch}");
    let output = Command::new("git")
        .args(["rev-parse", "--verify", "--quiet", &branch_ref])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if !output.status.success() {
        return Ok(None);
    }
    let oid = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if oid.is_empty() {
        Err(format!("branch {branch} resolved to an empty object id"))
    } else {
        Ok(Some(oid))
    }
}

fn delete_dispatch_branch(
    project_root: &FsPath,
    branch: &str,
    expected_oid: Option<&str>,
) -> Result<bool, String> {
    let Some(expected_oid) = expected_oid else {
        return Ok(false);
    };
    let branch_ref = format!("refs/heads/{branch}");
    let output = Command::new("git")
        .args(["update-ref", "-d", &branch_ref, expected_oid])
        .current_dir(project_root)
        .output()
        .map_err(|err| err.to_string())?;
    if output.status.success() {
        Ok(true)
    } else {
        let combined = format!(
            "{}{}",
            String::from_utf8_lossy(&output.stderr),
            String::from_utf8_lossy(&output.stdout)
        );
        Err(combined)
    }
}

fn delete_dispatch_branch_after_removal(
    project_root: &FsPath,
    branch: &str,
    expected_oid: Option<&str>,
    _salvage: Option<&DispatchSalvageCommit>,
) -> Result<bool, String> {
    delete_dispatch_branch(project_root, branch, expected_oid)
}

/// Clear an orphaned dispatch lease — one whose run record is gone (e.g. the
/// dispatching CLI timed out and gave up while the daemon held the lease).
/// Refuses (409) when a live run still holds the lease: release the run
/// instead. This is the manager's lever for a stuck lease, replacing the
/// "restart the daemon" anti-pattern (which the restart guard now refuses).
async fn post_task_lease_release(
    State(state): State<ApiState>,
    Path((project_id, task_id)): Path<(String, String)>,
    Json(req): Json<LeaseReleaseRequest>,
) -> Result<Json<LeaseReleaseResponse>, ApiError> {
    let kind = match req.kind.as_deref().unwrap_or("implementer") {
        // `architector` is legacy (dec_HBK6A): no dispatch spawns one any more,
        // but a lease left behind by a historical architector run must still be
        // clearable by name rather than answering 400.
        "implementer" | "reviewer" | "architector" => RunKind::Worker,
        other => return Err(ApiError::bad_request(format!("unknown lease kind {other}"))),
    };
    match state
        .supervisor
        .release_orphaned_lease(&project_id, &task_id, kind)
        .await
    {
        crate::supervisor::OrphanedLeaseOutcome::Released { run_id } => {
            tracing::info!(%task_id, %run_id, "cleared orphaned lease");
            Ok(Json(LeaseReleaseResponse {
                status: "released".into(),
                run_id: Some(run_id),
            }))
        }
        crate::supervisor::OrphanedLeaseOutcome::NoLease => Ok(Json(LeaseReleaseResponse {
            status: "no_lease".into(),
            run_id: None,
        })),
        crate::supervisor::OrphanedLeaseOutcome::HeldByLiveRun { run_id } => {
            Err(ApiError::conflict(format!(
                "lease for {task_id} is held by live run {run_id}; release the run instead"
            )))
        }
    }
}

fn validate_dispatch_path(field: &str, path: &FsPath) -> Result<(), ApiError> {
    if !path.is_absolute() {
        return Err(ApiError::bad_request(format!("{field} must be absolute")));
    }
    if field == "worktree_path" {
        validate_dispatch_worktree_dir(path)?;
    }
    Ok(())
}

fn validate_dispatch_worktree_dir(path: &FsPath) -> Result<(), ApiError> {
    match std::fs::symlink_metadata(path) {
        Ok(meta) if meta.file_type().is_symlink() => {
            Err(ApiError::bad_request("worktree path must not be a symlink"))
        }
        Ok(meta) if meta.is_dir() => Ok(()),
        _ => Err(ApiError::bad_request(
            "worktree path does not exist or is not a directory",
        )),
    }
}

fn validate_dispatch_applicable_states(
    worker: &StageWorker,
    task: &crate::index::TaskSummary,
) -> Result<(), ApiError> {
    if worker.applicable_states.is_empty() {
        return Ok(());
    }
    let state = match task.lifecycle_stage {
        LifecycleStage::Done => "done",
        LifecycleStage::Cancelled => "cancelled",
        _ => "working",
    };
    if !worker
        .applicable_states
        .iter()
        .any(|allowed| allowed == state)
    {
        return Err(ApiError::bad_request(format!(
            "task lifecycle state {} (run state {state}) is not in worker applicable_states",
            task.lifecycle_stage
        )));
    }
    Ok(())
}

fn compile_dispatch_prompt_bundle(
    home: &Home,
    project: &ProjectIndex,
    kind: DispatchEndpointKind,
    task_id: &str,
    worker: &StageWorker,
    brief: &str,
) -> Result<String, ApiError> {
    let mut values = SlotValues::new();
    values.insert("task.id".to_string(), task_id.to_string());
    values.insert("dispatch.brief".to_string(), prompt_value_or_not_set(brief));
    hydrate_dispatch_task_slots(&mut values, project, task_id)?;
    hydrate_dispatch_project_slots(&mut values, project);
    hydrate_dispatch_worker_slots(&mut values, worker, kind);
    values.insert("skills.all".to_string(), skills_manifest(home)?);
    if let Some(max_iterations) = worker.max_iterations {
        values.insert("run.max_iterations".to_string(), max_iterations.to_string());
    }
    if let Some(context_budget_chars) = worker.context_budget_chars {
        values.insert(
            "run.context_budget_chars".to_string(),
            context_budget_chars.to_string(),
        );
    }
    hydrate_skill_slots(home, worker, &mut values)?;
    let req = crate::prompt_compiler::PromptCompileRequest {
        project: Some(project.project_id.clone()),
        mode: Some("dispatch".to_string()),
        worker: Some(worker.id.clone()),
        harness: Some(worker.harness.clone()),
        renderer: None,
        reason: Some(format!("{} dispatch for {task_id}", kind.as_str())),
        context_overrides: BTreeMap::new(),
        values,
    };
    let compiled = crate::prompt_compiler::compile_prompt_spec(home, kind.as_str(), req)
        .map_err(|e| content_list_error(e, "dispatch prompt spec"))?;
    if crate::prompt_compiler::has_error(&compiled.diagnostics) {
        let messages = compiled
            .diagnostics
            .iter()
            .filter(|diag| diag.level == "error")
            .map(|diag| diag.message.as_str())
            .collect::<Vec<_>>()
            .join("; ");
        return Err(ApiError::bad_request(format!(
            "dispatch prompt compile failed: {messages}"
        )));
    }
    enforce_context_budget_chars(
        compiled.char_count,
        worker.context_budget_chars,
        "dispatch prompt",
    )?;
    Ok(format!(
        "orgasmic compiled prompt\ndispatch_kind: {}\ntask: {}\nworker: {}\nprompt_spec: {}\n\n{}\n",
        kind.as_str(),
        task_id,
        worker.id,
        compiled.spec.id,
        compiled.text.trim()
    ))
}

struct DispatchStartedRecord<'a> {
    project_id: &'a str,
    project_root: &'a FsPath,
    task_id: &'a str,
    kind: DispatchEndpointKind,
    req: &'a DispatchRequest,
    run_id: &'a str,
}

fn dispatch_expected_next(kind: DispatchEndpointKind) -> &'static str {
    match kind {
        DispatchEndpointKind::Implementer => "fix-implementer-watch-then-integrate",
        DispatchEndpointKind::Reviewer => "reviewer-watch-then-fix-or-close",
    }
}

/// Render a path for tx records without leaking the local directory layout
/// into the project tx log (committed to git, possibly public). Paths under
/// the project root become project-relative; paths under the orgasmic home
/// (sessions, state) become home-relative. Anything else (e.g. `/tmp`
/// worktrees) is recorded verbatim.
fn tx_safe_path(path: &FsPath, project_root: Option<&FsPath>, home: &Home) -> String {
    if let Some(root) = project_root {
        if let Ok(rel) = path.strip_prefix(root) {
            return rel.display().to_string();
        }
    }
    if let Ok(rel) = path.strip_prefix(&home.root) {
        return rel.display().to_string();
    }
    path.display().to_string()
}

async fn record_dispatch_started(
    state: &ApiState,
    record: DispatchStartedRecord<'_>,
) -> Result<String, ApiError> {
    let started_at = Utc::now().format("[%Y-%m-%d %a %H:%M:%S]").to_string();
    let mut extra = vec![
        ("KIND".to_string(), record.kind.as_str().to_string()),
        ("MODE".to_string(), record.req.mode.clone()),
        ("HARNESS".to_string(), record.req.harness.clone()),
        (
            "WORKTREE".to_string(),
            record.req.worktree_path.display().to_string(),
        ),
        (
            "BRANCH".to_string(),
            non_empty_field(record.req.branch.clone()).unwrap_or_default(),
        ),
        (
            "BRIEF_PATH".to_string(),
            tx_safe_path(
                &record.req.brief_path,
                Some(record.project_root),
                &state.home,
            ),
        ),
        ("STARTED_AT".to_string(), started_at),
        (
            "LIVENESS".to_string(),
            non_empty_field(record.req.liveness.clone()).unwrap_or_default(),
        ),
        (
            "NEXT".to_string(),
            dispatch_expected_next(record.kind).to_string(),
        ),
    ];
    if let Some(runtime) = non_empty_field(record.req.runtime.clone()) {
        extra.push(("RUNTIME".to_string(), runtime));
    }
    // Raw argv preserved as a JSON array string — never shell-joined (dec_WDR5K item 4).
    if !record.req.harness_args.is_empty() {
        extra.push((
            "HARNESS_ARGS".to_string(),
            serde_json::to_string(&record.req.harness_args).unwrap_or_else(|_| "[]".into()),
        ));
    }
    if let Some(model) = verbatim_optional(record.req.model_override.clone()) {
        extra.push(("MODEL".to_string(), model));
    }
    if let Some(effort) = verbatim_optional(record.req.effort_override.clone()) {
        extra.push(("EFFORT".to_string(), effort));
    }
    if let Some(goal_id) = non_empty_field(record.req.goal_id.clone()) {
        extra.push(("GOAL_ID".to_string(), goal_id));
    }
    if !record.req.reviewed_dispatch_txs.is_empty() {
        extra.push((
            "REVIEWS_TX".to_string(),
            record.req.reviewed_dispatch_txs.join(" "),
        ));
    }
    if let Some(reason) = non_empty_field(record.req.reason.clone()) {
        extra.push(("REASON_INITIAL".to_string(), reason));
    }
    record_api_tx(
        state,
        ApiTxRequest {
            ty: "manager.dispatch_started".to_string(),
            actor: None,
            project: Some(record.project_id.to_string()),
            task: Some(record.task_id.to_string()),
            target: None,
            reason: String::new(),
            request_id: Some(format!("dispatch-started-{}", record.run_id)),
            extra,
        },
    )
    .await
}

struct DispatchCreatedRecord<'a> {
    project_id: &'a str,
    project_root: &'a FsPath,
    task_id: &'a str,
    kind: DispatchEndpointKind,
    req: &'a DispatchRequest,
    acquire: &'a crate::supervisor::AcquireResponse,
    session_path: &'a FsPath,
    worker: &'a StageWorker,
    dispatch_tx_id: &'a str,
}

async fn record_dispatch_created(
    state: &ApiState,
    record: DispatchCreatedRecord<'_>,
) -> Result<String, ApiError> {
    let mut extra = vec![
        ("RUN_ID".to_string(), record.acquire.run_id.clone()),
        ("ORIGIN".to_string(), "cli_dispatch".to_string()),
        ("WORKER".to_string(), record.worker.id.clone()),
        ("KIND".to_string(), record.kind.as_str().to_string()),
        ("DRIVER".to_string(), record.worker.driver.clone()),
        ("HARNESS".to_string(), record.worker.harness.clone()),
        (
            "WORKTREE".to_string(),
            record.req.worktree_path.display().to_string(),
        ),
        (
            "BRIEF_PATH".to_string(),
            tx_safe_path(
                &record.req.brief_path,
                Some(record.project_root),
                &state.home,
            ),
        ),
        (
            "LAST_PATH".to_string(),
            tx_safe_path(
                &record.req.last_path,
                Some(record.project_root),
                &state.home,
            ),
        ),
        (
            "STDOUT_PATH".to_string(),
            tx_safe_path(
                &record.req.stdout_path,
                Some(record.project_root),
                &state.home,
            ),
        ),
    ];
    if let Some(token) = record.req.dispatch_attempt_token.as_deref() {
        extra.push(("DISPATCH_ATTEMPT".to_string(), token.to_string()));
    }
    if let Some(pid) = record.acquire.pid {
        extra.push(("PID".to_string(), pid.to_string()));
    }
    extra.push(("DISPATCH_TX".to_string(), record.dispatch_tx_id.to_string()));
    if let Some(model) = verbatim_optional(record.req.model_override.clone()) {
        extra.push(("MODEL_OVERRIDE".to_string(), model));
    }
    if let Some(effort) = verbatim_optional(record.req.effort_override.clone()) {
        extra.push(("EFFORT_OVERRIDE".to_string(), effort));
    }
    if let Some(provider) = non_empty_field(record.req.provider_override.clone()) {
        extra.push(("PROVIDER_OVERRIDE".to_string(), provider));
    }
    record_api_tx(
        state,
        ApiTxRequest {
            ty: "run.created".to_string(),
            actor: None,
            project: Some(record.project_id.to_string()),
            task: Some(record.task_id.to_string()),
            target: Some(tx_safe_path(
                record.session_path,
                Some(record.project_root),
                &state.home,
            )),
            reason: record.req.reason.clone().unwrap_or_else(|| {
                format!(
                    "cli dispatch {} with {}",
                    record.kind.as_str(),
                    record.worker.id
                )
            }),
            request_id: None,
            extra,
        },
    )
    .await
}

#[derive(Clone)]
struct DispatchCompletion {
    project_id: String,
    task_id: String,
    run_id: String,
    session_path: PathBuf,
    #[allow(dead_code)] // artifact paths; worker finalize writes directly
    last_path: PathBuf,
    #[allow(dead_code)]
    stdout_path: PathBuf,
    worktree_path: PathBuf,
}

/// Follow the run while the supervisor holds it live, then classify its
/// persisted release. Worker finalize owns all success artifacts; this watcher
/// only records failed/orphaned termination and never scrapes a report.
fn spawn_dispatch_completion_watcher(state: ApiState, completion: DispatchCompletion) {
    tokio::spawn(async move {
        let grace = state.dispatch_watcher_grace;
        let poll = std::time::Duration::from_millis(250);
        let mut finalize_deadline: Option<std::time::Instant> = None;
        loop {
            let live = state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .any(|run| run.run_id == completion.run_id);
            if live {
                finalize_deadline = None;
                tokio::time::sleep(poll).await;
                continue;
            }
            let deadline =
                *finalize_deadline.get_or_insert_with(|| std::time::Instant::now() + grace);
            let grace_elapsed = std::time::Instant::now() >= deadline;
            let Ok(envelopes) = read_session_file(&completion.session_path) else {
                if grace_elapsed {
                    tracing::warn!(
                        run_id = %completion.run_id,
                        path = %completion.session_path.display(),
                        "dispatch completion watcher gave up: session file unreadable after post-release grace"
                    );
                    return;
                }
                tokio::time::sleep(poll).await;
                continue;
            };
            // dec_3M7M0 / TASK-AFE5Q: worker-declared finalize is the sole
            // success authority. If it landed, the worker already wrote
            // last.txt/stdout.log verbatim — never overwrite that report.
            if dispatch_release_finalized_by_worker(&envelopes) {
                tracing::info!(
                    run_id = %completion.run_id,
                    "dispatch completion watcher: worker finalized via `orgasmic dispatch finalize`, skipping scrape"
                );
                return;
            }
            // dec_3M7M0 / TASK-ZB90M: only worker finalize may author
            // completion artifacts. Any tombstone with finalized_by_worker=false
            // is orphan — never synthesize last.txt/stdout.log from driver events.
            if dispatch_release_without_worker_finalize(&envelopes) {
                if dispatch_release_requires_orphan_signal(&envelopes) {
                    tracing::warn!(
                        run_id = %completion.run_id,
                        reason = dispatch_release_reason(&envelopes).as_deref().unwrap_or(""),
                        "dispatch completion watcher: release without worker finalize, flagging orphan"
                    );
                    record_dispatch_orphaned(&state, &completion).await;
                } else {
                    tracing::info!(
                        run_id = %completion.run_id,
                        reason = dispatch_release_reason(&envelopes).as_deref().unwrap_or(""),
                        "dispatch completion watcher: cancelled release without worker finalize, no orphan"
                    );
                }
                return;
            }
            if grace_elapsed {
                if dispatch_terminal_reached(&envelopes)
                    && dispatch_release_requires_orphan_signal(&envelopes)
                {
                    tracing::warn!(
                        run_id = %completion.run_id,
                        "dispatch completion watcher: terminal without worker finalize, flagging orphan"
                    );
                    record_dispatch_orphaned(&state, &completion).await;
                } else {
                    tracing::info!(
                        run_id = %completion.run_id,
                        "dispatch completion watcher: post-release grace elapsed without worker finalize; no artifacts"
                    );
                }
                return;
            }
            tokio::time::sleep(poll).await;
        }
    });
}

/// Whether a non-finalized release should emit `manager.dispatch_orphaned`.
/// Intentional cancellation (`ReleaseOutcome::Cancelled`) stays artifact-free
/// and must not trigger orphan rescue (TASK-756WX).
// orgasmic:TASK-756WX,dec_3M7M0
fn dispatch_release_requires_orphan_signal(envelopes: &[SessionEnvelope]) -> bool {
    if !dispatch_release_without_worker_finalize(envelopes) {
        return false;
    }
    match dispatch_release_outcome(envelopes) {
        Some(ReleaseOutcome::Cancelled) => false,
        Some(ReleaseOutcome::Failed) | Some(ReleaseOutcome::Interrupted) => true,
        Some(ReleaseOutcome::Completed) => true,
        None => dispatch_release_reason(envelopes)
            .is_some_and(|reason| anomalous_without_finalize_release_reason(&reason)),
    }
}

// orgasmic:TASK-JK66P — matched on the reason's leading token: a stall release
// now carries the evidence it could not find (`stall_timeout_exceeded: no work
// evidence for 612s; …`), and an orphan is an orphan either way.
fn anomalous_without_finalize_release_reason(reason: &str) -> bool {
    matches!(
        reason.split(':').next().unwrap_or(reason).trim(),
        "stall_timeout_exceeded"
            | "max_run_duration_exceeded"
            | "idle_timeout_exceeded"
            | "protocol_end_without_finalize"
            | "driver terminal event"
    )
}

/// Last `Lifecycle::Release` event's outcome, if any.
fn dispatch_release_outcome(envelopes: &[SessionEnvelope]) -> Option<ReleaseOutcome> {
    envelopes.iter().rev().find_map(|envelope| {
        if envelope.kind != SessionEventKind::Lifecycle {
            return None;
        }
        match serde_json::from_value::<Lifecycle>(envelope.event.clone()) {
            Ok(Lifecycle::Release { outcome, .. }) => Some(outcome),
            _ => None,
        }
    })
}

/// Subprocess harness exited after `Ready` (or fatal startup error) with no
/// work envelopes — same orphan contract as protocol-end without finalize
/// (TASK-R28CP / TASK-QPKCD review).
#[cfg(test)]
const EARLY_EXIT_NO_WORK_REASON: &str = "early-exit subprocess with no work envelopes";

#[cfg(test)]
fn is_timeout_release_reason(reason: &str) -> bool {
    matches!(
        reason,
        "stall_timeout_exceeded" | "max_run_duration_exceeded" | "idle_timeout_exceeded"
    )
}

/// Release reasons that mean the run ended without `orgasmic dispatch
/// finalize` and must be flagged orphan (never scraped into a fake done
/// report). Timeouts plus structured-transport protocol-end without finalize
/// (TASK-P4MGK / dec_WDR5K): TUI EOT (`driver terminal event`) stays a
/// scrape fallback until TASK-AFE5Q.
#[cfg(test)]
fn is_orphan_without_finalize_release_reason(reason: &str) -> bool {
    is_timeout_release_reason(reason)
        || reason == "protocol_end_without_finalize"
        || reason == EARLY_EXIT_NO_WORK_REASON
}

/// Last `Lifecycle::Release` event's `reason`, if any — used to tell a timeout
/// release apart from every other release path.
fn dispatch_release_reason(envelopes: &[SessionEnvelope]) -> Option<String> {
    envelopes.iter().rev().find_map(|envelope| {
        if envelope.kind != SessionEventKind::Lifecycle {
            return None;
        }
        match serde_json::from_value::<Lifecycle>(envelope.event.clone()) {
            Ok(Lifecycle::Release { reason, .. }) => Some(reason),
            _ => None,
        }
    })
}

/// Whether the run's `Lifecycle::Release` event carries `finalized_by_worker`
/// (set by `orgasmic dispatch finalize`, dec_3M7M0).
fn dispatch_release_finalized_by_worker(envelopes: &[SessionEnvelope]) -> bool {
    envelopes.iter().rev().any(|envelope| {
        envelope.kind == SessionEventKind::Lifecycle
            && matches!(
                serde_json::from_value::<Lifecycle>(envelope.event.clone()),
                Ok(Lifecycle::Release {
                    finalized_by_worker: true,
                    ..
                })
            )
    })
}

/// Whether the run was released without the worker calling
/// `orgasmic dispatch finalize` (any reason/outcome).
// orgasmic:TASK-ZB90M,dec_3M7M0
fn dispatch_release_without_worker_finalize(envelopes: &[SessionEnvelope]) -> bool {
    envelopes.iter().rev().any(|envelope| {
        envelope.kind == SessionEventKind::Lifecycle
            && matches!(
                serde_json::from_value::<Lifecycle>(envelope.event.clone()),
                Ok(Lifecycle::Release {
                    finalized_by_worker: false,
                    ..
                })
            )
    })
}

/// Flag a dispatch run that ended without the worker ever calling
/// `orgasmic dispatch finalize` (dec_3M7M0 / TASK-P4MGK): distinct from a
/// normal completion tx so the manager can rescue it rather than mistake
/// it for silent success.
async fn record_dispatch_orphaned(state: &ApiState, completion: &DispatchCompletion) {
    let extra = vec![
        ("RUN_ID".to_string(), completion.run_id.clone()),
        (
            "WORKTREE".to_string(),
            completion.worktree_path.display().to_string(),
        ),
    ];
    if let Err(e) = record_api_tx(
        state,
        ApiTxRequest {
            ty: "manager.dispatch_orphaned".to_string(),
            actor: None,
            project: Some(completion.project_id.clone()),
            task: Some(completion.task_id.clone()),
            target: Some(tx_safe_path(&completion.session_path, None, &state.home)),
            reason: "worker never called `orgasmic dispatch finalize` before the run was released"
                .to_string(),
            request_id: None,
            extra,
        },
    )
    .await
    {
        tracing::warn!(
            run_id = %completion.run_id,
            error = ?e,
            "manager.dispatch_orphaned tx failed"
        );
    }
}

#[allow(dead_code)] // retained for unit tests of dispatch_last_summary_from_session
fn write_dispatch_last_path(
    last_path: &FsPath,
    envelopes: &[SessionEnvelope],
) -> std::io::Result<()> {
    let summary = dispatch_last_summary_from_session(envelopes);
    if summary.is_empty() {
        return Ok(());
    }
    if let Some(parent) = last_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(last_path, summary)
}

#[allow(dead_code)] // retained for unit tests of dispatch_stdout_from_session
fn write_dispatch_stdout_path(
    stdout_path: &FsPath,
    envelopes: &[SessionEnvelope],
) -> std::io::Result<()> {
    let body = dispatch_stdout_from_session(envelopes);
    if body.is_empty() {
        return Ok(());
    }
    if let Some(parent) = stdout_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(stdout_path, body)
}

fn dispatch_stdout_from_session(envelopes: &[SessionEnvelope]) -> String {
    let mut text_lines = Vec::new();
    let mut json_lines = Vec::new();
    for envelope in envelopes {
        if envelope.kind != SessionEventKind::DriverEvent {
            continue;
        }
        if let Ok(line) = serde_json::to_string(&envelope.event) {
            json_lines.push(line);
        }
        if envelope.event.get("type").and_then(Value::as_str) != Some("text_chunk") {
            continue;
        }
        let Some(chunk) = envelope.event.get("chunk").and_then(Value::as_str) else {
            continue;
        };
        if chunk.is_empty() {
            continue;
        }
        let stream = envelope
            .event
            .get("stream")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        text_lines.push(format!("[{stream}] {chunk}"));
    }
    if !text_lines.is_empty() {
        return text_lines.join("\n");
    }
    json_lines.join("\n")
}

fn dispatch_terminal_reached(envelopes: &[SessionEnvelope]) -> bool {
    session_driver_terminal_event(envelopes).is_some()
        || envelopes.iter().rev().any(|envelope| {
            release_outcome(envelope)
                .map(|outcome| {
                    matches!(
                        outcome,
                        ReleaseOutcome::Completed
                            | ReleaseOutcome::Failed
                            | ReleaseOutcome::Cancelled
                    )
                })
                .unwrap_or(false)
        })
}

/// Bare status markers the codex app-server adapter fabricated before TASK-YHA6V
/// ("codex turn completed", "thread closed"). Sessions recorded by the old
/// adapter still carry them; they must never shadow the worker's real report.
fn is_generic_completion_marker(summary: &str) -> bool {
    summary == "thread closed"
        || summary
            .strip_prefix("codex turn ")
            .is_some_and(|status| !status.is_empty() && !status.contains(char::is_whitespace))
}

fn dispatch_last_summary_from_session(envelopes: &[SessionEnvelope]) -> String {
    let mut run_complete_summary = None;
    let mut marker_summary = None;
    let mut assistant_text = String::new();
    let mut system_text = String::new();
    let mut release_reason = None;
    for envelope in envelopes {
        if envelope.kind == SessionEventKind::Lifecycle {
            if release_reason.is_none() {
                if let Ok(Lifecycle::Release { reason, .. }) =
                    serde_json::from_value::<Lifecycle>(envelope.event.clone())
                {
                    let trimmed = reason.trim();
                    if !trimmed.is_empty() {
                        release_reason = Some(trimmed.to_string());
                    }
                }
            }
            continue;
        }
        if envelope.kind != SessionEventKind::DriverEvent {
            continue;
        }
        match envelope.event.get("type").and_then(Value::as_str) {
            Some("run_complete") if run_complete_summary.is_none() => {
                if let Some(summary) = envelope
                    .event
                    .get("summary")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    if is_generic_completion_marker(summary) {
                        if marker_summary.is_none() {
                            marker_summary = Some(summary.to_string());
                        }
                    } else {
                        run_complete_summary = Some(summary.to_string());
                    }
                }
            }
            Some("text_chunk") => {
                let Some(chunk) = envelope.event.get("chunk").and_then(Value::as_str) else {
                    continue;
                };
                if chunk.is_empty() {
                    continue;
                }
                let stream = envelope.event.get("stream").and_then(Value::as_str);
                let assistant = envelope.event.get("role").and_then(Value::as_str)
                    == Some("assistant")
                    || stream == Some("assistant");
                if assistant {
                    assistant_text.push_str(chunk);
                } else if stream == Some("system") {
                    system_text.push_str(chunk);
                }
            }
            _ => {}
        }
    }
    // tmux `release(reason)` synthesizes a `RunComplete { summary: reason }`
    // when they tear down a run that never emitted its own terminal event (e.g.
    // stall detector / operator stop). That sentinel is not a worker report:
    // when the run_complete summary merely echoes the release reason, drop it
    // so a native-transcript or system tail can still be used if present,
    // instead of being shadowed by "stall_timeout_exceeded".
    let run_complete_echoes_release = matches!(
        (run_complete_summary.as_deref(), release_reason.as_deref()),
        (Some(rc), Some(reason)) if rc == reason
    );
    if run_complete_echoes_release {
        run_complete_summary = None;
    }
    let assistant_summary = tail_summary(&assistant_text);
    let system_summary = tail_summary(&system_text);
    run_complete_summary
        .or(assistant_summary)
        .or(system_summary)
        .or(release_reason)
        .or(marker_summary)
        .unwrap_or_default()
}

/// Streaming transcripts can be large, and the worker's report is always at the
/// scrollback here) can be large, and the worker's report is always at the
/// tail. Cap the fallback summary to its last [`DISPATCH_SUMMARY_TAIL_BYTES`] on
/// a char boundary so last.txt stays bounded while still carrying the report.
const DISPATCH_SUMMARY_TAIL_BYTES: usize = 32 * 1024;

fn tail_summary(text: &str) -> Option<String> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return None;
    }
    if trimmed.len() <= DISPATCH_SUMMARY_TAIL_BYTES {
        return Some(trimmed.to_string());
    }
    let mut start = trimmed.len() - DISPATCH_SUMMARY_TAIL_BYTES;
    while !trimmed.is_char_boundary(start) {
        start += 1;
    }
    Some(format!(
        "[…transcript truncated to last {} KiB…]\n{}",
        DISPATCH_SUMMARY_TAIL_BYTES / 1024,
        &trimmed[start..]
    ))
}

#[derive(Clone)]
struct StageCompletion {
    stage: String,
    project_id: String,
    task_id: String,
    target: String,
    run_id: String,
    session_path: PathBuf,
}

pub(crate) enum StageOutcome {
    Completed,
    Failed { reason: Option<String> },
}

fn spawn_stage_completion_watcher(state: ApiState, completion: StageCompletion) {
    tokio::spawn(async move {
        loop {
            let live = state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .any(|run| run.run_id == completion.run_id);
            if live {
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                continue;
            }
            let outcome = stage_outcome_from_session(&completion.session_path);
            let tx_type = match &outcome {
                StageOutcome::Completed => format!("{}.completed", completion.stage),
                StageOutcome::Failed { .. } => format!("{}.failed", completion.stage),
            };
            let reason = match &outcome {
                StageOutcome::Completed => format!("{} stage completed", completion.stage),
                StageOutcome::Failed { reason } => reason
                    .clone()
                    .unwrap_or_else(|| format!("{} stage failed", completion.stage)),
            };
            match record_api_tx(
                &state,
                ApiTxRequest {
                    ty: tx_type.clone(),
                    actor: None,
                    project: Some(completion.project_id.clone()),
                    task: Some(completion.task_id.clone()),
                    target: Some(completion.target.clone()),
                    reason,
                    request_id: None,
                    extra: vec![
                        ("RUN_ID".to_string(), completion.run_id.clone()),
                        (
                            "SESSION_PATH".to_string(),
                            completion.session_path.display().to_string(),
                        ),
                    ],
                },
            )
            .await
            {
                Ok(tx_id) => {
                    let payload = match &outcome {
                        StageOutcome::Completed => EventPayload::StageCompleted {
                            stage: completion.stage.clone(),
                            project_id: completion.project_id.clone(),
                            task_id: completion.task_id.clone(),
                            run_id: completion.run_id.clone(),
                            tx_id: tx_id.clone(),
                        },
                        StageOutcome::Failed { .. } => EventPayload::StageFailed {
                            stage: completion.stage.clone(),
                            project_id: completion.project_id.clone(),
                            task_id: completion.task_id.clone(),
                            run_id: completion.run_id.clone(),
                            tx_id: tx_id.clone(),
                        },
                    };
                    state.events.publish(Topic::Run, payload);
                    state.events.publish(
                        Topic::Manager,
                        EventPayload::ManagerNotice {
                            message: format!(
                                "{} for run {} recorded as {}",
                                tx_type, completion.run_id, tx_id
                            ),
                        },
                    );
                    state
                        .events
                        .publish(Topic::Board, EventPayload::BoardRefreshed);
                }
                Err(e) => {
                    tracing::warn!(
                        run_id = %completion.run_id,
                        stage = %completion.stage,
                        error = ?e,
                        "stage completion tx failed"
                    );
                }
            }
            break;
        }
    });
}

pub(crate) fn stage_outcome_from_session(session_path: &FsPath) -> StageOutcome {
    let envelopes = match read_session_file(session_path) {
        Ok(envelopes) => envelopes,
        Err(e) => {
            tracing::warn!(path = %session_path.display(), error = %e, "stage session read failed");
            return StageOutcome::Failed { reason: None };
        }
    };
    // orgasmic:TASK-C0XMR — parse the COMPLETE session instead of returning on
    // the first failure signal. `orgasmic dispatch finalize` finalizes from the
    // worker's still-ACTIVE turn: the release interrupts the turn and teardown
    // reaps the harness process group, so the driver synthesizes a fatal
    // "exited with signal" error which the supervisor drains BEFORE it appends
    // the authoritative `finalized_by_worker` release. Short-circuiting on that
    // error recorded a normal, successful stage as `<stage>.failed`.
    //
    // The rule is ORDERING, not presence: an authoritative worker finalize
    // dominates only the failure signals that PRECEDE it in session order.
    // Anything failing with no worker finalize after it — the ordinary case
    // where the driver dies before the worker can finalize, and the supervisor
    // releases the run non-authoritatively — still fails the stage.
    //
    // orgasmic:TASK-QSSQH — but dominance is not unconditional, and the
    // release event is not the boundary. Both a genuine `run_fail` and a
    // teardown-induced fatal `driver_error` are drained BEFORE the release,
    // and both freeze the run's terminal outcome to `Failed`, so
    // `Release { outcome: Failed, finalized_by_worker: true }` is byte-identical
    // in the two cases and can discriminate neither. What separates them:
    //
    // 1. KIND. `run_fail` is a semantic, harness-declared failure — the
    //    adapters emit it only from a protocol result (`is_error`, a failed
    //    turn, a stop reason). Teardown cannot synthesize it: reaping the
    //    process group produces a fatal `DriverError` (see
    //    `classify_pane_exit` in `orgasmic-drivers`). So a `run_fail` is
    //    sticky — no later finalize may clear it, wherever it lands relative
    //    to the finalize, which matters because a `run_fail` still queued when
    //    the finalize is admitted is drained AFTER the admission marker.
    // 2. The finalize-admission MARKER for everything else. The supervisor
    //    appends a durable `worker_finalize_admitted` note at the instant it
    //    admits a worker finalize and before it tears the driver down
    //    (`supervisor::release_one`). A fatal driver error after that marker
    //    is one the finalize caused and stays suppressed; one before it was
    //    already there and is sticky too.
    //
    // Sessions with no marker — written before TASK-QSSQH, or where the marker
    // append failed — keep the TASK-C0XMR reading for driver errors: dominance
    // by the following finalize. The kind rule in (1) still applies to them.
    let admission_marker_present = envelopes.iter().any(is_finalize_admission_marker);
    let mut completed = false;
    let mut pending_failure: Option<Option<String>> = None;
    // A failure no worker finalize is allowed to clear.
    let mut sticky_failure: Option<Option<String>> = None;
    let mut driver_error_reason = None;
    let mut finalize_admitted = false;
    for envelope in envelopes {
        match envelope.kind {
            SessionEventKind::DriverEvent => {
                match envelope.event.get("type").and_then(Value::as_str) {
                    Some("run_fail") => {
                        pending_failure = Some(None);
                        sticky_failure = Some(None);
                    }
                    Some("driver_error") => {
                        if driver_error_reason.is_none() {
                            driver_error_reason = envelope
                                .event
                                .get("message")
                                .and_then(Value::as_str)
                                .filter(|value| !value.trim().is_empty())
                                .map(|message| format!("driver error: {message}"));
                        }
                        if envelope
                            .event
                            .get("fatal")
                            .and_then(Value::as_bool)
                            .unwrap_or(false)
                        {
                            let reason = driver_error_reason
                                .clone()
                                .unwrap_or_else(|| "fatal driver error".to_string());
                            pending_failure = Some(Some(reason.clone()));
                            if admission_marker_present && !finalize_admitted {
                                sticky_failure = Some(Some(reason));
                            }
                        }
                    }
                    // Protocol RunComplete alone is not stage success for
                    // grill/plan (TASK-S52X9): only a worker-declared
                    // finalize tombstone or an explicit Completed release
                    // counts. Ignore run_complete here so protocol-end
                    // without finalize (Failed release) cannot be rescued
                    // by an earlier RunComplete event.
                    Some("run_complete") => {}
                    _ => {}
                }
            }
            SessionEventKind::Lifecycle => {
                if envelope.event.get("phase").and_then(Value::as_str) == Some("release") {
                    // orgasmic:TASK-S52X9 — worker finalize tombstone is
                    // Completed even when the HTTP release path historically
                    // stamped Cancelled; prefer the declaration flag.
                    let finalized = envelope
                        .event
                        .get("finalized_by_worker")
                        .and_then(Value::as_bool)
                        .unwrap_or(false);
                    if finalized {
                        // orgasmic:TASK-C0XMR — the authoritative worker
                        // finalize dominates every failure signal recorded
                        // before it, including the teardown-induced fatal
                        // driver error its own release causes.
                        completed = true;
                        pending_failure = None;
                        driver_error_reason = None;
                        continue;
                    }
                    match envelope.event.get("outcome").and_then(Value::as_str) {
                        Some("completed") => completed = true,
                        Some("failed") | Some("interrupted") | Some("cancelled") => {
                            pending_failure = Some(driver_error_reason.clone().or_else(|| {
                                envelope
                                    .event
                                    .get("reason")
                                    .and_then(Value::as_str)
                                    .filter(|r| *r == "protocol_end_without_finalize")
                                    .map(|r| r.to_string())
                            }));
                        }
                        _ => {}
                    }
                }
            }
            SessionEventKind::Note => {
                if is_finalize_admission_marker(&envelope) {
                    finalize_admitted = true;
                }
            }
        }
    }
    if let Some(reason) = sticky_failure.or(pending_failure) {
        return StageOutcome::Failed { reason };
    }
    if completed {
        StageOutcome::Completed
    } else {
        StageOutcome::Failed { reason: None }
    }
}

/// orgasmic:TASK-QSSQH — the durable finalize-admission boundary, written by
/// [`crate::supervisor`] before it tears a finalizing run's driver down.
fn is_finalize_admission_marker(envelope: &SessionEnvelope) -> bool {
    envelope.kind == SessionEventKind::Note
        && crate::supervisor::is_worker_finalize_admitted_note(&envelope.event)
}

struct ApiTxRequest {
    ty: String,
    actor: Option<String>,
    project: Option<String>,
    task: Option<String>,
    target: Option<String>,
    reason: String,
    request_id: Option<String>,
    extra: Vec<(String, String)>,
}

/// Is the origin→replacement association for `run_id` already durable in the tx
/// ledger (TASK-6AYEJ.3)? The whole tx directory is indexed, so a hit here means
/// the entry is on disk, not merely cached.
async fn recovery_association_is_durable(
    state: &ApiState,
    project: Option<&str>,
    run_id: &str,
) -> Result<bool, ApiError> {
    if let Some(project_id) = project {
        ensure_loaded_snapshot(state, Some(project_id)).await?;
    } else {
        state
            .index
            .ensure_all_projects_loaded()
            .await
            .map_err(|error| ApiError::unavailable(format!("tx coverage failed: {error}")))?;
    }
    let snap = state.index.snapshot().await;
    Ok(snap.tx.iter().any(|record| {
        if record.entry.ty != "run.created" {
            return false;
        }
        if let (Some(want), Some(got)) = (project, record.project_id.as_deref()) {
            if want != got {
                return false;
            }
        }
        let has = |key: &str, value: &str| {
            record
                .entry
                .extra
                .iter()
                .any(|(k, v)| k == key && v == value)
        };
        has("ORIGIN", "recovery") && has("RUN_ID", run_id)
    }))
}

/// Bind a recovery REPLACEMENT run to the dispatch generation that owns its
/// origin (TASK-6AYEJ.2, widened by TASK-6AYEJ.3).
///
/// A recovery keeps the task and the terminal contract but acquires a new run
/// id, so the worker's eventual `*.reported` carries an id the dispatch
/// generation has never seen. Only `run.created ORIGIN=cli_dispatch` binds a run
/// to a `manager.dispatch_started`, and recovery never emits one — without this
/// link `dispatch-status` stays `[unreported]` forever and `dispatch-close`
/// addresses a run id that no longer exists.
///
/// TASK-6AYEJ.3: every return path that hands back a replacement id must call
/// this, not just the freshly-acquired one. The crash paths were all missing it:
/// a reattach (the replacement session already carried its Acquire) was assumed
/// to imply an unchanged id, and the two crash-reconciled fast returns hand back
/// a committed claim without running the recovery action at all. Each of those
/// left the replacement live with no ledger link — and a close aimed at the
/// origin id then tears the worktree down beneath it.
#[allow(clippy::too_many_arguments)]
async fn record_recovery_replacement_association(
    state: &ApiState,
    project: Option<&str>,
    origin_run_id: &str,
    replacement_run_id: &str,
    task_id: &str,
    role: &str,
    action: &str,
    requires_worker_finalize: bool,
) -> Result<(), ApiError> {
    // Reattach-in-place preserves the id, so there is nothing to link; a run
    // with no worker-finalize contract reports nothing to associate; and a
    // synthesized `recover:<id>` task never belonged to a dispatch.
    if replacement_run_id == origin_run_id
        || !requires_worker_finalize
        || task_id.starts_with("recover:")
    {
        return Ok(());
    }
    // The writer's `request_id` idempotence cache is in-memory, and a crash
    // retry by definition arrives on a daemon that has just restarted — so on
    // exactly the paths this exists for, that cache is always cold. Consult the
    // durable ledger instead. The manager side is set-based and would tolerate a
    // duplicate; the ledger a human reads should not carry one.
    if recovery_association_is_durable(state, project, replacement_run_id).await? {
        return Ok(());
    }
    record_api_tx(
        state,
        ApiTxRequest {
            ty: "run.created".to_string(),
            actor: None,
            project: project.map(str::to_string),
            task: Some(task_id.to_string()),
            target: None,
            reason: format!("{action} replacing run {origin_run_id}"),
            request_id: Some(format!("recovery-run-created-{replacement_run_id}")),
            extra: vec![
                ("RUN_ID".to_string(), replacement_run_id.to_string()),
                ("ORIGIN".to_string(), "recovery".to_string()),
                ("ORIGIN_RUN_ID".to_string(), origin_run_id.to_string()),
                ("ACTION".to_string(), action.to_string()),
                ("KIND".to_string(), role.to_string()),
            ],
        },
    )
    .await?;
    Ok(())
}

/// [`record_recovery_replacement_association`] for the crash-reconciled returns,
/// which answer from a committed claim rather than from an executed action.
async fn record_recovery_replacement_association_from_claim(
    state: &ApiState,
    project: Option<&str>,
    claim: &RecoveryClaim,
) -> Result<(), ApiError> {
    record_recovery_replacement_association(
        state,
        project,
        &claim.origin_run_id,
        &claim.replacement_run_id,
        claim.task_id.as_deref().unwrap_or("recover:"),
        claim.role.as_deref().unwrap_or("worker"),
        claim.action.as_deref().unwrap_or("start_recovery_run"),
        claim.requires_worker_finalize.unwrap_or(false),
    )
    .await
}

async fn record_api_tx(state: &ApiState, req: ApiTxRequest) -> Result<String, ApiError> {
    record_api_tx_after_project_mutation(state, req, None).await
}

async fn record_api_tx_after_project_mutation(
    state: &ApiState,
    req: ApiTxRequest,
    mutation_project_id: Option<&str>,
) -> Result<String, ApiError> {
    let prepared = prepare_api_tx(state, req).await?;
    let res = state
        .writer
        .append_tx(prepared.tx, None)
        .await
        .map_err(writer_append_error)?;
    if let Some(project_id) = mutation_project_id {
        refresh_after_project_mutation(state, project_id, prepared.project_tx, &res.tx_id).await?;
    } else {
        refresh_after_tx(
            state,
            prepared.project_tx,
            prepared.destination_project_id,
            &res.tx_id,
        )
        .await?;
    }
    Ok(res.tx_id)
}

struct PreparedApiTx {
    tx: TxAppend,
    project_tx: bool,
    destination_project_id: Option<String>,
}

async fn prepare_api_tx(state: &ApiState, req: ApiTxRequest) -> Result<PreparedApiTx, ApiError> {
    let now = Utc::now();
    if let Some(project_id) = req.project.as_deref() {
        let registered = state
            .index
            .snapshot()
            .await
            .board
            .iter()
            .any(|entry| entry.id == project_id);
        if registered {
            state
                .index
                .ensure_project_loaded(project_id)
                .await
                .map_err(|error| {
                    ApiError::unavailable(format!("project {project_id} failed to load: {error}"))
                })?;
        }
    }
    let snap = state.index.snapshot().await;
    let project_entry = req
        .project
        .as_deref()
        .and_then(|id| snap.board.iter().find(|entry| entry.id == id))
        .cloned();
    let pseudo_req = TxAppendRequest {
        request_id: req.request_id.clone(),
        r#type: req.ty.clone(),
        actor: req.actor,
        machine: None,
        project: req.project,
        task: req.task,
        target: req.target,
        reason: Some(req.reason),
        extra: req.extra,
        tx_path: None,
    };
    let destination = tx_destination(state, &pseudo_req, project_entry.as_ref(), &now)?;
    let tx_id = match &destination.tx_id_policy {
        TxIdPolicy::Preserve => format!(
            "tx-{}-{}",
            tx_preserve_id_timestamp_utc(&now),
            &uuid::Uuid::new_v4().to_string()[..8]
        ),
        TxIdPolicy::ProjectSequence { .. } => "pending-project-sequence".to_string(),
    };
    let time_str = tx_time_string_utc(&now);
    let mut entry = TxEntry::new(
        tx_id,
        &req.ty,
        time_str,
        choose_actor(&pseudo_req, project_entry.as_ref(), state),
        state.machine.clone(),
    );
    entry.project = pseudo_req.project;
    entry.task = pseudo_req.task;
    entry.target = pseudo_req.target;
    entry.reason = pseudo_req.reason;
    entry.extra = pseudo_req.extra;
    Ok(PreparedApiTx {
        tx: TxAppend {
            tx_path: destination.tx_path,
            entry,
            project_id: destination.project_id.clone(),
            tx_id_policy: destination.tx_id_policy,
            request_id: req.request_id,
        },
        project_tx: destination.project_tx,
        destination_project_id: destination.project_id,
    })
}

async fn refresh_after_tx(
    state: &ApiState,
    project_tx: bool,
    destination_project_id: Option<String>,
    tx_id: &str,
) -> Result<(), ApiError> {
    if project_tx {
        if let Some(project_id) = destination_project_id {
            state
                .index
                .refresh_after_tx(&project_id, tx_id)
                .await
                .map_err(|error| committed_refresh_error(tx_id, error))?;
        }
    } else {
        state
            .index
            .refresh_home_after_tx(tx_id)
            .await
            .map_err(|error| committed_refresh_error(tx_id, error))?;
    }
    Ok(())
}

/// Publish every projection made stale by one project-file mutation. The
/// project is always refreshed; a home-routed tx refreshes the home ledger as
/// part of the same API-level acknowledgement orchestration.
async fn refresh_after_project_mutation(
    state: &ApiState,
    project_id: &str,
    project_tx: bool,
    tx_id: &str,
) -> Result<(), ApiError> {
    if project_tx {
        return state
            .index
            .refresh_after_tx(project_id, tx_id)
            .await
            .map_err(|error| committed_refresh_error(tx_id, error));
    }

    let (project_result, home_result) = tokio::join!(
        state.index.refresh_after_tx(project_id, tx_id),
        state.index.refresh_home_after_tx(tx_id),
    );
    project_result.map_err(|error| committed_refresh_error(tx_id, error))?;
    home_result.map_err(|error| committed_refresh_error(tx_id, error))?;
    Ok(())
}

fn committed_refresh_error(tx_id: &str, error: impl std::fmt::Display) -> ApiError {
    tracing::error!(tx_id, error = %error, "committed mutation index refresh failed");
    ApiError::service_unavailable(json!({
        "error": format!("mutation committed but index refresh failed: {error}"),
        "committed": true,
        "tx_id": tx_id,
        "index_status": "refresh_failed",
    }))
}

fn safe_session_fragment(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' || ch == '.' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

struct TxDestination {
    tx_path: PathBuf,
    project_id: Option<String>,
    project_tx: bool,
    tx_id_policy: TxIdPolicy,
}

fn tx_destination(
    state: &ApiState,
    req: &TxAppendRequest,
    project_entry: Option<&BoardEntry>,
    now: &chrono::DateTime<Utc>,
) -> Result<TxDestination, ApiError> {
    if let Some(tx_path) = req.tx_path.clone() {
        return Ok(TxDestination {
            tx_path,
            project_id: req.project.clone(),
            project_tx: false,
            tx_id_policy: TxIdPolicy::Preserve,
        });
    }
    if state.tx_commit_to_project {
        if let Some(project_id) = req
            .project
            .as_deref()
            .map(str::trim)
            .filter(|project_id| !project_id.is_empty())
        {
            let Some(entry) = project_entry else {
                tracing::warn!(
                    project_id = %project_id,
                    "tx project not found on board"
                );
                return Err(ApiError::bad_request("project could not be resolved"));
            };
            if !valid_project_root(&entry.path) {
                tracing::warn!(
                    project_id = %project_id,
                    path = %entry.path.display(),
                    "tx project root is invalid"
                );
                return Err(ApiError::bad_request("project could not be resolved"));
            }
            let tx_path = entry
                .path
                .join(".orgasmic")
                .join("tx")
                .join(format!("{}.org", tx_file_month_utc(now)));
            return Ok(TxDestination {
                tx_path,
                project_id: Some(entry.id.clone()),
                project_tx: true,
                tx_id_policy: TxIdPolicy::ProjectSequence {
                    project_id: entry.id.clone(),
                    date: tx_project_date_utc(now),
                },
            });
        }
    }
    Ok(TxDestination {
        tx_path: state
            .default_tx_path
            .with_file_name(format!("{}.org", tx_file_month_utc(now))),
        project_id: req.project.clone(),
        project_tx: false,
        tx_id_policy: TxIdPolicy::Preserve,
    })
}

fn valid_project_root(path: &FsPath) -> bool {
    !path.as_os_str().is_empty() && path.join(".orgasmic").is_dir()
}

fn choose_actor(
    req: &TxAppendRequest,
    _project_entry: Option<&BoardEntry>,
    state: &ApiState,
) -> String {
    req.actor
        .clone()
        .and_then(non_empty)
        .or_else(|| state.manager_actor.clone())
        .unwrap_or_else(|| state.actor.clone())
}

fn non_empty(value: String) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

#[derive(Debug, Serialize)]
pub struct StatusResponse {
    pub name: &'static str,
    pub version: String,
    pub runtime_version: String,
    pub boot_id: String,
    pub pid: u32,
    pub started_at: String,
    pub home: PathBuf,
    pub machine: String,
    pub bind_host: String,
    pub bind_port: u16,
    pub local_only: bool,
    pub ui_asset_hash: String,
    /// Projects whose operational projection is ready.
    pub projects: usize,
    /// Projects the board registers. Unloaded projects are healthy catalog
    /// entries and load naturally on first scoped access.
    pub registered_projects: usize,
    pub unloaded_projects: Vec<String>,
    pub loading_projects: Vec<String>,
    pub ready_projects: Vec<String>,
    pub delayed_projects: BTreeMap<String, String>,
    pub failed_projects: BTreeMap<String, String>,
    pub parse_errors: usize,
    pub tx_count: usize,
    pub rebuilt_at: Option<String>,
    pub writer: crate::writer::WriterStatus,
    pub index_refresh: crate::index::IndexRefreshStatus,
    /// Descriptor headroom: an fd leak shows here long before EMFILE.
    pub open_fds: Option<usize>,
    pub fd_limit: Option<u64>,
}

async fn get_status(State(state): State<ApiState>) -> Json<StatusResponse> {
    let snap: IndexSnapshot = state.index.snapshot().await;
    let writer = state.writer.status();
    let index_refresh = state.index.refresh_status().await;
    let (open_fds, fd_limit) = crate::fd_usage();
    let unloaded_projects = snap.project_ids_in_state(crate::index::ProjectLoadState::Unloaded);
    let loading_projects = snap.project_ids_in_state(crate::index::ProjectLoadState::Loading);
    let ready_projects = snap.project_ids_in_state(crate::index::ProjectLoadState::Ready);
    let delayed_projects = snap
        .project_loads
        .iter()
        .filter(|(_, load)| load.state == crate::index::ProjectLoadState::Delayed)
        .map(|(id, load)| {
            (
                id.clone(),
                load.error
                    .clone()
                    .unwrap_or_else(|| "project load delayed".to_string()),
            )
        })
        .collect();
    let failed_projects = snap
        .project_loads
        .iter()
        .filter(|(_, load)| load.state == crate::index::ProjectLoadState::Failed)
        .map(|(id, load)| {
            (
                id.clone(),
                load.error
                    .clone()
                    .unwrap_or_else(|| "project load failed".to_string()),
            )
        })
        .collect();
    Json(StatusResponse {
        name: "orgasmic",
        version: state.boot.version.clone(),
        runtime_version: state.boot.version.clone(),
        boot_id: state.boot.boot_id.clone(),
        pid: state.boot.pid,
        started_at: state.boot.started_at.to_rfc3339(),
        home: state.index.home_root().await.to_path_buf(),
        machine: state.machine,
        local_only: state.bind_host == "127.0.0.1" || state.bind_host == "::1",
        bind_host: state.bind_host,
        bind_port: state.bind_port,
        ui_asset_hash: state.ui_asset_hash,
        projects: ready_projects.len(),
        registered_projects: snap.board.len(),
        unloaded_projects,
        loading_projects,
        ready_projects,
        delayed_projects,
        failed_projects,
        parse_errors: snap.parse_errors.len(),
        tx_count: snap.tx.len(),
        rebuilt_at: snap.rebuilt_at.map(|t| t.to_rfc3339()),
        writer,
        index_refresh,
        open_fds,
        fd_limit,
    })
}

#[derive(Debug, Serialize)]
pub struct RecoveryResponse {
    pub boot_id: String,
    pub acquisition_paused: bool,
    pub live_runs: Vec<crate::supervisor::RunSummary>,
    pub interrupted_runs: Vec<RecoveredRun>,
    pub reattached_runs: Vec<RecoveredRun>,
    /// Terminal `ReleaseOutcome::Failed` tombstones that remain immutable but
    /// expose manager-authorized recovery actions (TASK-R28CP / TASK-QPKCD).
    pub failed_recoverable_runs: Vec<RecoveredRun>,
    pub terminal_noop_runs: Vec<RecoveredRun>,
    pub ambiguous_runs: Vec<RecoveredRun>,
    /// Bounded-inventory stage metrics for this response. Present so an
    /// operator (and the wire regression) can prove enumeration cost is a
    /// function of record count, not transcript bytes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub inventory: Option<InventoryStageMetrics>,
    /// orgasmic:TASK-WGXKD.2 finding 3 — releases this daemon accepted whose
    /// terminal tx never landed (task panicked/aborted, or the append failed).
    /// The lease is already gone, so no worker will retry: recovery status is
    /// where an operator can still see that the run is unreported.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub lost_release_finalizations: Vec<LostReleaseFinalization>,
    pub note: &'static str,
}

/// What one `GET /api/runs` inventory pass actually touched.
///
/// Deliberately carries counts and byte totals only: never a session path's
/// contents, transcript text, prompts, or any harness credential material.
#[derive(Debug, Clone, Default, Serialize)]
pub struct InventoryStageMetrics {
    /// Session JSONL files considered across every registered project.
    pub session_files: u64,
    /// Total on-disk size of those files.
    pub session_file_bytes: u64,
    /// Bytes actually read to classify them. The whole point of the bounded
    /// scan is that this stays flat as `session_file_bytes` grows.
    pub bytes_inspected: u64,
    /// Files whose middle region was skipped because they exceeded the budget.
    pub truncated_scans: u64,
    /// Files that could not be scanned or parsed, classified `ambiguous`.
    pub unreadable_sessions: u64,
    // orgasmic:TASK-FZB6T — the catalog's own cost model. `catalog_cache_hits`
    // is the number of records answered without opening their session file at
    // all; on a board whose runs have ended it is every record and
    // `bytes_inspected` is zero, which is the acceptance stated as a number an
    // operator can read off one response.
    pub catalog_cache_hits: u64,
    pub catalog_rebuilds: u64,
    pub catalog_evictions: u64,
    /// Records whose recorded worktree is gone. Each one is an attach probe
    /// this pass did NOT start.
    pub tombstoned_authority: u64,
    /// Terminal records held by the catalog, whether or not this response
    /// returned them.
    pub terminal_total: u64,
    /// Terminal records actually returned in the bounded window.
    pub terminal_returned: u64,
    /// Driver attach proofs started for non-terminal records.
    pub attach_probes_started: u64,
    /// Attach proofs abandoned at the shared inventory deadline.
    pub attach_probes_timed_out: u64,
    /// Session files read by the recovery-origin index, when it ran at all.
    pub origin_index_files: u64,
    /// Bytes read by the recovery-origin index.
    pub origin_index_bytes_inspected: u64,
    pub interrupted: u64,
    pub reattached: u64,
    pub failed_recoverable: u64,
    pub terminal_noop: u64,
    pub ambiguous: u64,
    /// Wall-clock cost of the whole inventory pass.
    pub duration_ms: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct RecoveredRun {
    pub run_id: String,
    pub runtime_id: String,
    pub boot_id: String,
    pub session_path: PathBuf,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project_id: Option<String>,
    /// Canonical registered project root containing this session file. This is
    /// board authority, never reconstructed from project-owned JSONL.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub project_root: Option<PathBuf>,
    /// Canonical origin worktree recorded by RunMeta and verified to belong to
    /// the containing registered project.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub worktree: Option<PathBuf>,
    /// orgasmic:TASK-FZB6T item 2 — the stable authority verdict for the
    /// recorded worktree: `verified`, `tombstoned` (recorded but gone from
    /// disk), `mismatched`, `unrecorded`, or `unidentified`. A separate axis
    /// from `classification` because "the worktree is gone" is a permanent
    /// property of the run, not a liveness guess that a later poll can revise.
    #[serde(default)]
    pub worktree_authority: String,
    pub classification: String,
    pub reason: String,
    /// Backend-owned, ordered, harness-aware recovery actions (dec_052). The
    /// first entry is the preferred action; the UI renders its `label` and
    /// executes through `POST /runs/:id/recover` with `action.kind`.
    #[serde(default)]
    pub recovery_actions: Vec<RecoveryAction>,
    /// Why the recovery actions above were SUPPRESSED rather than being absent.
    ///
    /// orgasmic:TASK-2QK4P.1.1.1 F3 — an empty `recovery_actions` had two
    /// meanings, and the endpoint could not tell them apart: "this record offers
    /// nothing" and "the origin enumeration did not complete, so we refuse to
    /// say". `POST /runs/:id/recover` needs the difference to keep its
    /// authority-INDEPENDENT request validation authority-independent — an
    /// invalid action must answer 400 whether or not some unrelated session file
    /// happens to be readable — so the actions it would have offered are kept in
    /// `suppressed_recovery_actions` and validated against.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recovery_unobserved: Option<String>,
    /// WHICH FILE the observation failed on — sanitized and project-relative.
    ///
    /// orgasmic:TASK-2QK4P.1.1.1.1 F3 — `recovery_unobserved` carried a reason
    /// and nothing else, and the refusal it describes is project-wide and does
    /// not self-repair. An operator was told every recovery in the project is
    /// unavailable and given no way to find the one file responsible.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recovery_unobserved_subject: Option<String>,
    /// What would clear it — a stable [`orgasmic_daemon::recovery_claim::Remediation`]
    /// class, paired with `recovery_unobserved_subject`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recovery_unobserved_remediation: Option<String>,
    /// The actions this record would offer had the enumeration completed. Empty
    /// unless `recovery_unobserved` is set.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub suppressed_recovery_actions: Vec<RecoveryAction>,
    /// When a Failed origin already has a committed recovery replacement, the
    /// link is exposed and actionable recovery is suppressed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recovery_replacement_run_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recovery_replacement_session_path: Option<PathBuf>,
    /// When this run reached its terminal state. Ordering key for the bounded
    /// recent-terminal window `GET /api/runs` serves.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub terminal_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// A concrete recovery action the backend will take through `/recover`.
#[derive(Debug, Clone, Serialize)]
pub struct RecoveryAction {
    /// Stable machine identifier: `reattach_tmux`, `resume_native_fork`, or
    /// `start_recovery_run`.
    pub kind: String,
    /// Human-facing label rendered by the notification bell / Run Dock.
    pub label: String,
    /// Where recovery opens once executed: `manager` or `worker`.
    pub target: String,
}

/// Recovery surface a successful recover opens.
fn recovery_target_for(_run_kind: Option<RunKind>, worker_id: &str) -> &'static str {
    if worker_id == "manager" || worker_id.starts_with("manager") {
        "manager"
    } else {
        "worker"
    }
}

async fn get_recovery(State(state): State<ApiState>) -> Json<RecoveryResponse> {
    Json(recovery_status(&state).await)
}

/// The supervisor-local answer to "is anything running right now".
///
/// orgasmic:task_6HJYT — the same argument `get_run` already makes for exact
/// id lookups, applied to the plural question. Live runs are held in
/// supervisor memory with their identities; answering liveness through
/// [`get_recovery_inventory`] made a control-path fence (daemon stop/restart,
/// `orgasmic update`, `manager dispatch-close`) pay for classifying every
/// historical run on the board, and — worse than the cost — made its verdict
/// depend on unrelated durable history being readable at all.
///
/// This handler performs no session-file reads. It carries no classifications
/// and no inventory metrics precisely so it cannot grow into a second run
/// list: `live` here is [`SupervisorSnapshot::runs`] verbatim, the same value
/// the inventory consumes for its own `live` bucket, so the two cannot drift.
async fn get_live_runs(State(state): State<ApiState>) -> Json<Value> {
    let live = state.supervisor.snapshot().await;
    Json(json!({
        "boot_id": state.boot.boot_id,
        "acquisition_paused": live.acquisition_paused,
        "live": live.runs,
    }))
}

/// `GET /api/runs` — the crash-recovery inventory, not a general run list.
///
/// orgasmic:task_6HJYT — every bucket but `live` is classified by reading
/// durable session JSONL across the whole board; that scan is the point of the
/// endpoint and its cost. Callers that only want "what is running right now"
/// belong on [`get_live_runs`]. The `live` bucket is retained here because the
/// recovery view renders live and recoverable runs together, and it is the
/// supervisor snapshot verbatim — never a second classification.
async fn get_recovery_inventory(
    State(state): State<ApiState>,
    Query(query): Query<RunInventoryQuery>,
) -> Json<Value> {
    let recovery = {
        let _status_guard = state.recovery_status_lock.lock().await;
        recovery_status_inner(&state, query.into(), &mut ProjectOriginAuthority::default()).await
    };
    Json(json!({
        "live": recovery.live_runs,
        "interrupted": recovery.interrupted_runs,
        "reattached": recovery.reattached_runs,
        "failed_recoverable": recovery.failed_recoverable_runs,
        "terminal_noop": recovery.terminal_noop_runs,
        "ambiguous": recovery.ambiguous_runs,
        // Bounded-inventory stage metrics for this exact response, so an
        // operator can see what enumeration cost without reading daemon logs.
        "inventory": recovery.inventory,
    }))
}

/// `GET /api/runs/history` — read-only accounting of what durable run history
/// actually holds, by driver+harness and event class.
///
/// orgasmic:TASK-FZB6T item 4. Deliberately a separate route from the
/// inventory: this one visits every byte of every session file (accounting for
/// bytes means reading them), which is precisely the cost `GET /api/runs` must
/// never pay. It runs only when an operator asks.
///
/// It is a dry run and there is no other mode in this build. Nothing is
/// written, moved, truncated, or deleted; the response states the reclaimable
/// total so the destructive pass — which requires its own explicit
/// authorization — has an exact number to be checked against.
async fn get_run_history(
    State(state): State<ApiState>,
    Query(query): Query<RunHistoryQuery>,
) -> Result<Json<Value>, ApiError> {
    if let Some(project) = query.project.as_deref() {
        state
            .index
            .ensure_project_loaded(project)
            .await
            .map_err(|error| {
                ApiError::unavailable(format!("project {project} failed to load: {error}"))
            })?;
    }
    let board = state.index.snapshot().await.board;
    let roots: Vec<PathBuf> = board
        .iter()
        .filter(|entry| {
            query
                .project
                .as_deref()
                .is_none_or(|project| project == entry.id)
        })
        .map(|entry| entry.path.clone())
        .collect();
    if roots.is_empty() {
        if let Some(project) = query.project.as_deref() {
            return Err(ApiError::not_found(format!("project {project}")));
        }
    }
    let catalog = state.run_catalog.clone();
    let started = std::time::Instant::now();
    let report = tokio::task::spawn_blocking(move || {
        let mut entries = Vec::new();
        let mut seen: BTreeSet<PathBuf> = BTreeSet::new();
        for root in &roots {
            let Ok(canonical) = root.canonicalize() else {
                continue;
            };
            if !seen.insert(canonical.clone()) {
                continue;
            }
            let project_id =
                read_existing_project_identity(&canonical.join(".orgasmic/project.org"))
                    .ok()
                    .map(|identity| identity.project_id);
            catalog.refresh_dir(
                &project_sessions_dir(&canonical),
                project_id.as_deref(),
                &canonical,
                SessionScanBudget::DEFAULT,
            );
            entries.extend(catalog.entries_for_project(&canonical));
        }
        crate::run_catalog::inspect_history(&entries)
    })
    .await
    .map_err(|error| ApiError::internal(format!("run history inspection failed: {error}")))?;

    Ok(Json(json!({
        "report": report,
        "duration_ms": started.elapsed().as_millis() as u64,
    })))
}

#[derive(Debug, Default, Deserialize)]
pub struct RunHistoryQuery {
    /// Restrict accounting to one registered project id.
    #[serde(default)]
    project: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
pub struct RunHistoryCompactRequest {
    /// The registered project to maintain. Required: maintenance is per
    /// project, and a board-wide destructive default is not a thing an
    /// operator should be able to reach by omission.
    pub project: String,
    /// The manifest id of the plan the operator read. Absent means dry run.
    #[serde(default)]
    pub confirm: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
pub struct RunHistoryRollbackRequest {
    pub project: String,
    pub manifest_id: String,
}

/// Resolve one registered project id to its canonical root.
async fn project_root_for(state: &ApiState, project: &str) -> Result<PathBuf, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(state, Some(project)).await?;
    let entry = snap
        .board
        .iter()
        .find(|entry| entry.id == project)
        .ok_or_else(|| ApiError::not_found(format!("project {project}")))?;
    entry
        .path
        .canonicalize()
        .map_err(|error| ApiError::internal(format!("canonicalize project root: {error}")))
}

/// `POST /runs/history/compact` — the maintenance transaction
/// (orgasmic:TASK-FZB6T.1 finding 1).
///
/// Dry run by default and in every ambiguous case: without a `confirm` token
/// this reads and reports, and with a token that does not match the plan it
/// just computed it refuses. The token is a digest of the plan itself, so
/// "confirm" cannot be satisfied by anything except having read this exact
/// plan.
async fn post_run_history_compact(
    State(state): State<ApiState>,
    Json(request): Json<RunHistoryCompactRequest>,
) -> Result<Json<Value>, ApiError> {
    let root = project_root_for(&state, &request.project).await?;
    let catalog = state.run_catalog.clone();
    let started = std::time::Instant::now();
    let confirm = request.confirm.clone();

    // Plan first, and on its own: the plan names the session paths, and the
    // writer has to be fenced against every one of them BEFORE the transaction
    // is allowed to rename anything over them (orgasmic:TASK-FZB6T.2 finding
    // 3 / dec_BBPW4).
    let plan = {
        let catalog = catalog.clone();
        let root = root.clone();
        tokio::task::spawn_blocking(move || {
            refresh_project_catalog(&catalog, &root);
            let entries = catalog.entries_for_project(&root);
            crate::run_history::plan_compaction(&root, &entries)
        })
        .await
        .map_err(|error| ApiError::internal(format!("run history planning failed: {error}")))?
    };

    let Some(confirm) = confirm else {
        return Ok(Json(json!({
            "report": crate::run_history::dry_run_report(plan),
            "duration_ms": started.elapsed().as_millis() as u64,
        })));
    };

    // orgasmic:TASK-FZB6T.3 finding 1 — a LEASE, held for the whole
    // transaction, not a one-shot handle close. While it is held every append
    // for these paths queues in the writer before it opens anything, so no line
    // can land on the inode the rename is about to orphan.
    //
    // orgasmic:TASK-FZB6T.4 finding 1 — and the lease is owned by a DETACHED
    // task, not by this handler. A client disconnect or route cancellation used
    // to drop the handler, which dropped the lease, which reopened the writer
    // while the already-started blocking transaction was still mid-rename.
    // Awaiting this call is now the only thing cancellation can take away.
    let paths: Vec<PathBuf> = plan
        .files
        .iter()
        .map(|file| file.session_path.clone())
        .collect();
    let fenced = crate::run_history::FencedSessions::new(paths.clone());
    let report = {
        let catalog = catalog.clone();
        let paths = paths.clone();
        state
            .writer
            .with_detached_session_lease(paths.clone(), move || {
                let outcome = crate::run_history::apply_compaction(plan, Some(&confirm), &fenced);
                // Whatever happened, every rewritten file's cached entry is stale.
                for path in &paths {
                    catalog.invalidate_session(path);
                }
                outcome
            })
            .await
            .map_err(|error| match error {
                crate::writer::LeasedTransactionError::Lease(error) => {
                    ApiError::internal(format!("hold session writer across compaction: {error}"))
                }
                crate::writer::LeasedTransactionError::Transaction(error) => {
                    ApiError::internal(format!("run history compaction failed: {error}"))
                }
            })?
    };

    let report = report.map_err(|error| match error {
        crate::run_history::CompactionError::ConfirmationRequired { .. }
        | crate::run_history::CompactionError::ConfirmationStale { .. }
        | crate::run_history::CompactionError::MaintenanceBusy { .. } => {
            ApiError::bad_request(error.to_string())
        }
        other => ApiError::internal(other.to_string()),
    })?;
    Ok(Json(json!({
        "report": report,
        "duration_ms": started.elapsed().as_millis() as u64,
    })))
}

/// `POST /runs/history/rollback` — restore the originals one manifest archived.
async fn post_run_history_rollback(
    State(state): State<ApiState>,
    Json(request): Json<RunHistoryRollbackRequest>,
) -> Result<Json<Value>, ApiError> {
    let root = project_root_for(&state, &request.project).await?;
    let catalog = state.run_catalog.clone();
    let manifest_id = request.manifest_id.clone();

    // Rollback renames over live paths exactly like the forward pass, so it
    // needs the same writer fence (orgasmic:TASK-FZB6T.2 finding 3).
    let paths = {
        let root = root.clone();
        let manifest_id = manifest_id.clone();
        tokio::task::spawn_blocking(move || {
            crate::run_history::manifest_session_paths(&root, &manifest_id)
        })
        .await
        .map_err(|error| ApiError::internal(format!("read compaction manifest: {error}")))?
    };
    // orgasmic:TASK-FZB6T.4 finding 1 — same detached owner as the forward
    // pass. Rollback renames over live paths too, so a handler-scoped lease left
    // the same window open here.
    //
    // orgasmic:TASK-FZB6T.5 finding 3 — and the leased paths are handed to the
    // transaction as the FENCE, exactly as the forward pass hands its own. The
    // manifest is read here, before the maintenance lock; `rollback_compaction`
    // decodes it again after taking that lock, and anything the second decode
    // names that this lease does not cover is refused rather than renamed.
    let fenced = crate::run_history::FencedSessions::new(paths.clone());
    let report = state
        .writer
        .with_detached_session_lease(paths, move || {
            let report = crate::run_history::rollback_compaction(&root, &manifest_id, &fenced);
            if let Ok(report) = &report {
                for path in &report.restored {
                    catalog.invalidate_session(path);
                }
            }
            report
        })
        .await
        .map_err(|error| match error {
            crate::writer::LeasedTransactionError::Lease(error) => {
                ApiError::internal(format!("hold session writer across rollback: {error}"))
            }
            crate::writer::LeasedTransactionError::Transaction(error) => {
                ApiError::internal(format!("run history rollback failed: {error}"))
            }
        })?;

    let report = report.map_err(|error| match error {
        crate::run_history::CompactionError::ManifestNotFound { .. } => {
            ApiError::not_found(error.to_string())
        }
        other => ApiError::bad_request(other.to_string()),
    })?;
    Ok(Json(json!({ "report": report })))
}

async fn get_run(
    State(state): State<ApiState>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    // Exact active-run lookups are supervisor-local. Worker finalize and
    // manager close must not scan unrelated durable recovery history before
    // they can act on a live run whose id they already know.
    let live = state.supervisor.snapshot().await;
    if let Some(run) = live.runs.iter().find(|run| run.run_id == id) {
        let source = read_artifact(&run.session_path, "run session")?;
        return Ok(Json(json!({"source": source, "run": run})));
    }

    // orgasmic:TASK-FZB6T.1 finding 9 — an exact id is answered by an exact
    // lookup. The previous route ran the whole inventory and then searched its
    // *paged* result, so `run show <id>` returned "no such run" for any
    // terminal run older than the default fifty-record window: the record
    // existed, was indexed, and was simply not in the page. The catalog is
    // keyed by path and carries the id, so a direct lookup answers without
    // classifying the board at all.
    let recovery = recovery_status_for_run(&state, &id).await;
    for (classification, runs) in [
        ("interrupted", &recovery.interrupted_runs),
        ("reattached", &recovery.reattached_runs),
        ("failed_recoverable", &recovery.failed_recoverable_runs),
        ("terminal_noop", &recovery.terminal_noop_runs),
        ("ambiguous", &recovery.ambiguous_runs),
    ] {
        if let Some(run) = runs.iter().find(|run| run.run_id == id) {
            let source = read_artifact(&run.session_path, "run session")?;
            return Ok(Json(
                json!({"classification": classification, "source": source, "run": run}),
            ));
        }
    }
    Err(ApiError::not_found(format!("run {id}")))
}

/// The inventory answer for ONE run id, without paging it out of the response.
///
/// orgasmic:TASK-FZB6T.1 finding 9. The catalog is refreshed for the project
/// that holds the run — nothing else on the board is touched — and only that
/// one record is classified. A run the catalog does not hold falls back to the
/// full unbounded inventory, which is the pre-catalog answer and still finds
/// records the index has not seen yet.
async fn recovery_status_for_run(state: &ApiState, run_id: &str) -> RecoveryResponse {
    let _status_guard = state.recovery_status_lock.lock().await;
    let board = state.index.snapshot().await.board;
    let roots: Vec<PathBuf> = board.iter().map(|entry| entry.path.clone()).collect();

    // Refresh only the project whose sessions directory could hold this id.
    // The catalog may not have it yet (a run created since the last poll), so a
    // miss re-indexes every project once and then asks again.
    let catalog = state.run_catalog.clone();
    let lookup_id = run_id.to_string();
    let refresh_roots = roots.clone();
    let found = tokio::task::spawn_blocking(move || {
        if let Some(entry) = catalog.find_by_run_id(&lookup_id) {
            if let Some(root) = entry.project_root.clone() {
                refresh_project_catalog(&catalog, &root);
                return catalog.find_by_run_id(&lookup_id).map(|_| root);
            }
        }
        for root in &refresh_roots {
            let Ok(canonical) = root.canonicalize() else {
                continue;
            };
            refresh_project_catalog(&catalog, &canonical);
            if catalog.find_by_run_id(&lookup_id).is_some() {
                return Some(canonical);
            }
        }
        None
    })
    .await
    .unwrap_or(None);

    let scoped: Vec<PathBuf> = found.map(|root| vec![root]).unwrap_or(roots);
    let live = state.supervisor.snapshot().await;
    let (recovered, _) = classify_session_files(
        &state.home,
        state.trusted_claude_binary.as_ref(),
        &state.boot.boot_id,
        &live.runs,
        &scoped,
        &state.run_catalog,
        Some(&state.writer),
        TerminalWindow::unbounded(),
    )
    .await;

    // One authority for this whole lookup, built lazily: a board with no
    // failed-recoverable run never enumerates anything.
    let mut origin_authority = ProjectOriginAuthority::default();
    let mut response = RecoveryResponse {
        boot_id: state.boot.boot_id.clone(),
        acquisition_paused: live.acquisition_paused,
        live_runs: live.runs,
        interrupted_runs: Vec::new(),
        reattached_runs: Vec::new(),
        failed_recoverable_runs: Vec::new(),
        terminal_noop_runs: Vec::new(),
        ambiguous_runs: Vec::new(),
        inventory: None,
        lost_release_finalizations: state.release_tasks.lost_finalizations(),
        note: "exact run lookup: one record, classified under the same rules as the inventory",
    };
    for mut run in recovered {
        if run.run_id != run_id {
            continue;
        }
        if run.classification == "failed_recoverable" && run.project_id.is_some() {
            apply_recovery_claim_to_run(&state.home, &mut origin_authority, &mut run);
        }
        match run.classification.as_str() {
            "interrupted" => response.interrupted_runs.push(run),
            "reattached" => response.reattached_runs.push(run),
            "failed_recoverable" => response.failed_recoverable_runs.push(run),
            "terminal_noop" => response.terminal_noop_runs.push(run),
            _ => response.ambiguous_runs.push(run),
        }
    }
    response
}

/// Refresh one canonical project root's catalog entries. Blocking.
fn refresh_project_catalog(catalog: &crate::run_catalog::RunCatalog, canonical_root: &FsPath) {
    let project_id = read_existing_project_identity(&canonical_root.join(".orgasmic/project.org"))
        .ok()
        .map(|identity| identity.project_id);
    catalog.refresh_dir(
        &project_sessions_dir(canonical_root),
        project_id.as_deref(),
        canonical_root,
        SessionScanBudget::DEFAULT,
    );
}

/// Resolve harness-native session transcript for a run (TASK-0SADP / dec_WDR5K item 7).
async fn get_run_native_transcript(
    State(state): State<ApiState>,
    Path(id): Path<String>,
) -> Result<Json<Value>, ApiError> {
    let session_path = resolve_run_session_path(&state, &id)
        .await
        .ok_or_else(|| ApiError::not_found(format!("run {id}")))?;
    let envelopes = read_session_file(&session_path).map_err(|e| {
        ApiError::internal(format!(
            "failed to read session {}: {e}",
            session_path.display()
        ))
    })?;
    let Some(lookup) = lookup_from_envelopes(&envelopes) else {
        return Ok(Json(json!({
            "run_id": id,
            "orgasmic_session_path": session_path,
            "result": {
                "status": "not_found",
                "reason": "session JSONL has no RunMeta harness / NativeRuntime provider to select an adapter",
            },
        })));
    };
    let roots = TranscriptRoots::from_env_home().ok_or_else(|| {
        ApiError::internal("HOME is unset; cannot resolve harness transcript roots")
    })?;
    let result = find_native_transcript(&lookup, &roots);
    Ok(Json(json!({
        "run_id": id,
        "harness": lookup.harness,
        "session_id": lookup.session_id,
        "cwd": lookup.cwd,
        "orgasmic_session_path": session_path,
        "result": result,
    })))
}

/// Locate the orgasmic session JSONL for `run_id` across live, recovered, and
/// on-disk project session directories.
async fn resolve_run_session_path(state: &ApiState, run_id: &str) -> Option<PathBuf> {
    let live = state.supervisor.snapshot().await;
    if let Some(run) = live.runs.iter().find(|run| run.run_id == run_id) {
        return Some(run.session_path.clone());
    }
    let recovery = recovery_status(state).await;
    for runs in [
        &recovery.interrupted_runs,
        &recovery.reattached_runs,
        &recovery.failed_recoverable_runs,
        &recovery.terminal_noop_runs,
        &recovery.ambiguous_runs,
    ] {
        if let Some(run) = runs.iter().find(|run| run.run_id == run_id) {
            return Some(run.session_path.clone());
        }
    }
    let project_roots: Vec<PathBuf> = state
        .index
        .snapshot()
        .await
        .board
        .iter()
        .map(|entry| entry.path.clone())
        .collect();
    let mut seen = BTreeSet::new();
    for root in project_roots {
        let dir = project_sessions_dir(&root);
        if !seen.insert(dir.clone()) {
            continue;
        }
        let Ok(entries) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
                continue;
            }
            // Identity lookup only: read the bounded lifecycle window rather
            // than the whole transcript of every recorded run.
            let Ok(scan) = scan_session_lifecycle(&path, SessionScanBudget::DEFAULT) else {
                continue;
            };
            if scan.envelopes.iter().any(|e| e.run_id == run_id) {
                return Some(path);
            }
        }
    }
    None
}

#[derive(Debug, Deserialize)]
pub struct RunReleaseRequest {
    #[serde(default)]
    pub reason: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
    /// Set by `orgasmic dispatch finalize` (dec_3M7M0): the worker itself
    /// declared completion over this same authenticated call, so the
    /// dispatch completion watcher must not scrape/overwrite the report it
    /// already wrote verbatim. `false` for every other caller (manager
    /// dispatch-close, manual cancel, etc.).
    #[serde(default)]
    pub finalized_by_worker: bool,
    /// Set by `orgasmic dispatch finalize` (TASK-DWJVH, review #4): the
    /// run's own `RuntimeIdentity` as the worker resolved it, so the release
    /// can be rejected if a different run has since reclaimed this run_id or
    /// the identity is otherwise stale (same self-consistency guard
    /// `send_input`/`transition_state` already apply). `None` for every
    /// other caller — preserves today's unauthenticated release for the
    /// human manager path (dispatch-close, lease-release).
    #[serde(default)]
    pub caller_identity: Option<RuntimeIdentity>,
    /// Set by `orgasmic dispatch finalize` (TASK-WGXKD): the worker's terminal
    /// tx, to be written by the DAEMON immediately after this release succeeds
    /// rather than by the client afterwards.
    ///
    /// The client cannot write it afterwards: releasing the lease tears down
    /// the driver, and the driver reaps the harness's whole setsid process
    /// group — which the `orgasmic dispatch finalize` process is a member of.
    /// The client is therefore signalled by the very call it is waiting on,
    /// and on stdio it never returns. Handing the tx to the daemon with
    /// the release is what makes "released but unreported" impossible; the
    /// content is the client's verbatim, so tx matching (RUN_ID, deterministic
    /// request id — TASK-6AYEJ.1) is unchanged.
    #[serde(default)]
    pub terminal_tx: Option<TxAppendRequest>,
}

#[derive(Debug, Serialize)]
pub struct RunReleaseResponse {
    pub run_id: String,
    pub task_id: String,
    pub owner: TaskOwner,
    /// Id of the tx written from `terminal_tx`, when the request carried one.
    /// `None` tells a finalize client the daemon did not write its terminal tx
    /// (older daemon, or no `terminal_tx` sent) so it can still post it itself.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub terminal_tx_id: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct RunInputRequest {
    pub input: String,
}

#[derive(Debug, Serialize)]
pub struct RunInputResponse {
    pub run_id: String,
    pub accepted: bool,
    pub message: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct RunRuntimeOptionsResponse {
    pub run_id: String,
    pub accepted: bool,
    pub message: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct RunRuntimeOptionsCatalogResponse {
    pub run_id: String,
    pub catalog: RuntimeOptionsCatalog,
}

async fn post_run_input(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Json(req): Json<RunInputRequest>,
) -> Result<Json<RunInputResponse>, ApiError> {
    let input = req.input.trim().to_string();
    if input.is_empty() {
        return Err(ApiError::bad_request("run input must not be empty"));
    }
    let live = state.supervisor.snapshot().await;
    let run = live
        .runs
        .iter()
        .find(|run| run.run_id == id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("active run {id}")))?;
    let ack = state
        .supervisor
        .send_input(&id, input, &run.identity)
        .await
        .map_err(|e| match e {
            crate::supervisor::SupervisorError::RunNotFound(_) => {
                ApiError::not_found(format!("active run {id}"))
            }
            other => supervisor_control_error("run input", other),
        })?;
    Ok(Json(RunInputResponse {
        run_id: id,
        accepted: ack.accepted,
        message: ack.message,
    }))
}

async fn post_run_runtime_options(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Json(req): Json<RuntimeOptionsRequest>,
) -> Result<Json<RunRuntimeOptionsResponse>, ApiError> {
    let req = req.normalized().map_err(ApiError::bad_request)?;
    if req.is_empty() {
        return Err(ApiError::bad_request(
            "runtime options request must not be empty",
        ));
    }
    let live = state.supervisor.snapshot().await;
    let run = live
        .runs
        .iter()
        .find(|run| run.run_id == id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("active run {id}")))?;
    let ack = state
        .supervisor
        .switch_runtime_options(&id, req, &run.identity)
        .await
        .map_err(|e| match e {
            crate::supervisor::SupervisorError::RunNotFound(_) => {
                ApiError::not_found(format!("active run {id}"))
            }
            other => supervisor_control_error("runtime options", other),
        })?;
    Ok(Json(RunRuntimeOptionsResponse {
        run_id: id,
        accepted: ack.accepted,
        message: ack.message,
    }))
}

async fn get_run_runtime_options(
    State(state): State<ApiState>,
    Path(id): Path<String>,
) -> Result<Json<RunRuntimeOptionsCatalogResponse>, ApiError> {
    let live = state.supervisor.snapshot().await;
    let run = live
        .runs
        .iter()
        .find(|run| run.run_id == id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("active run {id}")))?;
    let catalog = state
        .supervisor
        .runtime_options_catalog(&id, &run.identity)
        .await
        .map_err(|e| match e {
            crate::supervisor::SupervisorError::RunNotFound(_) => {
                ApiError::not_found(format!("active run {id}"))
            }
            other => supervisor_control_error("runtime options catalog", other),
        })?;
    Ok(Json(RunRuntimeOptionsCatalogResponse {
        run_id: id,
        catalog,
    }))
}

async fn post_run_release(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Json(req): Json<RunReleaseRequest>,
) -> Result<Json<RunReleaseResponse>, ApiError> {
    // orgasmic:TASK-WGXKD.1 — a daemon that has begun shutting down cannot
    // promise the terminal tx will reach the writer, so it refuses the release
    // instead of half-performing it. That leaves the lease HELD, which is
    // visible in `dispatch-status` and retryable against the next daemon;
    // releasing without the tx is the invisible state this task exists to
    // eliminate. Checked before the run lookup: whether this daemon is still
    // accepting releases is a property of the daemon, not of the run.
    //
    // orgasmic:TASK-WGXKD.2 — and the refusal and the accounting are ONE atomic
    // step. Reading `is_closed()` here and incrementing later (at the spawn,
    // after the snapshot await) let a release slip between a restart's `close()`
    // and its `in_flight`-empty observation, so it registered and ran after the
    // drain and possibly after the writer barrier. The admission below both
    // decides and counts, under a single synchronization boundary, before any
    // await a restart could overtake.
    let admission = match state
        .release_tasks
        .try_admit(&id, req.terminal_tx.as_ref().map(|tx| tx.r#type.clone()))
    {
        Some(admission) => admission,
        None => {
            return Err(ApiError::unavailable(
                "daemon is shutting down; release refused so the lease stays held \
                 — this finalize can be retried against the restarted daemon \
                 (if it reports the run as gone, use `orgasmic recovery status` \
                 and `orgasmic run recover <run_id>` first)",
            ));
        }
    };
    // Test-only hook occupying the window the pre-fix code really had between
    // the closed check and the tracker registration. See
    // `ApiState::release_admission_delay`.
    if let Some(delay) = state.release_admission_delay {
        tokio::time::sleep(delay).await;
    }
    let live = state.supervisor.snapshot().await;
    let run = live
        .runs
        .iter()
        .find(|run| run.run_id == id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("active run {id}")))?;
    let task_id = run.task_id.clone();
    // orgasmic:TASK-37TAF — the OTHER version-skew direction, fail-closed on
    // this side because only this side can see it.
    //
    // TASK-WGXKD.1 made new-CLI/old-daemon safe with a pre-flight capability
    // probe (`require_daemon_writes_terminal_tx`). Old-CLI/new-daemon had no
    // guard at all: `terminal_tx` is optional, so a pre-WGXKD `dispatch
    // finalize` — which declares `finalized_by_worker` and then intends to
    // `POST /tx` on its own turn — released the run and got a 200 with
    // `terminal_tx_id: null`. It never gets that turn: this release tears down
    // the driver, the driver reaps the harness's setsid process group, and the
    // finalize CLI is a member of it (on stdio a direct `kill(-pgid, …)`,
    // lost 3/3 when measured). What survives is a released run with a
    // `Completed` tombstone, no terminal tx, and NO orphan flag — the dispatch
    // completion watcher reads `finalized_by_worker` as "already reported by
    // the worker" and skips its fallback (see
    // `spawn_dispatch_completion_watcher`). Invisible to both the success path
    // and the rescue path.
    //
    // So refuse before releasing anything, and take the same trade the CLI-side
    // handshake takes: the lease stays HELD, which `dispatch-status` shows and
    // the orphan/stall paths can rescue. Reconstructing the tx server-side
    // instead was rejected — the daemon cannot know the two things that decide
    // what to write (`--status done|blocked`, which selects
    // `<kind>.reported` vs `manager.dispatch_aborted`, and the worker's commit
    // sha); the release reason is byte-identical in both cases, so any
    // reconstruction would be a manufactured success claim.
    //
    // Narrow by construction: `finalized_by_worker` on THIS route is only ever
    // set by `dispatch finalize`. `dispatch-close` sends `false`, and the
    // `artifact_submitted` / `manager_released` declarations never come through
    // here — they call `supervisor.release_with_finalization` directly.
    if req.finalized_by_worker && req.terminal_tx.is_none() {
        return Err(ApiError::bad_request(format!(
            "refusing to release run {id} ({task_id}): this finalize declared \
             `finalized_by_worker` but sent no `terminal_tx`, so it comes from an \
             `orgasmic dispatch finalize` older than this daemon and still expects \
             to write the terminal tx itself after this call returns. It cannot: \
             releasing reaps the harness process group that finalize runs in, so \
             the run would end released and permanently unreported, with no orphan \
             flag. The lease is still held and this finalize is safe to re-run: \
             upgrade the CLI that ran it (`orgasmic update`, or rebuild the source \
             checkout it ran from) so it hands its terminal tx to the release, \
             then run the same `orgasmic dispatch finalize` command again."
        )));
    }
    // orgasmic:TASK-WGXKD — run the release, and the terminal tx that must
    // follow it, on a detached task. Hyper drops this handler's future the
    // moment the caller's connection closes (measured, not assumed: without the
    // spawn, `dispatch_endpoint_worker_finalize_tx_survives_caller_disconnect`
    // loses the tx) — and for a worker finalize the caller is killed BY this
    // very call, because the driver teardown reaps the harness's setsid process
    // group and the finalize CLI is in it. Anything left on the request future
    // is therefore lost exactly when it matters most; anything on the spawned
    // task completes regardless of who is still listening.
    //
    // orgasmic:TASK-WGXKD.1 — and it is spawned through the daemon-owned
    // `release_tasks` tracker, not bare `tokio::spawn`: the JoinHandle below
    // dies with the request future, so it is graceful shutdown's only handle on
    // this work. See [`ReleaseTaskTracker`].
    let release_tasks = state.release_tasks.clone();
    let handle = release_tasks.spawn_release(admission, async move {
        release_run_and_record_tx(state, id, req).await
    });
    let (id, terminal_tx_id) = handle.await.map_err(|error| {
        tracing::error!(error = %error, "run release task failed to join");
        ApiError::internal("failed to release run")
    })??;
    Ok(Json(RunReleaseResponse {
        run_id: id,
        task_id,
        owner: TaskOwner::Human,
        terminal_tx_id,
    }))
}

/// Release `id`, then — only if the release itself succeeded — write the
/// worker's terminal tx when the caller sent one (TASK-WGXKD).
///
/// The ordering is the one `cmd_dispatch_finalize` has always argued for: the
/// release is the authority on whether this worker may claim completion at all
/// (ownership mismatch, a slot reclaimed by another run, a stall sweep that
/// already released), so a refused release must leave no "done" claim behind.
/// What changes is only WHO holds the gap between the two steps: the daemon,
/// which is not the process the release kills.
async fn release_run_and_record_tx(
    state: ApiState,
    id: String,
    req: RunReleaseRequest,
) -> Result<(String, Option<String>), ApiError> {
    let reason = req.reason.unwrap_or_else(|| "run released".to_string());
    // orgasmic:TASK-S52X9 — a worker-declared terminal call is Completed;
    // every other release path stays Cancelled (manager cancel, etc.).
    let outcome = if req.finalized_by_worker {
        ReleaseOutcome::Completed
    } else {
        ReleaseOutcome::Cancelled
    };
    match state
        .supervisor
        .release_with_finalization(
            &id,
            &reason,
            outcome,
            req.finalized_by_worker,
            req.caller_identity.as_ref(),
        )
        .await
    {
        Ok(()) => {}
        // orgasmic:TASK-ARZGD — operator cancel waits for artifactor writer/
        // regenerate ack, then records Cancelled.
        Err(crate::supervisor::SupervisorError::DeferredWhileInFlight(_)) => {}
        // orgasmic:TASK-RB1ZN — the incident's first symptom, closed at its
        // source. This route answered `404 active run <id>` for a run that was
        // present in `runs` and mid-release, i.e. for a run `GET /runs/live`
        // was reporting at that same moment. The supervisor now separates the
        // two states, so 404 keeps its plain meaning here and the live-but-busy
        // one gets the 409 that names how long it can last.
        Err(crate::supervisor::SupervisorError::ReleaseInProgress(_)) => {
            return Err(release_in_progress_conflict(&id));
        }
        Err(crate::supervisor::SupervisorError::RunNotFound(_)) => {
            return Err(ApiError::not_found(format!("active run {id}")));
        }
        Err(crate::supervisor::SupervisorError::OwnershipMismatch {
            run_id,
            field,
            expected,
            got,
        }) => {
            return Err(ApiError::conflict_json(json!({
                "error": "runtime ownership mismatch",
                "run_id": run_id,
                "field": field,
                "expected": expected,
                "got": got,
            })));
        }
        Err(other) => return Err(supervisor_release_error(&id, other)),
    }
    let terminal_tx_id = match req.terminal_tx {
        Some(tx) => {
            if let Some(delay) = state.release_terminal_tx_delay {
                tokio::time::sleep(delay).await;
            }
            let ty = tx.r#type.clone();
            match append_tx_request(&state, tx).await {
                Ok(res) => Some(res.tx_id),
                // The lease is already gone, so there is nobody left to retry:
                // log loudly rather than let the run go quietly unreported.
                Err(error) => {
                    if let Some(committed_tx_id) = error.committed_tx_id() {
                        tracing::error!(
                            run_id = %id,
                            tx_type = %ty,
                            tx_id = committed_tx_id,
                            error = %error.message,
                            "released run and wrote its terminal tx, but projection refresh failed"
                        );
                    } else {
                        tracing::error!(
                            run_id = %id,
                            tx_type = %ty,
                            error = %error.message,
                            "released run but failed to write its terminal tx"
                        );
                    }
                    return Err(error);
                }
            }
        }
        None => None,
    };
    Ok((id, terminal_tx_id))
}

#[derive(Debug, Deserialize)]
pub struct RunRecoverRequest {
    /// Explicit recovery action: `reattach_tmux`, `resume_native_fork`,
    /// `start_recovery_run`, or `abandon`. When omitted, the backend executes
    /// the run's sole valid action or returns a 409 conflict listing the
    /// choices.
    ///
    /// orgasmic:task_VSWZT — `abandon` is never auto-picked and never appears
    /// in a run's `recovery_actions`: it is a manager judgment about a live
    /// run, not a rescue the daemon can infer from the run's own state.
    #[serde(default)]
    pub action: Option<String>,
    #[serde(default)]
    pub project: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
    #[serde(default)]
    pub force_inert: Option<bool>,
    #[serde(default)]
    pub mode: Option<String>,
    #[serde(default)]
    pub harness: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct RunRecoverResponse {
    pub run_id: String,
    pub runtime_id: String,
    pub boot_id: String,
    pub session_path: PathBuf,
    /// Machine identifier of the executed action.
    pub action: String,
    /// UI surface to open: `manager` or `worker`.
    pub target: String,
    /// Staged recovery prompt for the operator to send manually. `None` for
    /// reattach, which leaves the composer empty.
    pub draft_prompt: Option<String>,
}

/// Resolve the harness driver for a recovered run from its session JSONL.
fn recovery_driver(
    home: &Home,
    envelopes: &[SessionEnvelope],
) -> Option<(Box<dyn WorkerDriver>, SessionAcquireMeta)> {
    let meta = session_acquire_meta(envelopes)?;
    let (driver, _id) = session_driver(home, envelopes, &meta)?;
    Some((driver, meta))
}

/// Resolve persisted `(mode, harness)` from session RunMeta events.
fn persisted_run_address_from_session(envelopes: &[SessionEnvelope]) -> Option<(String, String)> {
    for env in envelopes {
        if env.kind != SessionEventKind::Lifecycle {
            continue;
        }
        if let Ok(Lifecycle::RunMeta {
            transport, harness, ..
        }) = serde_json::from_value::<Lifecycle>(env.event.clone())
        {
            let harness = harness.filter(|h| !h.trim().is_empty())?;
            if transport.trim().is_empty() {
                continue;
            }
            return Some((transport, harness));
        }
    }
    None
}

/// Best-effort harness name for a recorded worker id (e.g. `claude` for
/// `implementer-claude-tmux`). Returns `None` when address truth is absent.
fn recovery_harness_for_worker(_home: &Home, envelopes: &[SessionEnvelope]) -> Option<String> {
    persisted_run_address_from_session(envelopes).map(|(_, harness)| harness)
}

fn pinned_claude_execution_config(
    home: &Home,
    pin: &PinnedClaudeExecutable,
    wrapper_override: Option<&FsPath>,
) -> Result<Value, ApiError> {
    #[cfg(test)]
    let candidate = wrapper_override
        .map(FsPath::to_path_buf)
        .or_else(|| {
            let configured = home.bin_orgasmic();
            configured.exists().then_some(configured)
        })
        .map(Ok)
        .unwrap_or_else(std::env::current_exe)
        .map_err(|_| ApiError::internal("trusted orgasmic exec wrapper is unavailable"))?;
    #[cfg(not(test))]
    let candidate = wrapper_override
        .map(FsPath::to_path_buf)
        .map(Ok)
        .unwrap_or_else(std::env::current_exe)
        .map_err(|_| ApiError::internal("trusted orgasmic exec wrapper is unavailable"))?;
    let exec_wrapper = candidate
        .canonicalize()
        .map_err(|_| ApiError::internal("trusted orgasmic exec wrapper is unavailable"))?;
    let wrapper_meta = std::fs::metadata(&exec_wrapper)
        .map_err(|_| ApiError::internal("trusted orgasmic exec wrapper is unavailable"))?;
    if !wrapper_meta.is_file() {
        return Err(ApiError::internal(
            "trusted orgasmic exec wrapper is not a regular file",
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        if wrapper_meta.uid() != unsafe { libc::getuid() }
            || wrapper_meta.permissions().mode() & 0o111 == 0
        {
            return Err(ApiError::internal(
                "trusted orgasmic exec wrapper identity is invalid",
            ));
        }
    }
    #[cfg(unix)]
    let (exec_wrapper, wrapper_dev, wrapper_ino) = {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        let aliases = home.state().join("trusted-exec-wrappers");
        std::fs::create_dir_all(&aliases)
            .map_err(|_| ApiError::internal("trusted wrapper alias directory is unavailable"))?;
        std::fs::set_permissions(&aliases, std::fs::Permissions::from_mode(0o700))
            .map_err(|_| ApiError::internal("trusted wrapper alias directory is unavailable"))?;
        let alias = aliases.join(format!(
            "orgasmic-{}-{}",
            wrapper_meta.dev(),
            wrapper_meta.ino()
        ));
        match std::fs::hard_link(&exec_wrapper, &alias) {
            Ok(()) => {}
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(_) => {
                return Err(ApiError::internal(
                    "trusted orgasmic wrapper retained alias failed",
                ));
            }
        }
        let alias_meta = std::fs::symlink_metadata(&alias)
            .map_err(|_| ApiError::internal("trusted orgasmic wrapper retained alias failed"))?;
        if !alias_meta.is_file()
            || alias_meta.file_type().is_symlink()
            || alias_meta.dev() != wrapper_meta.dev()
            || alias_meta.ino() != wrapper_meta.ino()
        {
            return Err(ApiError::internal(
                "trusted orgasmic wrapper retained identity mismatch",
            ));
        }
        (alias, wrapper_meta.dev(), wrapper_meta.ino())
    };
    #[cfg(unix)]
    let pinned = json!({
        "path": pin.target_path,
        "dev": pin.dev,
        "ino": pin.ino,
        "exec_wrapper": exec_wrapper,
        "exec_wrapper_dev": wrapper_dev,
        "exec_wrapper_ino": wrapper_ino,
    });
    #[cfg(not(unix))]
    let pinned = json!({
        "path": pin.target_path,
        "exec_wrapper": exec_wrapper,
    });
    let provider_home = if pin
        .entry_path
        .parent()
        .is_some_and(|parent| parent.ends_with(".local/bin"))
    {
        pin.entry_path
            .parent()
            .and_then(FsPath::parent)
            .and_then(FsPath::parent)
            .map(FsPath::to_path_buf)
    } else if home.root.file_name().and_then(|name| name.to_str()) == Some(".orgasmic") {
        home.root.parent().map(FsPath::to_path_buf)
    } else {
        // A daemon-local test/development binary has no provider layout of its
        // own. Anchor provider metadata to the same explicit Home instead of a
        // later process-global HOME lookup.
        home.root.parent().map(FsPath::to_path_buf)
    }
    .ok_or_else(|| ApiError::internal("trusted Claude provider home is unavailable"))?;
    Ok(json!({
        "trusted_provider_identity": "claude",
        "pinned_executable": pinned,
        "provider_home": provider_home,
    }))
}

/// Build immutable driver/harness fields for a pending recovery claim.
fn recovery_planned_driver_fields(
    state: &ApiState,
    action: &str,
    origin_envelopes: &[SessionEnvelope],
    origin_worktree: &FsPath,
    force_inert: bool,
) -> Result<(DriverConfig, Option<String>, String), ApiError> {
    let terminal_contract = persisted_terminal_contract_from_session(&state.home, origin_envelopes)
        .map_err(|err| ApiError::bad_request(err.to_string()))?;
    let native = session_native_runtime(origin_envelopes);
    if action == "resume_native_fork" {
        let native = native.ok_or_else(|| {
            ApiError::bad_request("resume_native_fork requires recorded native metadata")
        })?;
        let session_id =
            validated_claude_native_session_id(state.trusted_claude_binary.as_ref(), &native)
                .ok_or_else(|| {
                    ApiError::bad_request(
                        "recorded native metadata does not prove a trustworthy Claude session",
                    )
                })?;
        let (command, args) = reconstruct_claude_native_resume_command(
            state.trusted_claude_binary.as_ref(),
            &session_id,
        )
        .ok_or_else(|| {
            ApiError::bad_request("trusted Claude executable unavailable for native resume")
        })?;
        let pin = state
            .trusted_claude_binary
            .as_ref()
            .filter(|pin| pin.revalidate())
            .ok_or_else(|| {
                ApiError::bad_request("trusted Claude executable unavailable for native resume")
            })?;
        let execution = pinned_claude_execution_config(
            &state.home,
            pin,
            state.trusted_exec_wrapper.as_deref(),
        )?;
        let cfg = DriverConfig::from_value(json!({
            "command": command.to_string_lossy(),
            "args": args,
            "harness": "claude",
            "cwd": origin_worktree,
            "force_inert": force_inert,
            "native_resume_mode": true,
            "trusted_provider_identity": execution["trusted_provider_identity"].clone(),
            "pinned_executable": execution["pinned_executable"].clone(),
            "provider_home": execution["provider_home"].clone(),
        }));
        return Ok((cfg, Some("claude".into()), "tmux".into()));
    }
    let harness = terminal_contract
        .harness
        .clone()
        .or_else(|| native.as_ref().map(|n| n.provider.clone()))
        .or_else(|| recovery_harness_for_worker(&state.home, origin_envelopes))
        .unwrap_or_else(|| "claude".to_string());
    let cfg = if harness == "claude" {
        let pin = state
            .trusted_claude_binary
            .as_ref()
            .filter(|pin| pin.revalidate())
            .ok_or_else(|| {
                ApiError::bad_request("trusted Claude executable unavailable for recovery")
            })?;
        let execution = pinned_claude_execution_config(
            &state.home,
            pin,
            state.trusted_exec_wrapper.as_deref(),
        )?;
        DriverConfig::from_value(json!({
            "command": pin.target_path,
            "args": [],
            "harness": harness.clone(),
            "cwd": origin_worktree,
            "force_inert": force_inert,
            "trusted_provider_identity": execution["trusted_provider_identity"].clone(),
            "pinned_executable": execution["pinned_executable"].clone(),
            "provider_home": execution["provider_home"].clone(),
        }))
    } else {
        DriverConfig::from_value(json!({
            "harness": harness.clone(),
            "cwd": origin_worktree,
            "force_inert": force_inert,
        }))
    };
    Ok((cfg, Some(harness), "tmux".into()))
}

/// Mechanical recovery prompt (dec_052): prior run id, absolute prior session
/// JSONL path, a mechanical summary from the JSONL, the current diff stat, and
/// inspect-before-acting instructions. No model-generated summary.
fn build_recovery_prompt(
    prior_run_id: &str,
    prior_session_path: &std::path::Path,
    envelopes: &[SessionEnvelope],
    diff_stat: &str,
) -> String {
    let mut driver_events = 0usize;
    let mut tool_calls = 0usize;
    let mut last_assistant = String::new();
    for env in envelopes {
        if env.kind == SessionEventKind::DriverEvent {
            let ty = env.event.get("type").and_then(Value::as_str);
            // Heartbeats and pane-activity signals are liveness pings, not
            // work; counting them inflates the "driver events recorded" figure
            // on long quiet pane runs.
            if ty == Some("heartbeat") || ty == Some("pane_activity") {
                continue;
            }
            driver_events += 1;
            if let Some(ty) = ty {
                if ty == "tool_call" {
                    tool_calls += 1;
                }
                if ty == "text_chunk" {
                    if let Some(chunk) = env.event.get("chunk").and_then(Value::as_str) {
                        last_assistant = chunk.to_string();
                    }
                }
            }
        }
    }
    let last_excerpt: String = last_assistant.chars().take(280).collect();
    let diff_block = if diff_stat.trim().is_empty() {
        "(no uncommitted changes)".to_string()
    } else {
        diff_stat.trim().to_string()
    };
    format!(
        "You are recovering an interrupted orgasmic run. Inspect before acting; do not assume the prior run finished cleanly.\n\n\
Prior run id: {prior_run_id}\n\
Prior session JSONL (absolute): {prior_path}\n\n\
Mechanical summary (no model interpretation):\n\
- driver events recorded: {driver_events}\n\
- tool calls recorded: {tool_calls}\n\
- last assistant text excerpt: {last_excerpt}\n\n\
Current worktree diff stat:\n{diff_block}\n\n\
Instructions:\n\
1. Read the prior session JSONL at the absolute path above.\n\
2. Review the worktree diff before making any change.\n\
3. Only then continue the work; re-verify gates before declaring done.\n\
This prompt is staged in the composer and has NOT been sent. Send it yourself when ready.",
        prior_run_id = prior_run_id,
        prior_path = prior_session_path.display(),
        driver_events = driver_events,
        tool_calls = tool_calls,
        last_excerpt = last_excerpt,
        diff_block = diff_block,
    )
}

struct RecoveryOriginAuthority {
    project_root: PathBuf,
    worktree: PathBuf,
    sessions: SessionDirectory,
    origin_session: SessionFile,
    origin_envelopes: Vec<SessionEnvelope>,
}

/// Test-only fault injection for the window after `POST /runs/:id/recover` has
/// taken origin authority, keyed by the origin `run_id` it was armed for.
///
/// Same shape as `recovery_claim::PENDING_RECONCILE_AFTER_OPEN_HOOK`: the static
/// is shared by every test in this binary, and the site below is reached by
/// *every* `POST /runs/:id/recover` — a dozen-plus tests. An unkeyed hook is
/// consumed by whichever recover request arrives first, so the arming test sees
/// an unperturbed recovery while an unrelated test runs a closure written
/// against the arming test's tempdir. Keying makes the hook fire for exactly one
/// origin run, so arming is exclusive without serializing any test.
#[cfg(test)]
#[allow(clippy::type_complexity)]
static RECOVERY_POST_ORIGIN_AUTHORITY_HOOK: std::sync::Mutex<
    Option<(String, Box<dyn FnOnce() + Send>)>,
> = std::sync::Mutex::new(None);

/// Arm [`RECOVERY_POST_ORIGIN_AUTHORITY_HOOK`] for one origin `run_id`.
#[cfg(test)]
fn arm_recovery_post_origin_authority_hook(run_id: &str, hook: Box<dyn FnOnce() + Send>) {
    *RECOVERY_POST_ORIGIN_AUTHORITY_HOOK
        .lock()
        .expect("recovery origin authority hook lock") = Some((run_id.to_string(), hook));
}

/// Take the hook only when it was armed for `run_id`.
#[cfg(test)]
fn take_recovery_post_origin_authority_hook(run_id: &str) -> Option<Box<dyn FnOnce() + Send>> {
    let mut slot = RECOVERY_POST_ORIGIN_AUTHORITY_HOOK
        .lock()
        .expect("recovery origin authority hook lock");
    match slot.as_ref() {
        Some((armed_for, _)) if armed_for == run_id => slot.take().map(|(_, hook)| hook),
        _ => None,
    }
}

impl RecoveryOriginAuthority {
    fn envelopes(&self) -> Result<&[SessionEnvelope], ApiError> {
        self.origin_session.validate_current().map_err(|_| {
            ApiError::bad_request("origin session authority changed during recovery")
        })?;
        Ok(&self.origin_envelopes)
    }
}

async fn recovery_origin_authority(
    state: &ApiState,
    requested_project_id: &str,
    prior: &RecoveredRun,
) -> Result<RecoveryOriginAuthority, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(state, Some(requested_project_id)).await?;
    let matches: Vec<_> = snap
        .board
        .iter()
        .filter(|entry| entry.id == requested_project_id)
        .collect();
    let [entry] = matches.as_slice() else {
        return Err(ApiError::bad_request(
            "recovery project must name exactly one registered project",
        ));
    };
    let project_root = entry
        .path
        .canonicalize()
        .map_err(|_| ApiError::bad_request("registered recovery project root is unavailable"))?;
    let identity = read_existing_project_identity(&project_root.join(".orgasmic/project.org"))
        .map_err(|_| ApiError::bad_request("registered recovery project identity is invalid"))?;
    if identity.project_id != requested_project_id
        || prior.project_id.as_deref() != Some(requested_project_id)
        || prior.project_root.as_deref() != Some(project_root.as_path())
    {
        return Err(ApiError::bad_request(
            "origin session is not contained by the requested registered project",
        ));
    }
    let worktree = prior
        .worktree
        .as_ref()
        .ok_or_else(|| ApiError::bad_request("origin RunMeta worktree is required for recovery"))?
        .canonicalize()
        .map_err(|_| ApiError::bad_request("origin RunMeta worktree is unavailable"))?;
    let worktree_identity = read_existing_project_identity(&worktree.join(".orgasmic/project.org"))
        .map_err(|_| {
            ApiError::bad_request("origin RunMeta worktree project identity is invalid")
        })?;
    if worktree_identity.project_id != requested_project_id {
        return Err(ApiError::bad_request(
            "origin RunMeta worktree belongs to another project",
        ));
    }
    let sessions = SessionDirectory::open(&project_root).map_err(|_| {
        ApiError::bad_request("registered project sessions directory is unavailable")
    })?;
    let origin_session = sessions
        .open_path(&prior.session_path, false)
        .map_err(|_| {
            ApiError::bad_request(
                "origin session is not a direct regular file of the registered project",
            )
        })?;
    let origin_envelopes = origin_session
        .read_checked()
        .map_err(|_| ApiError::bad_request("origin session is unavailable"))?;
    Ok(RecoveryOriginAuthority {
        project_root,
        worktree,
        sessions,
        origin_session,
        origin_envelopes,
    })
}

/// The fourth manager rescue judgment from
/// `shipped/prompt-studio/conventions/rescue-policy.org`: end a run the manager
/// has decided not to rescue.
///
/// orgasmic:task_VSWZT — the other three judgments answer "how do we keep this
/// attempt going"; this one answers "this attempt is over". It is deliberately
/// a recovery action rather than a bare release verb: release stays the
/// daemon's act, and what the manager performs is a judgment that *results* in
/// a release carrying a tombstone that names the judgment.
pub(crate) const RECOVERY_ACTION_ABANDON: &str = "abandon";

/// The `Lifecycle::Release` reason an abandon writes. It names the judgment, so
/// a later reader of the session JSONL can tell a manager's decision from a
/// worker's finalize or a timeout sweep.
pub(crate) const ABANDON_RELEASE_REASON: &str = "manager rescue judgment: abandon";

/// What `abandon` says about a run the supervisor is not holding.
///
/// Deliberately not "run not found": the caller named a run, and the answer to
/// "is it live" is no. A run that already ended carries its own release
/// tombstone, so there is nothing mechanical left for abandon to do.
fn abandon_not_live_message(id: &str) -> String {
    format!(
        "run {id} is not live, so there is nothing to abandon — a run that has \
         already ended carries its own release tombstone. Record the abandon \
         judgment in tx instead."
    )
}

/// `POST /runs/:id/recover {"action":"abandon"}`.
///
/// orgasmic:task_VSWZT — the abandon judgment, and the only recovery action
/// whose subject is a **live** run. The other three resolve their subject out
/// of the crash-recovery inventory's `interrupted / reattached /
/// failed_recoverable / ambiguous` buckets, which by construction exclude
/// everything `GET /runs/live` reports; that is why a run the update fence
/// refused on had no recover action able to clear it. This one reads the same
/// supervisor the fence reads.
///
/// It creates no replacement run, so it takes no recovery claim and needs no
/// origin authority: there is no second run for a crash to strand.
///
/// It does not bypass the release path either. Abandon calls the same
/// `release_with_finalization` a worker finalize does, so a run whose drain is
/// wedged rides TASK-HAREX's `DrainGate` — bounded by `RELEASE_DRAIN_BUDGET` —
/// rather than being ripped out from under it.
async fn abandon_live_run(
    state: &ApiState,
    id: &str,
    req: &RunRecoverRequest,
) -> Result<Json<RunRecoverResponse>, ApiError> {
    let project_id = req
        .project
        .clone()
        .ok_or_else(|| ApiError::bad_request("project is required for recovery"))?;
    let run = state
        .supervisor
        .snapshot()
        .await
        .runs
        .iter()
        .find(|run| run.run_id == id)
        .cloned()
        .ok_or_else(|| ApiError::not_found(abandon_not_live_message(id)))?;
    // A recovery action is scoped to one registered project. A live run that
    // declares no project (manager/artifactor shapes) is not fenced out by a
    // project it never claimed.
    if let Some(owner) = run.project_id.as_deref() {
        if owner != project_id {
            return Err(ApiError::bad_request(format!(
                "run {id} belongs to project {owner}, not {project_id}"
            )));
        }
    }
    match state
        .supervisor
        .release_with_finalization(
            id,
            ABANDON_RELEASE_REASON,
            // Never Completed: rescue-policy's hard rule is that an abandoned
            // attempt is never recorded as success.
            ReleaseOutcome::Cancelled,
            false,
            None,
        )
        .await
    {
        Ok(()) => {}
        // orgasmic:TASK-ARZGD — an artifactor writer/regenerate ack owns the
        // record until it returns; the cancel is recorded now and the release
        // follows it. Same reading `post_run_release` gives this error.
        Err(crate::supervisor::SupervisorError::DeferredWhileInFlight(_)) => {}
        // orgasmic:TASK-RB1ZN — VSWZT answered both of these by re-reading the
        // supervisor snapshot after a `RunNotFound`, because `release_one` gave
        // both states the same error. That re-read describes a later instant
        // than the decision it is interpreting: the record can be removed
        // between the refusal and the snapshot, so a call refused because the
        // run was live and wedged can still be told the run is not live. It
        // lands on a defensible answer only because record removal is one-way —
        // an invariant it never states. The supervisor decides it under the same
        // lock as the action now, and this surface renders the two answers.
        Err(crate::supervisor::SupervisorError::ReleaseInProgress(_)) => {
            return Err(release_in_progress_conflict(id));
        }
        Err(crate::supervisor::SupervisorError::RunNotFound(_)) => {
            return Err(ApiError::not_found(abandon_not_live_message(id)));
        }
        Err(other) => return Err(supervisor_recover_error(other)),
    }
    Ok(Json(RunRecoverResponse {
        run_id: id.to_string(),
        runtime_id: run.identity.runtime_id.clone(),
        boot_id: run.identity.boot_id.clone(),
        session_path: run.session_path.clone(),
        action: RECOVERY_ACTION_ABANDON.to_string(),
        // Abandon opens no surface. The run it names is over.
        target: "none".to_string(),
        draft_prompt: None,
    }))
}

async fn post_run_recover(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Json(req): Json<RunRecoverRequest>,
) -> Result<Json<RunRecoverResponse>, ApiError> {
    // orgasmic:task_VSWZT — abandon is resolved before the inventory lookup
    // below, because its subject is a live run and the inventory's recoverable
    // buckets never contain one.
    if req.action.as_deref() == Some(RECOVERY_ACTION_ABANDON) {
        return abandon_live_run(&state, &id, &req).await;
    }
    let project_id = req
        .project
        .clone()
        .ok_or_else(|| ApiError::bad_request("project is required for recovery"))?;

    // A dispatch waiter must not declare this origin dead while any accepted
    // recovery path is inventorying authority, reconciling a prior claim,
    // planning a replacement, or publishing its durable lineage edge. This
    // guard deliberately starts before those paths diverge (including the
    // crash-reconciled fast returns) and is released only when this whole POST
    // returns; durable tx lineage takes over after a restart.
    let _generation_transition = state.recovery_generation_transitions.begin(id.clone());

    // Inventory never takes a per-origin lock. Recovery holds the global
    // status mutex only for the initial claim/index decision and, after
    // external work, the final RecoveryOrigin + claim commit.
    let claim_lock = state.recovery_claim_lock(&project_id, &id);
    let _claim_guard = claim_lock.lock().await;
    let status_guard = state.recovery_status_lock.lock().await;

    // orgasmic:TASK-2QK4P.1.1.1 F2 — ONE authority for the WHOLE POST, built
    // here and handed to the inventory classification below rather than created
    // inside it. The inventory pass enumerates this project to classify the run;
    // the claim branch further down needs the same enumeration; before this,
    // each built its own and the endpoint paid two full passes over the same
    // session files in one decision.
    let mut origin_links = ProjectOriginAuthority::default();
    let recovery =
        recovery_status_inner(&state, TerminalWindow::default(), &mut origin_links).await;
    let prior = recovery
        .interrupted_runs
        .iter()
        .chain(recovery.reattached_runs.iter())
        .chain(recovery.failed_recoverable_runs.iter())
        .chain(recovery.ambiguous_runs.iter())
        .find(|run| run.run_id == id && run.project_id.as_deref() == Some(project_id.as_str()))
        .cloned()
        .ok_or_else(|| ApiError::not_found(format!("recoverable run {id}")))?;
    let origin_authority = recovery_origin_authority(&state, &project_id, &prior).await?;
    #[cfg(test)]
    if let Some(hook) = take_recovery_post_origin_authority_hook(&id) {
        hook();
    }

    let failed_origin = prior.classification == "failed_recoverable";

    // orgasmic:TASK-2QK4P.1.1.1 F3 — AUTHORITY-INDEPENDENT REQUEST VALIDATION,
    // AHEAD OF THE REFUSAL. Whether the requested action exists for this record,
    // whether the caller had to name one, and whether a terminal Failed record
    // can be reattached are all decided from the record itself. Answering 503 to
    // any of them made a malformed request look retryable and silently become an
    // actionable 400/409 once some unrelated session file was repaired.
    //
    // `offered_actions` is the un-suppressed set: an enumeration that did not
    // complete empties `recovery_actions`, and validating against that empty
    // list would just move the same defect (an invalid action would answer "not
    // valid for this run" only because we could not look).
    //
    // An EMPTY offered set is deliberately not validated here. It has a third
    // meaning this check cannot serve: an authoritative committed claim
    // suppresses the actions, and that origin's recover request is an
    // IDEMPOTENT REPLAY which must answer with the existing replacement rather
    // than "that action is not valid for this run". The claim branch below owns
    // that case, and the empty-action arm of the resolver already consults it.
    let offered_actions = if prior.recovery_actions.is_empty() {
        prior.suppressed_recovery_actions.as_slice()
    } else {
        prior.recovery_actions.as_slice()
    };
    if !offered_actions.is_empty() {
        match req.action.as_deref() {
            Some(requested) => {
                if !offered_actions.iter().any(|act| act.kind == requested) {
                    return Err(ApiError::bad_request(format!(
                        "recovery action {requested} is not valid for run {id}"
                    )));
                }
                if failed_origin && requested == "reattach_tmux" {
                    return Err(ApiError::bad_request(
                        "reattach_tmux is not valid for terminal Failed records",
                    ));
                }
            }
            None => {
                if offered_actions.len() > 1 {
                    return Err(ApiError::conflict_json(json!({
                        "error": "multiple recovery actions; specify action",
                        "run_id": id,
                        "recovery_actions": offered_actions,
                    })));
                }
                if failed_origin
                    && matches!(offered_actions, [single] if single.kind == "reattach_tmux")
                {
                    return Err(ApiError::bad_request(
                        "reattach_tmux is not valid for terminal Failed records",
                    ));
                }
            }
        }
    }

    // orgasmic:TASK-2QK4P.1.1 F3 — refuse BEFORE the claim branch, not inside
    // it. The dangerous path is the one with NO claim on disk: it walks straight
    // to `plan_pending_recovery_claim` and mints a fresh replacement, and
    // "there is no authenticated replacement for this origin" is a statement
    // only a completed enumeration can make. An unresolved one must refuse, or
    // the new replacement lands beside whatever the unread file was holding.
    //
    // orgasmic:TASK-2QK4P.1.1.1 F3 — and it stays IMMEDIATELY before that
    // branch. Everything moved above this point decides nothing about authority;
    // everything below can mint it or accept it.
    if failed_origin {
        let unobserved = match origin_links.links_for(
            &state.home,
            &origin_authority.project_root,
            &project_id,
        ) {
            AuthoritativeOriginLinks::Unobserved(evidence) => Some(evidence.clone()),
            AuthoritativeOriginLinks::Complete(_) => None,
        };
        if let Some(evidence) = unobserved {
            // A swapped or symlinked ORIGIN session is one of the ways the
            // enumeration cannot complete, and it has its own, more specific
            // refusal. Report that one: "the origin you took authority over is
            // no longer the file you took it over" is actionable, while "the
            // enumeration did not complete" is not.
            origin_authority.envelopes()?;
            return Err(recovery_origins_unobserved(&id, &evidence));
        }
    }
    let request_id = req
        .request_id
        .clone()
        .filter(|id| !id.is_empty())
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    let mut pending_plan: Option<PendingRecoveryPlan> = None;
    if failed_origin {
        if let Some(claim) = load_recovery_claim(&state.home, &project_id, &id)
            .map_err(|err| recovery_claim_load_error(&id, err))?
        {
            match claim.status {
                RecoveryClaimStatus::Committed => {
                    match committed_claim_is_authoritative(
                        &state.home,
                        &origin_authority.project_root,
                        &project_id,
                        &id,
                        &mut origin_links,
                        &claim,
                    ) {
                        CommittedClaimAuthority::Unobserved(evidence) => {
                            return Err(recovery_origins_unobserved(&id, &evidence))
                        }
                        CommittedClaimAuthority::NotAuthoritative => {}
                        CommittedClaimAuthority::Authoritative => {
                            if claim.request_id == request_id {
                                // TASK-6AYEJ.3: this answers with a REPLACEMENT run
                                // id without running the recovery action, so it is
                                // one of the paths that used to hand the caller a
                                // live replacement with no ledger link at all.
                                record_recovery_replacement_association_from_claim(
                                    &state,
                                    req.project.as_deref(),
                                    &claim,
                                )
                                .await?;
                                return recovery_response_from_claim(&claim);
                            }
                            return Err(recovery_claim_conflict(&id, &claim));
                        }
                    }
                }
                RecoveryClaimStatus::Pending => {
                    if claim.request_id != request_id {
                        return Err(recovery_claim_conflict(&id, &claim));
                    }
                    let plan = reconcile_pending_claim(
                        &state.home,
                        &origin_authority.project_root,
                        &claim,
                    )
                    .map_err(|err| recovery_claim_reconcile_error(&id, err))?;
                    if let Some(plan) = plan {
                        if plan.claim.status == RecoveryClaimStatus::Committed {
                            match committed_claim_is_authoritative(
                                &state.home,
                                &origin_authority.project_root,
                                &project_id,
                                &id,
                                &mut origin_links,
                                &plan.claim,
                            ) {
                                CommittedClaimAuthority::Unobserved(evidence) => {
                                    return Err(recovery_origins_unobserved(&id, &evidence))
                                }
                                CommittedClaimAuthority::Authoritative => {
                                    // Same as above, reached one crash earlier:
                                    // the pending claim reconciled straight to
                                    // Committed.
                                    record_recovery_replacement_association_from_claim(
                                        &state,
                                        req.project.as_deref(),
                                        &plan.claim,
                                    )
                                    .await?;
                                    return recovery_response_from_claim(&plan.claim);
                                }
                                CommittedClaimAuthority::NotAuthoritative => {}
                            }
                        }
                        pending_plan = Some(plan);
                    }
                }
            }
        }
    }

    // Resolve the explicit action, or auto-pick when exactly one exists.
    let mut action = match req.action.clone() {
        Some(a) => {
            if !prior.recovery_actions.iter().any(|act| act.kind == a) {
                return Err(ApiError::bad_request(format!(
                    "recovery action {a} is not valid for run {id}"
                )));
            }
            a
        }
        None => match prior.recovery_actions.as_slice() {
            [single] => single.kind.clone(),
            [] => {
                if failed_origin {
                    if let Some(claim) =
                        load_committed_recovery_claim(&state.home, &project_id, &id)
                            .map_err(|err| recovery_claim_load_error(&id, err))?
                    {
                        match committed_claim_is_authoritative(
                            &state.home,
                            &origin_authority.project_root,
                            &project_id,
                            &id,
                            &mut origin_links,
                            &claim,
                        ) {
                            CommittedClaimAuthority::Unobserved(evidence) => {
                                return Err(recovery_origins_unobserved(&id, &evidence))
                            }
                            CommittedClaimAuthority::Authoritative => {
                                if claim.request_id == request_id {
                                    return recovery_response_from_claim(&claim);
                                }
                                return Err(recovery_claim_conflict(&id, &claim));
                            }
                            CommittedClaimAuthority::NotAuthoritative => {}
                        }
                    }
                }
                return Err(ApiError::not_found(format!(
                    "no recovery actions available for run {id}"
                )));
            }
            _ => {
                return Err(ApiError::conflict_json(json!({
                    "error": "multiple recovery actions; specify action",
                    "run_id": id,
                    "recovery_actions": prior.recovery_actions,
                })))
            }
        },
    };

    if let Some(plan) = pending_plan.as_ref() {
        if let Some(claimed_action) = plan.claim.action.as_deref() {
            if action != claimed_action {
                return Err(ApiError::conflict_json(json!({
                    "error": "recovery action does not match pending claim",
                    "origin_run_id": id,
                    "claimed_action": claimed_action,
                    "requested_action": action,
                })));
            }
            action = claimed_action.to_string();
        }
    }

    if failed_origin && action == "reattach_tmux" {
        return Err(ApiError::bad_request(
            "reattach_tmux is not valid for terminal Failed records",
        ));
    }

    let target = pending_plan
        .as_ref()
        .and_then(|plan| plan.claim.target.clone())
        .or_else(|| {
            prior
                .recovery_actions
                .iter()
                .find(|act| act.kind == action)
                .map(|act| act.target.clone())
        })
        .unwrap_or_else(|| "worker".to_string());

    let recovery_draft_prompt = {
        let envelopes = origin_authority.envelopes()?;
        let diff_stat = crate::supervisor::GitDiffSummarizer
            .summarize(Some(origin_authority.worktree.as_path()))
            .to_string();
        Some(build_recovery_prompt(
            &id,
            &prior.session_path,
            envelopes,
            &diff_stat,
        ))
    };

    if failed_origin && pending_plan.is_none() {
        let replacement_session_path = prior
            .session_path
            .parent()
            .map(|dir| dir.join(format!("recover-{}.jsonl", uuid::Uuid::new_v4())))
            .ok_or_else(|| ApiError::internal("origin session path has no parent"))?;
        let origin_envelopes = origin_authority.envelopes()?;
        let meta = session_acquire_meta(origin_envelopes);
        let terminal_contract =
            persisted_terminal_contract_from_session(&state.home, origin_envelopes)
                .map_err(|err| ApiError::bad_request(err.to_string()))?;
        let native = session_native_runtime(origin_envelopes);
        let force_inert = req.force_inert.unwrap_or(false);
        let worktree = Some(origin_authority.worktree.clone());
        let (driver_config, harness, transport) = recovery_planned_driver_fields(
            &state,
            &action,
            origin_envelopes,
            &origin_authority.worktree,
            force_inert,
        )?;
        let last_path =
            if terminal_contract.requires_worker_finalize {
                Some(terminal_contract.last_path.clone().unwrap_or_else(|| {
                    provision_recovery_last_path(&replacement_session_path, &id)
                }))
            } else {
                None
            };
        let stdout_path = if terminal_contract.requires_worker_finalize {
            terminal_contract.stdout_path.clone()
        } else {
            None
        };
        let kind = "worker".to_string();
        let spec = PendingRecoveryClaimSpec {
            project_id: project_id.clone(),
            origin_run_id: id.clone(),
            request_id: request_id.clone(),
            origin_session_path: prior.session_path.clone(),
            replacement_session_path,
            boot_id: state.boot.boot_id.clone(),
            action: action.clone(),
            target: target.clone(),
            draft_prompt: recovery_draft_prompt.clone(),
            force_inert,
            task_id: meta
                .as_ref()
                .map(|m| m.task_id.clone())
                .unwrap_or_else(|| format!("recover:{id}")),
            kind,
            worker_id: meta
                .as_ref()
                .map(|m| m.worker_id.clone())
                .unwrap_or_else(|| "manager".to_string()),
            role: terminal_contract.role.clone(),
            requires_worker_finalize: terminal_contract.requires_worker_finalize,
            transport,
            harness,
            driver_config: driver_config.0,
            worktree: worktree.clone(),
            last_path,
            stdout_path,
            planned_native_runtime: native.map(|n| orgasmic_drivers::NativeRuntimeMeta {
                provider: n.provider,
                session_id: n.session_id,
                session_path: None,
                launch_argv: vec![],
                credential_mode: None,
                resume_argv: n.resume_argv,
            }),
            run_options: RecoveryRunOptions {
                stall_timeout_secs: None,
                max_run_duration_secs: None,
                idle_timeout_secs: None,
                cleanup_on_failure: false,
            },
        };
        let mut plan =
            plan_pending_recovery_claim(&state.home, &spec).map_err(|err| match err {
                RecoveryClaimError::AlreadyClaimed(claim) => recovery_claim_conflict(&id, &claim),
                other => ApiError::internal(format!("recovery claim acquire failed: {other:?}")),
            })?;
        plan.session_file = Some(
            origin_authority
                .sessions
                .create_path(&plan.claim.replacement_session_path)
                .map_err(|err| {
                    ApiError::internal(format!(
                        "recovery replacement session authority failed: {err:?}"
                    ))
                })?,
        );
        pending_plan = Some(plan);
    }

    if failed_origin {
        if let Some(plan) = pending_plan.as_mut() {
            if plan.claim.status == RecoveryClaimStatus::Pending {
                plan.claim = mark_pending_recovery_spawn_started(&state.home, &project_id, &id)
                    .map_err(|err| {
                        ApiError::internal(format!(
                            "recovery planned-handle claim failed closed: {err:?}"
                        ))
                    })?;
            }
        }
    }

    // Driver recovery can wait on an external runtime. Pending claims are safe
    // for inventory to observe, so do not let that work hold the global status
    // lock and stall every GET /runs request.
    drop(status_guard);
    let execute = execute_run_recover_action(
        &state,
        &id,
        &prior,
        &action,
        &target,
        &req,
        pending_plan.as_ref(),
        origin_authority.envelopes()?,
    )
    .await;
    match execute {
        Ok(response) => {
            if failed_origin {
                // Publish the durable RecoveryOrigin link and committed claim
                // as one inventory-visible transition. GET /runs cannot build
                // an origin index between these two writes.
                let _status_guard = state.recovery_status_lock.lock().await;
                let mut claim_snapshot = pending_plan
                    .as_ref()
                    .map(|plan| plan.claim.clone())
                    .ok_or_else(|| ApiError::internal("failed recovery missing pending plan"))?;
                claim_snapshot.status = RecoveryClaimStatus::Committed;
                claim_snapshot.runtime_id = Some(response.runtime_id.clone());
                claim_snapshot.boot_id = Some(response.boot_id.clone());
                claim_snapshot.action = Some(response.action.clone());
                claim_snapshot.target = Some(response.target.clone());
                claim_snapshot.draft_prompt = response.draft_prompt.clone();
                let replacement_envelopes = pending_plan
                    .as_ref()
                    .and_then(|plan| plan.session_file.as_ref())
                    .ok_or_else(|| {
                        ApiError::internal("failed recovery missing replacement session authority")
                    })?
                    .read_checked()
                    .map_err(|err| {
                        ApiError::internal(format!(
                            "replacement session authority changed: {err:?}"
                        ))
                    })?;
                let origin_already_installed = replacement_envelopes.iter().any(|envelope| {
                    matches!(
                        serde_json::from_value::<Lifecycle>(envelope.event.clone()),
                        Ok(Lifecycle::RecoveryOrigin {
                            ref project_id,
                            ref origin_run_id,
                            ref request_id,
                            ref replacement_run_id,
                            ..
                        }) if project_id == &claim_snapshot.project_id
                            && origin_run_id == &claim_snapshot.origin_run_id
                            && request_id == &claim_snapshot.request_id
                            && replacement_run_id == &claim_snapshot.replacement_run_id
                    )
                });
                if !origin_already_installed {
                    state
                        .supervisor
                        .write_recovery_origin(
                            &response.run_id,
                            &response.session_path,
                            &RuntimeIdentity::planned(
                                response.run_id.clone(),
                                response.runtime_id.clone(),
                                response.boot_id.clone(),
                            ),
                            &project_id,
                            &id,
                            &prior.session_path,
                            &request_id,
                            &response.action,
                            &response.target,
                            Some(
                                serde_json::to_value(&claim_snapshot)
                                    .map_err(|err| ApiError::internal(err.to_string()))?,
                            ),
                        )
                        .await
                        .map_err(supervisor_recover_error)?;
                }
                commit_recovery_claim(
                    &state.home,
                    &project_id,
                    &id,
                    CommitRecoveryDetails {
                        runtime_id: response.runtime_id.clone(),
                        boot_id: response.boot_id.clone(),
                        action: response.action.clone(),
                        target: response.target.clone(),
                        draft_prompt: response.draft_prompt.clone(),
                    },
                )
                .map_err(|err| {
                    ApiError::internal(format!("recovery claim commit failed: {err:?}"))
                })?;
                crate::recovery_claim::recovery_failpoint("response");
            }
            Ok(Json(response))
        }
        Err(err) => Err(err),
    }
}

#[allow(clippy::too_many_arguments)]
async fn execute_run_recover_action(
    state: &ApiState,
    id: &str,
    prior: &RecoveredRun,
    action: &str,
    target: &str,
    req: &RunRecoverRequest,
    pending_plan: Option<&PendingRecoveryPlan>,
    origin_envelopes: &[SessionEnvelope],
) -> Result<RunRecoverResponse, ApiError> {
    let envelopes = origin_envelopes;
    let meta = session_acquire_meta(envelopes);
    let force_inert = pending_plan
        .and_then(|p| p.claim.force_inert)
        .unwrap_or_else(|| req.force_inert.unwrap_or(false));
    let recovery_run_options = pending_plan
        .and_then(|plan| plan.claim.run_options.clone())
        .unwrap_or_default();
    let worker_id = pending_plan
        .and_then(|p| p.claim.worker_id.clone())
        .or_else(|| meta.as_ref().map(|m| m.worker_id.clone()))
        .unwrap_or_else(|| "manager".to_string());
    let run_kind = pending_plan
        .and_then(|p| p.claim.kind.as_deref().map(run_kind_from_lifecycle))
        .flatten()
        .or_else(|| meta.as_ref().map(|m| m.kind))
        .unwrap_or(RunKind::Worker);
    let worktree = pending_plan
        .and_then(|p| p.claim.worktree.clone())
        .or_else(|| prior.worktree.clone())
        .ok_or_else(|| ApiError::bad_request("origin RunMeta worktree is required for recovery"))?;

    // Shared terminal contract for every recovery entry (TASK-ARZGD P2).
    let terminal_contract = if let Some(plan) = pending_plan {
        PersistedTerminalContract {
            role: plan.claim.role.clone().unwrap_or_else(|| "worker".into()),
            requires_worker_finalize: plan.claim.requires_worker_finalize.unwrap_or(true),
            last_path: plan.claim.last_path.clone(),
            stdout_path: plan.claim.stdout_path.clone(),
            harness: plan.claim.harness.clone(),
        }
    } else {
        persisted_terminal_contract_from_session(&state.home, envelopes)
            .map_err(|err| ApiError::bad_request(err.to_string()))?
    };

    match action {
        "reattach_tmux" => {
            let (driver, _meta) = recovery_driver(&state.home, envelopes).ok_or_else(|| {
                ApiError::internal("recovered run has no recoverable driver identity")
            })?;
            let identity = RuntimeIdentity {
                run_id: prior.run_id.clone(),
                runtime_id: prior.runtime_id.clone(),
                boot_id: prior.boot_id.clone(),
            };
            let acquire = state
                .supervisor
                .reattach(
                    driver.as_ref(),
                    identity,
                    run_kind,
                    meta.as_ref()
                        .map(|m| m.task_id.clone())
                        .unwrap_or_else(|| format!("recover:{id}")),
                    worker_id.clone(),
                    terminal_contract.role.clone(),
                    terminal_contract.requires_worker_finalize,
                    req.project.clone(),
                    Some(worktree.clone()),
                    prior.session_path.clone(),
                    DriverConfig::from_value(json!({
                        "force_inert": force_inert,
                    })),
                    true,
                    None,
                )
                .await
                .map_err(supervisor_recover_error)?;
            // Reattach attaches as-is and leaves the composer empty (dec_052).
            // Force the inherited contract even when artifact paths are absent.
            state
                .supervisor
                .restore_terminal_contract(
                    &acquire.run_id,
                    terminal_contract.role,
                    terminal_contract.requires_worker_finalize,
                )
                .await;
            Ok(RunRecoverResponse {
                run_id: acquire.run_id,
                runtime_id: acquire.identity.runtime_id,
                boot_id: acquire.identity.boot_id,
                session_path: prior.session_path.clone(),
                action: action.to_string(),
                target: target.to_string(),
                draft_prompt: None,
            })
        }
        "resume_native_fork" | "start_recovery_run" => {
            let native = session_native_runtime(envelopes);
            let diff_stat = crate::supervisor::GitDiffSummarizer
                .summarize(Some(worktree.as_path()))
                .to_string();
            let prompt = pending_plan
                .and_then(|plan| plan.claim.draft_prompt.clone())
                .unwrap_or_else(|| {
                    build_recovery_prompt(id, &prior.session_path, envelopes, &diff_stat)
                });

            let recover_name = pending_plan
                .and_then(|plan| {
                    plan.claim
                        .replacement_session_path
                        .file_name()
                        .and_then(|name| name.to_str())
                        .map(str::to_string)
                })
                .unwrap_or_else(|| format!("recover-{}.jsonl", uuid::Uuid::new_v4()));
            let session_path = pending_plan
                .map(|plan| plan.claim.replacement_session_path.clone())
                .or_else(|| {
                    prior
                        .session_path
                        .parent()
                        .map(|dir| dir.join(&recover_name))
                })
                .unwrap_or_else(|| state.home.sessions().join(&recover_name));
            let planned_identity = pending_plan.map(|plan| plan.planned_identity.clone());

            let (driver, driver_config) = if let Some(plan) = pending_plan {
                if let Some(cfg) = plan.claim.driver_config.clone() {
                    if action == "resume_native_fork" {
                        let planned_native =
                            plan.claim.planned_native_runtime.as_ref().ok_or_else(|| {
                                ApiError::bad_request(
                                    "pending native recovery plan is missing native identity",
                                )
                            })?;
                        let planned = SessionNativeRuntime {
                            provider: planned_native.provider.clone(),
                            session_id: planned_native.session_id.clone(),
                            resume_argv: planned_native.resume_argv.clone(),
                        };
                        let session_id = validated_claude_native_session_id(
                            state.trusted_claude_binary.as_ref(),
                            &planned,
                        )
                        .ok_or_else(|| {
                            ApiError::bad_request(
                                "trusted Claude identity changed after recovery plan was pinned",
                            )
                        })?;
                        let (command, args) = reconstruct_claude_native_resume_command(
                            state.trusted_claude_binary.as_ref(),
                            &session_id,
                        )
                        .ok_or_else(|| {
                            ApiError::bad_request(
                                "trusted Claude executable unavailable for pending recovery",
                            )
                        })?;
                        let pin = state
                            .trusted_claude_binary
                            .as_ref()
                            .filter(|pin| pin.revalidate())
                            .ok_or_else(|| {
                                ApiError::bad_request(
                                    "trusted Claude executable unavailable for pending recovery",
                                )
                            })?;
                        let execution = pinned_claude_execution_config(
                            &state.home,
                            pin,
                            state.trusted_exec_wrapper.as_deref(),
                        )?;
                        if cfg.get("command").and_then(Value::as_str)
                            != Some(command.to_string_lossy().as_ref())
                            || cfg.get("args")
                                != Some(&serde_json::to_value(&args).map_err(|err| {
                                    ApiError::internal(format!(
                                        "native recovery argv serialization failed: {err}"
                                    ))
                                })?)
                            || cfg.get("trusted_provider_identity")
                                != execution.get("trusted_provider_identity")
                            || cfg.get("pinned_executable") != execution.get("pinned_executable")
                            || cfg.get("provider_home") != execution.get("provider_home")
                        {
                            return Err(ApiError::bad_request(
                                "pending native recovery executable plan no longer matches daemon authority",
                            ));
                        }
                    }
                    let harness = plan.claim.harness.as_deref().unwrap_or("claude");
                    let driver = resolve_driver("tmux", harness)
                        .or_else(|| resolve_driver("tmux", "claude"))
                        .ok_or_else(|| {
                            ApiError::internal("tmux driver unavailable for recovery run")
                        })?;
                    (driver, DriverConfig::from_value(cfg))
                } else {
                    let (cfg, _, _) = recovery_planned_driver_fields(
                        state,
                        action,
                        envelopes,
                        &worktree,
                        force_inert,
                    )?;
                    let harness = cfg
                        .0
                        .get("harness")
                        .and_then(|v| v.as_str())
                        .unwrap_or("claude");
                    let driver = resolve_driver("tmux", harness)
                        .or_else(|| resolve_driver("tmux", "claude"))
                        .ok_or_else(|| {
                            ApiError::internal("tmux driver unavailable for recovery run")
                        })?;
                    (driver, cfg)
                }
            } else if action == "resume_native_fork" {
                let native = native.ok_or_else(|| {
                    ApiError::bad_request("resume_native_fork requires recorded native metadata")
                })?;
                let session_id = validated_claude_native_session_id(
                    state.trusted_claude_binary.as_ref(),
                    &native,
                )
                .ok_or_else(|| {
                    ApiError::bad_request(
                        "recorded native metadata does not prove a trustworthy Claude session",
                    )
                })?;
                let (command, args) = reconstruct_claude_native_resume_command(
                    state.trusted_claude_binary.as_ref(),
                    &session_id,
                )
                .ok_or_else(|| {
                    ApiError::bad_request("trusted Claude executable unavailable for native resume")
                })?;
                let pin = state
                    .trusted_claude_binary
                    .as_ref()
                    .filter(|pin| pin.revalidate())
                    .ok_or_else(|| {
                        ApiError::bad_request(
                            "trusted Claude executable unavailable for native resume",
                        )
                    })?;
                let execution = pinned_claude_execution_config(
                    &state.home,
                    pin,
                    state.trusted_exec_wrapper.as_deref(),
                )?;
                let driver = resolve_driver("tmux", "claude").ok_or_else(|| {
                    ApiError::internal("tmux/claude driver unavailable for native resume")
                })?;
                let cfg = DriverConfig::from_value(json!({
                    "command": command.to_string_lossy(),
                    "args": args,
                    "harness": "claude",
                    "cwd": &worktree,
                    "force_inert": force_inert,
                    "native_resume_mode": true,
                    "trusted_provider_identity": execution["trusted_provider_identity"].clone(),
                    "pinned_executable": execution["pinned_executable"].clone(),
                    "provider_home": execution["provider_home"].clone(),
                }));
                (driver, cfg)
            } else {
                let harness = terminal_contract
                    .harness
                    .clone()
                    .or_else(|| terminal_contract.harness.clone())
                    .or_else(|| native.as_ref().map(|n| n.provider.clone()))
                    .or_else(|| {
                        meta.as_ref()
                            .and_then(|_| recovery_harness_for_worker(&state.home, envelopes))
                    })
                    .ok_or_else(|| {
                        ApiError::bad_request(
                            "recovery address unavailable; supply mode+harness/start fresh",
                        )
                    })?;
                let mode = req
                    .mode
                    .clone()
                    .or_else(|| persisted_run_address_from_session(envelopes).map(|(mode, _)| mode))
                    .ok_or_else(|| {
                        ApiError::bad_request(
                            "recovery address unavailable; supply mode+harness/start fresh",
                        )
                    })?;
                let driver = resolve_persisted_run_driver(&mode, &harness).ok_or_else(|| {
                    ApiError::bad_request(format!(
                        "unsupported recovery mode/harness pair {mode}/{harness}"
                    ))
                })?;
                let cfg = DriverConfig::from_value(json!({
                    "transport": mode,
                    "harness": harness,
                    "cwd": &worktree,
                    "force_inert": force_inert,
                }));
                (driver, cfg)
            };

            let last_path = pending_plan
                .and_then(|p| p.claim.last_path.clone())
                .or_else(|| {
                    if terminal_contract.requires_worker_finalize {
                        Some(
                            terminal_contract
                                .last_path
                                .clone()
                                .unwrap_or_else(|| provision_recovery_last_path(&session_path, id)),
                        )
                    } else {
                        None
                    }
                });
            let stdout_path = pending_plan
                .and_then(|p| p.claim.stdout_path.clone())
                .or_else(|| {
                    if terminal_contract.requires_worker_finalize {
                        terminal_contract.stdout_path.clone()
                    } else {
                        None
                    }
                });
            let task_id = pending_plan
                .and_then(|p| p.claim.task_id.clone())
                .or_else(|| {
                    meta.as_ref()
                        .map(|m| m.task_id.clone())
                        .or_else(|| Some(format!("recover:{id}")))
                })
                .unwrap_or_else(|| format!("recover:{id}"));
            let reattach_existing = pending_plan.is_some_and(|plan| plan.reattach_existing);
            // Kept for the replacement-generation association below, which
            // needs them after `acquire_request` has taken ownership.
            let association_task_id = task_id.clone();
            let association_role = terminal_contract.role.clone();

            let acquire = if reattach_existing {
                let plan = pending_plan.ok_or_else(|| {
                    ApiError::internal("reattach recovery is missing immutable pending plan")
                })?;
                let identity = plan.planned_identity.clone();
                let acquire = if let Some(existing) = state
                    .supervisor
                    .recovery_run_if_exact(&identity, &session_path, &plan.claim.project_id)
                    .await
                {
                    existing
                } else {
                    state
                        .supervisor
                        .reattach(
                            driver.as_ref(),
                            identity,
                            run_kind,
                            task_id.clone(),
                            worker_id.clone(),
                            terminal_contract.role.clone(),
                            terminal_contract.requires_worker_finalize,
                            req.project.clone(),
                            Some(worktree.clone()),
                            session_path.clone(),
                            driver_config.clone(),
                            false,
                            Some(RecoveryReattachPlan {
                                claim: plan.claim.clone(),
                                last_path: last_path.clone(),
                                stdout_path: stdout_path.clone(),
                                native_runtime: plan.claim.planned_native_runtime.clone(),
                                prompt_draft: prompt.clone(),
                                session_file: plan.session_file.clone(),
                            }),
                        )
                        .await
                        .map_err(supervisor_recover_error)?
                };
                state
                    .supervisor
                    .restore_recovery_run_options(
                        &acquire.run_id,
                        recovery_run_options.stall_timeout_secs,
                        recovery_run_options.max_run_duration_secs,
                        recovery_run_options.idle_timeout_secs,
                    )
                    .await;
                acquire
            } else {
                let acquire_request = AcquireRequest {
                    task_id,
                    kind: run_kind,
                    role: terminal_contract.role.clone(),
                    worker_id,
                    project_id: req.project.clone(),
                    worktree: Some(worktree),
                    last_path,
                    stdout_path,
                    dispatch_attempt_token: None,
                    session_path: session_path.clone(),
                    driver_config,
                    stall_timeout_secs: recovery_run_options.stall_timeout_secs,
                    max_run_duration_secs: recovery_run_options.max_run_duration_secs,
                    idle_timeout_secs: recovery_run_options.idle_timeout_secs,
                    applicable_states: Vec::new(),
                    max_iterations: None,
                    planned_identity,
                };
                if let Some(plan) = pending_plan {
                    state
                        .supervisor
                        .acquire_recovery(
                            driver.as_ref(),
                            acquire_request,
                            RecoveryReattachPlan {
                                claim: plan.claim.clone(),
                                last_path: plan.claim.last_path.clone(),
                                stdout_path: plan.claim.stdout_path.clone(),
                                native_runtime: plan.claim.planned_native_runtime.clone(),
                                prompt_draft: prompt.clone(),
                                session_file: plan.session_file.clone(),
                            },
                        )
                        .await
                        .map_err(supervisor_recover_error)?
                } else {
                    state
                        .supervisor
                        .acquire(driver.as_ref(), acquire_request)
                        .await
                        .map_err(supervisor_recover_error)?
                }
            };

            state
                .supervisor
                .restore_terminal_contract(
                    &acquire.run_id,
                    terminal_contract.role.clone(),
                    terminal_contract.requires_worker_finalize,
                )
                .await;

            if !reattach_existing && pending_plan.is_none() {
                state
                    .supervisor
                    .append_prompt_draft(&acquire.run_id, &session_path, &acquire.identity, &prompt)
                    .await
                    .map_err(supervisor_recover_error)?;
            }

            // The replacement now has a live pane/session, but that fresh run
            // is not yet in the durable dispatch lineage. A crash exactly
            // here is covered by the signed, spawn-started pending claim: on
            // restart `dispatch-wait` verifies the live planned handle and
            // returns waiting until this association is replayed. Keep an
            // explicit crash boundary for the real restart regression test.
            crate::recovery_claim::recovery_failpoint("association_pending");

            record_recovery_replacement_association(
                state,
                req.project.as_deref(),
                id,
                &acquire.run_id,
                &association_task_id,
                &association_role,
                action,
                terminal_contract.requires_worker_finalize,
            )
            .await?;

            Ok(RunRecoverResponse {
                run_id: acquire.run_id,
                runtime_id: acquire.identity.runtime_id,
                boot_id: pending_plan
                    .and_then(|p| p.claim.boot_id.clone())
                    .unwrap_or(acquire.identity.boot_id),
                session_path,
                action: action.to_string(),
                target: target.to_string(),
                draft_prompt: Some(prompt),
            })
        }
        other => Err(ApiError::bad_request(format!(
            "unknown recovery action {other}"
        ))),
    }
}

async fn recovery_status(state: &ApiState) -> RecoveryResponse {
    let _status_guard = state.recovery_status_lock.lock().await;
    recovery_status_inner(
        state,
        TerminalWindow::default(),
        &mut ProjectOriginAuthority::default(),
    )
    .await
}

/// How much terminal history one inventory response carries.
///
/// orgasmic:TASK-FZB6T item 2 — actionable records (live, recoverable,
/// ambiguous) are always served in full; bounding those would hide work.
/// Terminal history only grows, is never re-decided, and is what makes a
/// response size a function of a board's whole past. It is therefore a bounded,
/// explicitly pageable window.
#[derive(Debug, Clone, Copy)]
struct TerminalWindow {
    limit: usize,
    offset: usize,
}

impl Default for TerminalWindow {
    fn default() -> Self {
        Self {
            limit: crate::run_catalog::DEFAULT_TERMINAL_WINDOW,
            offset: 0,
        }
    }
}

impl TerminalWindow {
    /// Every terminal record. The exact-id lookup and the tests that compare a
    /// whole board's classifications use it; no request handler does.
    fn unbounded() -> Self {
        Self {
            limit: usize::MAX,
            offset: 0,
        }
    }
}

#[derive(Debug, Default, Deserialize)]
pub struct RunInventoryQuery {
    /// Terminal records to return, newest first. Capped at
    /// [`crate::run_catalog::MAX_TERMINAL_WINDOW`].
    #[serde(default)]
    terminal_limit: Option<usize>,
    /// Terminal records to skip, for paging older history.
    #[serde(default)]
    terminal_offset: Option<usize>,
    /// `all` returns every terminal record — the explicit query the body
    /// reserves for older history.
    #[serde(default)]
    terminal: Option<String>,
}

impl From<RunInventoryQuery> for TerminalWindow {
    fn from(query: RunInventoryQuery) -> Self {
        let all = query
            .terminal
            .as_deref()
            .is_some_and(|value| value.eq_ignore_ascii_case("all"));
        let limit = if all {
            usize::MAX
        } else {
            query
                .terminal_limit
                .unwrap_or(crate::run_catalog::DEFAULT_TERMINAL_WINDOW)
                .min(crate::run_catalog::MAX_TERMINAL_WINDOW)
        };
        Self {
            limit,
            offset: query.terminal_offset.unwrap_or(0),
        }
    }
}

/// orgasmic:TASK-2QK4P.1.1.1 F2 — the authority is a PARAMETER, not a local.
///
/// `post_run_recover` calls this to classify the run it was handed, and this
/// function enumerated every failed-recoverable run's project to do it. The
/// handler then dropped that authority on the floor and built a second one for
/// the claim decision, so one POST paid roughly two full passes over the same
/// session files inside a single decision — and the second pass was not
/// represented in the inventory metrics at all. Taking the authority from the
/// caller makes the sharing the type system's business: there is no local left
/// to forget to reuse, and `cost()` now totals every pass the decision made.
async fn recovery_status_inner(
    state: &ApiState,
    window: TerminalWindow,
    origin_authority: &mut ProjectOriginAuthority,
) -> RecoveryResponse {
    let started = std::time::Instant::now();
    let live = state.supervisor.snapshot().await;
    let live_ids: BTreeSet<_> = live.runs.iter().map(|run| run.run_id.as_str()).collect();
    let board = state.index.snapshot().await.board;
    let project_roots: Vec<PathBuf> = board.iter().map(|entry| entry.path.clone()).collect();
    let (recovered, mut metrics) = classify_session_files(
        &state.home,
        state.trusted_claude_binary.as_ref(),
        &state.boot.boot_id,
        &live.runs,
        &project_roots,
        &state.run_catalog,
        Some(&state.writer),
        window,
    )
    .await;
    let mut interrupted_runs = Vec::new();
    let mut reattached_runs = Vec::new();
    let mut failed_recoverable_runs = Vec::new();
    let mut terminal_noop_runs = Vec::new();
    let mut ambiguous_runs = Vec::new();
    // Recovery-origin indexing is a per-project session scan. Rebuilding it once
    // per failed tombstone made GET /runs O(failed_runs * session_bytes) and
    // effectively unbounded on projects with large transcripts, so ONE authority
    // serves this whole pass (orgasmic:TASK-2QK4P.1.1 F4).
    //
    // orgasmic:TASK-FZB6T.1 finding 3 was closed by deriving the candidate files
    // from the run catalog, and that is exactly what TASK-2QK4P.1 had to undo:
    // the catalog drops a record on every lifecycle append, so it cannot state
    // what it has not looked at, and authority over a lease may not be decided
    // from a set that cannot. What survives of FZB6T.1's property is the part
    // that was really doing the work — a board with no failed-recoverable run
    // opens no session file at all, because `ProjectOriginAuthority` enumerates
    // lazily and only for the projects a claim decision actually reaches.
    for mut run in recovered {
        if live_ids.contains(run.run_id.as_str()) {
            continue;
        }
        if run.classification == "failed_recoverable" && run.project_id.is_some() {
            apply_recovery_claim_to_run(&state.home, origin_authority, &mut run);
        }
        match run.classification.as_str() {
            "interrupted" => interrupted_runs.push(run),
            "reattached" => reattached_runs.push(run),
            "failed_recoverable" => failed_recoverable_runs.push(run),
            "terminal_noop" => terminal_noop_runs.push(run),
            _ => ambiguous_runs.push(run),
        }
    }
    // orgasmic:TASK-FZB6T item 2 — the terminal window is bounded, newest
    // first, so the default response answers "what just ended" and older
    // history is reached by an explicit page rather than by making every poll
    // carry the whole board.
    //
    // orgasmic:TASK-FZB6T.1 finding 3 — the bound is now applied by
    // `classify_session_files`, BEFORE classification, so the records outside
    // the window cost a comparison rather than a classification. All that is
    // left here is presenting them in the response's order; `terminal_total`
    // and `terminal_returned` were both set by the pass that decided them.
    terminal_noop_runs.sort_by(|a, b| {
        b.terminal_at
            .cmp(&a.terminal_at)
            .then(a.run_id.cmp(&b.run_id))
    });

    let origin_cost = origin_authority.cost();
    metrics.origin_index_files = origin_cost.files;
    metrics.origin_index_bytes_inspected = origin_cost.bytes_inspected;
    metrics.interrupted = interrupted_runs.len() as u64;
    metrics.reattached = reattached_runs.len() as u64;
    metrics.failed_recoverable = failed_recoverable_runs.len() as u64;
    metrics.terminal_noop = terminal_noop_runs.len() as u64;
    metrics.ambiguous = ambiguous_runs.len() as u64;
    metrics.duration_ms = started.elapsed().as_millis() as u64;
    // Counts and byte totals only: no session paths, transcript text, prompts,
    // or harness credential material may reach the log.
    tracing::debug!(
        session_files = metrics.session_files,
        session_file_bytes = metrics.session_file_bytes,
        bytes_inspected = metrics.bytes_inspected,
        truncated_scans = metrics.truncated_scans,
        unreadable_sessions = metrics.unreadable_sessions,
        attach_probes_started = metrics.attach_probes_started,
        attach_probes_timed_out = metrics.attach_probes_timed_out,
        origin_index_files = metrics.origin_index_files,
        origin_index_bytes_inspected = metrics.origin_index_bytes_inspected,
        interrupted = metrics.interrupted,
        reattached = metrics.reattached,
        failed_recoverable = metrics.failed_recoverable,
        terminal_noop = metrics.terminal_noop,
        ambiguous = metrics.ambiguous,
        duration_ms = metrics.duration_ms,
        "run inventory pass complete"
    );
    RecoveryResponse {
        boot_id: state.boot.boot_id.clone(),
        acquisition_paused: live.acquisition_paused,
        live_runs: live.runs,
        interrupted_runs,
        reattached_runs,
        failed_recoverable_runs,
        terminal_noop_runs,
        ambiguous_runs,
        inventory: Some(metrics),
        lost_release_finalizations: state.release_tasks.lost_finalizations(),
        note: "boot reconciliation classifies durable session JSONL without restoring snapshots or mutating graph state",
    }
}

/// Reattach material reconstructed from a non-terminal run's session JSONL.
struct BootReattachCandidate {
    run_id: String,
    runtime_id: String,
    boot_id: String,
    task_id: String,
    kind: RunKind,
    worker_id: String,
    transport: String,
    harness: Option<String>,
    project_id: Option<String>,
    worktree: Option<PathBuf>,
    /// Dispatch artifact paths, when the reattached run was a CLI dispatch —
    /// enables respawning its completion watcher (TASK-567JG).
    last_path: Option<PathBuf>,
    stdout_path: Option<PathBuf>,
    dispatch_attempt_token: Option<String>,
    role: Option<String>,
    requires_worker_finalize: Option<bool>,
    /// The stage this run was launched as, when it was a `grill`/`plan`
    /// launch — enables respawning its stage completion watcher (TASK-KPMFK).
    /// `None` for every non-stage run and for session JSONL written before the
    /// stage identity was durable.
    stage: Option<String>,
    driver_config: serde_json::Value,
    session_path: PathBuf,
}

/// `(transport, harness, project_id, worktree, last_path, stdout_path,
/// dispatch_attempt_token, role, requires_worker_finalize, driver_config)` from a
/// `RunMeta` lifecycle event.
type RunMetaFields = (
    String,
    Option<String>,
    Option<String>,
    Option<PathBuf>,
    Option<PathBuf>,
    Option<PathBuf>,
    Option<String>,
    Option<String>,
    Option<bool>,
    serde_json::Value,
);

/// Extract a [`BootReattachCandidate`] from a bounded lifecycle scan of a
/// session JSONL if the run is non-terminal and carries both an `Acquire` and a
/// `RunMeta` lifecycle event. Returns `None` for terminal runs, runs missing
/// the metadata (pre-`RunMeta`
/// sessions), and scans whose unread middle makes the answer unprovable.
///
/// orgasmic:TASK-7QM8M — the input is a [`SessionLifecycleScan`], not whole-file
/// envelopes, so the boot pass costs bounded bytes per session file instead of
/// transcript size. Everything this function consumes (`Acquire`, `RunMeta`,
/// `StageMeta`, `Release`, the terminal driver events, and the external
/// registration marker) is in the scanner's retained set: it keeps every
/// non-`driver_event` line and the four lifecycle driver event types.
fn boot_reattach_candidate(
    entry: &crate::run_catalog::RunCatalogEntry,
) -> Option<BootReattachCandidate> {
    let session_path = entry.session_path.as_path();
    // The catalog already segmented this file: `lifecycle_envelopes` is the
    // newest contiguous run segment by `run_id`, the same
    // `latest_run_segment` recovery of a second-granularity manager file the
    // pre-catalog reader performed on every read.
    let envelopes = entry.lifecycle_envelopes.as_slice();
    let first = envelopes.first()?;
    // orgasmic:TASK-7QM8M — a truncated scan read a prefix and a tail with an
    // unread gap between them, and two rules keep that gap from inventing a
    // candidate. Both are no-ops on a whole-file scan. They live here, on the
    // catalog entry, because the entry is now what reattach reads: a guard that
    // only ran on a fresh scan would be silently skipped by every cache hit.
    if entry.scan_truncated {
        // 1. The gap can hold this run's release AND a later run's acquire, so
        //    the newest RETAINED segment is not provably the newest segment on
        //    disk: pairing a prefix run's `Acquire`/`RunMeta` with the file's
        //    end would reattach a run that already released, and would do it
        //    under the wrong identity. The final line names the run that owns
        //    the end of the file even when that line was dropped as transcript
        //    — which is the normal shape for a live TUI run — so require it to
        //    be this segment's run. When it is not, the live run's own metadata
        //    sits in the gap and no candidate is provable from this file.
        if entry.final_line_run_id.as_deref() != Some(first.run_id.as_str()) {
            tracing::info!(
                session_path = %session_path.display(),
                segment_run_id = %first.run_id,
                final_line_run_id = ?entry.final_line_run_id,
                "boot reattach: truncated scan's newest retained segment does not \
                 own the end of the file; skipped rather than combined"
            );
            return None;
        }
        // 2. `latest_run_segment` segments on `run_id` alone, which cannot see
        //    a boundary the gap hides: a second-granularity manager file could
        //    append two runtimes under one run id, and combining the prefix
        //    runtime's acquire with the tail runtime's end is exactly the
        //    misattribution this scan must not introduce. `boot_id` is
        //    deliberately not part of this — a run reattached across daemon
        //    restarts keeps its runtime, and refusing on boot id would decline
        //    live runs for no evidence.
        if let Some(other) = envelopes
            .iter()
            .find(|envelope| envelope.runtime_id != first.runtime_id)
        {
            tracing::info!(
                session_path = %session_path.display(),
                run_id = %first.run_id,
                runtime_id = %first.runtime_id,
                other_runtime_id = %other.runtime_id,
                "boot reattach: truncated scan retained two runtimes under one run \
                 id; skipped rather than combined"
            );
            return None;
        }
    }
    // Skip terminal runs.
    //
    // orgasmic:TASK-7QM8M — only the file's genuine final envelope can prove a
    // terminal release; when the scan dropped that line as transcript, the
    // newest retained lifecycle line is not the end of the run and treating it
    // as terminal would refuse to reattach a run that is still writing. Both
    // inputs are decided once, at index time.
    //
    // The rule is deliberately NOT `entry.terminal`: reattach and the inventory
    // classifier differ on an `Interrupted` release, and always have. The
    // classifier stops there and calls the run recoverable; reattach falls
    // through to the terminal driver events, because a run whose driver already
    // said `run_complete` has no live runtime to reattach to whatever its
    // release line says. `run_catalog` keeps the two raw facts separate so this
    // asymmetry stays visible instead of being silently normalized away.
    let terminal = match entry.final_release_outcome {
        Some(ReleaseOutcome::Completed)
        | Some(ReleaseOutcome::Failed)
        | Some(ReleaseOutcome::Cancelled) => true,
        Some(ReleaseOutcome::Interrupted) | None => entry.driver_terminal_event.is_some(),
    };
    if terminal {
        return None;
    }
    // External registrations are daemon-local presence records with no
    // attachable runtime. Re-registration is their only recovery path.
    if entry.external_registration {
        return None;
    }
    // orgasmic:TASK-FZB6T.5 finding 1 — the SAME refusal `/api/runs` already
    // applies (`WorktreeAuthority::blocks_attach`, used by the polled inventory
    // pass). Boot used to reattach the recorded worktree without consulting the
    // authority at all, so a durably tombstoned run — or one whose ledger is
    // unreadable and therefore `Unprovable` — was auto-reattached across a
    // restart into a worktree the inventory refuses to probe. The two paths
    // reattach the same runs; they cannot answer this differently.
    if entry.worktree_authority.blocks_attach() {
        tracing::info!(
            session_path = %session_path.display(),
            run_id = %first.run_id,
            authority = %entry.worktree_authority.label(),
            reason = entry.worktree_authority.authority_error().unwrap_or_default(),
            "boot reattach: recorded worktree authority blocks attach; skipped"
        );
        return None;
    }

    let mut acquire: Option<(String, String, String)> = None;
    let mut meta: Option<RunMetaFields> = None;
    let mut stage: Option<String> = None;
    for env in envelopes {
        if env.kind != SessionEventKind::Lifecycle {
            continue;
        }
        match serde_json::from_value::<Lifecycle>(env.event.clone()) {
            Ok(Lifecycle::Acquire {
                task_id,
                kind,
                worker_id,
            }) => acquire = Some((task_id, kind, worker_id)),
            // orgasmic:TASK-QRTT8 — every field is named and none is matched
            // against a literal. A literal here is REFUTABLE: `credential_mode:
            // None` silently dropped every run whose harness had resolved a
            // mode (claude's `native_login` / `bare_api_key`), so those runs
            // were not boot-reattach candidates at all. The `..` that used to
            // absorb this field is gone on purpose — a field added to
            // `Lifecycle::RunMeta` must now be a compile error here, decided,
            // rather than silently dropped from the reattach material.
            Ok(Lifecycle::RunMeta {
                transport,
                harness,
                project_id,
                worktree,
                last_path,
                stdout_path,
                dispatch_attempt_token,
                role,
                requires_worker_finalize,
                // Read back by the operator from the session JSONL; not input
                // to the reattach call. Bound, never tested.
                credential_mode: _,
                driver_config,
            }) => {
                meta = Some((
                    transport,
                    harness,
                    project_id,
                    worktree,
                    last_path,
                    stdout_path,
                    dispatch_attempt_token,
                    role,
                    requires_worker_finalize,
                    driver_config,
                ))
            }
            // orgasmic:TASK-KPMFK
            Ok(Lifecycle::StageMeta { stage: launched }) => stage = Some(launched),
            _ => {}
        }
    }

    let (task_id, kind_str, worker_id) = acquire?;
    let (
        transport,
        harness,
        project_id,
        worktree,
        last_path,
        stdout_path,
        dispatch_attempt_token,
        meta_role,
        meta_requires,
        driver_config,
    ) = meta?;
    let kind = match kind_str.as_str() {
        "worker" | "implementer" => RunKind::Worker,
        _ => return None,
    };

    Some(BootReattachCandidate {
        run_id: first.run_id.clone(),
        runtime_id: first.runtime_id.clone(),
        boot_id: first.boot_id.clone(),
        task_id,
        kind,
        worker_id,
        transport,
        harness,
        project_id,
        worktree,
        last_path,
        stdout_path,
        dispatch_attempt_token,
        role: meta_role,
        requires_worker_finalize: meta_requires,
        stage,
        driver_config,
        session_path: session_path.to_path_buf(),
    })
}

fn validate_boot_reattach_harness_args(candidate: &BootReattachCandidate) -> Result<(), String> {
    let persisted_harness_args = candidate
        .driver_config
        .get("harness_args")
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .map(ToString::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    validate_address_harness_args(
        candidate.harness.as_deref().unwrap_or_default(),
        &persisted_harness_args,
    )
}

/// Boot auto-reattach: rehydrate still-live runs into the freshly built
/// supervisor so a daemon restart/rebuild is transparent to the operator. For
/// each project's session JSONL that is non-terminal and carries reattach
/// metadata, build the recorded driver and call [`Supervisor::reattach`] — the
/// driver's `attach()` proves the mux session is still live (otherwise the run
/// is skipped, not interrupted). Manager runs (`manager.launch:` task ids) are
/// reattached first so the operator's terminal reconnects promptly.
///
/// A reattached run that carries dispatch artifact paths (`last_path` /
/// `stdout_path`, set only for CLI dispatch runs) gets its dispatch
/// completion watcher respawned (TASK-567JG): that watcher is a tokio task
/// spawned only at dispatch time, so it dies with the old daemon process on a
/// mid-run restart, and without a respawn `last.txt`/`stdout.log` are never
/// written on release. Runs missing either path (manager, recovery, stage
/// launch, or pre-upgrade session JSONL) are reattached with no watcher, same
/// as before this fix.
/// Scan every session file under `dirs` and keep the runs worth reattaching.
/// Blocking by nature; callers must keep it off the async runtime's threads.
///
/// orgasmic:TASK-7QM8M — bounded per file. This read used to be
/// `read_session_file` (`fs::read_to_string`), so a board's whole transcript
/// volume was paid at every daemon start; a live TUI run alone can persist
/// hundreds of megabytes that say nothing about whether it is reattachable.
/// The lifecycle scanner reads a prefix and a tail window instead, the same
/// substitution TASK-KWSTJ made on `GET /api/runs`.
/// Build boot reattach candidates from the run catalog.
///
/// orgasmic:TASK-FZB6T — the scan itself was already bounded (TASK-7QM8M made
/// this a prefix/tail window instead of a whole-file read, 14.00s → 0.145s on a
/// 2.41 GiB board). What remained was that every boot re-derived the whole board
/// from disk. The catalog's durable snapshot carries the previous boot's index,
/// so a restart re-reads only the session files that were written since — which
/// on a restart is the live runs and nothing else.
///
/// Blocking by nature; callers must keep it off the async runtime's threads.
fn collect_boot_reattach_candidates(
    catalog: &crate::run_catalog::RunCatalog,
    project_roots: &[PathBuf],
) -> Vec<BootReattachCandidate> {
    let started = std::time::Instant::now();
    let mut stats = crate::run_catalog::CatalogRefreshStats::default();
    let mut snapshot_entries = 0_usize;
    let mut seen_dirs: std::collections::BTreeSet<PathBuf> = std::collections::BTreeSet::new();
    let mut candidates = Vec::new();

    for root in project_roots {
        let Ok(canonical_root) = root.canonicalize() else {
            continue;
        };
        let dir = project_sessions_dir(&canonical_root);
        if !seen_dirs.insert(dir.clone()) {
            continue;
        }
        // Derived state: an absent, corrupt, or foreign-version snapshot is
        // discarded and the refresh below rebuilds the whole project. Boot must
        // not be able to fail on a file that only ever saved work.
        let load = catalog.load_snapshot(&canonical_root);
        snapshot_entries += load.loaded_entries();
        if !matches!(load, crate::run_catalog::SnapshotLoad::Loaded { .. }) {
            tracing::info!(
                project_root = %canonical_root.display(),
                outcome = ?load,
                "run catalog snapshot not usable; rebuilding from session files"
            );
        }
        let project_id =
            read_existing_project_identity(&canonical_root.join(".orgasmic/project.org"))
                .ok()
                .map(|identity| identity.project_id);
        let refreshed = catalog.refresh_dir(
            &dir,
            project_id.as_deref(),
            &canonical_root,
            SessionScanBudget::DEFAULT,
        );
        stats.session_files += refreshed.session_files;
        stats.session_file_bytes += refreshed.session_file_bytes;
        stats.bytes_inspected += refreshed.bytes_inspected;
        stats.cache_hits += refreshed.cache_hits;
        stats.rebuilt += refreshed.rebuilt;
        stats.truncated_scans += refreshed.truncated_scans;

        for entry in catalog.entries_for_project(&canonical_root) {
            if let Some(candidate) = boot_reattach_candidate(&entry) {
                candidates.push(candidate);
            }
        }
    }
    // The point of the catalog, stated where an operator can see it:
    // `bytes_inspected` is what this boot actually had to read, and
    // `catalog_cache_hits` is what it did not.
    tracing::info!(
        session_files = stats.session_files,
        session_file_bytes = stats.session_file_bytes,
        bytes_inspected = stats.bytes_inspected,
        catalog_snapshot_entries = snapshot_entries,
        catalog_cache_hits = stats.cache_hits,
        catalog_rebuilds = stats.rebuilt,
        truncated_scans = stats.truncated_scans,
        candidates = candidates.len(),
        duration_ms = started.elapsed().as_millis() as u64,
        "boot reattach scan complete"
    );
    candidates
}

/// Write every project's pending catalog snapshot through the writer.
///
/// Per project, and each one's dirty flag and throttle are its own
/// (orgasmic:TASK-FZB6T.1 finding 6). Best-effort by design: the catalog is
/// derived state, and a failed snapshot write costs a rebuild, never
/// correctness.
async fn persist_catalog_snapshots(
    state: &ApiState,
    project_roots: &[PathBuf],
    min_interval: std::time::Duration,
) {
    let mut seen: BTreeSet<PathBuf> = BTreeSet::new();
    for root in project_roots {
        let Ok(canonical_root) = root.canonicalize() else {
            continue;
        };
        if !seen.insert(canonical_root.clone()) {
            continue;
        }
        let Some(bytes) = state
            .run_catalog
            .snapshot_bytes_after(&canonical_root, min_interval)
        else {
            continue;
        };
        let path = canonical_root.join(crate::run_catalog::CATALOG_REL_PATH);
        if let Err(error) = state
            .writer
            .rewrite_file(
                crate::writer::FileRewrite {
                    path: path.clone(),
                    new_contents: bytes,
                },
                None,
            )
            .await
        {
            tracing::debug!(
                path = %path.display(),
                error = %error,
                "run catalog snapshot write failed; the next inventory rebuilds it"
            );
        }
    }
}

/// The boot pass's reattach-ownership decision for ONE candidate.
///
/// orgasmic:TASK-2QK4P.1.1.1.1 F2 — extracted from the loop below so the
/// regression exercises the PRODUCTION routing predicate rather than a
/// restatement of it. The loop reattaches only on
/// [`ClaimEvidence::Invalid`]; `Valid` and `Unobserved` both mean "leave the
/// prefix alone", because `Supervisor::reattach` appends `Reattach` into an
/// immutable prefix a pending recovery owns and that write cannot be undone,
/// while a skipped reattach is simply retried on the next boot.
fn boot_reattach_ownership(home: &Home, candidate: &BootReattachCandidate) -> ClaimEvidence {
    candidate
        .project_id
        .as_deref()
        .zip(candidate.worktree.as_deref())
        .map(|(project_id, project_root)| {
            pending_recovery_claim_owns_session(
                home,
                project_root,
                project_id,
                &candidate.session_path,
            )
        })
        .unwrap_or(ClaimEvidence::Invalid)
}

pub async fn reattach_live_runs_on_boot(state: &ApiState, project_roots: &[PathBuf]) {
    let home = &state.home;
    let supervisor = &state.supervisor;
    // Every read here can block indefinitely rather than fail: a path the
    // process lacks permission for, or any non-regular file, stalls inside
    // `open()` before a descriptor exists. Keep all of it on a blocking thread
    // so one such file costs this scan and nothing else — running it inline
    // wedged the whole runtime (TASK-KKGKM).
    let catalog = state.run_catalog.clone();
    let roots: Vec<PathBuf> = project_roots.to_vec();
    let mut candidates: Vec<BootReattachCandidate> = match tokio::task::spawn_blocking(move || {
        collect_boot_reattach_candidates(&catalog, &roots)
    })
    .await
    {
        Ok(candidates) => {
            // orgasmic:TASK-FZB6T.1 finding 6 — persist what the boot pass just
            // derived. The boot scan was the ONLY production caller that
            // rebuilt the whole index and never wrote it: a daemon that booted
            // cold and was then stopped before any `GET /api/runs` poll threw
            // its rebuild away and paid for it again on the next boot, which is
            // exactly the cost the durable snapshot exists to remove. The floor
            // is `ZERO` because a cold boot's index is the one save that must
            // not be throttled away.
            persist_catalog_snapshots(state, project_roots, std::time::Duration::ZERO).await;
            candidates
        }
        Err(error) => {
            tracing::warn!(error = %error, "boot reattach scan failed; skipping reattach");
            return;
        }
    };
    // Managers first (false sorts before true).
    candidates.sort_by_key(|c| !c.task_id.starts_with("manager.launch:"));

    let (mut reattached, mut skipped) = (0usize, 0usize);
    for c in candidates {
        if let Some(project_id) = c.project_id.as_deref() {
            if let Err(error) = state.index.ensure_project_loaded(project_id).await {
                skipped += 1;
                tracing::warn!(
                    run_id = %c.run_id,
                    project_id,
                    error = %error,
                    "boot reattach: required project failed to load; skipped"
                );
                continue;
            }
        }
        // orgasmic:TASK-2QK4P.1.1.1 acceptance 1 — this hint used to be a bool
        // and every failure inside it answered "no pending recovery owns this
        // session", which is the FAIL-OPEN direction: boot then appends a
        // `Reattach` into a prefix a pending claim owns and that write cannot be
        // undone. `Unobserved` is therefore treated exactly like ownership, and
        // a skipped reattach is retried on the next boot.
        let ownership = boot_reattach_ownership(home, &c);
        if !matches!(ownership, ClaimEvidence::Invalid) {
            // orgasmic:TASK-2QK4P.1.1.1.1 F3 — an `Unobserved` skip here is the
            // one an operator has to be able to act on: the run stays unattached
            // for as long as the fault lasts, so the log names the file and the
            // repair instead of only the `Debug` of a bare tag.
            let (subject, remediation) = match &ownership {
                ClaimEvidence::Unobserved(evidence) => (
                    evidence.subject.clone(),
                    Some(evidence.remediation.class().to_string()),
                ),
                ClaimEvidence::Valid | ClaimEvidence::Invalid => (None, None),
            };
            tracing::info!(
                run_id = %c.run_id,
                session_path = %c.session_path.display(),
                ownership = ?ownership,
                subject = subject.as_deref().unwrap_or("-"),
                remediation = remediation.as_deref().unwrap_or("-"),
                "boot reattach: pending recovery prefix reserved for locked reconciliation"
            );
            continue;
        }
        if let Err(error) = validate_boot_reattach_harness_args(&c) {
            skipped += 1;
            tracing::info!(
                run_id = %c.run_id,
                error = %error,
                "boot reattach: persisted harness argv rejected"
            );
            continue;
        }
        let Some(driver) = resolve_driver(&c.transport, c.harness.as_deref().unwrap_or_default())
        else {
            skipped += 1;
            tracing::info!(
                run_id = %c.run_id,
                transport = %c.transport,
                "boot reattach: no driver for recorded transport/harness; skipped"
            );
            continue;
        };
        let identity = RuntimeIdentity {
            run_id: c.run_id.clone(),
            runtime_id: c.runtime_id.clone(),
            boot_id: c.boot_id.clone(),
        };
        let (role, requires_worker_finalize) = match boot_reattach_terminal_contract(
            home,
            &c.worker_id,
            c.kind,
            c.harness.as_deref(),
            &c.last_path,
            c.role.clone(),
            c.requires_worker_finalize,
        ) {
            Ok(contract) => contract,
            Err(error) => {
                skipped += 1;
                tracing::info!(
                    run_id = %c.run_id,
                    worker_id = %c.worker_id,
                    error = %error,
                    "boot reattach: missing persisted role; skipped"
                );
                continue;
            }
        };
        match supervisor
            .reattach(
                driver.as_ref(),
                identity,
                c.kind,
                c.task_id.clone(),
                c.worker_id.clone(),
                role.clone(),
                requires_worker_finalize,
                c.project_id.clone(),
                c.worktree.clone(),
                c.session_path.clone(),
                DriverConfig::from_value(c.driver_config.clone()),
                true,
                None,
            )
            .await
        {
            Ok(_) => {
                reattached += 1;
                tracing::info!(
                    run_id = %c.run_id,
                    task_id = %c.task_id,
                    "boot reattach: rehydrated live run"
                );
                if c.last_path.is_none() && c.stdout_path.is_none() {
                    supervisor
                        .restore_terminal_contract(&c.run_id, role, requires_worker_finalize)
                        .await;
                }
                // orgasmic:TASK-KPMFK — a stage run is answered here and never
                // reaches the dispatch rule below. It is not dispatch-shaped:
                // `post_stage` gives it a `last_path` and never a
                // `stdout_path`, so the dispatch rule read it as a
                // half-recorded dispatch, warned, and respawned nothing — and
                // the stage then completed with no terminal tx at all, because
                // stage completion lived only in the watcher that died with the
                // old daemon process.
                if let Some(stage) = c.stage.clone() {
                    match (stage_spec_for(&stage), c.project_id.clone()) {
                        (Some(spec), Some(project_id)) => {
                            tracing::info!(
                                run_id = %c.run_id,
                                task_id = %c.task_id,
                                stage = %spec.stage,
                                "boot reattach: respawning stage completion watcher"
                            );
                            spawn_stage_completion_watcher(
                                state.clone(),
                                StageCompletion {
                                    stage: spec.stage.to_string(),
                                    project_id,
                                    task_id: c.task_id.clone(),
                                    target: spec.target.to_string(),
                                    run_id: c.run_id.clone(),
                                    session_path: c.session_path.clone(),
                                },
                            );
                        }
                        (Some(_), None) => {
                            tracing::warn!(
                                run_id = %c.run_id,
                                stage = %stage,
                                "boot reattach: stage run without a persisted project; \
                                 skipping stage completion watcher"
                            );
                        }
                        (None, _) => {
                            tracing::warn!(
                                run_id = %c.run_id,
                                stage = %stage,
                                "boot reattach: unrecognized persisted stage; \
                                 skipping stage completion watcher"
                            );
                        }
                    }
                    continue;
                }
                match (
                    c.last_path.clone(),
                    c.stdout_path.clone(),
                    c.project_id.clone(),
                    c.worktree.clone(),
                ) {
                    (Some(last_path), Some(stdout_path), Some(project_id), Some(worktree_path)) => {
                        tracing::info!(
                            run_id = %c.run_id,
                            task_id = %c.task_id,
                            "boot reattach: respawning dispatch completion watcher"
                        );
                        // Backfill RunRecord so `orgasmic dispatch finalize`
                        // can resolve this reattached run's artifact paths
                        // via `/runs`, same as a freshly acquired dispatch.
                        supervisor
                            .set_dispatch_artifact_paths(
                                &c.run_id,
                                last_path.clone(),
                                stdout_path.clone(),
                                c.dispatch_attempt_token.clone(),
                            )
                            .await;
                        spawn_dispatch_completion_watcher(
                            state.clone(),
                            DispatchCompletion {
                                project_id,
                                task_id: c.task_id.clone(),
                                run_id: c.run_id.clone(),
                                session_path: c.session_path.clone(),
                                last_path,
                                stdout_path,
                                worktree_path,
                            },
                        );
                    }
                    (None, None, _, _) => {
                        // Non-dispatch run (manager, recovery, stage launch) or
                        // pre-upgrade RunMeta: no watcher, as before this fix.
                    }
                    _ => {
                        // Reached by a partially-recorded dispatch, and by a
                        // stage run launched before its stage identity was
                        // durable (TASK-KPMFK) — the pre-upgrade case, which
                        // this daemon cannot tell from the former and so
                        // cannot recover. Name what is actually missing.
                        tracing::warn!(
                            run_id = %c.run_id,
                            task_id = %c.task_id,
                            has_last_path = c.last_path.is_some(),
                            has_stdout_path = c.stdout_path.is_some(),
                            has_project_id = c.project_id.is_some(),
                            has_worktree = c.worktree.is_some(),
                            "boot reattach: incomplete dispatch metadata; skipping completion watcher"
                        );
                    }
                }
            }
            Err(e) => {
                skipped += 1;
                tracing::info!(
                    run_id = %c.run_id,
                    task_id = %c.task_id,
                    error = %e,
                    "boot reattach: skipped (mux session not live / not reattachable)"
                );
            }
        }
    }
    if reattached > 0 || skipped > 0 {
        tracing::info!(reattached, skipped, "boot auto-reattach pass complete");
    }
}

/// Bring the run catalog up to date across the board and classify from it.
///
/// orgasmic:TASK-FZB6T — this used to open, scan, and re-derive every session
/// file on every call. The bounded scan (TASK-KWSTJ / TASK-7QM8M) made each
/// read cheap; the catalog makes the repeat reads disappear. A run whose
/// session file has not been written since it was indexed is answered from the
/// catalog for zero bytes, so a steady-state poll costs record count and
/// nothing else.
///
/// The classification below is unchanged and deliberately so: its input is the
/// catalog's retained lifecycle envelope set, which is what the pre-catalog
/// code passed it. The catalog decides *when* a file is read, never what its
/// lifecycle means.
#[allow(clippy::too_many_arguments)]
async fn classify_session_files(
    home: &Home,
    trusted_claude_binary: Option<&PinnedClaudeExecutable>,
    _current_boot_id: &str,
    live_runs: &[crate::supervisor::RunSummary],
    project_roots: &[PathBuf],
    catalog: &crate::run_catalog::RunCatalog,
    writer: Option<&WriterHandle>,
    window: TerminalWindow,
) -> (Vec<RecoveredRun>, InventoryStageMetrics) {
    let live_ids: std::collections::BTreeSet<_> =
        live_runs.iter().map(|run| run.run_id.as_str()).collect();
    let mut metrics = InventoryStageMetrics::default();
    let mut runs = Vec::new();
    let mut indexed: Vec<crate::run_catalog::RunCatalogEntry> = Vec::new();
    let mut attach_probes = Vec::new();
    let attach_limit = Arc::new(tokio::sync::Semaphore::new(RECOVERY_ATTACH_MAX_CONCURRENCY));
    // Per-run transcripts live per project under `.orgasmic/tmp/sessions/`
    // (dec: per-project tmp). Enumerate each registered project's sessions dir;
    // de-dup roots so a project listed twice on the board isn't scanned twice.
    let mut seen_dirs: std::collections::BTreeSet<PathBuf> = std::collections::BTreeSet::new();
    for root in project_roots {
        let Ok(canonical_root) = root.canonicalize() else {
            continue;
        };
        let dir = project_sessions_dir(&canonical_root);
        if !seen_dirs.insert(dir.clone()) {
            continue;
        }
        // orgasmic:TASK-FZB6T.1 finding 8 — the refresh reads a directory,
        // scans session files, and stats worktrees. None of that may run on an
        // async runtime thread: `GET /api/runs` is a request handler, and a
        // session file on a slow or unresponsive volume would block the whole
        // executor, not just this poll.
        let stats = {
            let catalog = catalog.clone();
            let dir = dir.clone();
            let canonical_root = canonical_root.clone();
            match tokio::task::spawn_blocking(move || {
                let project_id =
                    read_existing_project_identity(&canonical_root.join(".orgasmic/project.org"))
                        .ok()
                        .map(|identity| identity.project_id);
                catalog.refresh_dir(
                    &dir,
                    project_id.as_deref(),
                    &canonical_root,
                    SessionScanBudget::DEFAULT,
                )
            })
            .await
            {
                Ok(stats) => stats,
                Err(error) => {
                    tracing::warn!(
                        error = %error,
                        "run catalog refresh failed; skipping this project for this pass"
                    );
                    continue;
                }
            }
        };
        metrics.session_files += stats.session_files;
        metrics.session_file_bytes += stats.session_file_bytes;
        metrics.bytes_inspected += stats.bytes_inspected;
        metrics.truncated_scans += stats.truncated_scans;
        metrics.unreadable_sessions += stats.unreadable_sessions;
        metrics.catalog_cache_hits += stats.cache_hits;
        metrics.catalog_rebuilds += stats.rebuilt;
        metrics.catalog_evictions += stats.evicted;

        // Persist the derived index so the next daemon boot starts from it
        // rather than re-indexing the legacy board. Best-effort by design: the
        // catalog is derived state, and a failed snapshot write costs a rebuild,
        // never correctness.
        // `writer` first, and in its own `if let`: a tuple pattern would
        // evaluate `snapshot_bytes` unconditionally, and that call CLEARS the
        // dirty flag. With no writer the flag would be consumed with nothing
        // written, so the next caller that does have a writer would persist
        // nothing.
        if let Some(writer) = writer {
            if let Some(bytes) = catalog.snapshot_bytes(&canonical_root) {
                let path = canonical_root.join(crate::run_catalog::CATALOG_REL_PATH);
                if let Err(error) = writer
                    .rewrite_file(
                        crate::writer::FileRewrite {
                            path: path.clone(),
                            new_contents: bytes,
                        },
                        None,
                    )
                    .await
                {
                    tracing::debug!(
                        path = %path.display(),
                        error = %error,
                        "run catalog snapshot write failed; the next inventory rebuilds it"
                    );
                }
            }
        }

        indexed.extend(catalog.entries_for_project(&canonical_root));
    }

    // orgasmic:TASK-FZB6T.1 finding 3 — page BEFORE classifying. Terminal
    // history is the unbounded part of a board and it is also the part nothing
    // can be done about: classifying all of it and then returning fifty records
    // paid the whole cost of the history on every poll, including a recovery
    // action resolution per record. The split below is decided from catalog
    // fields alone — no session read, no attach probe — and only the records
    // this response will actually carry are classified.
    let (mut terminal, actionable): (Vec<_>, Vec<_>) = indexed
        .into_iter()
        .partition(|entry| entry_is_terminal_noop(entry, &live_ids));
    metrics.terminal_total = terminal.len() as u64;
    // The same ordering key the response uses: newest terminal first, run id
    // as the tiebreak so a page boundary is stable across polls.
    terminal.sort_by(|a, b| {
        b.terminal_at()
            .cmp(&a.terminal_at())
            .then(a.run_id.cmp(&b.run_id))
    });
    let paged: Vec<crate::run_catalog::RunCatalogEntry> = terminal
        .into_iter()
        .skip(window.offset)
        .take(window.limit)
        .collect();
    metrics.terminal_returned = paged.len() as u64;

    for entries in [&actionable, &paged] {
        classify_catalog_entries(
            home,
            trusted_claude_binary,
            entries,
            &live_ids,
            &attach_limit,
            &mut attach_probes,
            &mut runs,
            &mut metrics,
        )
        .await;
    }
    // Every external probe starts while its session is classified. Resolve all
    // of them against one deadline only after the durable scan is complete:
    // one hanging handle cannot starve a later healthy tmux proof, and N
    // hanging handles still add at most one bounded wait to the endpoint.
    metrics.attach_probes_started = attach_probes.len() as u64;
    let attach_deadline = tokio::time::Instant::now() + RECOVERY_ATTACH_PROBE_BUDGET;
    for pending in attach_probes {
        let (attach, timed_out) =
            finish_driver_attach(pending.task, pending.driver_id, attach_deadline).await;
        if timed_out {
            metrics.attach_probes_timed_out += 1;
        }
        let Some(run) = runs.get_mut(pending.run_index) else {
            continue;
        };
        if run.classification != "attach_pending" {
            continue;
        }
        run.classification = attach.classification.to_string();
        run.reason = attach.reason;
        if attach.classification == "reattached" {
            let target = run
                .recovery_actions
                .first()
                .map(|action| action.target.clone())
                .unwrap_or_else(|| "worker".to_string());
            run.recovery_actions.insert(
                0,
                RecoveryAction {
                    kind: "reattach_tmux".to_string(),
                    label: "Reattach".to_string(),
                    target,
                },
            );
        }
    }
    runs.sort_by(|a, b| a.run_id.cmp(&b.run_id));
    (runs, metrics)
}

/// Whether this catalog record will classify as `terminal_noop`, decided from
/// catalog fields alone.
///
/// orgasmic:TASK-FZB6T.1 finding 3 — this predicate is what makes paging before
/// classification safe, so it has to reproduce the classifier's terminal branch
/// exactly: the same three [`TerminalRecord`] shapes, the same live-registration
/// exception, and the same `Failed` carve-out that routes a failed tombstone to
/// `failed_recoverable` instead. An unreadable record classifies `ambiguous`
/// and is never paged out — a record the daemon could not read is work, not
/// history.
fn entry_is_terminal_noop(
    entry: &crate::run_catalog::RunCatalogEntry,
    live_ids: &std::collections::BTreeSet<&str>,
) -> bool {
    use crate::run_catalog::TerminalRecord;
    if entry.unreadable {
        return false;
    }
    let Some(first) = entry.lifecycle_envelopes.first() else {
        return false;
    };
    let is_terminal = match entry.terminal.as_ref() {
        Some(TerminalRecord::Release { .. }) | Some(TerminalRecord::DriverEvent { .. }) => true,
        Some(TerminalRecord::ExternalRegistrationEnded) => {
            !live_ids.contains(first.run_id.as_str())
        }
        None => false,
    };
    is_terminal
        && entry
            .terminal
            .as_ref()
            .and_then(TerminalRecord::outcome)
            .is_none_or(|outcome| outcome != ReleaseOutcome::Failed)
}

/// Classify one project's catalog entries, appending to `runs`.
///
/// orgasmic:TASK-FZB6T — the body is the pre-catalog `classify_session_dir`
/// with its `scan_session_lifecycle` call replaced by the catalog lookup that
/// already performed it. Every rule about what an envelope set means is
/// unchanged, which is what makes "same actionable classifications before and
/// after migration" a property of the change rather than a hope.
#[allow(clippy::too_many_arguments)]
async fn classify_catalog_entries(
    home: &Home,
    trusted_claude_binary: Option<&PinnedClaudeExecutable>,
    entries: &[crate::run_catalog::RunCatalogEntry],
    live_ids: &std::collections::BTreeSet<&str>,
    attach_limit: &Arc<tokio::sync::Semaphore>,
    attach_probes: &mut Vec<PendingAttachProbe>,
    runs: &mut Vec<RecoveredRun>,
    metrics: &mut InventoryStageMetrics,
) {
    use crate::run_catalog::TerminalRecord;

    for entry in entries {
        if entry.unreadable {
            runs.push(RecoveredRun {
                run_id: entry.run_id.clone(),
                runtime_id: String::new(),
                boot_id: String::new(),
                session_path: entry.session_path.clone(),
                project_id: entry.project_id.clone(),
                project_root: entry.project_root.clone(),
                worktree: None,
                worktree_authority: "unrecorded".to_string(),
                classification: "ambiguous".to_string(),
                reason: "session JSONL could not be parsed".to_string(),
                recovery_unobserved: None,
                recovery_unobserved_subject: None,
                recovery_unobserved_remediation: None,
                suppressed_recovery_actions: Vec::new(),
                recovery_actions: Vec::new(),
                recovery_replacement_run_id: None,
                recovery_replacement_session_path: None,
                terminal_at: None,
            });
            continue;
        }
        let envelopes = entry.lifecycle_envelopes.as_slice();
        let Some(first) = envelopes.first() else {
            continue;
        };

        // Terminal truth, decided once at index time under the same rule the
        // inventory always used: only the file's genuine final envelope can
        // prove a release, so a scan that dropped it as transcript (the normal
        // shape for a run that is still writing) may not tombstone the run.
        let terminal_outcome = entry
            .terminal
            .as_ref()
            .and_then(crate::run_catalog::TerminalRecord::outcome);
        let terminal = match entry.terminal.as_ref() {
            Some(TerminalRecord::Release { .. }) => {
                Some("session ended with terminal release".to_string())
            }
            Some(TerminalRecord::DriverEvent { .. }) => {
                Some("session ended with terminal driver event".to_string())
            }
            // A live external registration is a presence record for a run that
            // is running right now, not a run that ended with a restart.
            Some(TerminalRecord::ExternalRegistrationEnded)
                if !live_ids.contains(first.run_id.as_str()) =>
            {
                Some("external manager registration ended with daemon restart".to_string())
            }
            _ => None,
        };

        let authority_error = entry.worktree_authority.authority_error();
        let (mut classification, mut reason, mut recovery_actions) = if let Some(terminal_reason) =
            terminal
        {
            if terminal_outcome == Some(ReleaseOutcome::Failed) {
                // A Failed tombstone is immutable and can never be reattached
                // under its old run id. Its recovery actions do not depend on
                // liveness classification, so probing the dead driver here is
                // both meaningless and a source of endpoint stalls.
                let actions = resolve_recovery_actions(
                    home,
                    trusted_claude_binary,
                    envelopes,
                    "interrupted",
                    true,
                )
                .await;
                ("failed_recoverable".to_string(), terminal_reason, actions)
            } else {
                ("terminal_noop".to_string(), terminal_reason, Vec::new())
            }
        } else if entry.worktree_authority.blocks_attach() {
            // orgasmic:TASK-FZB6T item 2 — the recorded worktree is gone, so no
            // attach can ever succeed for this run under this identity. Before
            // the catalog this fell through to a driver attach probe whose
            // answer was then thrown away by the authority check below, on every
            // single poll, forever. State it once and stop probing.
            metrics.tombstoned_authority += 1;
            (
                "ambiguous".to_string(),
                authority_error
                    .unwrap_or("recorded worktree is gone")
                    .to_string(),
                Vec::new(),
            )
        } else {
            match start_current_boot_attach_probe(home, envelopes, first, live_ids, attach_limit) {
                AttachProbeStart::Ready(attach) => {
                    let actions = resolve_recovery_actions(
                        home,
                        trusted_claude_binary,
                        envelopes,
                        attach.classification,
                        false,
                    )
                    .await;
                    (attach.classification.to_string(), attach.reason, actions)
                }
                AttachProbeStart::Pending { driver_id, task } => {
                    let actions = resolve_recovery_actions(
                        home,
                        trusted_claude_binary,
                        envelopes,
                        "interrupted",
                        false,
                    )
                    .await;
                    attach_probes.push(PendingAttachProbe {
                        run_index: runs.len(),
                        driver_id,
                        task,
                    });
                    (
                        "attach_pending".to_string(),
                        "driver attach proof pending".to_string(),
                        actions,
                    )
                }
            }
        };
        if classification != "terminal_noop" {
            if let Some(error) = authority_error {
                classification = "ambiguous".to_string();
                reason = error.to_string();
                recovery_actions.clear();
            }
        }
        runs.push(RecoveredRun {
            run_id: first.run_id.clone(),
            runtime_id: first.runtime_id.clone(),
            boot_id: first.boot_id.clone(),
            session_path: entry.session_path.clone(),
            project_id: entry.project_id.clone(),
            project_root: entry.project_root.clone(),
            worktree: entry
                .worktree_authority
                .verified_worktree()
                .map(std::path::Path::to_path_buf),
            worktree_authority: entry.worktree_authority.label().to_string(),
            classification,
            reason,
            recovery_actions,
            recovery_unobserved: None,
            recovery_unobserved_subject: None,
            recovery_unobserved_remediation: None,
            suppressed_recovery_actions: Vec::new(),
            recovery_replacement_run_id: None,
            recovery_replacement_session_path: None,
            terminal_at: entry.terminal.as_ref().and_then(TerminalRecord::at),
        });
    }
}

/// One-shot, idempotent, non-fatal relocation of legacy home-level session
/// transcripts (`$ORGASMIC_HOME/sessions/*.jsonl`) into their project's
/// per-project `.orgasmic/tmp/sessions/` dir. Runs at boot before recovery is
/// served.
///
/// Mapping: a `manager-<project_id>-…jsonl` file goes to the board project with
/// that id; any other file goes to the sole board project when there is exactly
/// one (covers the common single-project case, incl. stage/dispatch/recover);
/// otherwise it is left in place with a warning (a handful of unmappable
/// historical files simply won't appear in per-project recovery). Never deletes
/// on failure; skips when the destination already exists.
pub(crate) fn migrate_legacy_home_sessions(home: &Home, projects: &[(String, PathBuf)]) {
    let legacy_dir = home.sessions();
    let Ok(entries) = std::fs::read_dir(&legacy_dir) else {
        return; // no legacy dir → nothing to migrate
    };
    let by_id: std::collections::HashMap<&str, &PathBuf> = projects
        .iter()
        .map(|(id, root)| (id.as_str(), root))
        .collect();
    let sole_root = if projects.len() == 1 {
        Some(&projects[0].1)
    } else {
        None
    };
    let (mut moved, mut left) = (0u32, 0u32);
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("jsonl") {
            continue;
        }
        let Some(file_name) = path.file_name().and_then(|s| s.to_str()) else {
            continue;
        };
        let target_root = file_name
            .strip_prefix("manager-")
            .and_then(|rest| {
                // `manager-<project_id>-<timestamp>.jsonl`: the id is everything
                // before the final `-<timestamp>` segment.
                rest.rsplit_once('-').map(|(id, _)| id)
            })
            .and_then(|id| by_id.get(id).copied())
            .or(sole_root);
        let Some(root) = target_root else {
            tracing::warn!(session = %file_name, "legacy session could not be mapped to a project; leaving in place");
            left += 1;
            continue;
        };
        let dest_dir = project_sessions_dir(root);
        let dest = dest_dir.join(file_name);
        if dest.exists() {
            continue; // already migrated (idempotent)
        }
        if let Err(e) = std::fs::create_dir_all(&dest_dir) {
            tracing::warn!(session = %file_name, error = %e, "create per-project sessions dir failed");
            left += 1;
            continue;
        }
        if let Err(e) = std::fs::rename(&path, &dest) {
            tracing::warn!(session = %file_name, error = %e, "move legacy session failed; leaving in place");
            left += 1;
            continue;
        }
        moved += 1;
    }
    if moved > 0 || left > 0 {
        tracing::info!(
            moved,
            left,
            "migrated legacy home session transcripts to per-project tmp"
        );
    }
}

struct AttachClassification {
    classification: &'static str,
    reason: String,
}

const RECOVERY_ATTACH_PROBE_BUDGET: std::time::Duration = std::time::Duration::from_secs(1);
const RECOVERY_ATTACH_MAX_CONCURRENCY: usize = 16;

struct PendingAttachProbe {
    run_index: usize,
    driver_id: String,
    task: AbortOnDropAttachProbe,
}

struct AbortOnDropAttachProbe {
    handle: tokio::task::JoinHandle<Result<AttachOutcome, orgasmic_drivers::DriverError>>,
}

impl AbortOnDropAttachProbe {
    fn new(
        handle: tokio::task::JoinHandle<Result<AttachOutcome, orgasmic_drivers::DriverError>>,
    ) -> Self {
        Self { handle }
    }
}

impl Drop for AbortOnDropAttachProbe {
    fn drop(&mut self) {
        self.handle.abort();
    }
}

enum AttachProbeStart {
    Ready(AttachClassification),
    Pending {
        driver_id: String,
        task: AbortOnDropAttachProbe,
    },
}

#[derive(Debug, Clone)]
struct SessionAcquireMeta {
    task_id: String,
    kind: RunKind,
    worker_id: String,
}

fn start_current_boot_attach_probe(
    home: &Home,
    envelopes: &[SessionEnvelope],
    first: &SessionEnvelope,
    live_ids: &std::collections::BTreeSet<&str>,
    attach_limit: &Arc<tokio::sync::Semaphore>,
) -> AttachProbeStart {
    if live_ids.contains(first.run_id.as_str()) {
        return AttachProbeStart::Ready(AttachClassification {
            classification: "reattached",
            reason: "supervisor-live run; attach proof skipped for active lease".to_string(),
        });
    }
    let Some(meta) = session_acquire_meta(envelopes) else {
        return AttachProbeStart::Ready(AttachClassification {
            classification: "ambiguous",
            reason: "current-boot session has no acquire lifecycle metadata".to_string(),
        });
    };
    let Some((driver, driver_id)) = session_driver(home, envelopes, &meta) else {
        // orgasmic:TASK-XCJYC — a run that recorded a real address the current
        // registry cannot build (a mode renamed since it ran) still proved one
        // thing about itself: reattach is a pane-transport capability, and this
        // is not a pane transport. `ambiguous` here would demote records that
        // never became less legible, only less current.
        if let Some((mode, harness)) = persisted_run_address_from_session(envelopes) {
            if !crate::run_catalog::transport_is_pane(&mode) {
                return AttachProbeStart::Ready(AttachClassification {
                    classification: "interrupted",
                    reason: format!("driver {mode}/{harness} does not support runtime reattach"),
                });
            }
        }
        return AttachProbeStart::Ready(AttachClassification {
            classification: "ambiguous",
            reason: "current-boot session has no recoverable driver identity".to_string(),
        });
    };
    if !driver_supports_recovery_attach(&driver_id) {
        return AttachProbeStart::Ready(AttachClassification {
            classification: "interrupted",
            reason: format!("driver {driver_id} does not support runtime reattach"),
        });
    }
    let ctx = DriverContext {
        identity: RuntimeIdentity {
            run_id: first.run_id.clone(),
            runtime_id: first.runtime_id.clone(),
            boot_id: first.boot_id.clone(),
        },
        run_kind: meta.kind,
        task_id: meta.task_id,
        worker_id: meta.worker_id,
        project_id: None,
        worktree: None,
    };
    let task = spawn_driver_attach_probe(driver, ctx, attach_limit.clone());
    AttachProbeStart::Pending { driver_id, task }
}

fn driver_supports_recovery_attach(driver_id: &str) -> bool {
    driver_id == "tmux-tui" || driver_id.starts_with("tmux/")
}

fn spawn_driver_attach_probe(
    driver: Box<dyn WorkerDriver>,
    ctx: DriverContext,
    attach_limit: Arc<tokio::sync::Semaphore>,
) -> AbortOnDropAttachProbe {
    AbortOnDropAttachProbe::new(tokio::spawn(async move {
        let _permit = attach_limit
            .acquire_owned()
            .await
            .expect("recovery attach semaphore remains open");
        driver.attach(ctx, DriverConfig::empty()).await
    }))
}

/// Resolve one pending attach proof against the shared inventory deadline.
/// The second element is true when the probe was abandoned at that deadline,
/// which the caller records as an inventory stage metric.
async fn finish_driver_attach(
    mut probe: AbortOnDropAttachProbe,
    driver_id: String,
    attach_deadline: tokio::time::Instant,
) -> (AttachClassification, bool) {
    match tokio::time::timeout_at(attach_deadline, &mut probe.handle).await {
        Ok(Ok(Ok(AttachOutcome::Attached(_attached)))) => (
            AttachClassification {
                classification: "reattached",
                reason: format!("driver {driver_id} proved live runtime handle"),
            },
            false,
        ),
        Ok(Ok(Ok(AttachOutcome::NotReattachable))) => (
            AttachClassification {
                classification: "interrupted",
                reason: format!("driver {driver_id} could not prove a live runtime handle"),
            },
            false,
        ),
        Ok(Ok(Err(error))) => (
            AttachClassification {
                classification: "interrupted",
                reason: format!("driver {driver_id} attach proof failed: {error}"),
            },
            false,
        ),
        Ok(Err(error)) => (
            AttachClassification {
                classification: "interrupted",
                reason: format!("driver {driver_id} attach proof task failed: {error}"),
            },
            false,
        ),
        Err(_) => {
            probe.handle.abort();
            let _ = (&mut probe.handle).await;
            (
                AttachClassification {
                    classification: "interrupted",
                    reason: format!("driver {driver_id} attach proof exceeded inventory deadline"),
                },
                true,
            )
        }
    }
}

fn session_acquire_meta(envelopes: &[SessionEnvelope]) -> Option<SessionAcquireMeta> {
    envelopes.iter().find_map(|envelope| {
        if envelope.kind != SessionEventKind::Lifecycle {
            return None;
        }
        match serde_json::from_value::<Lifecycle>(envelope.event.clone()).ok()? {
            Lifecycle::Acquire {
                task_id,
                kind,
                worker_id,
            } => Some(SessionAcquireMeta {
                task_id,
                kind: run_kind_from_lifecycle(&kind)?,
                worker_id,
            }),
            _ => None,
        }
    })
}

/// Native runtime identity recorded into the session JSONL at launch time.
#[derive(Debug, Clone)]
struct SessionNativeRuntime {
    provider: String,
    session_id: Option<String>,
    resume_argv: Vec<String>,
}

fn session_native_runtime(envelopes: &[SessionEnvelope]) -> Option<SessionNativeRuntime> {
    envelopes.iter().rev().find_map(|envelope| {
        if envelope.kind != SessionEventKind::Lifecycle {
            return None;
        }
        match serde_json::from_value::<Lifecycle>(envelope.event.clone()).ok()? {
            Lifecycle::NativeRuntime {
                provider,
                session_id,
                resume_argv,
                ..
            } => Some(SessionNativeRuntime {
                provider,
                session_id,
                resume_argv,
            }),
            _ => None,
        }
    })
}

fn validate_safe_session_id(id: &str) -> bool {
    !id.is_empty()
        && !id.contains('/')
        && !id.contains('\\')
        && id != "."
        && id != ".."
        && FsPath::new(id)
            .components()
            .all(|c| matches!(c, Component::Normal(_)))
}

/// Canonical Claude executable pinned at daemon boot with target identity.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PinnedClaudeExecutable {
    /// Discovery entry (may be a symlink such as `~/.local/bin/claude`).
    pub entry_path: PathBuf,
    /// Canonical regular-file target executed on resume/fork.
    pub target_path: PathBuf,
    #[cfg(unix)]
    pub dev: u64,
    #[cfg(unix)]
    pub ino: u64,
}

impl PinnedClaudeExecutable {
    pub fn as_path(&self) -> &FsPath {
        &self.target_path
    }

    /// Revalidate pinned target identity immediately before execute.
    pub fn revalidate(&self) -> bool {
        trusted_claude_target_matches_pin(self)
    }
}

/// Resolve and pin the trusted Claude executable from daemon-owned discovery.
/// Does not consult request/project cwd PATH or bare `claude` on PATH.
pub fn pin_trusted_claude_binary(home: &Home) -> Option<PinnedClaudeExecutable> {
    let mut candidates = vec![home.bin().join("claude")];
    if let Some(local_bin) = std::env::var_os("HOME").map(|home| {
        PathBuf::from(home)
            .join(".local")
            .join("bin")
            .join("claude")
    }) {
        candidates.push(local_bin);
    }
    candidates
        .iter()
        .find_map(|candidate| pin_trusted_claude_candidate(candidate))
}

fn pin_trusted_claude_candidate(entry: &FsPath) -> Option<PinnedClaudeExecutable> {
    let Ok(entry_meta) = std::fs::symlink_metadata(entry) else {
        return None;
    };
    let file_type = entry_meta.file_type();
    if !(file_type.is_file() || file_type.is_symlink()) {
        return None;
    }
    let target = entry.canonicalize().ok()?;
    let Ok(target_meta) = std::fs::metadata(&target) else {
        return None;
    };
    if !target_meta.is_file() {
        return None;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        if target_meta.permissions().mode() & 0o111 == 0 {
            return None;
        }
        let current_uid = unsafe { libc::getuid() };
        if target_meta.uid() != current_uid {
            return None;
        }
        Some(PinnedClaudeExecutable {
            entry_path: entry.to_path_buf(),
            target_path: target,
            dev: target_meta.dev(),
            ino: target_meta.ino(),
        })
    }
    #[cfg(not(unix))]
    {
        Some(PinnedClaudeExecutable {
            entry_path: entry.to_path_buf(),
            target_path: target,
        })
    }
}

fn trusted_claude_target_matches_pin(pin: &PinnedClaudeExecutable) -> bool {
    let Ok(entry_target) = pin.entry_path.canonicalize() else {
        return false;
    };
    if entry_target != pin.target_path {
        return false;
    }
    let Ok(meta) = std::fs::metadata(&pin.target_path) else {
        return false;
    };
    if !meta.is_file() {
        return false;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        if meta.permissions().mode() & 0o111 == 0 {
            return false;
        }
        let current_uid = unsafe { libc::getuid() };
        if meta.uid() != current_uid {
            return false;
        }
        meta.dev() == pin.dev && meta.ino() == pin.ino
    }
    #[cfg(not(unix))]
    {
        let _ = pin;
        true
    }
}

fn resume_argv_proves_claude_fork(resume_argv: &[String], session_id: &str) -> bool {
    let mut saw_resume = false;
    let mut saw_fork = false;
    for (idx, arg) in resume_argv.iter().enumerate() {
        if arg == "--resume" && resume_argv.get(idx + 1).is_some_and(|id| id == session_id) {
            saw_resume = true;
        }
        if arg == "--fork-session" {
            saw_fork = true;
        }
    }
    saw_resume && saw_fork
}

/// Prove structured Claude native identity without trusting persisted argv.
fn validated_claude_native_session_id(
    trusted_claude_binary: Option<&PinnedClaudeExecutable>,
    native: &SessionNativeRuntime,
) -> Option<String> {
    let pinned = trusted_claude_binary.filter(|pin| pin.revalidate())?;
    if native.provider != "claude" {
        return None;
    }
    let session_id = native.session_id.as_ref()?;
    if !validate_safe_session_id(session_id) {
        return None;
    }
    if !native.resume_argv.is_empty() {
        if !resume_argv_proves_claude_fork(&native.resume_argv, session_id) {
            return None;
        }
        if let Some(cmd) = native.resume_argv.first() {
            if (cmd.contains('/') || cmd.contains('\\'))
                && pinned.as_path().to_string_lossy() != cmd.as_str()
            {
                return None;
            }
            if cmd == "sh" || cmd.ends_with("/sh") {
                return None;
            }
        }
    }
    Some(session_id.clone())
}

/// Reconstruct the daemon-owned Claude resume/fork command from validated identity.
fn reconstruct_claude_native_resume_command(
    trusted_claude_binary: Option<&PinnedClaudeExecutable>,
    session_id: &str,
) -> Option<(PathBuf, Vec<String>)> {
    let pinned = trusted_claude_binary.filter(|pin| pin.revalidate())?;
    Some((
        pinned.target_path.clone(),
        vec![
            "--dangerously-skip-permissions".to_string(),
            "--resume".to_string(),
            session_id.to_string(),
            "--fork-session".to_string(),
        ],
    ))
}

fn recovery_response_from_claim(
    claim: &RecoveryClaim,
) -> Result<Json<RunRecoverResponse>, ApiError> {
    Ok(Json(RunRecoverResponse {
        run_id: claim.replacement_run_id.clone(),
        runtime_id: claim
            .runtime_id
            .clone()
            .ok_or_else(|| ApiError::internal("committed recovery claim missing runtime id"))?,
        boot_id: claim
            .boot_id
            .clone()
            .ok_or_else(|| ApiError::internal("committed recovery claim missing boot id"))?,
        session_path: claim.replacement_session_path.clone(),
        action: claim
            .action
            .clone()
            .ok_or_else(|| ApiError::internal("committed recovery claim missing action"))?,
        target: claim.target.clone().unwrap_or_else(|| "worker".to_string()),
        draft_prompt: claim.draft_prompt.clone(),
    }))
}

fn recovery_claim_conflict(origin_run_id: &str, claim: &RecoveryClaim) -> ApiError {
    ApiError::conflict_json(json!({
        "error": "recovery already claimed for this origin",
        "origin_run_id": origin_run_id,
        "existing_request_id": claim.request_id,
        "replacement_run_id": claim.replacement_run_id,
        "replacement_session_path": claim.replacement_session_path,
    }))
}

/// A claim load that could not decide is retryable, not an internal error.
///
/// orgasmic:TASK-2QK4P.1.1.1 acceptance 2 — `load_recovery_claim` recomputes the
/// `authority_tag` to accept the file, so an unreadable key file makes the load
/// itself unobserved. Reporting that as a 500 would hide the one thing the
/// caller can act on: retry once the daemon can read its own auth material.
fn recovery_claim_load_error(origin_run_id: &str, err: RecoveryClaimError) -> ApiError {
    match err {
        RecoveryClaimError::Unobserved(evidence) => {
            recovery_origins_unobserved(origin_run_id, &evidence)
        }
        // orgasmic:TASK-2QK4P.1.1.1.1 F4 — raw `Io` used to land here and become
        // a 500. A 500 tells the caller "the daemon is broken"; the truth is
        // "the daemon could not read one file and will decide once it can",
        // which is a 503 with a remediation. The errno policy makes the split:
        // an `Absent`/`Decided` io error is a fact about the claim and keeps
        // failing closed, everything else is the observer.
        RecoveryClaimError::Io(err) => match classify_observation(&err) {
            ObservationClass::Unobserved => recovery_origins_unobserved(
                origin_run_id,
                &UnobservedEvidence::about(
                    UnobservedSession::ClaimFileUnreadable,
                    format!("recovery-claims/{origin_run_id}.json"),
                ),
            ),
            ObservationClass::Absent | ObservationClass::Decided => {
                ApiError::internal(format!("recovery claim load failed: {err:?}"))
            }
        },
        other => ApiError::internal(format!("recovery claim load failed: {other:?}")),
    }
}

/// A pending recovery claim that cannot be reconciled because its exact tmux
/// handle was unobservable must remain pending. In particular, do not turn a
/// local tmux client failure into the generic 500/409 path that can lead a
/// caller to treat the durable replacement authority as dead.
fn recovery_claim_reconcile_error(origin_run_id: &str, err: RecoveryClaimError) -> ApiError {
    match err {
        RecoveryClaimError::Unobserved(evidence) => ApiError::service_unavailable(json!({
            "error": "recovery claim reconciliation could not observe its planned handle; retry",
            "origin_run_id": origin_run_id,
            "reason": evidence.reason.tag(),
            "subject": evidence.subject,
            "remediation": evidence.remediation.class(),
            "remediation_hint": evidence.remediation.hint(),
        })),
        other => ApiError::internal(format!("recovery claim reconcile failed: {other:?}")),
    }
}

/// Refuse a recover request whose candidate set could not be enumerated.
///
/// orgasmic:TASK-2QK4P.1.1 — 503 and not 409: nothing is known to conflict, the
/// daemon simply could not look. The claim on disk is untouched, so a retry once
/// the file is readable resolves normally and the rescue keeps its idempotency.
///
/// orgasmic:TASK-2QK4P.1.1.1.1 F3 — the body now says WHICH FILE and WHAT TO DO.
/// `reason` alone told the operator a category and nothing else, and the refusal
/// is project-wide and permanent for a malformed session file, so "which file"
/// is the difference between a clearable fault and an outage with no exit.
fn recovery_origins_unobserved(origin_run_id: &str, evidence: &UnobservedEvidence) -> ApiError {
    ApiError::service_unavailable(json!({
        "error": "recovery origin enumeration did not complete; refusing to decide authority",
        "origin_run_id": origin_run_id,
        "reason": evidence.reason.tag(),
        "subject": evidence.subject,
        "remediation": evidence.remediation.class(),
        "remediation_hint": evidence.remediation.hint(),
    }))
}

fn committed_claim_is_authoritative(
    home: &Home,
    project_root: &FsPath,
    project_id: &str,
    origin_run_id: &str,
    authority: &mut ProjectOriginAuthority,
    claim: &RecoveryClaim,
) -> CommittedClaimAuthority {
    match resolve_authoritative_recovery_claim(
        home,
        project_root,
        project_id,
        origin_run_id,
        authority,
    ) {
        Ok(
            ResolvedRecoveryClaim::Valid(resolved) | ResolvedRecoveryClaim::Reconstructed(resolved),
        ) if resolved.status == RecoveryClaimStatus::Committed && resolved == *claim => {
            CommittedClaimAuthority::Authoritative
        }
        // orgasmic:TASK-2QK4P.1.1 F1/F2 — a failed enumeration must not read as
        // "this claim is not authoritative". That answer sends the handler on to
        // the no-plan branch, where it mints a SECOND replacement beside the one
        // the unread file may already hold. Unknown gets its own answer and the
        // caller refuses.
        Ok(ResolvedRecoveryClaim::Unobserved(evidence)) => {
            CommittedClaimAuthority::Unobserved(evidence)
        }
        // orgasmic:TASK-2QK4P.1.1.1.1 F4 — THE WILDCARD IS GONE, and that is the
        // fix. `_ => NotAuthoritative` swept EVERY resolver `Err` — raw `Io`
        // included — into a decided negative, which is literally the rejected
        // shape: "I could not decide" spelled as "I decided no". A decided no
        // sends the handler to the no-plan branch, where it can mint a second
        // replacement. Every arm below is now written out, so adding a variant
        // to either enum is a compile error rather than a silent negative.
        Ok(ResolvedRecoveryClaim::Valid(_) | ResolvedRecoveryClaim::Reconstructed(_)) => {
            // Resolved, but not to THIS claim in Committed state: a decided
            // negative about the claim the caller passed in.
            CommittedClaimAuthority::NotAuthoritative
        }
        Ok(ResolvedRecoveryClaim::InvalidQuarantined) | Ok(ResolvedRecoveryClaim::Missing) => {
            CommittedClaimAuthority::NotAuthoritative
        }
        Err(RecoveryClaimError::Unobserved(evidence)) => {
            CommittedClaimAuthority::Unobserved(evidence)
        }
        Err(RecoveryClaimError::Io(err)) => match classify_observation(&err) {
            ObservationClass::Unobserved => {
                CommittedClaimAuthority::Unobserved(UnobservedEvidence::about(
                    UnobservedSession::ClaimFileUnreadable,
                    format!("recovery-claims/{origin_run_id}.json"),
                ))
            }
            // Absent or a decided path fact: the claim is not authoritative and
            // the daemon knows it.
            ObservationClass::Absent | ObservationClass::Decided => {
                CommittedClaimAuthority::NotAuthoritative
            }
        },
        // Every remaining variant is a DECIDED statement about the claim or its
        // identifiers, listed rather than swept.
        Err(RecoveryClaimError::InvalidIdentifier)
        | Err(RecoveryClaimError::UnresolvableProjectRoot)
        | Err(RecoveryClaimError::AlreadyClaimed(_))
        | Err(RecoveryClaimError::CorruptClaim)
        | Err(RecoveryClaimError::MissingClaim)
        | Err(RecoveryClaimError::DeadPlannedHandle)
        | Err(RecoveryClaimError::ForeignSessionPath) => CommittedClaimAuthority::NotAuthoritative,
    }
}

/// Three answers, because two were never enough.
#[derive(Debug, Clone, PartialEq, Eq)]
enum CommittedClaimAuthority {
    Authoritative,
    NotAuthoritative,
    Unobserved(UnobservedEvidence),
}

/// Suppress this record's recovery actions because the daemon could not look,
/// keeping what it would have offered so an authority-independent request check
/// can still validate against it.
///
/// orgasmic:TASK-2QK4P.1.1.1 — the claim on disk is deliberately left alone
/// (ruling 1: unobserved never quarantines), so the next pass — which may read
/// the file fine — still finds it and the rescue keeps its idempotency.
fn suppress_unobserved_recovery(run: &mut RecoveredRun, evidence: &UnobservedEvidence) {
    run.suppressed_recovery_actions = std::mem::take(&mut run.recovery_actions);
    run.recovery_unobserved = Some(evidence.reason.tag().to_string());
    run.recovery_unobserved_subject = evidence.subject.clone();
    run.recovery_unobserved_remediation = Some(evidence.remediation.class().to_string());
    let subject = evidence.subject.as_deref().unwrap_or("unnamed");
    // orgasmic:TASK-2QK4P.1.1.1.1 F3 — the log line names the file too. An
    // operator reading daemon logs is the other half of the surface; a reason
    // tag on its own sent them looking through every session file in the
    // project.
    tracing::warn!(
        run_id = %run.run_id,
        reason = evidence.reason.tag(),
        subject = %subject,
        remediation = evidence.remediation.class(),
        hint = evidence.remediation.hint(),
        "recovery authority unresolved; refusing to decide and offering a repair"
    );
    run.reason = format!(
        "{}; recovery origin enumeration unresolved ({} at {subject}; {})",
        run.reason,
        evidence.reason.tag(),
        evidence.remediation.class()
    );
}

fn apply_recovery_claim_to_run(
    home: &Home,
    authority: &mut ProjectOriginAuthority,
    run: &mut RecoveredRun,
) {
    if run.classification != "failed_recoverable" {
        return;
    }
    let Some(project_id) = run.project_id.as_deref() else {
        return;
    };
    let Some(project_root) = run.project_root.as_deref() else {
        run.recovery_actions.clear();
        return;
    };
    let resolved = match resolve_authoritative_recovery_claim(
        home,
        project_root,
        project_id,
        &run.run_id,
        authority,
    ) {
        Ok(resolved) => resolved,
        // orgasmic:TASK-2QK4P.1.1.1 — an error here is an observation failure
        // too, so it suppresses through the same field rather than by silently
        // emptying the action list.
        // orgasmic:TASK-2QK4P.1.1.1.1 F4 — matched explicitly so an `Io` failure
        // suppresses with a real observation reason instead of a `Debug` string.
        Err(RecoveryClaimError::Unobserved(evidence)) => {
            suppress_unobserved_recovery(run, &evidence);
            return;
        }
        Err(RecoveryClaimError::Io(err)) => {
            match classify_observation(&err) {
                ObservationClass::Unobserved => suppress_unobserved_recovery(
                    run,
                    &UnobservedEvidence::about(
                        UnobservedSession::ClaimFileUnreadable,
                        format!("recovery-claims/{}.json", run.run_id),
                    ),
                ),
                // Absent or a decided path fact about the claim file. The record
                // simply offers no recovery, which is a statement the daemon is
                // entitled to make.
                ObservationClass::Absent | ObservationClass::Decided => {
                    run.recovery_actions.clear()
                }
            }
            return;
        }
        // Decided statements about the claim or its identifiers.
        Err(_) => {
            run.recovery_actions.clear();
            return;
        }
    };
    let claim = match resolved {
        ResolvedRecoveryClaim::Valid(claim) | ResolvedRecoveryClaim::Reconstructed(claim) => claim,
        ResolvedRecoveryClaim::InvalidQuarantined => {
            run.recovery_actions.clear();
            run.reason = format!("{}; recovery claim invalid/quarantined", run.reason);
            return;
        }
        // orgasmic:TASK-2QK4P.1.1 — the actions are cleared exactly as for a
        // quarantine, because offering "start a recovery run" while a second
        // authenticated replacement may sit in an unread file is the duplicate
        // authority this whole path exists to prevent. The claim on disk is left
        // alone, so the next pass — which may read the file fine — still finds
        // it and the rescue stays idempotent.
        ResolvedRecoveryClaim::Unobserved(evidence) => {
            suppress_unobserved_recovery(run, &evidence);
            return;
        }
        ResolvedRecoveryClaim::Missing => return,
    };
    if claim.status != RecoveryClaimStatus::Committed {
        return;
    }
    // orgasmic:TASK-2QK4P.1.1.1 F1(b) — this is a SECOND read of the same
    // session, after the resolver's. `false` used to leave the recovery actions
    // standing, so an observation failure in the window between the two reads
    // offered "start a recovery run" for an origin that already has a live
    // authenticated replacement.
    match verify_committed_claim_against_session(home, project_root, &claim) {
        ClaimEvidence::Valid => {}
        ClaimEvidence::Invalid => return,
        ClaimEvidence::Unobserved(evidence) => {
            suppress_unobserved_recovery(run, &evidence);
            return;
        }
    }
    run.recovery_replacement_run_id = Some(claim.replacement_run_id.clone());
    run.recovery_replacement_session_path = Some(claim.replacement_session_path.clone());
    run.recovery_actions.clear();
    run.reason = format!(
        "{}; recovery replacement {}",
        run.reason, claim.replacement_run_id
    );
}

/// Backend-owned, ordered, harness-aware recovery action resolver (dec_052).
/// Priority: live tmux reattach, native session resume/fork, then a fresh
/// recovery run. `classification` is the attach-proof result for this run.
async fn resolve_recovery_actions(
    _home: &Home,
    trusted_claude_binary: Option<&PinnedClaudeExecutable>,
    envelopes: &[SessionEnvelope],
    classification: &str,
    failed_terminal: bool,
) -> Vec<RecoveryAction> {
    let meta = session_acquire_meta(envelopes);
    let worker_id = meta.as_ref().map(|m| m.worker_id.as_str()).unwrap_or("");
    let run_kind = meta.as_ref().map(|m| m.kind);
    let target = recovery_target_for(run_kind, worker_id).to_string();

    let mut actions = Vec::new();

    // 1. Live tmux reattach proven by the classifier — never for terminal Failed
    //    tombstones; those must resume under a distinct run/session identity.
    if classification == "reattached" && !failed_terminal {
        actions.push(RecoveryAction {
            kind: "reattach_tmux".to_string(),
            label: "Reattach".to_string(),
            target: target.clone(),
        });
    }

    // 2. Native session resume/fork when structured Claude identity is provable.
    if let Some(native) = session_native_runtime(envelopes) {
        if validated_claude_native_session_id(trusted_claude_binary, &native).is_some() {
            actions.push(RecoveryAction {
                kind: "resume_native_fork".to_string(),
                label: "Resume Claude (fork)".to_string(),
                target: target.clone(),
            });
        }
    }

    // 3. Fresh recovery run is always available as the last resort. No
    //    ~/.claude/projects best-effort discovery for legacy runs (dec_052).
    actions.push(RecoveryAction {
        kind: "start_recovery_run".to_string(),
        label: "Start Recovery Run".to_string(),
        target,
    });

    actions
}

fn run_kind_from_lifecycle(kind: &str) -> Option<RunKind> {
    match kind {
        // "implementer" is the pre-rename spelling still present in old
        // persisted session JSONLs.
        "worker" | "implementer" => Some(RunKind::Worker),
        _ => None,
    }
}

fn session_driver(
    _home: &Home,
    envelopes: &[SessionEnvelope],
    _meta: &SessionAcquireMeta,
) -> Option<(Box<dyn WorkerDriver>, String)> {
    if let Some((mode, harness)) = persisted_run_address_from_session(envelopes) {
        if let Some(driver) = resolve_persisted_run_driver(&mode, &harness) {
            return Some((driver, format!("{mode}/{harness}")));
        }
        // A recorded address the registry no longer knows — the pre-TASK-XCJYC
        // `acp-stdio`/`acp-ws` spelling is the reason this arm exists — is a
        // fact about the run, not a reason to abandon the record. Fall through
        // to the `Ready` protocol_version, which recognises the historical
        // string on its own terms.
    }
    let driver_id = session_driver_id_from_ready(envelopes)?;
    resolve_driver_by_transport(&driver_id).map(|driver| (driver, driver_id))
}

fn session_driver_id_from_ready(envelopes: &[SessionEnvelope]) -> Option<String> {
    envelopes.iter().find_map(|envelope| {
        if envelope.kind != SessionEventKind::DriverEvent {
            return None;
        }
        let DriverEvent::Ready {
            protocol_version, ..
        } = serde_json::from_value::<DriverEvent>(envelope.event.clone()).ok()?
        else {
            return None;
        };
        driver_id_from_protocol(&protocol_version).map(str::to_string)
    })
}

/// Recognise a run's driver from the `protocol_version` its `Ready` event
/// carried.
///
/// `acp/` is a **historical** protocol_version, never a live one: before
/// TASK-XCJYC the claude adapter's simulated start events reported `acp/1` for
/// what has always been Claude Code's own stream-json wire, while the real
/// path already reported `claude-code-stream-json/1`. Sessions written under
/// the old build are on disk and must keep resolving; per dec_WDR5K item 10
/// this is a read of a historical string, not an alias table that would let
/// anything new be written as `acp/`.
// orgasmic:TASK-XCJYC
fn driver_id_from_protocol(protocol_version: &str) -> Option<&'static str> {
    if protocol_version.starts_with("tmux-tui/") {
        Some("tmux-tui")
    } else if protocol_version.starts_with("codex-appserver/") {
        Some("codex-appserver")
    } else if protocol_version.starts_with("hermes/") {
        Some("hermes")
    } else if protocol_version.starts_with("acp/")
        || protocol_version.starts_with("claude-code-stream-json/")
    {
        Some("claude-stream-json")
    } else {
        None
    }
}

fn session_driver_terminal_event(envelopes: &[SessionEnvelope]) -> Option<&'static str> {
    for envelope in envelopes.iter().rev() {
        if envelope.kind != SessionEventKind::DriverEvent {
            continue;
        }
        match envelope.event.get("type").and_then(Value::as_str) {
            Some("run_complete") => return Some("run_complete"),
            Some("run_fail") | Some("run_error") => return Some("run_fail"),
            _ => {}
        }
    }
    None
}

fn release_outcome(envelope: &orgasmic_core::SessionEnvelope) -> Option<ReleaseOutcome> {
    if envelope.kind != SessionEventKind::Lifecycle {
        return None;
    }
    let lifecycle: Lifecycle = serde_json::from_value(envelope.event.clone()).ok()?;
    match lifecycle {
        Lifecycle::Release { outcome, .. } => Some(outcome),
        _ => None,
    }
}

#[derive(Debug, Deserialize)]
pub struct RestartRequest {
    #[serde(default)]
    pub reason: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
    /// Retained for old clients. Controlled restart is recovery-aware and no
    /// longer refuses live manager runs; stale leases are still cleared through
    /// the lease-release endpoint, not by restart.
    #[serde(default)]
    pub force: bool,
}

/// orgasmic:TASK-WGXKD.2 — `Deserialize` too, because the CLI's lifecycle stop
/// now PARSES this instead of dropping the response on the floor. An untyped
/// warning nobody reads is not a report.
#[derive(Debug, Serialize, Deserialize)]
pub struct RestartResponse {
    pub status: String,
    pub boot_id: String,
    pub acquisition_paused: bool,
    #[serde(default)]
    pub warnings: Vec<RestartWarning>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct RestartWarning {
    pub kind: String,
    pub pending_writes: usize,
    pub message: String,
    /// Runs this warning is about, when it has that identity (TASK-WGXKD.2).
    /// An operator cannot rescue "1 pending write"; they can rescue a run id.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub run_ids: Vec<String>,
}

/// Ceiling on the writer drain barrier placed after the release drain. The two
/// together are the budget every shutdown client must outlast (TASK-WGXKD.2).
pub const RESTART_WRITER_DRAIN_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);

/// Capability token for "this daemon writes a worker's terminal tx as part of
/// the release itself" (TASK-WGXKD).
///
/// It exists because `dispatch finalize` cannot discover this after the fact:
/// on stdio the release reaps the finalize process's own group, so there is
/// no client left to observe the response, let alone run a fallback. The probe
/// therefore has to complete BEFORE the release call.
pub const CAPABILITY_RELEASE_TERMINAL_TX: &str = "release.terminal_tx";

#[derive(Debug, Serialize)]
pub struct CapabilitiesResponse {
    pub capabilities: Vec<&'static str>,
}

/// Pre-flight handshake surface. A daemon older than TASK-WGXKD has no such
/// route at all and answers 404, which is exactly the signal a client needs:
/// absence of the route means absence of the guarantee.
async fn get_capabilities() -> Json<CapabilitiesResponse> {
    Json(CapabilitiesResponse {
        capabilities: vec![CAPABILITY_RELEASE_TERMINAL_TX],
    })
}

async fn post_daemon_restart(
    State(state): State<ApiState>,
    Json(_req): Json<RestartRequest>,
) -> Result<Json<RestartResponse>, ApiError> {
    let live_managers: Vec<String> = state
        .supervisor
        .snapshot()
        .await
        .runs
        .iter()
        .filter(|run| crate::supervisor::is_interactive_manager_task(&run.task_id))
        .map(|run| run.run_id.clone())
        .collect();
    state.supervisor.pause_acquisition().await;
    let mut warnings = Vec::new();
    if !live_managers.is_empty() {
        warnings.push(RestartWarning {
            kind: "live_manager_recovery".to_string(),
            pending_writes: 0,
            message: format!(
                "live manager run(s) {} will be reattached on next boot when the driver can prove the runtime is still live; otherwise they remain visible through run recovery",
                live_managers.join(", ")
            ),
            run_ids: live_managers,
        });
    }
    // orgasmic:TASK-WGXKD.1 — ORDER IS THE FIX. Outstanding release
    // finalizations must be awaited BEFORE the writer drain barrier is placed,
    // because the barrier only proves that work already enqueued in the writer
    // has landed. A release still in driver teardown has not reached
    // `append_tx_request` yet, so a barrier placed first passes, the writer
    // stops, and the terminal tx is lost — a graceful-restart loss, distinct
    // from the accepted daemon-crash gap. Swapping these two lines reproduces
    // the bug.
    warnings.extend(drain_release_finalizations(&state).await);
    warnings.extend(drain_writer_before_restart(&state).await?);
    Ok(Json(RestartResponse {
        status: "restart_requested".to_string(),
        boot_id: state.boot.boot_id.clone(),
        acquisition_paused: state.supervisor.snapshot().await.acquisition_paused,
        warnings,
    }))
}

/// Stop accepting new releases and wait for the ones in flight (TASK-WGXKD.1).
///
/// Closing is one-way, like `pause_acquisition` above it: a restart request is
/// a statement that this daemon is going away. A release arriving afterwards is
/// refused with 503 and its lease stays held, which is visible and retryable.
async fn drain_release_finalizations(state: &ApiState) -> Vec<RestartWarning> {
    state.release_tasks.close();
    let mut warnings = Vec::new();
    if let Err(outstanding) = state
        .release_tasks
        .wait_idle(RELEASE_FINALIZATION_DRAIN_TIMEOUT)
        .await
    {
        tracing::error!(
            outstanding = outstanding.len(),
            run_ids = %outstanding.join(", "),
            "release finalizations still in flight at restart; their terminal tx may be lost"
        );
        warnings.push(RestartWarning {
            kind: "release_finalization_timeout".to_string(),
            pending_writes: outstanding.len(),
            message: format!(
                "{} run release(s) had not finished writing their terminal tx after {}s; \
                 restarting now may leave them unreported. Rescue: \
                 `orgasmic recovery status`, then `orgasmic run recover <run_id>` \
                 for each run below.",
                outstanding.len(),
                RELEASE_FINALIZATION_DRAIN_TIMEOUT.as_secs()
            ),
            run_ids: outstanding,
        });
    }
    // orgasmic:TASK-WGXKD.2 finding 3 — a release whose task panicked, was
    // aborted, or failed at the append drains to zero like a healthy one. The
    // count says "clean"; only the retained outcome says which run is missing
    // its terminal tx.
    let lost = state.release_tasks.lost_finalizations();
    if !lost.is_empty() {
        warnings.push(RestartWarning {
            kind: "release_finalization_lost".to_string(),
            pending_writes: lost.len(),
            message: format!(
                "{} run release(s) ended WITHOUT their terminal tx on this daemon: {}. \
                 The lease is already gone, so nothing will retry them. Rescue: \
                 `orgasmic recovery status`, then `orgasmic run recover <run_id>`.",
                lost.len(),
                lost.iter()
                    .map(|entry| format!(
                        "{} ({}: {})",
                        entry.run_id,
                        entry
                            .terminal_tx_type
                            .as_deref()
                            .unwrap_or("no terminal tx"),
                        entry.reason
                    ))
                    .collect::<Vec<_>>()
                    .join("; ")
            ),
            run_ids: lost.iter().map(|entry| entry.run_id.clone()).collect(),
        });
    }
    warnings
}

async fn drain_writer_before_restart(state: &ApiState) -> Result<Vec<RestartWarning>, ApiError> {
    let marker = state
        .home
        .state()
        .join("writer-drain")
        .join(format!("restart-{}.marker", uuid::Uuid::new_v4().simple()));
    let request_id = format!("daemon-restart-drain/{}", uuid::Uuid::new_v4());
    let writer = state.writer.clone();
    let marker_for_task = marker.clone();
    let mut drain = tokio::spawn(async move {
        let result = writer
            .rewrite_file(
                FileRewrite {
                    path: marker_for_task.clone(),
                    new_contents: b"restart drain barrier\n".to_vec(),
                },
                Some(request_id),
            )
            .await;
        if result.is_ok() {
            let _ = tokio::fs::remove_file(&marker_for_task).await;
        }
        result
    });

    match tokio::time::timeout(RESTART_WRITER_DRAIN_TIMEOUT, &mut drain).await {
        Ok(Ok(Ok(()))) => Ok(Vec::new()),
        Ok(Ok(Err(e))) => Err(writer_drain_error("rewrite", e)),
        Ok(Err(e)) => Err(writer_drain_error("task", e)),
        Err(_) => {
            tokio::spawn(async move {
                let _ = drain.await;
            });
            Ok(vec![RestartWarning {
                kind: "writer_drain_timeout".to_string(),
                pending_writes: 1,
                message: "writer drain timed out; pending_writes is a proven lower bound"
                    .to_string(),
                run_ids: Vec::new(),
            }])
        }
    }
}

async fn get_whoami(State(state): State<ApiState>) -> Json<Value> {
    Json(json!({
        "authenticated": true,
        "boot_id": state.boot.boot_id,
    }))
}

/// `/graph/parse-errors` view: the raw `ParseError` plus the project it was
/// attributed to (TASK-V8WY9), so a caller never has to grep the daemon log
/// to learn which project owns a dangling reference or parse failure.
#[derive(Debug, Serialize)]
struct ParseErrorView {
    #[serde(skip_serializing_if = "Option::is_none")]
    project_id: Option<String>,
    path: PathBuf,
    kind: crate::index::ParseErrorKind,
    message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    line: Option<usize>,
    at: chrono::DateTime<Utc>,
}

fn parse_error_views(snap: &IndexSnapshot) -> Vec<ParseErrorView> {
    snap.parse_errors
        .iter()
        .map(|error| ParseErrorView {
            project_id: snap.parse_error_project_id(error).map(str::to_string),
            path: error.path.clone(),
            kind: error.kind.clone(),
            message: error.message.clone(),
            line: error.line,
            at: error.at,
        })
        .collect()
}

#[derive(Debug, Deserialize)]
pub struct ParseErrorsQuery {
    /// Explicit whole-board coverage request: materialize every registered
    /// project's core projection before reading the parse-error view, so
    /// identity diagnostics (duplicate ids, malformed mints, dangling
    /// references) reflect all projects rather than only loaded ones.
    /// Per-project load failures are surfaced through the coverage header's
    /// `failed=[...]` segment.
    #[serde(default)]
    pub full: bool,
}

async fn get_parse_errors(
    State(state): State<ApiState>,
    Query(q): Query<ParseErrorsQuery>,
) -> Response {
    if q.full {
        let project_ids: Vec<String> = state
            .index
            .snapshot()
            .await
            .board
            .into_iter()
            .map(|entry| entry.id)
            .collect();
        for project_id in project_ids {
            if let Err(error) = state.index.ensure_project_loaded(&project_id).await {
                tracing::warn!("full parse-error coverage skipped project {project_id}: {error}");
            }
        }
    }
    let snap = state.index.snapshot().await;
    let ready = snap.project_ids_in_state(ProjectLoadState::Ready);
    let unloaded = snap.project_ids_in_state(ProjectLoadState::Unloaded);
    let loading = snap.project_ids_in_state(ProjectLoadState::Loading);
    let delayed = snap.project_ids_in_state(ProjectLoadState::Delayed);
    let failed = snap.project_ids_in_state(ProjectLoadState::Failed);
    // Preserve the established header shape unless there is an actual queue
    // delay to report. The diagnostic remains additive without making empty
    // delayed state a wire-visible compatibility change.
    let delayed_segment = if delayed.is_empty() {
        String::new()
    } else {
        format!("; delayed=[{}]", coverage_project_ids(&delayed))
    };
    let coverage = format!(
        "{}; ready={}/{}; unloaded=[{}]; loading=[{}]{}; failed=[{}]",
        if ready.len() == snap.board.len() {
            "complete"
        } else {
            "partial"
        },
        ready.len(),
        snap.board.len(),
        coverage_project_ids(&unloaded),
        coverage_project_ids(&loading),
        delayed_segment,
        coverage_project_ids(&failed),
    );
    let mut response = Json(parse_error_views(&snap)).into_response();
    let coverage = HeaderValue::from_str(&coverage)
        .unwrap_or_else(|_| HeaderValue::from_static("partial; invalid-project-id"));
    response
        .headers_mut()
        .insert("x-orgasmic-project-coverage", coverage);
    response
}

fn coverage_project_ids(project_ids: &[String]) -> String {
    project_ids
        .iter()
        .map(|project_id| {
            let mut encoded = String::new();
            for byte in project_id.bytes() {
                if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
                    encoded.push(char::from(byte));
                } else {
                    encoded.push_str(&format!("%{byte:02X}"));
                }
            }
            encoded
        })
        .collect::<Vec<_>>()
        .join(",")
}

/// `orgasmic reindex [--project <id>]` response (TASK-V8WY9): fresh
/// per-project parse-error counts after forcing a rebuild, so a battle-tester
/// can confirm a fix without a daemon restart.
#[derive(Debug, Serialize)]
struct ReindexResponse {
    projects: BTreeMap<String, usize>,
    total_parse_errors: usize,
    failures: BTreeMap<String, String>,
}

fn reindex_response(snap: &IndexSnapshot, failures: BTreeMap<String, String>) -> ReindexResponse {
    ReindexResponse {
        projects: snap.parse_error_counts_by_project(),
        total_parse_errors: snap.parse_errors.len(),
        failures,
    }
}

async fn post_reindex(State(state): State<ApiState>) -> Result<Json<ReindexResponse>, ApiError> {
    let project_ids = state
        .index
        .snapshot()
        .await
        .board
        .into_iter()
        .map(|entry| entry.id)
        .collect::<Vec<_>>();
    let mut failures = BTreeMap::new();
    for project_id in project_ids {
        if let Err(error) = force_reindex_project(&state, &project_id).await {
            failures.insert(project_id, error.message);
        }
    }
    let snap = state.index.snapshot().await;
    Ok(Json(reindex_response(&snap, failures)))
}

async fn force_reindex_project(state: &ApiState, project_id: &str) -> Result<(), ApiError> {
    let catalog = state.index.snapshot().await;
    select_catalog_project_id(&catalog, Some(project_id))?;
    drop(catalog);
    state
        .index
        .refresh_project(project_id)
        .await
        .map_err(|error| {
            ApiError::unavailable(format!("project {project_id} reindex failed: {error}"))
        })?;
    state
        .index
        .ensure_project_artifacts_loaded(project_id)
        .await
        .map_err(|error| ApiError::unavailable(format!("artifact reindex failed: {error}")))?;
    let snap = state.index.snapshot().await;
    if let Some(project) = snap.project(project_id) {
        state
            .index
            .spawn_repo_url_reprobe_for(project_id.to_string(), project.root.clone());
    }
    Ok(())
}

async fn post_reindex_project(
    State(state): State<ApiState>,
    Path(project_id): Path<String>,
) -> Result<Json<ReindexResponse>, ApiError> {
    force_reindex_project(&state, &project_id).await?;
    let snap = state.index.snapshot().await;
    Ok(Json(reindex_response(&snap, BTreeMap::new())))
}

#[derive(Debug, Deserialize)]
pub struct OrgFileQuery {
    #[serde(default)]
    pub project: Option<String>,
    pub path: String,
}

#[derive(Debug, Deserialize)]
pub struct OrgFileWriteRequest {
    #[serde(default)]
    pub project: Option<String>,
    pub path: String,
    pub contents: String,
    #[serde(default)]
    pub request_id: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct OrgFileResponse {
    pub project: String,
    pub path: String,
    pub contents: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tx_id: Option<String>,
}

async fn get_org_file(
    State(state): State<ApiState>,
    Query(q): Query<OrgFileQuery>,
) -> Result<Json<OrgFileResponse>, ApiError> {
    let rel = validate_org_edit_path(&q.path)?;
    if rel == FsPath::new(".orgasmic/architecture.org") {
        return Err(ApiError::not_found("org file not found"));
    }
    let rel_str = rel.to_string_lossy().to_string();
    let (project_id, snap) = ensure_loaded_snapshot(&state, q.project.as_deref()).await?;
    let project = select_loaded_project(&snap, &project_id)?;
    let path = project.root.join(&rel);
    let label = org_file_artifact_label(&rel);
    let contents = read_artifact(&path, label)?;
    Ok(Json(OrgFileResponse {
        project: project.project_id.clone(),
        path: rel_str,
        contents,
        tx_id: None,
    }))
}

async fn post_org_file(
    State(state): State<ApiState>,
    Json(req): Json<OrgFileWriteRequest>,
) -> Result<Json<OrgFileResponse>, ApiError> {
    let rel = validate_org_edit_path(&req.path)?;
    reject_ledger_rewrite(&rel)?;
    let rel_str = rel.to_string_lossy().to_string();
    OrgFile::parse(req.contents.clone(), rel_str.clone())
        .map_err(|e| org_input_parse_error(FsPath::new(&rel_str), e))?;
    let (resolved_project_id, snap) =
        ensure_loaded_snapshot(&state, req.project.as_deref()).await?;
    let project = select_loaded_project(&snap, &resolved_project_id)?;
    let project_id = project.project_id.clone();
    let path = project.root.join(&rel);
    drop(snap);
    state
        .writer
        .rewrite_file(
            FileRewrite {
                path: path.clone(),
                new_contents: req.contents.clone().into_bytes(),
            },
            req.request_id.as_ref().map(|id| format!("{id}/rewrite")),
        )
        .await
        .map_err(|e| writer_rewrite_error(&path, e))?;
    let tx_id = record_api_tx_after_project_mutation(
        &state,
        ApiTxRequest {
            ty: "org.file_rewritten".to_string(),
            actor: None,
            project: Some(project_id.clone()),
            task: None,
            target: Some(rel_str.clone()),
            reason: "org file rewrite requested".to_string(),
            request_id: req.request_id.map(|id| format!("{id}/tx")),
            extra: Vec::new(),
        },
        Some(&project_id),
    )
    .await?;
    state.events.publish(
        Topic::Graph,
        EventPayload::GraphChanged {
            node_id: path.display().to_string(),
        },
    );
    Ok(Json(OrgFileResponse {
        project: project_id,
        path: rel_str,
        contents: req.contents,
        tx_id: Some(tx_id),
    }))
}

fn validate_org_edit_path(path: &str) -> Result<PathBuf, ApiError> {
    let rel = PathBuf::from(path);
    if rel.is_absolute()
        || !rel
            .components()
            .all(|component| matches!(component, Component::Normal(_)))
    {
        return Err(ApiError::bad_request("org file path must be relative"));
    }
    if rel.extension().and_then(|ext| ext.to_str()) != Some("org") {
        return Err(ApiError::bad_request("org file path must end in .org"));
    }
    if !(rel.starts_with(".orgasmic") || rel.starts_with("docs/adr")) {
        return Err(ApiError::bad_request(
            "org file path must be under .orgasmic/ or docs/adr/",
        ));
    }
    Ok(rel)
}

/// The generic org-file rewrite surface must never touch an append-only
/// ledger: a whole-file rewrite can silently erase committed history that the
/// writer's append path goes to great lengths to keep durable. Reads stay
/// open; only `post_org_file` calls this.
fn reject_ledger_rewrite(rel: &FsPath) -> Result<(), ApiError> {
    if rel.starts_with(".orgasmic/tx") {
        return Err(ApiError::bad_request(
            "org file path is an append-only tx ledger; append entries through the tx surface instead of rewriting the file",
        ));
    }
    Ok(())
}

fn org_file_artifact_label(relative_path: &FsPath) -> &'static str {
    match relative_path.file_name().and_then(|s| s.to_str()) {
        Some("decisions.org") => "decisions file",
        Some("glossary.org") => "glossary file",
        Some(name) if relative_path.starts_with("docs/adr") && name.ends_with(".org") => "ADR file",
        Some(name) if name.starts_with("adr-") && name.ends_with(".org") => "ADR file",
        _ => "org file",
    }
}

async fn get_graph_nodes(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Query(q): Query<GraphQuery>,
) -> Result<Json<Vec<crate::index::GraphNodeSummary>>, ApiError> {
    let (project_id, snap) =
        resolve_authorized_project(&state, &identity, q.project.as_deref(), Action::GraphRead)
            .await?;
    let project = select_loaded_project(&snap, &project_id)?;
    Ok(Json(project.graph.nodes.clone()))
}

async fn get_graph_edges(
    State(state): State<ApiState>,
    Extension(identity): Extension<Identity>,
    Query(q): Query<GraphEdgesQuery>,
) -> Result<Json<Vec<crate::index::GraphEdgeSummary>>, ApiError> {
    let (project_id, snap) =
        resolve_authorized_project(&state, &identity, q.project.as_deref(), Action::GraphRead)
            .await?;
    let project = select_loaded_project(&snap, &project_id)?;
    let graph = &project.graph;
    let (relation_kind, dir_from_relation) = graph_relation_filter(q.relation.as_deref())?;
    // A relation alias already fixes both kind and direction; reject a
    // conflicting explicit kind/dir rather than silently overriding the
    // alias's intent (VJXXC reviewer NIT). A redundant matching value is fine.
    if q.relation.is_some() {
        if let (Some(explicit), Some(want)) = (q.kind.as_deref(), relation_kind) {
            if explicit != want {
                return Err(ApiError::bad_request(format!(
                    "relation implies kind {want}; drop --kind or make it match"
                )));
            }
        }
        if let (Some(explicit), Some(want)) = (q.dir.as_deref(), dir_from_relation) {
            if explicit != want {
                return Err(ApiError::bad_request(format!(
                    "relation implies dir {want}; drop --dir or make it match"
                )));
            }
        }
    }
    let kind = q.kind.as_deref().or(relation_kind);
    let dir = q.dir.as_deref().or(dir_from_relation).unwrap_or("out");
    if dir != "out" && dir != "in" && dir != "both" {
        return Err(ApiError::bad_request(
            "graph edge dir must be one of out, in, both",
        ));
    }
    let edges = graph
        .edges
        .iter()
        .filter(|edge| kind.is_none_or(|want| edge.kind == want))
        .filter(|edge| {
            q.node.as_deref().is_none_or(|node| match dir {
                "out" => edge.from == node,
                "in" => edge.to == node,
                "both" => edge.from == node || edge.to == node,
                _ => false,
            })
        })
        .cloned()
        .collect();
    Ok(Json(edges))
}

fn graph_relation_filter(
    relation: Option<&str>,
) -> Result<(Option<&'static str>, Option<&'static str>), ApiError> {
    let Some(relation) = relation else {
        return Ok((None, None));
    };
    match relation {
        "depends_on" | "blocked_by" => Ok((Some("depends_on"), Some("out"))),
        "blocks" => Ok((Some("depends_on"), Some("in"))),
        "implements" => Ok((Some("implements"), Some("out"))),
        "implemented_by" => Ok((Some("implements"), Some("in"))),
        "produces" => Ok((Some("produces"), Some("out"))),
        "produced_by" => Ok((Some("produces"), Some("in"))),
        "motivated_by" => Ok((Some("motivated_by"), Some("out"))),
        "motivates" => Ok((Some("motivated_by"), Some("in"))),
        other => Err(ApiError::bad_request(format!(
            "unknown graph edge relation {other:?}"
        ))),
    }
}

