#[derive(Debug, Deserialize)]
pub struct NodeEditRequest {
    #[serde(default)]
    pub project: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
    /// Explicit layer selector; see [`NodeQuery::kind`].
    #[serde(default)]
    pub kind: Option<String>,
    pub base_version: String,
    pub ops: Vec<NodeEditOp>,
    /// Skip the write-time reference-token check (dec_4T80X) for intentional
    /// forward references. The index-time dangling lint still catches it.
    #[serde(default)]
    pub force: bool,
}

/// FNV-1a/64 over the bytes, as 16-char lowercase hex. Dependency-free and
/// MSRV-safe; used only as an opaque optimistic-concurrency token.
fn content_hash(bytes: &[u8]) -> String {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &b in bytes {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x0000_0100_0000_01B3);
    }
    format!("{hash:016x}")
}

/// Display title with the leading id token stripped (`dec_001 Foo` → `Foo`)
/// when the heading actually has that token. Tokenless drifted headings still
/// display their full title so a repair edit does not hide the bad state.
fn node_display_title(heading: &Heading) -> String {
    let Some(id) = heading.property("ID") else {
        return heading.title.trim().to_string();
    };
    heading
        .title
        .strip_prefix(id)
        .map(str::trim)
        .unwrap_or_else(|| heading.title.trim())
        .to_string()
}

// orgasmic:task_XPYRR
/// Reject a display title the heading line cannot hold before composing
/// anything, so the operator gets the reason rather than a round-trip
/// diagnostic. Everything subtler than this — a trailing `:tag:` shape, whose
/// legality depends on whether a tag run already anchors the line end — is
/// left to the rewriter's round-trip guard, which decides it by measurement
/// instead of by pattern.
fn validate_node_title(title: &str) -> Result<(), ApiError> {
    let title = title.trim();
    if title.is_empty() {
        return Err(ApiError::bad_request(
            "title must not be empty; a node heading carries its id token and its prose",
        ));
    }
    if title.contains(['\n', '\r']) {
        return Err(ApiError::bad_request(
            "title must be a single line; a newline would split the heading",
        ));
    }
    Ok(())
}

// orgasmic:task_XPYRR
/// Describe a node's title-line edit: the display title recomposed with its id
/// token, plus the tags only when the caller actually asked to change them.
/// Tags left as `None` are preserved by [`OrgRewriter::edit_heading_line`] —
/// deliberately not restated here, so a title write has no way to touch them.
fn node_heading_line_edit(
    heading: &Heading,
    new_title: Option<&str>,
    new_tags: Option<&[String]>,
) -> HeadingLineEdit {
    let drawer_id = heading.property("ID").unwrap_or(heading.title.as_str());
    let current_display = heading
        .title
        .strip_prefix(drawer_id)
        .map(str::trim)
        .unwrap_or_else(|| heading.title.trim());
    let display = new_title.map(str::trim).unwrap_or(current_display);
    let title = if display.is_empty() {
        drawer_id.to_string()
    } else {
        format!("{drawer_id} {display}")
    };
    HeadingLineEdit {
        title: Some(title),
        tags: new_tags.map(<[String]>::to_vec),
    }
}

// orgasmic:task_ZYWZD
/// Map nested headings to [`NodeSection`]s, recursively, so no depth of the
/// node's body is hidden from a reader.
fn node_sections(file: &OrgFile, sections: &[Heading]) -> Vec<NodeSection> {
    sections
        .iter()
        .map(|s| NodeSection {
            title: s.title.clone(),
            body: file.slice(s.body.clone()).trim_end().to_string(),
            sections: node_sections(file, &s.sections),
        })
        .collect()
}

fn org_node_doc(
    file: &OrgFile,
    heading: &Heading,
    layer: NodeLayer,
    source_file: String,
) -> NodeDoc {
    let properties = heading
        .property_entries()
        .map(|e| NodeProperty {
            key: e.key.clone(),
            value: e.value.clone(),
        })
        .collect();
    let sections = node_sections(file, &heading.sections);
    NodeDoc {
        id: heading.property("ID").unwrap_or_default().to_string(),
        kind: layer.layer_name().to_string(),
        title: node_display_title(heading),
        todo: heading.todo.clone(),
        tags: heading.tags.clone(),
        body: file.slice(heading.body.clone()).trim().to_string(),
        properties,
        sections,
        source: NodeSource {
            file: source_file,
            base_version: content_hash(file.slice(heading.span.clone()).as_bytes()),
        },
    }
}

/// Pick the layer that owns a node: an explicit `kind` selector when present,
/// otherwise inferred from the id prefix.
fn resolve_node_layer(kind: Option<&str>, id: &str) -> Result<NodeLayer, ApiError> {
    match kind {
        Some(kind) => NodeLayer::from_kind(kind)
            .ok_or_else(|| ApiError::bad_request(format!("unknown node kind {kind}"))),
        None => NodeLayer::for_id(id)
            .ok_or_else(|| ApiError::bad_request("architecture node layer is retired")),
    }
}

fn display_node_source_path(project_root: &FsPath, path: &FsPath) -> String {
    path.strip_prefix(project_root)
        .unwrap_or(path)
        .to_string_lossy()
        .to_string()
}

async fn org_node_path(
    state: &ApiState,
    project: Option<&str>,
    id: &str,
    layer: NodeLayer,
) -> Result<(String, PathBuf, String), ApiError> {
    let (project_id, snap) = ensure_loaded_snapshot(state, project).await?;
    let project = select_loaded_project(&snap, &project_id)?;
    match layer {
        NodeLayer::Task => {
            let task = project
                .tasks
                .iter()
                .find(|task| task.id == id)
                .ok_or_else(|| ApiError::not_found(format!("node {id}")))?;
            let path = task.source_file.clone();
            let source_file = display_node_source_path(&project.root, &path);
            Ok((project.project_id.clone(), path, source_file))
        }
        NodeLayer::Goal => {
            let path = goal_file_path(&project.root);
            let source_file = display_node_source_path(&project.root, &path);
            Ok((project.project_id.clone(), path, source_file))
        }
        NodeLayer::Handoff => {
            let path = handoff_file_path(&project.root);
            let source_file = display_node_source_path(&project.root, &path);
            Ok((project.project_id.clone(), path, source_file))
        }
        _ => {
            let file_name = layer
                .file_name()
                .expect("non-task node layers have fixed .org files");
            Ok((
                project.project_id.clone(),
                project.root.join(".orgasmic").join(file_name),
                format!(".orgasmic/{file_name}"),
            ))
        }
    }
}

async fn get_org_node(
    State(state): State<ApiState>,
    Query(q): Query<NodeQuery>,
) -> Result<Json<NodeDoc>, ApiError> {
    let layer = resolve_node_layer(q.kind.as_deref(), &q.id)?;
    let (_project_id, path, source_file) =
        org_node_path(&state, q.project.as_deref(), &q.id, layer).await?;
    let source = read_artifact(&path, layer.artifact_name())?;
    let file = OrgFile::parse(source, path.to_string_lossy())
        .map_err(|e| org_parse_bad_request(&path, layer.artifact_name(), e))?;
    let heading = file
        .find_by_id(&q.id)
        .ok_or_else(|| ApiError::not_found(format!("node {}", q.id)))?;
    Ok(Json(org_node_doc(&file, heading, layer, source_file)))
}

async fn post_org_node_edit(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Query(q): Query<MutationOutputQuery>,
    Json(req): Json<NodeEditRequest>,
) -> Result<Json<serde_json::Value>, ApiError> {
    let layer = resolve_node_layer(req.kind.as_deref(), &id)?;
    if layer == NodeLayer::Goal {
        return Err(ApiError::bad_request(
            "goal nodes are read-only through /org/node; use goal set/clear/supersede",
        ));
    }
    // orgasmic:task_ZKZBF
    // The same drawer every task write validates (TASK-HXSW0): a key that is
    // not its own uppercase is stored and never read, because
    // `Heading::property` compares byte for byte. `node prop set/unset` passed
    // keys through untyped, so `node prop set TASK-… priority P1` returned a
    // success object while the priority stayed unset — the exact silent-drop
    // shape TASK-HXSW0 fixed on task create/update, still live on this route.
    for op in &req.ops {
        let (key, value) = match op {
            NodeEditOp::SetProperty { key, value } => (key.as_str(), Some(value.as_str())),
            NodeEditOp::RemoveProperty { key } => (key.as_str(), None),
            _ => continue,
        };
        match layer {
            NodeLayer::Task => {
                if let Some(value) = value {
                    // Update-shaped verb: keys that only `task update` writes
                    // (BLOCKED_BY, FIX_SUBTASK, KIND) are legal here, same as
                    // `task update --property`.
                    let mut properties = BTreeMap::new();
                    properties.insert(key.to_string(), value.to_string());
                    validate_task_property_keys(&properties, &[])?;
                } else {
                    validate_drawer_property_key_case(
                        key,
                        "Task",
                        TASK_SCHEMA_PROPERTY_KEYS,
                        None,
                    )?;
                    // orgasmic:task_ZKZBF.1 — unset-shaped advice: this command
                    // has no `--property` flag, so the set-verb's
                    // "`--property KEY=…` is refused" phrasing would describe a
                    // flag the caller never passed.
                    //
                    // orgasmic:task_ZKZBF.2 — and the unset half consults its
                    // OWN table: only door-owned keys (STATE) refuse removal;
                    // dead keys (PARENT_TASK, LAST_UPDATED) are exactly the
                    // legacy lines this verb exists to clean up.
                    let canonical = key.trim().to_ascii_uppercase();
                    if let Some(refusal) = task_property_key_unset_refusal_reason(&canonical) {
                        return Err(ApiError::bad_request(format!(
                            "unsetting `{canonical}` is refused: {refusal}"
                        )));
                    }
                }
            }
            other => {
                validate_drawer_property_key_case(
                    key,
                    // orgasmic:task_ZKZBF — capitalized for the refusal sentence.
                    node_layer_label(other),
                    node_layer_schema_property_keys(other),
                    value,
                )?;
            }
        }
    }
    let (project_id, path, source_file) =
        org_node_path(&state, req.project.as_deref(), &id, layer).await?;
    if !req.force {
        let known_ids = known_reference_ids(&state, &project_id).await?;
        for op in &req.ops {
            if let NodeEditOp::SetProperty { key, value } = op {
                // Decision PARENT already has dedicated existence/class/cycle
                // validation below (validate_decision_parent_ops); don't
                // double-reject it here with a weaker generic check.
                if layer == NodeLayer::Decision && key == "PARENT" {
                    continue;
                }
                reject_unresolved_reference_token(&known_ids, key, value)?;
            }
        }
    }
    let source = read_artifact(&path, layer.artifact_name())?;
    let file = OrgFile::parse(source, path.to_string_lossy())
        .map_err(|e| org_parse_bad_request(&path, layer.artifact_name(), e))?;
    let heading = file
        .find_by_id(&id)
        .ok_or_else(|| ApiError::not_found(format!("node {id}")))?;

    // Optimistic concurrency: reject if the on-disk node drifted since read.
    let current_version = content_hash(file.slice(heading.span.clone()).as_bytes());
    if current_version != req.base_version {
        return Err(ApiError::conflict(format!(
            "node {id} changed on disk; reload before editing"
        )));
    }

    let parent_changed = if layer == NodeLayer::Decision {
        validate_decision_parent_ops(&file, &id, &req.ops)?
    } else {
        false
    };

    let mut rw = OrgRewriter::new(&file, path.to_string_lossy());
    let mut title_override: Option<String> = None;
    let mut tags_override: Option<Vec<String>> = None;
    let mut changed: BTreeMap<String, String> = BTreeMap::new();
    for op in req.ops {
        match op {
            NodeEditOp::SetBody { body, body_format } => {
                let body = prepare_body_edit(&body, body_format);
                reject_body_with_nested_headings("node body set", &body)?;
                rw.set_node_body(&id, &body)
                    .map_err(|e| org_rewriter_error("set body", &id, e))?;
                changed.insert("body".to_string(), body);
            }
            // orgasmic:TASK-CB6GQ
            // These two were one arm, both falling through to
            // `upsert_section_text`, which appends when the section is missing.
            // That made every section write a potential section *creation*: a
            // typo, or a section name borrowed from another node kind, minted a
            // permanent heading and nothing said so. `handoff-current` carries a
            // task-shaped `Description` stub that arrived exactly this way.
            // Editing and creating are now distinct, as the op names always
            // claimed.
            NodeEditOp::SetSectionBody {
                title,
                body,
                body_format,
            } => {
                let body = prepare_body_edit(&body, body_format);
                reject_body_with_nested_headings("node body set --section", &body)?;
                if !rw
                    .has_section(&id, &title)
                    .map_err(|e| org_rewriter_error("edit section", &id, e))?
                {
                    return Err(unknown_section_error(&rw, &id, &title, SECTION_WRITE_HINT));
                }
                rw.upsert_section_text(&id, &title, &body)
                    .map_err(|e| org_rewriter_error("edit section", &id, e))?;
                changed.insert(format!("section:{title}"), body);
            }
            NodeEditOp::AddSection {
                title,
                body,
                body_format,
            } => {
                let body = prepare_body_edit(&body, body_format);
                reject_body_with_nested_headings("node body set --section --create", &body)?;
                // Idempotent on purpose: `--create` is a statement of intent
                // ("a section by this name should exist and hold this"), not a
                // claim about the current file, so replaying it is safe.
                rw.upsert_section_text(&id, &title, &body)
                    .map_err(|e| org_rewriter_error("create section", &id, e))?;
                changed.insert(format!("section:{title}"), body);
            }
            NodeEditOp::RemoveSection { title } => {
                // orgasmic:TASK-CB6GQ — the rewriter refuses an absent section
                // with `SectionNotFound`, which `org_rewriter_error` renders as
                // a bare "org file update failed". That is the silence this
                // suite exists to remove (TASK-ZYWZD), so name the section and
                // list what the node actually has, exactly as a write does.
                if !rw
                    .has_section(&id, &title)
                    .map_err(|e| org_rewriter_error("remove section", &id, e))?
                {
                    return Err(unknown_section_error(&rw, &id, &title, SECTION_REMOVE_HINT));
                }
                rw.remove_section(&id, &title)
                    .map_err(|e| org_rewriter_error("remove section", &id, e))?;
                changed.insert(format!("section:{title}"), "<removed>".to_string());
            }
            NodeEditOp::SetProperty { key, value } => {
                rw.upsert_property(&id, &key, &value)
                    .map_err(|e| org_rewriter_error("set property", &id, e))?;
                changed.insert(key, value);
            }
            NodeEditOp::RemoveProperty { key } => {
                rw.remove_property(&id, &key).map_err(|e| match e {
                    // orgasmic:task_ZKZBF — this refusal names the key, file and
                    // heading; collapsing it into "org file update failed"
                    // hid the one fact (the exact spelling it looked for) that
                    // explained why `node prop unset <id> priority` failed
                    // while `:PRIORITY:` sat in the drawer.
                    // orgasmic:task_ZKZBF.1 — and the Display string itself
                    // carries the absolute file path, which the API never
                    // discloses; the path stays in this warn, the body names
                    // the node and its actual keys instead.
                    e @ orgasmic_core::OrgError::PropertyNotFound { .. } => {
                        tracing::warn!(node_id = %id, error = %e, "remove property refused");
                        unknown_property_error(heading, &id, &key)
                    }
                    e => org_rewriter_error("remove property", &id, e),
                })?;
                changed.insert(key, "<removed>".to_string());
            }
            NodeEditOp::SetTitle { title } => {
                validate_node_title(&title)?;
                changed.insert("title".to_string(), title.clone());
                title_override = Some(title);
            }
            NodeEditOp::SetTags { tags } => {
                changed.insert("tags".to_string(), tags.join(" "));
                tags_override = Some(tags);
            }
        }
    }
    if title_override.is_some() || tags_override.is_some() {
        // orgasmic:task_XPYRR
        let edit =
            node_heading_line_edit(heading, title_override.as_deref(), tags_override.as_deref());
        rw.edit_heading_line(&id, &edit).map_err(|e| match e {
            // The one rewriter failure an operator can act on: it names the
            // title they submitted and what Org would have stored instead.
            // Collapsing it into "org file update failed" would leave them
            // with a refusal and no way to tell what to change.
            e @ orgasmic_core::OrgError::HeadingRoundTripLoss { .. } => {
                tracing::warn!(node_id = %id, error = %e, "title edit refused");
                ApiError::bad_request(e.to_string())
            }
            e => org_rewriter_error("set title line", &id, e),
        })?;
    }

    let updated = rw.finish();
    OrgFile::parse(updated.clone(), path.to_string_lossy())
        .map_err(|e| org_parse_bad_request(&path, layer.artifact_name(), e))?;
    let tx_id = write_org_node_edit_and_record(NodeEditWriteRequest {
        state: &state,
        layer,
        project_id: project_id.clone(),
        path: path.clone(),
        source: updated,
        request_id: req.request_id,
        node_id: id.clone(),
        action: if parent_changed { "reparent" } else { "edited" },
    })
    .await?;

    // Re-read so the response carries the fresh base_version.
    let fresh = read_artifact(&path, layer.artifact_name())?;
    let file = OrgFile::parse(fresh, path.to_string_lossy())
        .map_err(|e| org_parse_internal(&path, layer.artifact_name(), e))?;
    let heading = file
        .find_by_id(&id)
        .ok_or_else(|| ApiError::not_found(format!("node {id}")))?;
    let doc = org_node_doc(&file, heading, layer, source_file);
    let compact = CompactMutationResponse {
        id: id.clone(),
        changed,
        tx_id,
        status: None,
    };
    compact_or_full_response(q.json, compact, doc)
}

#[derive(Debug, Deserialize)]
pub struct NodeDeleteRequest {
    #[serde(default)]
    pub project: Option<String>,
    #[serde(default)]
    pub request_id: Option<String>,
    /// Explicit layer selector; see [`NodeQuery::kind`].
    #[serde(default)]
    pub kind: Option<String>,
    pub base_version: String,
}

/// Delete one org node through the writer transaction (TASK-N4TGD).
/// Decision deletes reuse the existing child-guard semantics.
async fn post_org_node_delete(
    State(state): State<ApiState>,
    Path(id): Path<String>,
    Query(q): Query<MutationOutputQuery>,
    Json(req): Json<NodeDeleteRequest>,
) -> Result<Json<serde_json::Value>, ApiError> {
    // orgasmic:TASK-N4TGD
    let layer = resolve_node_layer(req.kind.as_deref(), &id)?;
    match layer {
        NodeLayer::Task => {
            return Err(ApiError::bad_request(
                "task deletion is not implemented through /org/node; task-specific delete semantics are required",
            ));
        }
        NodeLayer::Goal => {
            return Err(ApiError::bad_request(
                "goal nodes cannot be deleted through /org/node; use goal clear/supersede",
            ));
        }
        NodeLayer::Project => {
            return Err(ApiError::bad_request(
                "project nodes cannot be deleted through /org/node",
            ));
        }
        NodeLayer::Handoff => {
            return Err(ApiError::bad_request(
                "handoff nodes cannot be deleted through /org/node",
            ));
        }
        _ => {}
    }
    let (project_id, path, _source_file) =
        org_node_path(&state, req.project.as_deref(), &id, layer).await?;
    let source = read_artifact(&path, layer.artifact_name())?;
    let file = OrgFile::parse(source, path.to_string_lossy())
        .map_err(|e| org_parse_bad_request(&path, layer.artifact_name(), e))?;
    let heading = file
        .find_by_id(&id)
        .ok_or_else(|| ApiError::not_found(format!("node {id}")))?;
    let current_version = content_hash(file.slice(heading.span.clone()).as_bytes());
    if current_version != req.base_version {
        return Err(ApiError::conflict(format!(
            "node {id} changed on disk; reload before deleting"
        )));
    }
    let inbound = inbound_reference_owners(&project_id, &id, &state).await?;
    if !inbound.is_empty() {
        return Err(ApiError::bad_request(format!(
            "node {id} still has inbound references from {}; remove or redirect them before deleting",
            inbound.join(", ")
        )));
    }
    if layer == NodeLayer::Decision && decision_has_children(&file, &id)? {
        return Err(ApiError::bad_request(format!(
            "decision {id} still has child decisions; re-parent or delete children first"
        )));
    }
    let mut rw = OrgRewriter::new(&file, path.to_string_lossy());
    rw.remove_heading(&id)
        .map_err(|e| org_rewriter_error("remove heading", &id, e))?;
    let updated = rw.finish();
    OrgFile::parse(updated.clone(), path.to_string_lossy())
        .map_err(|e| org_parse_bad_request(&path, layer.artifact_name(), e))?;
    let tx_id = write_org_node_edit_and_record(NodeEditWriteRequest {
        state: &state,
        layer,
        project_id: project_id.clone(),
        path: path.clone(),
        source: updated,
        request_id: req.request_id,
        node_id: id.clone(),
        action: "deleted",
    })
    .await?;
    let mut changed = BTreeMap::new();
    changed.insert("deleted".to_string(), "true".to_string());
    let compact = CompactMutationResponse {
        id: id.clone(),
        changed,
        tx_id,
        status: None,
    };
    // Full output is just the compact shape: the node no longer exists.
    compact_or_full_response(q.json, compact, compact_or_delete_full(&id))
}

async fn inbound_reference_owners(
    project_id: &str,
    target_id: &str,
    state: &ApiState,
) -> Result<Vec<String>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(state, Some(project_id)).await?;
    let project = select_loaded_project(&snap, project_id)?;
    let dotorg = project.root.join(".orgasmic");
    let mut paths = vec![
        dotorg.join("project.org"),
        dotorg.join("decisions.org"),
        dotorg.join("glossary.org"),
        goal_file_path(&project.root),
        handoff_file_path(&project.root),
    ];
    paths.extend(iter_task_file_paths(&project.root));
    let mut owners = BTreeSet::new();
    for path in paths.into_iter().filter(|path| path.exists()) {
        let source = read_artifact(&path, "org file")?;
        let file = OrgFile::parse(source, path.to_string_lossy())
            .map_err(|error| org_parse_bad_request(&path, "org file", error))?;
        for heading in &file.headings {
            collect_inbound_reference_owners(heading, target_id, &mut owners);
        }
    }
    Ok(owners.into_iter().collect())
}

fn collect_inbound_reference_owners(
    heading: &Heading,
    target_id: &str,
    owners: &mut BTreeSet<String>,
) {
    let references_target = heading.property_entries().any(|property| {
        REFERENCE_PROPERTY_KEYS.contains(&property.key.as_str())
            && property
                .value
                .split_whitespace()
                .any(|token| token == target_id)
    });
    if references_target {
        owners.insert(
            heading
                .property("ID")
                .map(str::to_string)
                .unwrap_or_else(|| heading.title.clone()),
        );
    }
    for section in &heading.sections {
        collect_inbound_reference_owners(section, target_id, owners);
    }
}

fn compact_or_delete_full(id: &str) -> serde_json::Value {
    serde_json::json!({
        "id": id,
        "deleted": true,
    })
}

fn validate_decision_parent_ops(
    file: &OrgFile,
    id: &str,
    ops: &[NodeEditOp],
) -> Result<bool, ApiError> {
    let heading = file
        .find_by_id(id)
        .ok_or_else(|| ApiError::not_found(format!("decision {id}")))?;
    let current = decision_parent_from_heading(heading, id)?;
    let mut next = current.clone();
    let mut touched = false;
    for op in ops {
        match op {
            NodeEditOp::SetProperty { key, value } if key == "PARENT" => {
                next = orgasmic_core::parse_parent_value(
                    orgasmic_core::NodeIdClass::Decision,
                    id,
                    Some(value.as_str()),
                )
                .map_err(decision_parent_error)?;
                touched = true;
            }
            NodeEditOp::RemoveProperty { key } if key == "PARENT" => {
                next = None;
                touched = true;
            }
            _ => {}
        }
    }
    if !touched || next == current {
        return Ok(false);
    }
    let nodes = decision_parent_nodes_with_override(file, id, Some(next))?;
    orgasmic_core::validate_parent_tree(orgasmic_core::NodeIdClass::Decision, nodes)
        .map_err(decision_parent_error)?;
    Ok(true)
}

struct NodeEditWriteRequest<'a> {
    state: &'a ApiState,
    layer: NodeLayer,
    project_id: String,
    path: PathBuf,
    source: String,
    request_id: Option<String>,
    node_id: String,
    action: &'a str,
}

async fn write_org_node_edit_and_record(req: NodeEditWriteRequest<'_>) -> Result<String, ApiError> {
    let primary_rewrite = FileRewrite {
        path: req.path.clone(),
        new_contents: req.source.into_bytes(),
    };
    let project_tx_type = if req.layer == NodeLayer::Task {
        "task.edited".to_string()
    } else {
        format!("graph.{}.{}", req.layer.layer_name(), req.action)
    };
    let prepared_tx = prepare_api_tx(
        req.state,
        ApiTxRequest {
            ty: project_tx_type,
            actor: None,
            project: Some(req.project_id.clone()),
            task: if req.layer == NodeLayer::Task {
                Some(req.node_id.clone())
            } else {
                None
            },
            target: Some(req.path.display().to_string()),
            reason: format!(
                "{} {} node {}",
                req.action,
                req.layer.layer_name(),
                req.node_id
            ),
            request_id: req.request_id.map(|id| format!("{id}/tx")),
            extra: vec![("NODE_ID".to_string(), req.node_id.clone())],
        },
    )
    .await?;
    let tx_id = req
        .state
        .writer
        .transaction(vec![primary_rewrite], prepared_tx.tx)
        .await
        .map_err(writer_transaction_error)?;
    refresh_after_project_mutation(req.state, &req.project_id, prepared_tx.project_tx, &tx_id)
        .await?;
    if req.layer == NodeLayer::Task {
        req.state.events.publish(
            Topic::Task,
            EventPayload::TaskUpdated {
                project_id: req.project_id.clone(),
                task_id: req.node_id.clone(),
            },
        );
    } else {
        req.state.events.publish(
            Topic::Graph,
            EventPayload::GraphNodeRevised {
                project_id: req.project_id.clone(),
                layer: req.layer.layer_name().to_string(),
                node_id: req.node_id.clone(),
                action: req.action.to_string(),
                tx_id: tx_id.clone(),
            },
        );
    }
    Ok(tx_id)
}

async fn graph_path(
    state: &ApiState,
    project: Option<&str>,
    layer: GraphLayer,
) -> Result<(String, PathBuf), ApiError> {
    let (project_id, snap) = ensure_loaded_snapshot(state, project).await?;
    let project = select_loaded_project(&snap, &project_id)?;
    Ok((
        project.project_id.clone(),
        project.root.join(".orgasmic").join(layer.file_name()),
    ))
}

struct GraphWriteRequest<'a> {
    state: &'a ApiState,
    layer: GraphLayer,
    project_id: String,
    path: PathBuf,
    source: String,
    request_id: Option<String>,
    mutation: Option<MutationIdentity>,
    tx_type: String,
    node_id: String,
    action: &'a str,
}

async fn write_graph_and_record(
    req: GraphWriteRequest<'_>,
) -> Result<Json<GraphMutationResponse>, ApiError> {
    let primary_rewrite = FileRewrite {
        path: req.path.clone(),
        new_contents: req.source.into_bytes(),
    };
    let rewrites = vec![primary_rewrite];
    let prepared_tx = prepare_api_tx(
        req.state,
        ApiTxRequest {
            ty: req.tx_type,
            actor: None,
            project: Some(req.project_id.clone()),
            task: None,
            target: Some(req.path.display().to_string()),
            reason: format!("{} graph node {}", req.action, req.node_id),
            request_id: req.request_id.map(|id| format!("{id}/tx")),
            extra: vec![("NODE_ID".to_string(), req.node_id.clone())],
        },
    )
    .await?;
    let (tx_id, response_node_id) = match req.mutation {
        Some(mutation) => {
            let cached = req
                .state
                .writer
                .transaction_mutation(rewrites, prepared_tx.tx, mutation, req.node_id.clone())
                .await
                .map_err(writer_transaction_error)?;
            (cached.tx_id, cached.mutation_id)
        }
        None => (
            req.state
                .writer
                .transaction(rewrites, prepared_tx.tx)
                .await
                .map_err(writer_transaction_error)?,
            req.node_id.clone(),
        ),
    };
    refresh_after_project_mutation(req.state, &req.project_id, prepared_tx.project_tx, &tx_id)
        .await?;
    let layer = req.layer.layer_name().to_string();
    if req.action == "created" {
        req.state.events.publish(
            Topic::Graph,
            EventPayload::GraphNodeCreated {
                project_id: req.project_id.clone(),
                layer: layer.clone(),
                node_id: response_node_id.clone(),
                tx_id: tx_id.clone(),
            },
        );
    } else {
        req.state.events.publish(
            Topic::Graph,
            EventPayload::GraphNodeRevised {
                project_id: req.project_id.clone(),
                layer: layer.clone(),
                node_id: response_node_id.clone(),
                action: req.action.to_string(),
                tx_id: tx_id.clone(),
            },
        );
    }
    Ok(Json(GraphMutationResponse {
        id: response_node_id,
        action: req.action.to_string(),
        tx_id,
    }))
}

fn read_or_seed_graph_file(path: &FsPath, layer: GraphLayer) -> Result<String, ApiError> {
    if path.exists() {
        return read_artifact(path, layer.artifact_name());
    }
    Ok(format!(
        "#+title: orgasmic {}\n#+orgasmic_version: 1\n",
        layer.file_name()
    ))
}

fn render_graph_heading(
    layer: GraphLayer,
    req: &GraphCreateRequest,
    id: &str,
) -> Result<String, ApiError> {
    if id.trim().is_empty() {
        return Err(ApiError::bad_request("graph node id is required"));
    }
    if matches!(layer, GraphLayer::Glossary) {
        reject_glossary_implementation_detail(req)?;
    }
    let title = req.title.as_deref().unwrap_or(id).trim();
    let mut properties = req.properties.clone();
    properties.insert("ID".to_string(), id.to_string());
    let heading_title = match layer {
        GraphLayer::Decision if title == id => id.to_string(),
        GraphLayer::Decision => format!("{id} {title}"),
        GraphLayer::Glossary => {
            if id.starts_with("term_") {
                format!("{id} {title}")
            } else if title.starts_with("term:") {
                title.to_string()
            } else {
                format!("{}{} {}", layer.title_prefix(), id, title)
            }
        }
    };
    let mut out = format!("* {heading_title}\n:PROPERTIES:\n");
    for (key, value) in properties {
        out.push_str(&format!(":{key}: {value}\n"));
    }
    out.push_str(":END:\n");
    if let Some(body) = req.body.as_deref() {
        out.push('\n');
        out.push_str(body.trim_end());
        out.push('\n');
    }
    Ok(out)
}

/// Path/symbol markers: unambiguous in prose, matched as plain substrings.
const GLOSSARY_MARKER_SUBSTRINGS: &[&str] = &["crates/", "src/", ".rs", "::"];

/// Code-keyword markers: also legitimate English words/word-fragments
/// ("construct", "reconstruction", "implement"), so these are matched as
/// whole word tokens only.
const GLOSSARY_MARKER_WORDS: &[&str] = &["fn", "struct", "impl", "enum", "trait"];

/// True if `text` contains `word` as a standalone token: bounded on both
/// sides by the start/end of the string or a non-alphanumeric, non-`_`
/// character. Prevents `struct` from matching inside `construct` or
/// `reconstruction` while still catching `struct Foo {` or `a struct`.
fn contains_word(text: &str, word: &str) -> bool {
    let is_boundary = |c: Option<char>| !matches!(c, Some(c) if c.is_alphanumeric() || c == '_');
    let bytes = text.as_bytes();
    let word_len = word.len();
    text.match_indices(word).any(|(start, _)| {
        let before = text[..start].chars().next_back();
        let after_idx = start + word_len;
        let after = if after_idx <= bytes.len() {
            text[after_idx..].chars().next()
        } else {
            None
        };
        is_boundary(before) && is_boundary(after)
    })
}

fn reject_glossary_implementation_detail(req: &GraphCreateRequest) -> Result<(), ApiError> {
    if req.allow_marker {
        return Ok(());
    }
    let mut text = String::new();
    if let Some(definition) = req.properties.get("DEFINITION") {
        text.push_str(definition);
    }
    if let Some(body) = req.body.as_deref() {
        text.push('\n');
        text.push_str(body);
    }
    if let Some(marker) = GLOSSARY_MARKER_SUBSTRINGS
        .iter()
        .find(|marker| text.contains(**marker))
    {
        return Err(ApiError::bad_request(format!(
            "glossary definition contains implementation detail marker {marker:?} \
             (use --allow-marker if this glossary legitimately defines language constructs)"
        )));
    }
    if let Some(marker) = GLOSSARY_MARKER_WORDS
        .iter()
        .find(|marker| contains_word(&text, marker))
    {
        return Err(ApiError::bad_request(format!(
            "glossary definition contains implementation detail marker {marker:?} \
             (use --allow-marker if this glossary legitimately defines language constructs)"
        )));
    }
    Ok(())
}

fn select_catalog_project_id(
    snap: &IndexSnapshot,
    project: Option<&str>,
) -> Result<String, ApiError> {
    if let Some(id) = project {
        return snap
            .board
            .iter()
            .find(|entry| entry.id == id)
            .map(|entry| entry.id.clone())
            .ok_or_else(|| ApiError::not_found(format!("project {id}")));
    }
    if snap.board.len() == 1 {
        return Ok(snap.board[0].id.clone());
    }
    Err(ApiError::bad_request(
        "graph route requires ?project= when board has zero or multiple projects",
    ))
}

async fn ensure_loaded_snapshot(
    state: &ApiState,
    project: Option<&str>,
) -> Result<(String, IndexSnapshot), ApiError> {
    let catalog = state.index.snapshot().await;
    let project_id = select_catalog_project_id(&catalog, project)?;
    drop(catalog);
    state
        .index
        .ensure_project_loaded(&project_id)
        .await
        .map_err(|error| {
            tracing::warn!(project_id = %project_id, error = %error, "project load failed");
            ApiError::unavailable(format!("project {project_id} failed to load: {error}"))
        })?;
    Ok((project_id, state.index.snapshot().await))
}

/// Resolve registration, authorize it, then touch the filesystem through the
/// single-flight project-load boundary and take a fresh snapshot.
async fn resolve_authorized_project(
    state: &ApiState,
    identity: &Identity,
    project: Option<&str>,
    action: Action,
) -> Result<(String, IndexSnapshot), ApiError> {
    let catalog = state.index.snapshot().await;
    let project_id = select_catalog_project_id(&catalog, project)?;
    authz::require(identity, Some(&project_id), action)?;
    drop(catalog);
    state
        .index
        .ensure_project_loaded(&project_id)
        .await
        .map_err(|error| {
            tracing::warn!(project_id = %project_id, error = %error, "project load failed");
            ApiError::unavailable(format!("project {project_id} failed to load: {error}"))
        })?;
    Ok((project_id, state.index.snapshot().await))
}

/// Resolve the authorized catalog coverage before touching any repository,
/// then locate the task only inside that coverage. Legacy project-less task
/// routes remain usable without letting a member's request scan or disclose an
/// ungranted project.
async fn resolve_authorized_task(
    state: &ApiState,
    identity: &Identity,
    task_id: &str,
    project: Option<&str>,
    action: Action,
) -> Result<(LocatedTask, IndexSnapshot), ApiError> {
    if let Some(project_id) = project {
        let (_, snap) =
            resolve_authorized_project(state, identity, Some(project_id), action).await?;
        let loaded = select_loaded_project(&snap, project_id)?;
        if !loaded.tasks.iter().any(|task| task.id == task_id) {
            return Err(ApiError::not_found("task not found"));
        }
        return Ok((
            LocatedTask {
                project_id: project_id.to_string(),
            },
            snap,
        ));
    }

    let catalog = state.index.snapshot().await;
    let project_ids = catalog
        .board
        .iter()
        .filter(|entry| authz::require(identity, Some(&entry.id), action).is_ok())
        .map(|entry| entry.id.clone())
        .collect::<Vec<_>>();
    drop(catalog);
    for project_id in &project_ids {
        state
            .index
            .ensure_project_loaded(project_id)
            .await
            .map_err(|error| {
                ApiError::unavailable(format!("project {project_id} failed to load: {error}"))
            })?;
    }
    let snap = state.index.snapshot().await;
    let located = locate_task(&snap, task_id, &project_ids)?;
    Ok((located, snap))
}

fn select_loaded_project<'a>(
    snap: &'a IndexSnapshot,
    project_id: &str,
) -> Result<&'a ProjectIndex, ApiError> {
    snap.projects
        .get(project_id)
        .ok_or_else(|| ApiError::internal("project load published no projection"))
}

fn split_dispatch_scope(value: &str) -> Vec<&str> {
    value.split_whitespace().collect()
}

// orgasmic:task_HXSW0
/// Task drawer keys the schema actually reads, in the exact spelling
/// [`orgasmic_core::Heading::property`] looks up — that lookup is a byte
/// comparison, so `:priority:` and `:PRIORITY:` are two different keys and only
/// one of them is ever read.
///
/// This list exists to make a miscased key *nameable* in an error, not to close
/// the drawer to anything else: task headings legitimately carry free-form
/// annotations (`:MERGE_SHA:`, `:SEVERITY:`, `:CLOSED_AT:`) that no reader
/// consumes, and rejecting those would be a different, larger decision than the
/// one TASK-HXSW0 was filed for.
const TASK_SCHEMA_PROPERTY_KEYS: &[&str] = &[
    "DEPENDS_ON",
    "IMPLEMENTS",
    "MODEL",
    "PRIORITY",
    "PRODUCES",
    "PROVIDER",
    "READ_SCOPE",
    "REASONING_EFFORT",
    "SANDBOX_PERMISSIONS",
    "TEST_CMD",
    "WRITE_SCOPE",
];

/// Keys a task write must refuse because the value would be stored and then
/// never read, or is owned by a mechanism the caller has to reach through a
/// different door. Each carries the sentence that names that door.
///
/// TASK-HXSW0 was filed against the silent version of exactly this table: the
/// keys below used to be dropped on the floor by `task create` while the call
/// returned a normal `{id, tx_id}` success.
///
/// Set-direction only (orgasmic:task_ZKZBF.2): the unset half is
/// [`task_property_key_unset_refusal_reason`], because "refuse to write a key
/// nothing reads" must not extend to "refuse to delete a legacy line that is
/// already there" — dead keys get REMOVED, not re-pointed.
///
/// `ID` is absent on purpose (orgasmic:task_ZKZBF.1): the shared
/// [`validate_drawer_property_key_case`] guard refuses it first, on every
/// layer, so this table never sees it.
fn task_property_key_refusal_reason(key: &str) -> Option<&'static str> {
    let refusal = match key {
        "STATE" => {
            "STATE is owned by the lifecycle state machine — the heading keyword, the file the \
             task lives in and a `task.state_transitioned` tx all move together. Use \
             `orgasmic task update <id> --state <stage>`."
        }
        "PARENT_TASK" => {
            "PARENT_TASK is never read: `parent_task` is derived from the id grammar \
             (`TASK-<parent>.<n>` → `TASK-<parent>`). Mint the parentage into the id instead — \
             `orgasmic task create --id TASK-<parent>.1 …` — or the edge will not exist. A \
             legacy `:PARENT_TASK:` line is removable with `orgasmic node prop unset <task> \
             PARENT_TASK`."
        }
        "LAST_UPDATED" => {
            "LAST_UPDATED is not a task field; the tx ledger is the timestamped record \
             (`orgasmic tx list --project <id>`). A legacy `:LAST_UPDATED:` line is removable \
             with `orgasmic node prop unset <task> LAST_UPDATED`."
        }
        _ => return None,
    };
    Some(refusal)
}

// orgasmic:task_ZKZBF.2
/// The unset-direction half of the refusal table: only keys owned by another
/// door, where removal would desynchronise that door. The dead keys
/// (PARENT_TASK, LAST_UPDATED) are deliberately absent — round 1's unset arm
/// inherited the write-only table wholesale, so legacy drawer lines carrying
/// them had NO supported removal verb (`node prop unset` is the only door;
/// `POST /org/file` has no CLI verb). Removing them is the cleanup.
fn task_property_key_unset_refusal_reason(key: &str) -> Option<&'static str> {
    let refusal = match key {
        "STATE" => {
            "STATE is owned by the lifecycle state machine — the heading keyword, the file the \
             task lives in and a `task.state_transitioned` tx all move together. Use \
             `orgasmic task update <id> --state <stage>`."
        }
        _ => return None,
    };
    Some(refusal)
}

/// Keys `task update` writes and `task create` used to swallow. They stay
/// update-only — `FIX_SUBTASK` and `BLOCKED_BY` describe a relation to a task
/// that may not exist yet at create time — but the divergence is now stated at
/// the point of use instead of being invisible (TASK-HXSW0 instance 4).
const TASK_PROPERTY_KEYS_UPDATE_ONLY: &[&str] = &["BLOCKED_BY", "FIX_SUBTASK", "KIND"];

// orgasmic:task_ZKZBF
/// Drawer keys the decision and glossary read models consume, in the exact
/// spelling [`orgasmic_core::Heading::property`] looks up — the same byte
/// comparison that made miscased task keys stored-and-never-read (TASK-HXSW0).
/// Like `TASK_SCHEMA_PROPERTY_KEYS`, the list exists to make a miscased key
/// *nameable* in a refusal, not to close the drawer to anything else.
const DECISION_SCHEMA_PROPERTY_KEYS: &[&str] = &[
    "DECIDED_AT",
    "GLOSSARY_REFS",
    "PARENT",
    "SOURCE",
    "SUPERSEDES",
];

const GLOSSARY_SCHEMA_PROPERTY_KEYS: &[&str] = &[
    "AVOID",
    "CANONICAL",
    "DECIDED_AT",
    "DEFINITION",
    "RELATES_TO",
];

// orgasmic:task_ZKZBF
/// Drawer keys each node layer's readers consume, for the miscased-key refusal
/// on `node prop set`/`node prop unset`. Task is the schema-read drawer
/// [`validate_task_property_keys`] already governs; the other layers name
/// their own vocabulary so a refusal can point at the canonical spelling.
/// `ID` is deliberately absent from every list: it is derived from the node
/// identity and refused by the shared guard, not a key to advertise
/// (orgasmic:task_ZKZBF.1).
fn node_layer_schema_property_keys(layer: NodeLayer) -> &'static [&'static str] {
    match layer {
        NodeLayer::Task => TASK_SCHEMA_PROPERTY_KEYS,
        NodeLayer::Decision => DECISION_SCHEMA_PROPERTY_KEYS,
        NodeLayer::Glossary => GLOSSARY_SCHEMA_PROPERTY_KEYS,
        NodeLayer::Project => &["BRANCH", "DEFAULT_BRANCH", "LOCAL_PATH", "PATH", "STATUS"],
        NodeLayer::Goal | NodeLayer::Handoff => &["GOAL_ID", "LIVENESS"],
    }
}

// orgasmic:task_ZKZBF.1
/// Refusal label for a node layer, so every drawer-key refusal names the
/// vocabulary it is about. Total on purpose: no dead arms to drift.
fn node_layer_label(layer: NodeLayer) -> &'static str {
    match layer {
        NodeLayer::Task => "Task",
        NodeLayer::Decision => "Decision",
        NodeLayer::Glossary => "Glossary",
        NodeLayer::Project => "Project",
        NodeLayer::Goal => "Goal",
        NodeLayer::Handoff => "Handoff",
    }
}

// orgasmic:task_ZKZBF.2
/// The underscored spelling of a key that is its own uppercase but not
/// `[A-Z][A-Z0-9_]*` (`FOO-BAR` → `FOO_BAR`), when that mapping is itself a
/// valid shape. `None` when the key already conforms or no clean spelling
/// exists (`1FOO` has no uppercase first character to offer).
fn shaped_drawer_key_suggestion(key: &str) -> Option<String> {
    if orgasmic_core::tx::is_uppercase_snake_key(key) {
        return None;
    }
    let mapped = key
        .chars()
        .map(|ch| {
            if ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect::<String>();
    (mapped != key && orgasmic_core::tx::is_uppercase_snake_key(&mapped)).then_some(mapped)
}

// orgasmic:task_ZKZBF.1
/// The canonical-spelling check every drawer-key write surface shares: org
/// drawer keys are uppercase and [`orgasmic_core::Heading::property`] compares
/// them byte for byte, so a miscased key would be written and never read.
/// It also owns the identity guard: `:ID:` is derived from the node identity
/// (`find_by_id` matches it byte for byte), so writing it would re-key the
/// node and dangle every reference to the old id — refused on every layer,
/// before and instead of the case check.
///
// orgasmic:task_ZKZBF.3
/// `value` is the DIRECTION: `Some` for writes, `None` for removals. Only the
/// empty-key and identity refusals are direction-free. Everything after them
/// is a write-side argument and is skipped on removals — see the split inside.
///
// orgasmic:task_ZKZBF.2
/// It also enforces the ledger's own key SHAPE (`[A-Z][A-Z0-9_]*`, the core
/// `is_uppercase_snake_key`). A key that is its own uppercase but not that
/// shape (`FOO-BAR`) used to pass here and die only inside the tx writer —
/// a 500 "failed to apply changes" with the real reason confined to the
/// daemon log. One rule, refused here as a 400 before any file is read.
fn validate_drawer_property_key_case(
    key: &str,
    layer_label: &str,
    schema_keys: &[&str],
    value: Option<&str>,
) -> Result<(), ApiError> {
    let trimmed = key.trim();
    if trimmed.is_empty() {
        return Err(ApiError::bad_request(
            "empty `--property` key; pass `KEY=VALUE` with an uppercase drawer key",
        ));
    }
    // Case-insensitive so `id=…` gets this ONE refusal naming the immutability
    // rule, not a case correction ("use ID") into a hard refusal — two round
    // trips to learn one rule was the LOW-3 shape.
    if trimmed.eq_ignore_ascii_case("ID") {
        return Err(ApiError::bad_request(format!(
            "{layer_label} identity is immutable and the drawer :ID: is derived from it, so ID \
             cannot be set or unset as a property — writing it would re-key the node and dangle \
             every reference to the old id. Pin one at create time instead (the create verb's \
             `id` argument)"
        )));
    }
    // orgasmic:task_ZKZBF.3 — direction split. Everything below is a WRITE-side
    // argument: a miscased or wrong-shaped key would be *written* and never
    // read. A removal writes no key — `OrgRewriter::remove_property` matches
    // the drawer byte for byte (`crates/orgasmic-core/src/org.rs`), so the
    // spelling actually in the drawer is the only one that can delete the line
    // it names. The removal door refuses only keys another door owns (the
    // per-layer unset refusal tables, checked by the caller) and identity
    // (above); an absent key refuses as `PropertyNotFound`.
    let Some(value) = value else {
        return Ok(());
    };
    let canonical = trimmed.to_ascii_uppercase();
    if canonical != *key {
        // The canonical spelling to advertise must itself be a shape the
        // ledger accepts: correcting `foo-bar` to `FOO-BAR` would send the
        // caller into the shape refusal below — two round trips to learn one
        // rule, the LOW-3 shape again.
        let suggested =
            shaped_drawer_key_suggestion(&canonical).unwrap_or_else(|| canonical.clone());
        let tail = if schema_keys.contains(&canonical.as_str()) {
            format!(" — pass `{canonical}={value}`")
        } else {
            String::new()
        };
        return Err(ApiError::bad_request(format!(
            "property key `{key}` is not the canonical drawer spelling; org drawer keys are \
             uppercase and the reader compares them byte for byte, so `:{key}:` would be \
             written and never read. Use `{suggested}`{tail}. {layer_label} keys the schema \
             reads: {}",
            schema_keys.join(", ")
        )));
    }
    // orgasmic:task_ZKZBF.2 — self-uppercase but wrong SHAPE (`FOO-BAR`): the
    // tx ledger this write is also recorded on refuses it inside the writer.
    // Refused here instead, naming the flag on the set path (where
    // `task update --property FOO-BAR=1` is the shape that arrives) so the
    // caller gets one 400, not a 500 with the reason in the daemon log.
    if let Some(suggested) = shaped_drawer_key_suggestion(trimmed) {
        let shape_sentence = format!(
            "so `--property {trimmed}=…` would pass the drawer and die inside the tx \
             writer as a 500. Use `{suggested}`"
        );
        return Err(ApiError::bad_request(format!(
            "property key `{trimmed}` is not a drawer-key shape: org drawer keys and the tx \
             ledger both accept `[A-Z][A-Z0-9_]*` only, {shape_sentence}. {layer_label} keys \
             the schema reads: {}",
            schema_keys.join(", ")
        )));
    }
    if !orgasmic_core::tx::is_uppercase_snake_key(trimmed) {
        // No underscored spelling to offer (`1FOO`, `FOO__—BAR`, …): state the
        // rule without inventing a correction.
        return Err(ApiError::bad_request(format!(
            "property key `{trimmed}` is not a drawer-key shape: org drawer keys and the tx \
             ledger both accept `[A-Z][A-Z0-9_]*` only. {layer_label} keys the schema reads: {}",
            schema_keys.join(", ")
        )));
    }
    Ok(())
}

/// The write-time key check TASK-HXSW0 asks for: canonical spelling first, then
/// the refusal table.
///
/// `verb_hint` names the sibling verb when a key is legal there, so the error
/// answers "then where?" rather than only "not here".
fn validate_task_property_keys(
    properties: &BTreeMap<String, String>,
    verb_only_on_update: &[&str],
) -> Result<(), ApiError> {
    for (key, value) in properties {
        // orgasmic:task_ZKZBF — the case check is shared with the other
        // drawer-key surfaces this task audited; this task-facing spelling
        // keeps TASK-HXSW0's exact message.
        validate_drawer_property_key_case(key, "Task", TASK_SCHEMA_PROPERTY_KEYS, Some(value))?;
        let canonical = key.trim().to_ascii_uppercase();
        if let Some(refusal) = task_property_key_refusal_reason(&canonical) {
            return Err(ApiError::bad_request(format!(
                "`--property {canonical}=…` is refused: {refusal}"
            )));
        }
        if verb_only_on_update.contains(&canonical.as_str()) {
            return Err(ApiError::bad_request(format!(
                "`--property {canonical}=…` is not written by `task create` (it was silently \
                 dropped before TASK-HXSW0). Create the task, then set it with \
                 `orgasmic task update <id> --property {canonical}=…`."
            )));
        }
    }
    Ok(())
}

fn filter_default_dispatch_properties(
    properties: &BTreeMap<String, String>,
    default_test_cmd: &str,
    default_write_scope: &[String],
) -> BTreeMap<String, String> {
    properties
        .iter()
        .filter_map(|(key, value)| {
            let trimmed = value.trim();
            if matches!(key.as_str(), "WORKER" | "TEST_CMD" | "WRITE_SCOPE") && trimmed.is_empty() {
                return None;
            }
            if key == "TEST_CMD" && default_test_cmd.trim() == trimmed {
                return None;
            }
            if key == "WRITE_SCOPE"
                && split_dispatch_scope(trimmed)
                    == default_write_scope
                        .iter()
                        .map(String::as_str)
                        .collect::<Vec<_>>()
            {
                return None;
            }
            Some((key.clone(), value.clone()))
        })
        .collect()
}

// ---- task create + property update (TASK-NP5H6) ----------------------------

/// Target file for new top-level tasks (dec_QQYXM: always backlog.org).
fn task_create_target_file_name() -> &'static str {
    DEFAULT_TASK_FILE
}

fn task_create_target_path(project_root: &FsPath) -> PathBuf {
    task_file_path(project_root, task_create_target_file_name())
}

#[derive(Debug, Deserialize)]
struct TaskCreateRequest {
    #[serde(default)]
    id: Option<String>,
    title: String,
    #[serde(default)]
    tags: Vec<String>,
    #[serde(default)]
    properties: BTreeMap<String, String>,
    #[serde(default)]
    body: Option<String>,
    #[serde(default)]
    reason: Option<String>,
    #[serde(default)]
    request_id: Option<String>,
    /// Skip the write-time reference-token check (dec_4T80X / TASK-KSD6D)
    /// for intentional forward references. The index-time dangling lint
    /// still catches it.
    #[serde(default)]
    force: bool,
}

#[derive(Debug, Serialize)]
struct TaskCreateResponse {
    id: String,
    tx_id: String,
}

fn task_create_mutation_identity(
    project_id: &str,
    req: &TaskCreateRequest,
) -> Result<MutationIdentity, ApiError> {
    mutation_identity(
        "task.created",
        project_id,
        json!({
            "id": req.id,
            "title": req.title,
            "tags": req.tags,
            "properties": req.properties,
            "body": req.body,
            "reason": req.reason,
            "force": req.force,
        }),
    )
}

fn resolve_task_create_id(req: &TaskCreateRequest) -> Result<String, ApiError> {
    match req.id.as_deref().map(str::trim).filter(|id| !id.is_empty()) {
        None => Ok(orgasmic_core::mint_node_id(
            orgasmic_core::NodeIdClass::Task,
        )),
        Some(id) => {
            if orgasmic_core::is_legacy_sequential_create_id(orgasmic_core::NodeIdClass::Task, id) {
                return Err(ApiError::bad_request(format!(
                    "legacy sequential id {id} cannot be assigned on create; omit id to auto-mint or use `orgasmic id mint`"
                )));
            }
            if !orgasmic_core::is_valid_task_path_id(id) {
                return Err(ApiError::bad_request(format!("invalid task id: {id}")));
            }
            Ok(id.to_string())
        }
    }
}

// orgasmic:task_ZKZBF.3 — no STATE branch here: `validate_task_property_keys`
// refuses STATE case-insensitively via the refusal table, before this runs.
fn task_create_lifecycle_stage(_req: &TaskCreateRequest) -> Result<LifecycleStage, ApiError> {
    Ok(LifecycleStage::Backlog)
}

fn render_new_task_heading(
    id: &str,
    title: &str,
    tags: &[String],
    stage: LifecycleStage,
    properties: &BTreeMap<String, String>,
    body: Option<&str>,
) -> String {
    let clean_title = title
        .chars()
        .map(|ch| if ch == '\n' || ch == '\r' { ' ' } else { ch })
        .collect::<String>();
    let mut line = format!("* {} {} {}", stage.todo_keyword(), id, clean_title.trim());
    if !tags.is_empty() {
        line.push_str("    :");
        line.push_str(&tags.join(":"));
        line.push(':');
    }
    line.push('\n');
    line.push_str(":PROPERTIES:\n");
    let mut props = properties.clone();
    props
        .entry("ID".to_string())
        .or_insert_with(|| id.to_string());
    // orgasmic:task_ZKZBF.3 — no drop list here. STATE, PARENT_TASK and
    // LAST_UPDATED are refused by `task_property_key_refusal_reason`, and
    // KIND, BLOCKED_BY and FIX_SUBTASK by `TASK_PROPERTY_KEYS_UPDATE_ONLY` —
    // both inside `validate_task_property_keys`, which `post_task_create`
    // (this renderer's only caller) runs first and case-insensitively. A
    // second, silent copy of that rule was the exact shape TASK-HXSW0 filed:
    // if the guard ever regresses, a visible bad line beats a mute drop.
    for (key, value) in props {
        line.push_str(&format!(":{key}: {value}\n"));
    }
    line.push_str(":END:\n");
    if let Some(body) = body.filter(|value| !value.trim().is_empty()) {
        line.push('\n');
        line.push_str(body.trim_end());
        line.push('\n');
    }
    line
}

/// Task bodies are spliced into the task file verbatim; nested `**` sections
/// are legitimate structure, but a column-0 level-1 heading would escape the
/// task subtree and land as a sibling top-level task (the TASK-HC7PW
/// phantom-heading class). Block-aware so `#+begin_example` payloads keep
/// their literal star lines.
fn reject_structural_task_body(body: &str) -> Result<(), ApiError> {
    let mut block_depth = 0usize;
    for line in body.lines() {
        let directive = line.trim_start().to_ascii_lowercase();
        if directive.starts_with("#+begin_") {
            block_depth += 1;
            continue;
        }
        if directive.starts_with("#+end_") {
            block_depth = block_depth.saturating_sub(1);
            continue;
        }
        if block_depth == 0 && line.starts_with("* ") {
            return Err(ApiError::bad_request(format!(
                "task body must not contain column-0 level-1 `* ` headings (would escape the task subtree); use `**` sections or comma-escape inside a block: {line:?}"
            )));
        }
    }
    Ok(())
}

async fn post_task_create(
    State(state): State<ApiState>,
    Path(project_id): Path<String>,
    Json(req): Json<TaskCreateRequest>,
) -> Result<Json<TaskCreateResponse>, ApiError> {
    if req.title.trim().is_empty() {
        return Err(ApiError::bad_request("task title is required"));
    }
    if let Some(body) = req.body.as_deref() {
        reject_structural_task_body(body)?;
    }
    // orgasmic:task_HXSW0
    // The keys `render_new_task_heading` would drop on the floor. Refusing here
    // is the whole point of TASK-HXSW0: a create that returns `{id, tx_id}`
    // while discarding two of three arguments gives the caller no reason to
    // re-check, and a whole session of P1 work was filed unprioritised that way.
    validate_task_property_keys(&req.properties, TASK_PROPERTY_KEYS_UPDATE_ONLY)?;
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&project_id)).await?;
    let project = select_loaded_project(&snap, &project_id)?;
    let mutation = task_create_mutation_identity(&project_id, &req)?;
    if let Some(request_id) = transaction_request_key(req.request_id.as_deref()) {
        if let Some(cached) = state
            .writer
            .cached_mutation(&request_id, &mutation)
            .await
            .map_err(|error| ApiError::bad_request(error.to_string()))?
        {
            refresh_after_project_mutation(
                &state,
                &project_id,
                state.tx_commit_to_project,
                &cached.tx_id,
            )
            .await?;
            return Ok(Json(TaskCreateResponse {
                id: cached.mutation_id,
                tx_id: cached.tx_id,
            }));
        }
    }
    if !req.force {
        let known_ids = known_reference_ids(&state, &project_id).await?;
        for (key, value) in &req.properties {
            reject_unresolved_reference_token(&known_ids, key, value)?;
        }
    }
    let task_id = resolve_task_create_id(&req)?;
    let stage = task_create_lifecycle_stage(&req)?;
    let path = task_create_target_path(&project.root);
    let project_defaults = project_prompt_defaults(project);
    let properties = filter_default_dispatch_properties(
        &req.properties,
        project_defaults.test_cmd.as_str(),
        &project_defaults.write_scope,
    );
    let heading = render_new_task_heading(
        &task_id,
        &req.title,
        &req.tags,
        stage,
        &properties,
        req.body.as_deref(),
    );
    let transform_heading = heading.clone();
    let transform_path = path.to_string_lossy().to_string();
    let empty_header = empty_task_file_header(task_create_target_file_name());
    let target = task_file_rel(task_create_target_file_name());
    let reason = req
        .reason
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| format!("created task {task_id}"));
    let prepared = prepare_api_tx(
        &state,
        ApiTxRequest {
            ty: "task.created".to_string(),
            actor: None,
            project: Some(project_id.clone()),
            task: Some(task_id.clone()),
            target: Some(target),
            reason,
            request_id: req.request_id.clone().map(|id| format!("{id}/tx")),
            extra: Vec::new(),
        },
    )
    .await?;
    let cached = state
        .writer
        .transaction_mutate_file_mutation(
            FileMutate {
                path: path.clone(),
                transform: Box::new(move |source| {
                    let source = if source.is_empty() {
                        empty_header
                    } else {
                        source.to_string()
                    };
                    let updated = append_heading_to_task_file(&source, &transform_heading);
                    OrgFile::parse(updated.clone(), transform_path)
                        .map_err(|error| anyhow::anyhow!("task file parse failed: {error}"))?;
                    Ok(updated.into_bytes())
                }),
            },
            prepared.tx,
            mutation,
            task_id.clone(),
        )
        .await
        .map_err(writer_transaction_error)?;
    let tx_id = cached.tx_id;
    let response_task_id = cached.mutation_id;
    refresh_after_project_mutation(&state, &project_id, prepared.project_tx, &tx_id).await?;
    state.events.publish(
        Topic::Task,
        EventPayload::TaskUpdated {
            project_id: project_id.clone(),
            task_id: response_task_id.clone(),
        },
    );
    Ok(Json(TaskCreateResponse {
        id: response_task_id,
        tx_id,
    }))
}

