struct TaskLifecycleWriteRequest<'a> {
    state: &'a ApiState,
    project_id: &'a str,
    task_id: &'a str,
    rewrites: Vec<(PathBuf, String)>,
    target_rel: String,
    from_state: LifecycleStage,
    to_state: LifecycleStage,
    reason: String,
    request_id: Option<String>,
}

async fn write_task_lifecycle_and_record(
    req: TaskLifecycleWriteRequest<'_>,
) -> Result<String, ApiError> {
    for (path, source) in &req.rewrites {
        OrgFile::parse(source.clone(), path.to_string_lossy())
            .map_err(|e| org_parse_bad_request(path, "task file", e))?;
    }
    let prepared_tx = prepare_api_tx(
        req.state,
        ApiTxRequest {
            ty: "task.state_transitioned".to_string(),
            actor: None,
            project: Some(req.project_id.to_string()),
            task: Some(req.task_id.to_string()),
            target: Some(req.target_rel),
            reason: req.reason,
            request_id: req.request_id,
            extra: vec![
                (
                    "FROM_STATE".to_string(),
                    req.from_state.as_str().to_string(),
                ),
                ("TO_STATE".to_string(), req.to_state.as_str().to_string()),
            ],
        },
    )
    .await?;
    let file_rewrites = req
        .rewrites
        .into_iter()
        .map(|(path, source)| FileRewrite {
            path,
            new_contents: source.into_bytes(),
        })
        .collect();
    let tx_id = req
        .state
        .writer
        .transaction(file_rewrites, prepared_tx.tx)
        .await
        .map_err(writer_transaction_error)?;
    refresh_after_project_mutation(req.state, req.project_id, prepared_tx.project_tx, &tx_id)
        .await?;
    Ok(tx_id)
}

fn empty_task_file_header(file_name: &str) -> String {
    format!(
        "#+title: orgasmic {}\n#+orgasmic_version: 1\n",
        file_name.trim_end_matches(".org")
    )
}

fn append_heading_to_task_file(existing: &str, heading: &str) -> String {
    let mut out = existing.to_string();
    if !out.ends_with('\n') {
        out.push('\n');
    }
    if !out.ends_with("\n\n") {
        out.push('\n');
    }
    out.push_str(heading.trim_start_matches('\n'));
    if !out.ends_with('\n') {
        out.push('\n');
    }
    out
}

fn rewrite_heading_subtree_for_stage(
    subtree: &str,
    task_id: &str,
    stage: LifecycleStage,
) -> Result<String, ApiError> {
    let file = OrgFile::parse(subtree, "heading.org")
        .map_err(|e| ApiError::bad_request(format!("task subtree parse failed: {e}")))?;
    let heading = file
        .find_by_id(task_id)
        .ok_or_else(|| ApiError::not_found(format!("task {task_id} in subtree")))?;
    let mut rw = OrgRewriter::new(&file, "heading.org");
    rw.set_title_line(task_id, &task_lifecycle_title_line(heading, stage))
        .map_err(|e| org_rewriter_error("set task lifecycle title", task_id, e))?;
    Ok(rw.finish())
}

fn prepare_cross_file_lifecycle_move(
    source_text: &str,
    source_display: &str,
    task_id: &str,
    stage: LifecycleStage,
) -> Result<(String, String), ApiError> {
    let file = OrgFile::parse(source_text, source_display)
        .map_err(|e| org_parse_bad_request(&PathBuf::from(source_display), "task file", e))?;
    let heading = file
        .find_by_id(task_id)
        .ok_or_else(|| ApiError::not_found(format!("task {task_id}")))?;
    let subtree = file.slice(heading.span.clone());
    let moved = rewrite_heading_subtree_for_stage(subtree, task_id, stage)?;
    let mut rw = OrgRewriter::new(&file, source_display);
    rw.remove_heading(task_id)
        .map_err(|e| org_rewriter_error("remove task heading", task_id, e))?;
    Ok((rw.finish(), moved))
}

// orgasmic:task_P9T4N
/// Commit a dispatch terminal tx together with the lifecycle rewrite and its
/// `task.state_transitioned` tx. This is deliberately a dispatch-only surface:
/// ordinary task updates keep their existing API, while close no longer has a
/// client-visible boundary between its two ledger legs.
async fn post_task_dispatch_close_commit(
    State(state): State<ApiState>,
    Path((project_id, task_id)): Path<(String, String)>,
    Json(req): Json<DispatchCloseCommitRequest>,
) -> Result<Json<DispatchCloseCommitResponse>, ApiError> {
    if req.close_tx.project.as_deref() != Some(project_id.as_str())
        || req.close_tx.task.as_deref() != Some(task_id.as_str())
    {
        return Err(ApiError::bad_request(
            "dispatch close tx project/task must match the request path",
        ));
    }
    if !matches!(
        req.close_tx.r#type.as_str(),
        "implementer.done" | "reviewer.done" | "architector.done" | "manager.dispatch_aborted"
    ) {
        return Err(ApiError::bad_request(
            "dispatch close requires a terminal dispatch tx type",
        ));
    }
    let to_state = LifecycleStage::from_str(&req.state)
        .map_err(|_| ApiError::bad_request("unknown task state"))?;
    state
        .index
        .refresh_project(&project_id)
        .await
        .map_err(|error| {
            ApiError::unavailable(format!(
                "project {project_id} could not be refreshed before dispatch close: {error}"
            ))
        })?;
    let (_, snap) = ensure_loaded_snapshot(&state, Some(&project_id)).await?;
    let project = select_loaded_project(&snap, &project_id)?;
    let task = project
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .ok_or_else(|| ApiError::not_found("task not found"))?;
    let current_state = task.lifecycle_stage;
    let close_lifecycle = |key: &str| {
        req.close_tx
            .extra
            .iter()
            .find(|(candidate, _)| candidate == key)
            .map(|(_, value)| value.as_str())
    };
    let from_state = close_lifecycle("LIFECYCLE_FROM")
        .ok_or_else(|| ApiError::bad_request("dispatch close is missing LIFECYCLE_FROM"))
        .and_then(|stage| {
            LifecycleStage::from_str(stage)
                .map_err(|_| ApiError::bad_request("unknown dispatch close LIFECYCLE_FROM"))
        })?;
    if close_lifecycle("LIFECYCLE_TO") != Some(to_state.as_str()) {
        return Err(ApiError::bad_request(
            "dispatch close LIFECYCLE_TO does not match requested task state",
        ));
    }
    if current_state != from_state && current_state != to_state {
        return Err(ApiError::bad_request(format!(
            "dispatch close lifecycle intent starts at {}, but current task state is {}",
            from_state.as_str(),
            current_state.as_str()
        )));
    }
    let project_root = project.root.clone();
    let from_path = if current_state == from_state {
        task.source_file.clone()
    } else {
        task_file_path(&project_root, lifecycle_stage_file_name(from_state))
    };
    let to_file_name = lifecycle_stage_file_name(to_state);
    let to_path = task_file_path(&project_root, to_file_name);

    let rewrites = if from_state == to_state {
        Vec::new()
    } else if current_state == to_state {
        // A prior attempt may have appended both txs and installed these
        // rewrites before its fsync acknowledgement failed. Rebuild the same
        // final rewrite set from disk so the writer can validate semantic
        // identity and re-sync its retained descriptor without appending the
        // pair again.
        let paths = if from_path == to_path {
            vec![from_path]
        } else {
            vec![from_path, to_path]
        };
        paths
            .into_iter()
            .map(|path| {
                read_artifact(&path, "task file").map(|source| FileRewrite {
                    path,
                    new_contents: source.into_bytes(),
                })
            })
            .collect::<Result<Vec<_>, ApiError>>()?
    } else {
        let source_display = from_path.to_string_lossy().to_string();
        let source = read_artifact(&from_path, "task file")?;
        let pairs = if from_path == to_path {
            let file = OrgFile::parse(source.clone(), &source_display)
                .map_err(|e| org_parse_bad_request(&from_path, "task file", e))?;
            let mut rw = OrgRewriter::new(&file, &source_display);
            let heading = file
                .find_by_id(&task_id)
                .ok_or_else(|| ApiError::not_found(format!("task {task_id}")))?;
            rw.set_title_line(&task_id, &task_lifecycle_title_line(heading, to_state))
                .map_err(|e| org_rewriter_error("set task lifecycle title", &task_id, e))?;
            vec![(from_path, rw.finish())]
        } else {
            let (source_updated, moved_heading) =
                prepare_cross_file_lifecycle_move(&source, &source_display, &task_id, to_state)?;
            let dest_existing = if to_path.exists() {
                read_artifact(&to_path, "task file")?
            } else {
                empty_task_file_header(to_file_name)
            };
            vec![
                (from_path, source_updated),
                (
                    to_path,
                    append_heading_to_task_file(&dest_existing, &moved_heading),
                ),
            ]
        };
        pairs
            .into_iter()
            .map(|(path, source)| FileRewrite {
                path,
                new_contents: source.into_bytes(),
            })
            .collect()
    };
    for rewrite in &rewrites {
        let source = String::from_utf8(rewrite.new_contents.clone()).map_err(|error| {
            ApiError::bad_request(format!(
                "task file rewrite {} is not UTF-8: {error}",
                rewrite.path.display()
            ))
        })?;
        OrgFile::parse(source, rewrite.path.to_string_lossy())
            .map_err(|error| org_parse_bad_request(&rewrite.path, "task file", error))?;
    }

    let (close_tx, close_project_tx, _close_destination, close_time) =
        prepare_tx_append_request(&state, req.close_tx).await?;
    let close_path = close_tx.tx_path.clone();
    let lifecycle = if from_state == to_state {
        None
    } else {
        Some(
            prepare_api_tx(
                &state,
                ApiTxRequest {
                    ty: "task.state_transitioned".to_string(),
                    actor: None,
                    project: Some(project_id.clone()),
                    task: Some(task_id.clone()),
                    target: Some(task_file_rel(to_file_name)),
                    reason: req.reason,
                    request_id: Some(req.request_id),
                    extra: vec![
                        ("FROM_STATE".to_string(), from_state.as_str().to_string()),
                        ("TO_STATE".to_string(), to_state.as_str().to_string()),
                    ],
                },
            )
            .await?,
        )
    };
    let mut txs = vec![close_tx];
    if let Some(prepared) = lifecycle.as_ref() {
        txs.push(prepared.tx.clone());
    }
    let results = state
        .writer
        .transaction_multi(rewrites, txs)
        .await
        .map_err(dispatch_close_writer_error)?;
    let close_result = results.first().ok_or_else(|| {
        ApiError::internal("dispatch close writer returned no terminal transaction")
    })?;
    let transition_tx_id = results
        .get(1)
        .map(|result| result.tx_id.clone())
        .unwrap_or_default();
    let refresh_tx_id = if transition_tx_id.is_empty() {
        close_result.tx_id.as_str()
    } else {
        transition_tx_id.as_str()
    };
    refresh_after_project_mutation(&state, &project_id, close_project_tx, refresh_tx_id).await?;
    state.events.publish(
        Topic::Task,
        EventPayload::TaskUpdated {
            project_id,
            task_id,
        },
    );
    Ok(Json(DispatchCloseCommitResponse {
        close_tx: TxAppendResponse {
            tx_id: close_result.tx_id.clone(),
            tx_path: close_path,
            time: close_time,
        },
        transition_tx_id,
    }))
}

async fn post_task_update(
    State(state): State<ApiState>,
    Path((project_id, task_id)): Path<(String, String)>,
    Query(q): Query<MutationOutputQuery>,
    Json(req): Json<TaskUpdateRequest>,
) -> Result<Json<serde_json::Value>, ApiError> {
    if req.state.is_some() {
        // orgasmic:task_HXSW0
        // This arm used to return here with `{"changed":{"STATE":…}}` and drop
        // every drawer field on the same call without a word — the worst class
        // in TASK-HXSW0, because the success object looks complete. A lifecycle
        // move rewrites the heading keyword and may relocate the subtree to
        // another file under its own tx; the drawer write is a different write.
        // Refuse rather than half-apply, the same shape as `--title`.
        let mut also = Vec::new();
        if req.priority.is_some() {
            also.push("--priority".to_string());
        }
        for key in req.properties.keys() {
            also.push(format!("--property {key}=…"));
        }
        if !also.is_empty() {
            return Err(ApiError::bad_request(format!(
                "--state moves the task between lifecycle files and records its own \
                 `task.state_transitioned` tx, so it cannot share a call with {}; those fields \
                 would be silently dropped. Run the drawer write as its own \
                 `orgasmic task update {task_id} {}`.",
                also.join(", "),
                also.join(" ")
            )));
        }
        return update_task_state(&state, &project_id, &task_id, q.json, req).await;
    }
    if req.priority.is_some() || !req.properties.is_empty() {
        return update_task_properties(&state, &project_id, &task_id, q.json, req).await;
    }
    Err(ApiError::bad_request(
        "task update requires at least one field",
    ))
}

async fn update_task_state(
    state: &ApiState,
    project_id: &str,
    task_id: &str,
    want_full: bool,
    req: TaskUpdateRequest,
) -> Result<Json<serde_json::Value>, ApiError> {
    let to_state = LifecycleStage::from_str(req.state.as_deref().unwrap_or(""))
        .map_err(|_| ApiError::bad_request("unknown task state"))?;
    let (_, snap) = ensure_loaded_snapshot(state, Some(project_id)).await?;
    let project = select_loaded_project(&snap, project_id)?;
    let task = project
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .ok_or_else(|| {
            tracing::warn!(project_id = %project_id, task_id = %task_id, "task not found");
            ApiError::not_found("task not found")
        })?;
    let from_state = task.lifecycle_stage;
    if from_state == to_state {
        let supervisor = state.supervisor.snapshot().await;
        let project = apply_task_owners(project.clone(), &supervisor.runs);
        let task = project
            .tasks
            .iter()
            .find(|task| task.id == task_id)
            .cloned()
            .expect("task index membership checked above");
        let body = project.task_bodies.get(task_id).cloned();
        let detail = crate::index::TaskDetail::from_indexed_body(task, body);
        // TASK-EP3H1: label the no-op. If the caller's own request_id is in the
        // writer's idempotency record, this request already made the change and
        // its tx id is still the honest answer — the caller lost the response,
        // not the write. See [`NoOpLabel`] for the contract.
        let replayed = match req.request_id.as_deref() {
            Some(request_id) => state.writer.cached_tx_id(request_id).await,
            None => None,
        };
        let (status, tx_id) = match replayed {
            Some(tx_id) => (NoOpLabel::ALREADY_APPLIED, tx_id),
            None => (NoOpLabel::ALREADY_IN_STATE, String::new()),
        };
        let compact = CompactMutationResponse {
            id: task_id.to_string(),
            changed: BTreeMap::new(),
            tx_id,
            status: Some(status),
        };
        return compact_or_full_response(want_full, compact, detail);
    }
    let from_path = task.source_file.clone();
    let to_file_name = lifecycle_stage_file_name(to_state);
    let to_path = task_file_path(&project.root, to_file_name);
    let source_display = from_path.to_string_lossy().to_string();
    let source = read_artifact(&from_path, "task file")?;
    let rewrites = if from_path == to_path {
        let file = OrgFile::parse(source.clone(), &source_display)
            .map_err(|e| org_parse_bad_request(&from_path, "task file", e))?;
        let mut rw = OrgRewriter::new(&file, &source_display);
        let heading = file
            .find_by_id(task_id)
            .ok_or_else(|| ApiError::not_found(format!("task {task_id}")))?;
        rw.set_title_line(task_id, &task_lifecycle_title_line(heading, to_state))
            .map_err(|e| org_rewriter_error("set task lifecycle title", task_id, e))?;
        vec![(from_path, rw.finish())]
    } else {
        let (source_updated, moved_heading) =
            prepare_cross_file_lifecycle_move(&source, &source_display, task_id, to_state)?;
        let dest_existing = if to_path.exists() {
            read_artifact(&to_path, "task file")?
        } else {
            empty_task_file_header(to_file_name)
        };
        let dest_updated = append_heading_to_task_file(&dest_existing, &moved_heading);
        vec![(from_path, source_updated), (to_path, dest_updated)]
    };
    let reason = req
        .reason
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| format!("transition {task_id} to {}", to_state.as_str()));
    let tx_id = write_task_lifecycle_and_record(TaskLifecycleWriteRequest {
        state,
        project_id,
        task_id,
        rewrites,
        target_rel: task_file_rel(to_file_name),
        from_state,
        to_state,
        reason,
        request_id: req.request_id,
    })
    .await?;
    state.events.publish(
        Topic::Task,
        EventPayload::TaskUpdated {
            project_id: project_id.to_string(),
            task_id: task_id.to_string(),
        },
    );
    let snap = state.index.snapshot().await;
    let project = snap
        .project(project_id)
        .ok_or_else(|| ApiError::internal("project index unavailable after state flip"))?;
    let supervisor = state.supervisor.snapshot().await;
    let project = apply_task_owners(project.clone(), &supervisor.runs);
    let task = project
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .cloned()
        .ok_or_else(|| ApiError::internal("task missing from index after state flip"))?;
    let body = project.task_bodies.get(task_id).cloned();
    let detail = crate::index::TaskDetail::from_indexed_body(task, body);
    let mut changed = BTreeMap::new();
    changed.insert("STATE".to_string(), to_state.as_str().to_string());
    let compact = CompactMutationResponse {
        id: task_id.to_string(),
        changed,
        tx_id,
        status: None,
    };
    compact_or_full_response(want_full, compact, detail)
}

struct TaskPropertyWriteRequest<'a> {
    state: &'a ApiState,
    project_id: &'a str,
    project_root: &'a FsPath,
    task_id: &'a str,
    path: PathBuf,
    reason: String,
    request_id: Option<String>,
    changed: Vec<(String, String)>,
}

async fn write_task_property_and_record(
    req: TaskPropertyWriteRequest<'_>,
) -> Result<String, ApiError> {
    let target = req
        .path
        .strip_prefix(req.project_root)
        .unwrap_or(req.path.as_path())
        .to_string_lossy()
        .to_string();
    let mutation = MutationIdentity::new(
        "task.property_updated",
        req.project_id,
        json!({
            "task": req.task_id,
            "target": &target,
            "changed": &req.changed,
        })
        .to_string(),
    );
    let transform_task_id = req.task_id.to_string();
    let transform_path = req.path.to_string_lossy().to_string();
    let transform_changed = req.changed.clone();
    let prepared_tx = prepare_api_tx(
        req.state,
        ApiTxRequest {
            ty: "task.property_updated".to_string(),
            actor: None,
            project: Some(req.project_id.to_string()),
            task: Some(req.task_id.to_string()),
            target: Some(target),
            reason: req.reason,
            request_id: req.request_id,
            extra: req.changed,
        },
    )
    .await?;
    let tx_id = req
        .state
        .writer
        .transaction_mutate_file(
            FileMutate {
                path: req.path.clone(),
                transform: Box::new(move |source| {
                    let file = OrgFile::parse(source.to_string(), transform_path.clone())
                        .map_err(|error| anyhow::anyhow!("task file parse failed: {error}"))?;
                    let mut rw = OrgRewriter::new(&file, transform_path);
                    for (key, value) in transform_changed {
                        rw.upsert_property(&transform_task_id, &key, &value)
                            .map_err(|error| {
                                anyhow::anyhow!(
                                    "set task property {key} on {transform_task_id}: {error}"
                                )
                            })?;
                    }
                    Ok(rw.finish().into_bytes())
                }),
            },
            prepared_tx.tx,
            mutation,
        )
        .await
        .map_err(writer_transaction_error)?;
    refresh_after_project_mutation(req.state, req.project_id, prepared_tx.project_tx, &tx_id)
        .await?;
    Ok(tx_id)
}

async fn update_task_properties(
    state: &ApiState,
    project_id: &str,
    task_id: &str,
    want_full: bool,
    req: TaskUpdateRequest,
) -> Result<Json<serde_json::Value>, ApiError> {
    let (_, snap) = ensure_loaded_snapshot(state, Some(project_id)).await?;
    let project = select_loaded_project(&snap, project_id)?;
    let task = project
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .ok_or_else(|| {
            tracing::warn!(project_id = %project_id, task_id = %task_id, "task not found");
            ApiError::not_found("task not found")
        })?;
    // orgasmic:task_HXSW0
    // Same key check as `task create`, minus the update-only exclusions: the
    // two verbs now accept the same set apart from keys that name a relation to
    // a task that need not exist yet, and both say so instead of dropping.
    validate_task_property_keys(&req.properties, &[])?;
    let path = task.source_file.clone();
    let mut changed = Vec::new();
    if let Some(priority) = req
        .priority
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        changed.push(("PRIORITY".to_string(), priority.to_string()));
    }
    for (key, value) in req.properties {
        let key = key.trim();
        if key.is_empty() {
            continue;
        }
        // orgasmic:task_ZKZBF.2 — STATE and ID are refused by
        // `validate_task_property_keys` above (refusal table + shared guard,
        // case-insensitively); the hand-checks that used to sit here were
        // unreachable and said it in two more sentences.
        changed.push((key.to_string(), value));
    }
    if changed.is_empty() {
        return Err(ApiError::bad_request(
            "task update requires at least one property",
        ));
    }
    let reason = req
        .reason
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| format!("update properties on {task_id}"));
    let changed_map: BTreeMap<String, String> = changed.iter().cloned().collect();
    let tx_id = write_task_property_and_record(TaskPropertyWriteRequest {
        state,
        project_id,
        project_root: &project.root,
        task_id,
        path,
        reason,
        request_id: req.request_id,
        changed,
    })
    .await?;
    state.events.publish(
        Topic::Task,
        EventPayload::TaskUpdated {
            project_id: project_id.to_string(),
            task_id: task_id.to_string(),
        },
    );
    let snap = state.index.snapshot().await;
    let project = snap
        .project(project_id)
        .ok_or_else(|| ApiError::internal("project index unavailable after property update"))?;
    let supervisor = state.supervisor.snapshot().await;
    let project = apply_task_owners(project.clone(), &supervisor.runs);
    let task = project
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .cloned()
        .ok_or_else(|| ApiError::internal("task missing from index after property update"))?;
    let body = project.task_bodies.get(task_id).cloned();
    let detail = crate::index::TaskDetail::from_indexed_body(task, body);
    let compact = CompactMutationResponse {
        id: task_id.to_string(),
        changed: changed_map,
        tx_id,
        status: None,
    };
    compact_or_full_response(want_full, compact, detail)
}

