    /// The scan an in-memory boot-reattach fixture stands for: a whole-file
    /// read, nothing dropped and nothing truncated. orgasmic:TASK-7QM8M — the
    /// function takes a [`SessionLifecycleScan`] now, and a fixture that is a
    /// list of envelopes is exactly the untruncated case.
    fn whole_file_scan(envelopes: &[SessionEnvelope]) -> orgasmic_core::SessionLifecycleScan {
        orgasmic_core::SessionLifecycleScan {
            final_line_run_id: envelopes.last().map(|env| env.run_id.clone()),
            final_envelope_retained: !envelopes.is_empty(),
            envelopes: envelopes.to_vec(),
            ..Default::default()
        }
    }

    /// orgasmic:TASK-FZB6T — boot reattach now reads a catalog entry, so these
    /// fixtures index the scan exactly the way the boot pass does and hand over
    /// the entry. The scan-shaped fixtures stay: what they assert is what a
    /// bounded read of a file on disk implies, and that is still the input.
    fn boot_reattach_candidate_from_scan(
        scan: &orgasmic_core::SessionLifecycleScan,
        path: &FsPath,
    ) -> Option<BootReattachCandidate> {
        let fingerprint = std::fs::symlink_metadata(path)
            .map(|meta| crate::run_catalog::SessionFileFingerprint::of(&meta))
            .unwrap_or(crate::run_catalog::SessionFileFingerprint {
                dev: 0,
                ino: 0,
                len: 0,
                mtime_ns: 0,
            });
        let root = path.parent().unwrap_or(path);
        let entry = crate::run_catalog::entry_from_scan(scan, path, None, root, fingerprint);
        boot_reattach_candidate(&entry)
    }

    // ---------------------------------------------------------------------
    // orgasmic:TASK-FZB6T — the run catalog's acceptance, on a
    // production-shaped board.
    // ---------------------------------------------------------------------

    /// A registered project root with a sessions dir, no daemon involved.
    fn catalog_board_project(root: &FsPath, project_id: &str) {
        std::fs::create_dir_all(root.join(".orgasmic/tmp/sessions")).unwrap();
        std::fs::write(
            root.join(".orgasmic/project.org"),
            format!(
                "#+title: {project_id}\n#+orgasmic_version: 1\n\n* PROJECT {project_id}\n\
                 :PROPERTIES:\n:ID:               {project_id}\n:END:\n"
            ),
        )
        .unwrap();
    }

    /// Write one production-shaped session file.
    ///
    /// `transcript_bytes` is the payload volume between the lifecycle head and
    /// the file's end — the bytes the acceptance says enumeration must not be a
    /// function of.
    #[allow(clippy::too_many_arguments)]
    fn catalog_board_session(
        dir: &FsPath,
        run_id: &str,
        task_id: &str,
        project_id: &str,
        worktree: &FsPath,
        transcript_bytes: usize,
        release: Option<ReleaseOutcome>,
    ) -> PathBuf {
        let path = dir.join(format!("{run_id}.jsonl"));
        let mut seq = 0_u64;
        let mut out = String::new();
        let mut push = |kind: SessionEventKind, event: serde_json::Value, out: &mut String| {
            out.push_str(
                &serde_json::to_string(&SessionEnvelope {
                    seq,
                    time: chrono::Utc::now(),
                    run_id: run_id.to_string(),
                    runtime_id: format!("rt-{run_id}"),
                    boot_id: "boot-old".to_string(),
                    kind,
                    event,
                })
                .unwrap(),
            );
            out.push('\n');
            seq += 1;
        };
        push(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::Acquire {
                task_id: task_id.into(),
                kind: "worker".into(),
                worker_id: "implementer-claude-tmux".into(),
            })
            .unwrap(),
            &mut out,
        );
        push(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::RunMeta {
                transport: "tmux".into(),
                harness: Some("claude".into()),
                project_id: Some(project_id.into()),
                worktree: Some(worktree.to_path_buf()),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                role: Some("implementer".into()),
                requires_worker_finalize: Some(false),
                credential_mode: None,
                driver_config: json!({}),
            })
            .unwrap(),
            &mut out,
        );
        push(
            SessionEventKind::DriverEvent,
            json!({"type": "ready", "protocol_version": "tmux-tui/1"}),
            &mut out,
        );
        let chunk = "x".repeat(4096);
        let mut written = 0;
        while written < transcript_bytes {
            push(
                SessionEventKind::DriverEvent,
                json!({"type": "text_chunk", "stream": "stdout", "text": chunk}),
                &mut out,
            );
            written += chunk.len();
        }
        if let Some(outcome) = release {
            push(
                SessionEventKind::Lifecycle,
                serde_json::to_value(Lifecycle::Release {
                    reason: "done".into(),
                    outcome,
                    finalized_by_worker: false,
                })
                .unwrap(),
                &mut out,
            );
        }
        std::fs::write(&path, out).unwrap();
        path
    }

    /// The 197-file production-shaped history the acceptance names: mostly
    /// completed workers, a handful of Failed tombstones, several live TUI runs
    /// whose transcripts dwarf the scan budget, and one run whose worktree was
    /// pruned out from under it.
    ///
    /// `transcript_scale` multiplies only the payload volume; the record count
    /// and every classification-deciding line are identical at every scale.
    /// That is what makes the pair of boards a control.
    struct CatalogBoard {
        _tmp: tempfile::TempDir,
        root: PathBuf,
        sessions: PathBuf,
        pruned_worktree: PathBuf,
    }

    fn catalog_board(transcript_scale: usize) -> CatalogBoard {
        const FILES: usize = 197;
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("proj");
        catalog_board_project(&root, "proj");
        let sessions = root.join(".orgasmic/tmp/sessions");
        let pruned = tmp.path().join("worktree-pruned");
        catalog_board_project(&pruned, "proj");

        for index in 0..FILES {
            // 0..3 live (no release, huge transcript), 3..8 failed, one pruned
            // worktree, the rest completed.
            let (release, transcript, worktree) = match index {
                0..=2 => (None, 256 * 1024 * transcript_scale, root.clone()),
                3..=7 => (
                    Some(ReleaseOutcome::Failed),
                    8 * 1024 * transcript_scale,
                    root.clone(),
                ),
                8 => (None, 8 * 1024 * transcript_scale, pruned.clone()),
                _ => (
                    Some(ReleaseOutcome::Completed),
                    8 * 1024 * transcript_scale,
                    root.clone(),
                ),
            };
            catalog_board_session(
                &sessions,
                &format!("run-{index:03}"),
                &format!("TASK-B{index:04}"),
                "proj",
                &worktree,
                transcript,
                release,
            );
        }
        // Canonicalized: the inventory and the boot pass both canonicalize
        // project roots before keying the catalog, and on macOS a tempdir path
        // is a symlink into /private. A fixture that kept the uncanonicalized
        // path would silently compare two different catalogs.
        CatalogBoard {
            root: root.canonicalize().unwrap(),
            sessions: sessions.canonicalize().unwrap(),
            pruned_worktree: pruned.canonicalize().unwrap(),
            _tmp: tmp,
        }
    }

    fn catalog_home() -> (tempfile::TempDir, Home) {
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path());
        home.ensure().unwrap();
        (tmp, home)
    }

    /// `(classification, run_id, worktree_authority)` for every record, sorted.
    /// The comparable shape of one inventory pass.
    fn classification_fingerprint(runs: &[RecoveredRun]) -> Vec<(String, String, String)> {
        let mut out: Vec<(String, String, String)> = runs
            .iter()
            .map(|run| {
                (
                    run.classification.clone(),
                    run.run_id.clone(),
                    run.worktree_authority.clone(),
                )
            })
            .collect();
        out.sort();
        out
    }

    /// THE MIGRATION ACCEPTANCE: a 197-file production-shaped history yields
    /// the same actionable classifications before and after the catalog is
    /// populated, and the second pass costs no session bytes at all.
    ///
    /// "Before" is the cold pass — every file opened and scanned, which is
    /// exactly what the pre-catalog inventory did on EVERY call. "After" is the
    /// steady state the catalog introduces. If the catalog changed any verdict,
    /// the two fingerprints differ.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_production_shaped_board_classifies_identically_before_and_after_the_catalog() {
        let board = catalog_board(1);
        // One run's worktree was pruned out from under it — the production
        // shape this board is meant to carry.
        std::fs::remove_dir_all(&board.pruned_worktree).unwrap();
        let (_home_tmp, home) = catalog_home();
        let catalog = crate::run_catalog::RunCatalog::new();
        let roots = std::slice::from_ref(&board.root);

        let (cold_runs, cold) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        assert_eq!(cold.session_files, 197);
        assert_eq!(cold.catalog_rebuilds, 197);
        assert_eq!(cold.catalog_cache_hits, 0);
        assert!(cold.bytes_inspected > 0);

        let (warm_runs, warm) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        assert_eq!(
            warm.catalog_cache_hits, 197,
            "every record of an unchanged board must be answered from the catalog"
        );
        assert_eq!(
            warm.catalog_rebuilds, 0,
            "an unchanged session file must not be re-derived from disk"
        );
        assert_eq!(
            warm.bytes_inspected, 0,
            "after the one-time index, enumeration must read no session bytes"
        );

        assert_eq!(
            classification_fingerprint(&cold_runs),
            classification_fingerprint(&warm_runs),
            "the catalog decides WHEN a session file is read, never what its \
             lifecycle means"
        );

        // And the classifications are the production-shaped ones, not a
        // degenerate all-ambiguous board that would trivially match itself.
        let count = |class: &str| {
            cold_runs
                .iter()
                .filter(|run| run.classification == class)
                .count()
        };
        assert_eq!(count("failed_recoverable"), 5);
        assert_eq!(count("terminal_noop"), 188);
        assert_eq!(
            cold_runs
                .iter()
                .filter(|run| run.worktree_authority == "tombstoned")
                .count(),
            1,
            "the pruned worktree is a stable tombstone"
        );
    }

    /// THE COST ACCEPTANCE, pinned by consequence rather than wall time (the
    /// TASK-7QM8M precedent): two boards with the SAME 197 records and a 16x
    /// difference in transcript volume must cost the same to enumerate.
    ///
    /// A cost that tracked payload would show up as `bytes_inspected` scaling
    /// with `session_file_bytes`. It does not: the cold pass reads bounded
    /// windows, and the steady state reads nothing.
    #[tokio::test(flavor = "multi_thread")]
    async fn inventory_cost_does_not_follow_transcript_bytes() {
        let (_home_tmp, home) = catalog_home();

        let mut measurements = Vec::new();
        for scale in [1_usize, 16] {
            let board = catalog_board(scale);
            let catalog = crate::run_catalog::RunCatalog::new();
            let roots = std::slice::from_ref(&board.root);
            let (_, cold) = classify_session_files(
                &home,
                None,
                "boot-1",
                &[],
                roots,
                &catalog,
                None,
                TerminalWindow::unbounded(),
            )
            .await;
            let (_, warm) = classify_session_files(
                &home,
                None,
                "boot-1",
                &[],
                roots,
                &catalog,
                None,
                TerminalWindow::unbounded(),
            )
            .await;
            measurements.push((cold, warm));
        }
        let (small_cold, small_warm) = &measurements[0];
        let (big_cold, big_warm) = &measurements[1];

        assert_eq!(small_cold.session_files, big_cold.session_files);
        assert!(
            big_cold.session_file_bytes > small_cold.session_file_bytes * 8,
            "the control must actually differ in payload: {} vs {}",
            small_cold.session_file_bytes,
            big_cold.session_file_bytes
        );
        // The one-time index is bounded by RECORD COUNT: at any payload size it
        // reads at most one prefix+tail window per session file, never the file.
        // A cost that followed transcript bytes has no such ceiling — that is
        // the whole difference, and it is a hard number rather than a timing.
        let ceiling = |stats: &InventoryStageMetrics| {
            stats.session_files
                * (SessionScanBudget::DEFAULT.prefix_bytes + SessionScanBudget::DEFAULT.tail_bytes)
        };
        for (label, stats) in [("1x", small_cold), ("16x", big_cold)] {
            assert!(
                stats.bytes_inspected <= ceiling(stats),
                "{label}: the legacy index read {} bytes, past its {} ceiling for \
                 {} records",
                stats.bytes_inspected,
                ceiling(stats),
                stats.session_files
            );
        }
        assert!(
            big_cold.bytes_inspected < big_cold.session_file_bytes,
            "the index must never cost the board's payload: {} inspected of {} on disk",
            big_cold.bytes_inspected,
            big_cold.session_file_bytes
        );

        // And AFTER the one-time index — the acceptance's actual subject —
        // enumeration reads nothing at all, at either payload size.
        for (label, stats) in [("1x", small_warm), ("16x", big_warm)] {
            assert_eq!(
                stats.bytes_inspected, 0,
                "{label}: enumeration after the index still read session bytes, so \
                 its cost is still a function of what those files contain"
            );
        }
        assert_eq!(
            small_warm.catalog_cache_hits, big_warm.catalog_cache_hits,
            "enumeration cost must be the same at both payload sizes"
        );
        assert_eq!(small_warm.catalog_cache_hits, 197);
    }

    /// orgasmic:TASK-FZB6T.5 finding 1 — boot reattach must refuse exactly the
    /// authority `/api/runs` refuses.
    ///
    /// `WorktreeAuthority::blocks_attach` was correct and the polled inventory
    /// used it; `boot_reattach_candidate` checked truncation, terminal state and
    /// external registration and then returned the recorded worktree without
    /// consulting the authority at all. So a restart auto-reattached a run whose
    /// worktree is durably gone — and one whose ledger is unreadable and
    /// therefore `Unprovable` — straight into `Supervisor::reattach`, while the
    /// inventory endpoint refused to so much as probe it. The two paths reattach
    /// the same runs from the same catalog entries; they cannot answer this
    /// differently.
    #[test]
    fn boot_reattach_refuses_the_authority_the_inventory_refuses() {
        let board = catalog_board(1);
        let roots = std::slice::from_ref(&board.root);
        // ONE catalog across all three states, which is what a boot pass has:
        // the candidates below are cache hits, not re-derivations.
        let catalog = crate::run_catalog::RunCatalog::new();

        let live = collect_boot_reattach_candidates(&catalog, roots);
        assert!(
            live.iter().any(|c| c.run_id == "run-008"),
            "the fixture's pruned-worktree run must start out reattachable"
        );

        // Tombstoned: the recorded worktree is gone, which is terminal for the
        // run identity. No reattach can succeed under it.
        std::fs::remove_dir_all(&board.pruned_worktree).unwrap();
        let tombstoned = collect_boot_reattach_candidates(&catalog, roots);
        assert!(
            !tombstoned.iter().any(|c| c.run_id == "run-008"),
            "a durably tombstoned run must not be auto-reattached across a restart"
        );
        assert_eq!(
            tombstoned.len(),
            live.len() - 1,
            "and only that one: the live runs still reattach"
        );

        // Unprovable: the ledger that would prove any of them attachable cannot
        // be read, so none of them is proven attachable.
        std::fs::write(
            board.root.join(crate::run_catalog::TOMBSTONE_REL_PATH),
            b"{\"tombstoned\": {\"run-",
        )
        .unwrap();
        let unprovable = collect_boot_reattach_candidates(&catalog, roots);
        assert!(
            unprovable.is_empty(),
            "an unreadable authority must not be read as permission to reattach: {:?}",
            unprovable.iter().map(|c| &c.run_id).collect::<Vec<_>>()
        );
    }

    /// A pruned worktree must not be an eternal attach candidate.
    ///
    /// Before the catalog, a run whose recorded worktree was gone still had a
    /// driver attach probe spawned for it on every single inventory pass — the
    /// answer was then discarded by the authority check that ran afterwards.
    /// The verdict is stable, so it is stated once and the probe is skipped.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_pruned_worktree_stops_being_probed() {
        let board = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        let catalog = crate::run_catalog::RunCatalog::new();
        let roots = std::slice::from_ref(&board.root);

        // While the worktree is present, run-008 is a live non-terminal record
        // like any other and IS probed.
        let (runs, before) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        assert_eq!(before.tombstoned_authority, 0);
        assert!(runs
            .iter()
            .any(|run| run.run_id == "run-008" && run.worktree_authority == "verified"));

        std::fs::remove_dir_all(&board.pruned_worktree).unwrap();
        let (runs, after) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        assert_eq!(
            after.tombstoned_authority, 1,
            "the pruned worktree must be recognized once"
        );
        let tombstoned = runs
            .iter()
            .find(|run| run.run_id == "run-008")
            .expect("the run survives as a record");
        assert_eq!(tombstoned.worktree_authority, "tombstoned");
        assert!(
            tombstoned.recovery_actions.is_empty(),
            "a run whose worktree is gone offers no recovery under that identity"
        );
        assert!(
            after.attach_probes_started < before.attach_probes_started
                || before.attach_probes_started == 0,
            "the tombstoned record must stop consuming an attach probe"
        );
    }

    /// Boot reconciliation after the one-time index reads nothing.
    ///
    /// A restart loads the durable snapshot the previous daemon wrote and
    /// re-reads only the session files that changed since — on a board whose
    /// runs have ended, none of them. Candidate selection is unchanged.
    #[tokio::test(flavor = "multi_thread")]
    async fn boot_reconciliation_after_the_index_reads_no_session_bytes() {
        let board = catalog_board(1);
        let roots = std::slice::from_ref(&board.root);

        // First boot: cold. This is what every boot cost before the catalog.
        let first = crate::run_catalog::RunCatalog::new();
        let cold_candidates = collect_boot_reattach_candidates(&first, roots);
        let cold_stats = first.refresh_dir(
            &board.sessions,
            Some("proj"),
            &board.root,
            SessionScanBudget::DEFAULT,
        );
        assert_eq!(
            cold_stats.cache_hits, 197,
            "the first boot indexed the board"
        );
        let snapshot = first
            .snapshot_bytes(&board.root)
            .expect("the first boot has something to persist");
        std::fs::write(
            board.root.join(crate::run_catalog::CATALOG_REL_PATH),
            snapshot,
        )
        .unwrap();

        // Second boot: the snapshot is the index.
        let second = crate::run_catalog::RunCatalog::new();
        let warm_candidates = collect_boot_reattach_candidates(&second, roots);
        let warm_stats = second.refresh_dir(
            &board.sessions,
            Some("proj"),
            &board.root,
            SessionScanBudget::DEFAULT,
        );
        assert_eq!(
            warm_stats.rebuilt, 0,
            "a restart re-reads only session files written since the last index"
        );
        assert_eq!(warm_stats.bytes_inspected, 0);

        let ids = |candidates: &[BootReattachCandidate]| {
            let mut ids: Vec<String> = candidates.iter().map(|c| c.run_id.clone()).collect();
            ids.sort();
            ids
        };
        assert_eq!(ids(&cold_candidates), ids(&warm_candidates));
        assert!(
            !cold_candidates.is_empty(),
            "the board has live runs; a fixture that reattaches nothing proves nothing"
        );
    }

    /// A corrupt or foreign-version snapshot must not be able to poison
    /// classification: it is discarded and the board is re-indexed.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_corrupt_catalog_snapshot_cannot_poison_classification() {
        let board = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        let roots = std::slice::from_ref(&board.root);

        let sound = crate::run_catalog::RunCatalog::new();
        let (expected, _) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &sound,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        let snapshot_path = board.root.join(crate::run_catalog::CATALOG_REL_PATH);
        std::fs::write(&snapshot_path, sound.snapshot_bytes(&board.root).unwrap()).unwrap();

        // Three ways a derived index goes wrong on disk. Each must produce the
        // same classifications as a board with no snapshot at all.
        let good = std::fs::read_to_string(&snapshot_path).unwrap();
        let corruptions: Vec<(&str, String)> = vec![
            ("truncated mid-object", good[..good.len() / 2].to_string()),
            ("not json", "}{ not a catalog".to_string()),
            (
                "written by a daemon whose catalog version this build cannot vouch for",
                // Built from the constant, never a literal: a version bump must
                // not silently turn this case into "the same sound snapshot".
                good.replace(
                    &format!(
                        "\"catalog_version\": {}",
                        crate::run_catalog::CATALOG_VERSION
                    ),
                    "\"catalog_version\": 99",
                ),
            ),
        ];
        for (name, contents) in corruptions {
            std::fs::write(&snapshot_path, &contents).unwrap();
            let catalog = crate::run_catalog::RunCatalog::new();
            let load = catalog.load_snapshot(&board.root);
            assert!(
                !matches!(load, crate::run_catalog::SnapshotLoad::Loaded { .. }),
                "{name}: a catalog this daemon cannot vouch for must not load: {load:?}"
            );
            let (actual, stats) = classify_session_files(
                &home,
                None,
                "boot-1",
                &[],
                roots,
                &catalog,
                None,
                TerminalWindow::unbounded(),
            )
            .await;
            assert_eq!(
                stats.catalog_rebuilds, 197,
                "{name}: the board is re-indexed"
            );
            assert_eq!(
                classification_fingerprint(&actual),
                classification_fingerprint(&expected),
                "{name}: a discarded catalog must classify exactly as no catalog"
            );
        }
    }

    /// The terminal window is bounded by default and pageable on request; the
    /// actionable buckets never are.
    #[tokio::test(flavor = "multi_thread")]
    async fn the_terminal_window_is_bounded_and_pageable() {
        let board = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        let catalog = crate::run_catalog::RunCatalog::new();
        let roots = std::slice::from_ref(&board.root);
        let (runs, _) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;

        let mut terminal: Vec<RecoveredRun> = runs
            .into_iter()
            .filter(|run| run.classification == "terminal_noop")
            .collect();
        assert!(terminal.len() > crate::run_catalog::DEFAULT_TERMINAL_WINDOW);
        terminal.sort_by(|a, b| {
            b.terminal_at
                .cmp(&a.terminal_at)
                .then(a.run_id.cmp(&b.run_id))
        });

        let page = |window: TerminalWindow| -> Vec<String> {
            terminal
                .iter()
                .skip(window.offset)
                .take(window.limit)
                .map(|run| run.run_id.clone())
                .collect()
        };
        let default_page = page(TerminalWindow::default());
        assert_eq!(
            default_page.len(),
            crate::run_catalog::DEFAULT_TERMINAL_WINDOW
        );

        // Paging reaches older history without reclassifying anything.
        let second_page = page(TerminalWindow::from(RunInventoryQuery {
            terminal_limit: Some(crate::run_catalog::DEFAULT_TERMINAL_WINDOW),
            terminal_offset: Some(crate::run_catalog::DEFAULT_TERMINAL_WINDOW),
            terminal: None,
        }));
        assert_eq!(
            second_page.len(),
            crate::run_catalog::DEFAULT_TERMINAL_WINDOW
        );
        assert!(
            second_page.iter().all(|id| !default_page.contains(id)),
            "pages must not overlap"
        );

        // `terminal=all` is the explicit query for the whole history.
        let all = page(TerminalWindow::from(RunInventoryQuery {
            terminal_limit: None,
            terminal_offset: None,
            terminal: Some("all".to_string()),
        }));
        assert_eq!(all.len(), terminal.len());

        // And the requested limit is capped, so a client cannot ask for an
        // unbounded response by naming a huge number.
        let capped = TerminalWindow::from(RunInventoryQuery {
            terminal_limit: Some(usize::MAX),
            terminal_offset: None,
            terminal: None,
        });
        assert_eq!(capped.limit, crate::run_catalog::MAX_TERMINAL_WINDOW);
    }

    /// orgasmic:TASK-FZB6T.1 finding 3 — terminal history is paged BEFORE it
    /// is classified, so a poll pays for the window it returns rather than for
    /// the board's whole past.
    #[tokio::test(flavor = "multi_thread")]
    async fn the_terminal_window_is_applied_before_classification() {
        let board = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        let catalog = crate::run_catalog::RunCatalog::new();
        let roots = std::slice::from_ref(&board.root);

        let (bounded, metrics) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::default(),
        )
        .await;
        let returned = bounded
            .iter()
            .filter(|run| run.classification == "terminal_noop")
            .count();
        assert_eq!(returned, crate::run_catalog::DEFAULT_TERMINAL_WINDOW);
        assert_eq!(
            metrics.terminal_total, 188,
            "the total must still count every terminal record on the board"
        );
        assert_eq!(
            metrics.terminal_returned as usize, returned,
            "the metric must report what was actually classified"
        );
        assert!(
            bounded.len() < 197,
            "records outside the window must not be classified at all: {} classified",
            bounded.len()
        );
        // The actionable buckets are never bounded: a failed tombstone or an
        // ambiguous record is work, and hiding work behind a page is the one
        // thing the window must not do.
        assert_eq!(
            bounded
                .iter()
                .filter(|run| run.classification == "failed_recoverable")
                .count(),
            5
        );

        // And the page is the NEWEST terminal records, in the response's own
        // ordering — the same set an unbounded pass would put first.
        let (all, _) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        let mut every: Vec<&RecoveredRun> = all
            .iter()
            .filter(|run| run.classification == "terminal_noop")
            .collect();
        every.sort_by(|a, b| {
            b.terminal_at
                .cmp(&a.terminal_at)
                .then(a.run_id.cmp(&b.run_id))
        });
        let expected: Vec<&String> = every
            .iter()
            .take(crate::run_catalog::DEFAULT_TERMINAL_WINDOW)
            .map(|run| &run.run_id)
            .collect();
        let mut got: Vec<&String> = bounded
            .iter()
            .filter(|run| run.classification == "terminal_noop")
            .map(|run| &run.run_id)
            .collect();
        got.sort();
        let mut want: Vec<&String> = expected.clone();
        want.sort();
        assert_eq!(got, want, "the window must carry the newest terminal page");
    }

    /// orgasmic:TASK-FZB6T.1 finding 9 — an exact `run show <id>` resolves a
    /// terminal run that is far outside the default list window.
    #[tokio::test(flavor = "multi_thread")]
    async fn an_exact_id_resolves_a_terminal_run_older_than_the_default_window() {
        let board = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        std::fs::write(
            home.board(),
            format!(
                "#+title: orgasmic board\n#+orgasmic_version: 1\n\n* PROJECT proj\n\
                 :PROPERTIES:\n:ID:               proj\n:PATH:             {}\n\
                 :BRANCH:           main\n:STATUS:           active\n:END:\n",
                board.root.display()
            ),
        )
        .unwrap();
        let state = direct_stage_test_state(home).await;

        // Establish which terminal runs the DEFAULT window would hide, using
        // the same classification the endpoint uses.
        let (paged, _) = classify_session_files(
            &state.home,
            None,
            "boot-1",
            &[],
            std::slice::from_ref(&board.root),
            &state.run_catalog,
            None,
            TerminalWindow::default(),
        )
        .await;
        let visible: BTreeSet<String> = paged.iter().map(|run| run.run_id.clone()).collect();
        // run-196 is a completed worker; the board has 188 of them and the
        // window carries 50, so most are outside it.
        let hidden = (9..197)
            .map(|index| format!("run-{index:03}"))
            .find(|id| !visible.contains(id))
            .expect("a 197-record board must have terminal runs outside a 50-record window");

        let answer = get_run(State(state.clone()), Path(hidden.clone()))
            .await
            .unwrap_or_else(|error| {
                panic!("an indexed terminal run must resolve by exact id: {hidden}: {error:?}")
            });
        assert_eq!(answer.0["run"]["run_id"].as_str(), Some(hidden.as_str()));
        assert_eq!(answer.0["classification"].as_str(), Some("terminal_noop"));

        // A genuinely unknown id is still a 404, so the fix did not make the
        // lookup answer for runs that do not exist.
        assert!(get_run(State(state), Path("run-not-a-run".to_string()))
            .await
            .is_err());
    }

    /// orgasmic:TASK-FZB6T.1 finding 6 — two projects on one board each get
    /// their own snapshot, and neither consumes the other's.
    #[tokio::test(flavor = "multi_thread")]
    async fn two_projects_each_persist_their_own_catalog_snapshot() {
        let first = catalog_board(1);
        let second = catalog_board(1);
        let (_home_tmp, home) = catalog_home();
        let catalog = crate::run_catalog::RunCatalog::new();
        let roots = vec![first.root.clone(), second.root.clone()];

        let (_, metrics) = classify_session_files(
            &home,
            None,
            "boot-1",
            &[],
            &roots,
            &catalog,
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        assert_eq!(metrics.session_files, 394, "both boards were enumerated");

        for root in &roots {
            let bytes = catalog
                .snapshot_bytes_after(root, std::time::Duration::ZERO)
                .unwrap_or_else(|| {
                    panic!(
                        "every refreshed project must have a snapshot to persist: {}",
                        root.display()
                    )
                });
            std::fs::write(root.join(crate::run_catalog::CATALOG_REL_PATH), bytes).unwrap();
        }

        // Each snapshot carries exactly its own project's records, and a
        // restart loads both without re-reading a byte.
        for root in &roots {
            let reloaded = crate::run_catalog::RunCatalog::new();
            assert_eq!(
                reloaded.load_snapshot(root),
                crate::run_catalog::SnapshotLoad::Loaded { entries: 197 },
                "{}",
                root.display()
            );
            let stats = reloaded.refresh_dir(
                &project_sessions_dir(root),
                Some("proj"),
                root,
                SessionScanBudget::DEFAULT,
            );
            assert_eq!(stats.rebuilt, 0);
            assert_eq!(stats.bytes_inspected, 0);
        }
    }

    /// `run history inspect`'s dry run accounts for every byte and changes
    /// nothing on a production-shaped board.
    #[tokio::test(flavor = "multi_thread")]
    async fn run_history_inspect_accounts_exactly_and_changes_nothing() {
        let board = catalog_board(1);
        let catalog = crate::run_catalog::RunCatalog::new();
        catalog.refresh_dir(
            &board.sessions,
            Some("proj"),
            &board.root,
            SessionScanBudget::DEFAULT,
        );

        let before: std::collections::BTreeMap<PathBuf, (u64, Vec<u8>)> =
            std::fs::read_dir(&board.sessions)
                .unwrap()
                .flatten()
                .map(|entry| {
                    let path = entry.path();
                    let bytes = std::fs::read(&path).unwrap();
                    (path, (bytes.len() as u64, bytes))
                })
                .collect();
        let on_disk: u64 = before.values().map(|(len, _)| len).sum();

        let report = crate::run_catalog::inspect_history(&catalog.entries());
        assert!(report.dry_run);
        assert_eq!(report.session_files, 197);
        assert_eq!(report.unreadable_files, 0);
        assert_eq!(
            report.bytes_accounted, on_disk,
            "every byte on disk must land in exactly one event class"
        );
        assert!(report.reclaimable_bytes > 0);
        assert!(
            report.reclaimable_bytes < report.bytes_accounted,
            "authority bytes are never reclaimable"
        );
        assert_eq!(
            report.reclaimable_by_driver.keys().collect::<Vec<_>>(),
            vec!["tmux/claude"],
            "accounting is reported by driver+harness"
        );
        assert!(report
            .buckets
            .iter()
            .any(|bucket| bucket.event_class == "lifecycle" && !bucket.reclaimable));
        assert!(report
            .retention
            .iter()
            .any(|tier| tier.tier == "harness_native_history" && tier.authority == "vendor-owned"));

        let after: std::collections::BTreeMap<PathBuf, (u64, Vec<u8>)> =
            std::fs::read_dir(&board.sessions)
                .unwrap()
                .flatten()
                .map(|entry| {
                    let path = entry.path();
                    let bytes = std::fs::read(&path).unwrap();
                    (path, (bytes.len() as u64, bytes))
                })
                .collect();
        assert_eq!(before, after, "the dry run must change nothing");
    }

    /// orgasmic:TASK-FZB6T — the boot pass is catalog-backed and project-rooted
    /// now. These fixtures lay session files into a bare directory, so the shim
    /// drives one FRESH catalog over that directory: no snapshot, every file
    /// read, which is exactly the cold-start case they assert about.
    fn collect_boot_reattach_candidates_for_dirs(dirs: &[PathBuf]) -> Vec<BootReattachCandidate> {
        let catalog = crate::run_catalog::RunCatalog::new();
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("current-thread runtime")
            .block_on(async {
                let mut out = Vec::new();
                for dir in dirs {
                    catalog.refresh_dir(dir, None, dir, SessionScanBudget::DEFAULT);
                    for entry in catalog.entries_for_project(dir) {
                        if let Some(candidate) = boot_reattach_candidate(&entry) {
                            out.push(candidate);
                        }
                    }
                }
                out
            })
    }

    /// The bounded scan the boot pass really performs over a file on disk.
    fn boot_scan(path: &FsPath) -> orgasmic_core::SessionLifecycleScan {
        scan_session_lifecycle(path, SessionScanBudget::DEFAULT).expect("scan session file")
    }

    #[test]
    fn boot_reattach_candidate_requires_nonterminal_acquire_and_run_meta() {
        let env = |kind: SessionEventKind, event: serde_json::Value| SessionEnvelope {
            seq: 0,
            time: chrono::Utc::now(),
            run_id: "run-reattach".into(),
            runtime_id: "rt-reattach".into(),
            boot_id: "boot-old".into(),
            kind,
            event,
        };
        let acquire = env(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::Acquire {
                task_id: "manager.launch:orgasmic".into(),
                kind: "implementer".into(),
                worker_id: "manager".into(),
            })
            .unwrap(),
        );
        let meta = env(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::RunMeta {
                transport: "tmux".into(),
                harness: Some("claude".into()),
                project_id: Some("orgasmic".into()),
                worktree: Some(PathBuf::from("/tmp/orgasmic")),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                role: None,
                requires_worker_finalize: None,
                credential_mode: None,
                driver_config: json!({"persistent": true}),
            })
            .unwrap(),
        );
        let release = env(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::Release {
                reason: "done".into(),
                outcome: ReleaseOutcome::Completed,
                finalized_by_worker: false,
            })
            .unwrap(),
        );
        let path = PathBuf::from("/tmp/run-reattach.jsonl");

        // Acquire + RunMeta, non-terminal → a full candidate.
        let candidate = boot_reattach_candidate_from_scan(
            &whole_file_scan(&[acquire.clone(), meta.clone()]),
            &path,
        )
        .expect("candidate");
        assert_eq!(candidate.run_id, "run-reattach");
        assert_eq!(candidate.task_id, "manager.launch:orgasmic");
        assert_eq!(candidate.transport, "tmux");
        assert_eq!(candidate.harness.as_deref(), Some("claude"));
        assert_eq!(candidate.driver_config["persistent"], json!(true));
        // Pre-upgrade / non-dispatch RunMeta carries no artifact paths — boot
        // reattach must still succeed, just without a completion watcher.
        assert!(candidate.last_path.is_none());
        assert!(candidate.stdout_path.is_none());

        let invalid_argv_meta = env(
            SessionEventKind::Lifecycle,
            serde_json::to_value(Lifecycle::RunMeta {
                transport: "tmux".into(),
                harness: Some("claude".into()),
                project_id: Some("orgasmic".into()),
                worktree: Some(PathBuf::from("/tmp/orgasmic")),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                role: Some("terminal".into()),
                requires_worker_finalize: Some(false),
                credential_mode: None,
                driver_config: json!({"harness_args": ["--smuggle"]}),
            })
            .unwrap(),
        );
        let invalid_argv = boot_reattach_candidate_from_scan(
            &whole_file_scan(&[acquire.clone(), invalid_argv_meta]),
            &path,
        )
        .expect("invalid argv candidate");
        assert!(
            validate_boot_reattach_harness_args(&invalid_argv).is_err(),
            "boot reattach must use the shared custom-only argv validator"
        );

        // Terminal release → not a candidate.
        assert!(boot_reattach_candidate_from_scan(
            &whole_file_scan(&[acquire.clone(), meta.clone(), release]),
            &path
        )
        .is_none());
        // Missing RunMeta (pre-upgrade session) → not a candidate.
        assert!(boot_reattach_candidate_from_scan(&whole_file_scan(&[acquire]), &path).is_none());
    }

    /// TASK-QRTT8: the `RunMeta` pattern must BIND `credential_mode`, never
    /// test it against a literal.
    ///
    /// `boot_reattach_candidate` destructured `credential_mode: None` — a
    /// refutable pattern, not a binding. A `RunMeta` carrying `Some(mode)`
    /// therefore fell to the `_ => {}` arm, `meta` stayed `None`, and
    /// `let (…) = meta?` returned `None`: the run was not a boot-reattach
    /// candidate AT ALL. Production writes `Some` — `adapters/claude.rs`
    /// resolves the mode into `NativeRuntimeMeta` and `Supervisor::acquire`
    /// lifts it into `RunMeta` (TASK-S0QRM) — so a claude run that had
    /// resolved `native_login` or `bare_api_key` was silently never rehydrated
    /// after a daemon restart. Every pre-existing boot-reattach test passed
    /// `credential_mode: None`, which is exactly why nothing caught it.
    ///
    /// The assertion is stated over every value the field can hold, so it
    /// fails the moment the pattern narrows to any one of them again.
    #[test]
    fn boot_reattach_candidate_binds_every_resolved_credential_mode() {
        let env = |event: serde_json::Value| SessionEnvelope {
            seq: 0,
            time: chrono::Utc::now(),
            run_id: "run-qrtt8".into(),
            runtime_id: "rt-qrtt8".into(),
            boot_id: "boot-old".into(),
            kind: SessionEventKind::Lifecycle,
            event,
        };
        let acquire = env(serde_json::to_value(Lifecycle::Acquire {
            task_id: "TASK-QRTT8".into(),
            kind: "implementer".into(),
            worker_id: "implementer-claude-tmux".into(),
        })
        .unwrap());
        let path = PathBuf::from("/tmp/run-qrtt8.jsonl");

        // The two modes `adapters/claude.rs` actually resolves, plus the `None`
        // every other harness writes. All three are the same run to boot
        // reattach: the mode is recorded evidence, not an input to `reattach`.
        for credential_mode in [None, Some("native_login"), Some("bare_api_key")] {
            let meta = env(serde_json::to_value(Lifecycle::RunMeta {
                transport: "tmux".into(),
                harness: Some("claude".into()),
                project_id: Some("orgasmic".into()),
                worktree: Some(PathBuf::from("/tmp/orgasmic")),
                last_path: None,
                stdout_path: None,
                dispatch_attempt_token: None,
                role: Some("implementer".into()),
                requires_worker_finalize: Some(true),
                credential_mode: credential_mode.map(str::to_string),
                driver_config: json!({"persistent": true}),
            })
            .unwrap());
            let candidate = boot_reattach_candidate_from_scan(
                &whole_file_scan(&[acquire.clone(), meta]),
                &path,
            )
            .unwrap_or_else(|| {
                panic!(
                    "a live run whose harness resolved credential_mode={credential_mode:?} \
                         must be a boot-reattach candidate; a refutable pattern on this field \
                         drops the whole run and it is never rehydrated after a daemon restart"
                )
            });
            // The reattach material survives intact, not just the `Some`.
            assert_eq!(candidate.run_id, "run-qrtt8");
            assert_eq!(candidate.task_id, "TASK-QRTT8");
            assert_eq!(candidate.transport, "tmux");
            assert_eq!(candidate.harness.as_deref(), Some("claude"));
            assert_eq!(candidate.role.as_deref(), Some("implementer"));
            assert_eq!(candidate.requires_worker_finalize, Some(true));
            assert_eq!(candidate.driver_config["persistent"], json!(true));
        }
    }

    /// TASK-QRTT8, blast radius: the fix makes a whole class of runs candidates
    /// that never reached `Supervisor::reattach` before. The class that exists
    /// in production TODAY is `stdio`/`claude` — the one path that writes
    /// `credential_mode: Some(_)` (the mux drivers all write `None`; see
    /// `modes/tmux.rs`). Its runtime is a child of the
    /// daemon process, so after a restart there is nothing to attach to.
    ///
    /// This asserts the newly-reachable path declines SAFELY: the candidate is
    /// produced, `StdioDriver::attach` answers `NotReattachable`, and the
    /// lease `Supervisor::reattach` admits before attaching is released again —
    /// so the dead run neither enters the supervisor as live nor wedges the
    /// task's lease for the rest of the daemon's life.
    #[tokio::test]
    async fn a_credential_resolving_stdio_run_is_declined_without_holding_its_lease() {
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("proj");
        seed_project(&home, &project_root, "orgasmic");
        std::fs::create_dir_all(project_sessions_dir(&project_root)).unwrap();

        let identity = RuntimeIdentity {
            run_id: "run-qrtt8-stdio".into(),
            runtime_id: "rt-qrtt8-stdio".into(),
            boot_id: "boot-before-restart".into(),
        };
        let session_path =
            project_sessions_dir(&project_root).join(format!("{}.jsonl", identity.run_id));
        let mut writer = orgasmic_core::SessionWriter::open(&session_path, identity.clone())
            .expect("open session writer");
        writer
            .append(
                SessionEventKind::Lifecycle,
                serde_json::to_value(Lifecycle::Acquire {
                    task_id: "TASK-QRTT8-STDIO".into(),
                    kind: "worker".into(),
                    worker_id: "implementer-claude-stream-json".into(),
                })
                .unwrap(),
            )
            .unwrap();
        writer
            .append(
                SessionEventKind::Lifecycle,
                serde_json::to_value(Lifecycle::RunMeta {
                    // orgasmic:task_3NJ9K — the transport is the stub because a
                    // test build may not hold an `stdio` one. What this run
                    // is a candidate *for* is `credential_mode: Some(_)`, which
                    // is the TASK-QRTT8 pattern and is unchanged below.
                    transport: crate::driver_resolution::STUB_MODE.into(),
                    harness: Some(crate::driver_resolution::STUB_HARNESS.into()),
                    project_id: Some("orgasmic".into()),
                    worktree: Some(project_root.clone()),
                    last_path: None,
                    stdout_path: None,
                    dispatch_attempt_token: None,
                    role: Some("implementer".into()),
                    requires_worker_finalize: Some(true),
                    // What `adapters/claude.rs` really persists for this pair.
                    credential_mode: Some("native_login".into()),
                    driver_config: json!({}),
                })
                .unwrap(),
            )
            .unwrap();
        drop(writer);

        let candidate = boot_reattach_candidate_from_scan(&boot_scan(&session_path), &session_path)
            .expect("a credential-resolving stdio run is now a candidate");
        assert_eq!(candidate.transport, crate::driver_resolution::STUB_MODE);

        // A fresh Supervisor/ApiState never acquired this run — standing in for
        // the post-restart daemon boot.
        let state = direct_stage_test_state(home.clone()).await;
        reattach_live_runs_on_boot(&state, std::slice::from_ref(&project_root)).await;
        assert!(
            state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .all(|run| run.run_id != identity.run_id),
            "a stdio run whose process died with the old daemon must not be \
             rehydrated as live: its driver cannot prove a runtime handle"
        );

        // The lease is free: `Supervisor::reattach` admits the lease BEFORE it
        // calls `attach`, so a decline that leaked the reservation would block
        // this task from ever acquiring again. A fresh reattach of the same
        // run reaching `NotReattachable` (rather than a lease conflict) is what
        // proves the reservation was released.
        // The subject here is the supervisor's lease bookkeeping, not any one
        // transport's attach logic: what has to hold is that a driver which
        // declines leaves the lease free. The stub declines exactly as
        // `StdioDriver::attach` does (an unconditional `NotReattachable`),
        // and a test build must not hold a real transport at all — TASK-3NJ9K.
        // Whether stdio itself still declines is a drivers-crate contract
        // and is tested there.
        let driver = crate::driver_resolution::stub_driver();
        let error = state
            .supervisor
            .reattach(
                driver.as_ref(),
                identity.clone(),
                RunKind::Worker,
                candidate.task_id.clone(),
                candidate.worker_id.clone(),
                "implementer".to_string(),
                true,
                candidate.project_id.clone(),
                candidate.worktree.clone(),
                session_path.clone(),
                DriverConfig::from_value(candidate.driver_config.clone()),
                true,
                None,
            )
            .await
            .expect_err("a dead stdio runtime cannot be reattached");
        assert!(
            matches!(
                error,
                crate::supervisor::SupervisorError::NotReattachable { .. }
            ),
            "the boot pass must leave the lease free; a second reattach has to \
             reach the driver's own verdict, not a lease conflict, got: {error}"
        );
        state.writer.shutdown().await;
    }

    /// F2, ON THE PRODUCTION BOOT ROUTE — a failed `readdir` must not become a
    /// reattach.
    ///
    /// orgasmic:TASK-2QK4P.1.1.1.1.1 P1b — round five extracted
    /// `boot_reattach_ownership` "so the test exercises the real expression",
    /// and then the regression called `pending_recovery_claim_owns_session`
    /// directly and asserted the returned enum was not `Invalid`. That is a
    /// RESTATEMENT of the routing rule, not the routing rule: change the loop
    /// below to reattach on `ClaimEvidence::Unobserved` and it stays green.
    /// This test arms the same `readdir` seam and drives
    /// `reattach_live_runs_on_boot`, so the assertion is about what boot DID.
    ///
    /// The fixture is the exact shape the finding names: a pending recovery
    /// claim owns a replacement session file, and that same file is a live boot
    /// candidate. The harm is irreversible — `Supervisor::reattach` appends
    /// `Reattach` into the immutable prefix pending recovery owns — so the
    /// faulted phase asserts the file is BYTE-IDENTICAL, not merely that the run
    /// is absent from the supervisor.
    ///
    /// Phase three removes the claim and lets the very same boot pass reattach
    /// the very same candidate. Without it phases one and two would pass against
    /// a fixture that cannot be reattached at all, which is precisely the hole
    /// this round is closing.
    ///
    /// Injection to see it red: in `reattach_live_runs_on_boot`, change
    /// `if !matches!(ownership, ClaimEvidence::Invalid)` to
    /// `if matches!(ownership, ClaimEvidence::Valid)` — i.e. reattach on
    /// `Unobserved`. Phase one then rehydrates the run and grows the JSONL.
    // orgasmic:TASK-2QK4P.1.1.1.1
    #[tokio::test]
    async fn boot_reattach_refuses_a_candidate_whose_claim_store_could_not_be_listed() {
        use crate::driver_resolution::{STUB_HARNESS, STUB_MODE};

        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().canonicalize().unwrap();
        let home = Home::at(root.join("home"));
        home.ensure().unwrap();
        let project_root = root.join("proj");
        seed_project(&home, &project_root, "orgasmic");
        std::fs::create_dir_all(project_sessions_dir(&project_root)).unwrap();

        let origin_path = write_failed_recoverable_session(
            &project_root,
            "run-p1b-origin",
            "protocol_end_without_finalize",
            false,
        );
        let replacement_path = project_sessions_dir(&project_root).join("recover-p1b.jsonl");
        let spec = PendingRecoveryClaimSpec {
            project_id: "orgasmic".into(),
            origin_run_id: "run-p1b-origin".into(),
            request_id: "req-p1b".into(),
            origin_session_path: origin_path,
            replacement_session_path: replacement_path.clone(),
            boot_id: "boot-p1b".into(),
            action: "start_recovery_run".into(),
            target: "worker".into(),
            draft_prompt: Some("p1b draft".into()),
            force_inert: true,
            task_id: "TASK-P1B".into(),
            kind: "worker".into(),
            worker_id: "implementer-claude-stream-json".into(),
            role: "implementer".into(),
            requires_worker_finalize: true,
            transport: STUB_MODE.into(),
            harness: Some(STUB_HARNESS.into()),
            driver_config: json!({"stub_reattachable": true}),
            worktree: Some(project_root.clone()),
            last_path: None,
            stdout_path: None,
            planned_native_runtime: None,
            run_options: RecoveryRunOptions {
                stall_timeout_secs: None,
                max_run_duration_secs: None,
                idle_timeout_secs: None,
                cleanup_on_failure: false,
            },
        };
        let plan = plan_pending_recovery_claim(&home, &spec).expect("plan pending claim");
        assert_eq!(plan.claim.replacement_session_path, replacement_path);

        // The prefix the claim owns, and a live boot candidate at the same time.
        // That coincidence is the whole hazard: the boot pass sees a reattachable
        // run, and only the claim store says who owns it.
        let identity = RuntimeIdentity {
            run_id: "run-p1b-replacement".into(),
            runtime_id: "rt-p1b-replacement".into(),
            boot_id: "boot-before-restart".into(),
        };
        let mut writer =
            orgasmic_core::SessionWriter::open(&replacement_path, identity.clone()).unwrap();
        writer
            .append(
                SessionEventKind::Lifecycle,
                serde_json::to_value(Lifecycle::Acquire {
                    task_id: "TASK-P1B".into(),
                    kind: "worker".into(),
                    worker_id: "implementer-claude-stream-json".into(),
                })
                .unwrap(),
            )
            .unwrap();
        writer
            .append(
                SessionEventKind::Lifecycle,
                serde_json::to_value(Lifecycle::RunMeta {
                    transport: STUB_MODE.into(),
                    harness: Some(STUB_HARNESS.into()),
                    project_id: Some("orgasmic".into()),
                    worktree: Some(project_root.clone()),
                    last_path: None,
                    stdout_path: None,
                    dispatch_attempt_token: None,
                    role: Some("implementer".into()),
                    requires_worker_finalize: Some(true),
                    credential_mode: None,
                    // The stub answers `Attached` only for this flag, so the
                    // reattach in phase three really COMPLETES and really writes.
                    driver_config: json!({"stub_reattachable": true}),
                })
                .unwrap(),
            )
            .unwrap();
        drop(writer);

        assert!(
            boot_reattach_candidate_from_scan(&boot_scan(&replacement_path), &replacement_path)
                .is_some_and(|candidate| candidate.run_id == identity.run_id),
            "the owned replacement session must be a boot-reattach candidate, or \
             this test proves nothing about boot"
        );
        // PREMISE: with the claim store listable, the claim IS found. The test
        // cannot pass by the predicate being blind to the fixture.
        assert_eq!(
            pending_recovery_claim_owns_session(
                &home,
                &project_root,
                "orgasmic",
                &replacement_path
            ),
            ClaimEvidence::Valid,
            "the fixture must start out with the pending claim discoverable"
        );
        let before = std::fs::read(&replacement_path).unwrap();

        let state = direct_stage_test_state(home.clone()).await;

        // PHASE ONE — the claim store cannot be listed. Pre-fix this arrived as
        // `Ok(an empty directory)`, the predicate answered `Invalid`, and boot
        // reattached into the owned prefix.
        crate::recovery_claim::arm_readdir_fault_until_disarmed(&home, 1, libc::EIO);
        reattach_live_runs_on_boot(&state, std::slice::from_ref(&project_root)).await;
        crate::recovery_claim::disarm_readdir_fault(&home);
        let live_after_fault = state.supervisor.snapshot().await.runs;
        assert!(
            live_after_fault
                .iter()
                .all(|run| run.run_id != identity.run_id),
            "boot must SKIP, not reattach, while the claim store is unobserved; \
             live runs were {:?}",
            live_after_fault
                .iter()
                .map(|run| run.run_id.clone())
                .collect::<Vec<_>>()
        );
        assert_eq!(
            std::fs::read(&replacement_path).unwrap(),
            before,
            "no byte may be appended to the prefix pending recovery owns while \
             ownership is unobserved — that write is not undoable"
        );

        // PHASE TWO — fault cleared, claim still there: a DECIDED owner, so boot
        // still skips, and for the other reason.
        assert_eq!(
            pending_recovery_claim_owns_session(
                &home,
                &project_root,
                "orgasmic",
                &replacement_path
            ),
            ClaimEvidence::Valid,
            "a transient listing failure must not change the answer once it clears"
        );
        reattach_live_runs_on_boot(&state, std::slice::from_ref(&project_root)).await;
        assert!(
            state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .all(|run| run.run_id != identity.run_id),
            "a pending claim owning the session is still a skip"
        );
        assert_eq!(
            std::fs::read(&replacement_path).unwrap(),
            before,
            "and it is still byte-identical"
        );

        // PHASE THREE — no claim owns it, so the answer is a decided `Invalid`
        // and normal routing runs: the SAME candidate through the SAME boot pass
        // is rehydrated and the `Reattach` marker is appended.
        std::fs::remove_dir_all(
            crate::recovery_claim::recovery_claims_root(&home).join("orgasmic"),
        )
        .unwrap();
        assert_eq!(
            pending_recovery_claim_owns_session(
                &home,
                &project_root,
                "orgasmic",
                &replacement_path
            ),
            ClaimEvidence::Invalid,
            "with the claim gone the answer is a decided absence"
        );
        reattach_live_runs_on_boot(&state, std::slice::from_ref(&project_root)).await;
        assert!(
            state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .any(|run| run.run_id == identity.run_id),
            "the fixture must rehydrate once nothing owns it, or the two phases \
             above prove only that this candidate is unreattachable"
        );
        state.writer.shutdown().await;
        let after = std::fs::read_to_string(&replacement_path).unwrap();
        assert!(
            after.len() > before.len() && after.contains("\"phase\":\"reattach\""),
            "normal routing appends the `Reattach` marker — this is the exact \
             write the two phases above must not have made: {after}"
        );
    }

    #[test]
    fn same_second_external_end_then_app_launch_preserves_app_recovery_identity() {
        let tmp = tempfile::tempdir().unwrap();
        let stamp = launch_stamp();
        let external_ids = manager_launch_ids("proj", "external", stamp);
        let app_ids = manager_launch_ids("proj", "claude", stamp);
        assert_eq!(external_ids.task_id, app_ids.task_id);
        assert_ne!(external_ids.session_file, app_ids.session_file);

        let write_manager_session =
            |path: &FsPath, identity: RuntimeIdentity, transport: &str, terminal: bool| {
                let mut writer = orgasmic_core::SessionWriter::open(path, identity).unwrap();
                writer
                    .append(
                        SessionEventKind::Lifecycle,
                        serde_json::to_value(Lifecycle::Acquire {
                            task_id: "manager.launch:proj".into(),
                            kind: "worker".into(),
                            worker_id: "manager".into(),
                        })
                        .unwrap(),
                    )
                    .unwrap();
                writer
                    .append(
                        SessionEventKind::Lifecycle,
                        serde_json::to_value(Lifecycle::RunMeta {
                            transport: transport.into(),
                            harness: Some(transport.into()),
                            project_id: Some("proj".into()),
                            worktree: Some(tmp.path().join("proj")),
                            last_path: None,
                            stdout_path: None,
                            dispatch_attempt_token: None,
                            role: None,
                            requires_worker_finalize: None,
                            credential_mode: None,
                            driver_config: json!({}),
                        })
                        .unwrap(),
                    )
                    .unwrap();
                if terminal {
                    writer
                        .append(
                            SessionEventKind::Lifecycle,
                            serde_json::to_value(Lifecycle::Release {
                                reason: "external manager deregistered".into(),
                                outcome: ReleaseOutcome::Cancelled,
                                finalized_by_worker: false,
                            })
                            .unwrap(),
                        )
                        .unwrap();
                }
            };

        let external_path = tmp.path().join(external_ids.session_file);
        write_manager_session(
            &external_path,
            RuntimeIdentity {
                run_id: "run-external".into(),
                runtime_id: "rt-external".into(),
                boot_id: "boot-old".into(),
            },
            "external",
            true,
        );
        let app_path = tmp.path().join(app_ids.session_file);
        write_manager_session(
            &app_path,
            RuntimeIdentity {
                run_id: "run-app".into(),
                runtime_id: "rt-app".into(),
                boot_id: "boot-old".into(),
            },
            "tmux",
            false,
        );

        assert!(
            boot_reattach_candidate_from_scan(&boot_scan(&external_path), &external_path).is_none()
        );
        let app = boot_reattach_candidate_from_scan(&boot_scan(&app_path), &app_path)
            .expect("app manager remains a clean recovery candidate");
        assert_eq!(app.run_id, "run-app");
        assert_eq!(app.runtime_id, "rt-app");
        assert_eq!(app.task_id, "manager.launch:proj");
        assert_eq!(app.transport, "tmux");

        // Also repair residue written by the pre-fix layout: if both identities
        // already share one file, recovery selects the latest contiguous run
        // instead of pairing the external identity with the app's metadata.
        let legacy_collision_path = tmp.path().join("manager-proj-collided.jsonl");
        write_manager_session(
            &legacy_collision_path,
            RuntimeIdentity {
                run_id: "run-legacy-external".into(),
                runtime_id: "rt-legacy-external".into(),
                boot_id: "boot-old".into(),
            },
            "external",
            true,
        );
        write_manager_session(
            &legacy_collision_path,
            RuntimeIdentity {
                run_id: "run-legacy-app".into(),
                runtime_id: "rt-legacy-app".into(),
                boot_id: "boot-old".into(),
            },
            "tmux",
            false,
        );
        let recovered = boot_reattach_candidate_from_scan(
            &boot_scan(&legacy_collision_path),
            &legacy_collision_path,
        )
        .expect("legacy collision recovers the app segment");
        assert_eq!(recovered.run_id, "run-legacy-app");
        assert_eq!(recovered.runtime_id, "rt-legacy-app");
        assert_eq!(recovered.transport, "tmux");
    }

