    /// orgasmic:TASK-RB1ZN — the incident's first symptom, on the wire, at both
    /// release surfaces.
    ///
    /// A worker finalize is wedged in TASK-HAREX's bounded drain: the record is
    /// still in `runs`, so `GET /runs/live` reports the run and `orgasmic
    /// update` refuses on it. Everything an operator can reach for at that
    /// moment — `POST /runs/:id/release` and `run recover --action abandon` —
    /// used to answer 404 for a run both of them could see. That is the
    /// disagreement: a 404 says "over, nothing to do", which is the one thing
    /// that was not true.
    ///
    /// Post-split both surfaces answer 409 and name the bound. VSWZT reasoned
    /// its way to this branch on the abandon side but could not cheaply build
    /// the wedged state; this drives it, and adds the release route VSWZT did
    /// not touch. The last two assertions are the other half of the split: once
    /// the drain's budget expires and the record is gone, the same call goes
    /// back to 404 — the CLI's already-released rescue branch (TASK-DWJVH item
    /// B) keys on that and must keep working.
    #[tokio::test]
    async fn a_run_wedged_mid_release_is_a_conflict_at_both_release_surfaces() {
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("proj");
        seed_project(&home, &project_root, "proj");
        let state = direct_stage_test_state(home).await;
        // Wide enough to make assertions inside, small enough that the test
        // costs one wedge; the window itself is crossed in microseconds.
        let (run_id, session_path) = acquire_a_run_nothing_will_ever_end_with_budget(
            &state,
            &project_root,
            "TASK-RB1ZN-WIRE",
            Duration::from_millis(1_500),
        )
        .await;

        let wedged = tokio::spawn({
            let supervisor = state.supervisor.clone();
            let run_id = run_id.clone();
            async move {
                supervisor
                    .release_with_finalization(
                        &run_id,
                        "worker finalize for TASK-RB1ZN-WIRE",
                        ReleaseOutcome::Completed,
                        true,
                        None,
                    )
                    .await
            }
        });
        // The finalize-admission marker (TASK-QSSQH) is appended under the same
        // lock that sets the guard flag, so its arrival is proof the record is
        // present AND already being released — no sleep, and no second call
        // racing the first for admission.
        assert!(
            wait_session_reason(
                &session_path,
                crate::supervisor::WORKER_FINALIZE_ADMITTED_NOTE
            )
            .await,
            "the wedging release must reach finalize admission: {}",
            std::fs::read_to_string(&session_path).unwrap_or_default()
        );

        let release_error = post_run_release(
            State(state.clone()),
            Path(run_id.clone()),
            Json(RunReleaseRequest {
                reason: Some("manager cancel while the finalize is wedged".into()),
                request_id: None,
                finalized_by_worker: false,
                caller_identity: None,
                terminal_tx: None,
            }),
        )
        .await
        .expect_err("a second release cannot succeed while the first holds admission");
        assert_eq!(
            release_error.status,
            StatusCode::CONFLICT,
            "the release route answered {} for a run it can see is live: {}",
            release_error.status,
            release_error.message
        );

        let abandon_error = post_run_recover(
            State(state.clone()),
            Path(run_id.clone()),
            Json(RunRecoverRequest {
                action: Some(RECOVERY_ACTION_ABANDON.into()),
                project: Some("proj".into()),
                request_id: None,
                force_inert: None,
                mode: None,
                harness: None,
            }),
        )
        .await
        .expect_err("abandon has nothing to add to a release already running");
        assert_eq!(abandon_error.status, StatusCode::CONFLICT);

        // One renderer, so the two surfaces cannot disagree about the same
        // record, and the text names the bound rather than leaving the caller
        // to guess whether retrying is pointless.
        for error in [&release_error, &abandon_error] {
            let body = error.body.clone().expect("the conflict carries a body");
            assert_eq!(body["error"], "release already in progress");
            assert_eq!(body["run_id"], run_id);
            let detail = body["detail"].as_str().unwrap_or_default().to_string();
            assert!(
                detail.contains("is live and a release is already running")
                    && detail.contains(&format!(
                        "{}s",
                        RELEASE_FINALIZATION_DRAIN_TIMEOUT.as_secs()
                    )),
                "the conflict must name the HAREX drain budget: {detail}"
            );
        }

        assert!(
            live_run_ids(&state).await.contains(&run_id),
            "the two views must agree: both surfaces just called this run live, \
             so the snapshot the update fence reads must still report it"
        );

        wedged
            .await
            .expect("the wedged release task")
            .expect("the wedged release still completes within its drain budget");
        assert!(live_run_ids(&state).await.is_empty());

        // Genuinely gone now: 404 at both surfaces, with the answers that
        // distinguish "this run is over" from "never heard of it".
        let release_error = post_run_release(
            State(state.clone()),
            Path(run_id.clone()),
            Json(RunReleaseRequest {
                reason: Some("manager cancel after the wedge cleared".into()),
                request_id: None,
                finalized_by_worker: false,
                caller_identity: None,
                terminal_tx: None,
            }),
        )
        .await
        .expect_err("the record is gone");
        assert_eq!(release_error.status, StatusCode::NOT_FOUND);
        assert!(release_error.message.contains("active run"));

        let abandon_error = post_run_recover(
            State(state.clone()),
            Path(run_id.clone()),
            Json(RunRecoverRequest {
                action: Some(RECOVERY_ACTION_ABANDON.into()),
                project: Some("proj".into()),
                request_id: None,
                force_inert: None,
                mode: None,
                harness: None,
            }),
        )
        .await
        .expect_err("the record is gone");
        assert_eq!(abandon_error.status, StatusCode::NOT_FOUND);
        assert!(abandon_error.message.contains("is not live"));
    }
    /// TASK-KPMFK, production half: the stage identity boot recovery needs must
    /// actually be on disk after a REAL `POST /api/grill`. Without this, the
    /// recovery tests above would prove only that a hand-written session is
    /// recoverable. Reads the session as raw JSON — the assertion is about the
    /// durable on-disk contract, not about a Rust type.
    #[tokio::test]
    async fn a_launched_stage_persists_its_stage_identity_for_boot_recovery() {
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("proj");
        seed_project(&home, &project_root, "orgasmic");
        seed_minimal_graph(&project_root);

        let running = crate::Daemon::run(home.clone(), test_options())
            .await
            .expect("boot daemon");
        let token = read_token(&home);
        let client = reqwest::Client::new();

        let resp = client
            .post(format!("http://{}/api/grill", running.addr))
            .bearer_auth(&token)
            .json(&serde_json::json!({
                "project": "orgasmic",
                "task_id": "TASK-KPMFK-LAUNCH",
                // orgasmic:task_3NJ9K — this POST launches a real stage run
                // through the live daemon; `stdio`/`codex` made it exec
                // `codex app-server` on any host with codex on `$PATH`.
                "mode": crate::driver_resolution::STUB_MODE,
                "harness": crate::driver_resolution::STUB_HARNESS,
                "request_id": "kpmfk-stage-identity-test",
                "reason": "stage identity persistence"
            }))
            .send()
            .await
            .unwrap();
        let status = resp.status();
        let body: Value = resp.json().await.unwrap();
        assert!(status.is_success(), "grill stage: {status} {body}");

        let session_path = PathBuf::from(body["session_path"].as_str().expect("session_path"));
        let envelopes = read_session_file(&session_path).expect("read launched stage session");

        let run_meta = envelopes
            .iter()
            .find(|env| env.kind == SessionEventKind::Lifecycle && env.event["phase"] == "run_meta")
            .expect("a launched stage persists run_meta");
        assert!(
            run_meta.event.get("last_path").is_some(),
            "a stage run persists a last_path: {run_meta:?}"
        );
        assert!(
            run_meta.event.get("stdout_path").is_none(),
            "a stage run never has a stdout_path — this is exactly why the \
             dispatch-shaped respawn rule skipped it: {run_meta:?}"
        );

        let stage_meta = envelopes
            .iter()
            .find(|env| {
                env.kind == SessionEventKind::Lifecycle && env.event["phase"] == "stage_meta"
            })
            .unwrap_or_else(|| {
                panic!(
                    "a launched stage must persist its stage identity so boot \
                     recovery can respawn the completion watcher; session had: {:?}",
                    envelopes
                        .iter()
                        .map(|env| env.event["phase"].clone())
                        .collect::<Vec<_>>()
                )
            });
        assert_eq!(stage_meta.event["stage"], "grill");

        // The seam: what the launch wrote is what boot recovery reads. Without
        // this the restart tests would only prove that a hand-written session is
        // recoverable, and a launch that persisted the marker somewhere boot
        // recovery does not look would still pass everything.
        let candidate = boot_reattach_candidate_from_scan(&boot_scan(&session_path), &session_path)
            .expect("a live stage launch is a boot-reattach candidate");
        assert_eq!(
            candidate.stage.as_deref(),
            Some("grill"),
            "boot recovery must read back the stage identity the launch wrote"
        );

        let _ = running.shutdown.send(());
        let _ = running.join.await;
    }

    #[tokio::test]
    async fn external_manager_lease_is_free_after_restart_shaped_recovery() {
        // Daemon restart wipes the in-memory supervisor; an external
        // registration has no `attach()` support (unlike tmux managers),
        // so boot reattach must skip it rather than resurrect the lease —
        // re-registration is the only recovery path (dec_3Y2E1).
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("proj");
        std::fs::create_dir_all(project_sessions_dir(&project_root)).unwrap();

        let state = direct_stage_test_state(home.clone()).await;
        let ids = manager_launch_ids("proj", "external", Utc::now());
        let session_path = project_sessions_dir(&project_root).join(ids.session_file);
        let outcome = state
            .manager_registry
            .register(
                &state.supervisor,
                "proj",
                project_root.clone(),
                session_path.clone(),
                Some(std::process::id()),
                None,
            )
            .await
            .unwrap();
        assert!(matches!(
            outcome,
            crate::manager_registration::RegisterOutcome::Registered { .. }
        ));

        // A fresh Supervisor/ApiState never acquired this run — standing in
        // for the post-restart daemon boot.
        let post_restart_state = direct_stage_test_state(home).await;
        reattach_live_runs_on_boot(&post_restart_state, std::slice::from_ref(&project_root)).await;
        assert!(
            post_restart_state
                .supervisor
                .snapshot()
                .await
                .runs
                .iter()
                .all(|run| run.task_id != "manager.launch:proj"),
            "external manager run must not survive a restart-shaped recovery"
        );
        let external_envelopes = read_session_file(&session_path).unwrap();
        assert!(
            boot_reattach_candidate_from_scan(&boot_scan(&session_path), &session_path).is_none(),
            "external residue must not enter the no-driver reattach/log path"
        );
        let (recovered, _inventory) = classify_session_files(
            &post_restart_state.home,
            post_restart_state.trusted_claude_binary.as_ref(),
            &post_restart_state.boot.boot_id,
            &[],
            std::slice::from_ref(&project_root),
            &crate::run_catalog::RunCatalog::new(),
            None,
            TerminalWindow::unbounded(),
        )
        .await;
        let external = recovered
            .iter()
            .find(|run| run.run_id == external_envelopes[0].run_id)
            .expect("external residue is explicitly classified");
        assert_eq!(external.classification, "terminal_noop");
        assert!(external.reason.contains("daemon restart"));

        // Lease is free: a fresh register succeeds instead of colliding.
        let reregistered = post_restart_state
            .manager_registry
            .register(
                &post_restart_state.supervisor,
                "proj",
                project_root.clone(),
                project_sessions_dir(&project_root).join("manager-proj-after-restart.jsonl"),
                Some(std::process::id()),
                None,
            )
            .await
            .unwrap();
        assert!(matches!(
            reregistered,
            crate::manager_registration::RegisterOutcome::Registered { .. }
        ));
    }

