    // orgasmic:TASK-M47E5.1.1.1
    /// Exercise the real dispatch spawn edge so a change to its `last_path`
    /// derivation is visible in the config persisted for the driver.
    #[tokio::test]
    async fn dispatch_spawn_derives_the_authoritative_artifact_dir_from_last_path() {
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("project");
        seed_project(&home, &project_root, "project");
        let worktree = tmp.path().join("worktree");
        std::fs::create_dir_all(&worktree).unwrap();
        let state = direct_stage_test_state(home).await;

        let worker = StageWorker {
            id: "implementer-stub".to_string(),
            kind: WorkerKind::Implementer,
            driver: crate::driver_resolution::STUB_MODE.to_string(),
            harness: crate::driver_resolution::STUB_HARNESS.to_string(),
            linked_skills: Vec::new(),
            missing_skills: Vec::new(),
            max_iterations: None,
            context_budget_chars: None,
            applicable_states: Vec::new(),
            stall_timeout_secs: None,
            max_run_duration_secs: None,
            sandbox_permissions: None,
            harness_args: Vec::new(),
        };
        let expected_artifact_dir = project_root
            .join(".orgasmic")
            .join("tmp")
            .join("dispatch")
            .join("task-attempt-7");
        let last_path = expected_artifact_dir.join("task-attempt-7-last.txt");
        let spawn = spawn_worker_run(
            &state,
            SpawnWorkerRequest {
                project_id: "project",
                task_id: "TASK-M47E5-DERIVATION",
                worker,
                run_kind: RunKind::Worker,
                bundle: "last_path derivation regression",
                overrides: DriverOverrides::default(),
                project_root_path: &project_root,
                worktree_path: &worktree,
                last_path: Some(&last_path),
                stdout_path: None,
                dispatch_attempt_token: None,
                origin: "cli_dispatch",
                dispatch_kind: Some("implementer"),
                task_sandbox_permissions: None,
            },
        )
        .await
        .unwrap_or_else(|failure| panic!("stub dispatch spawn: {}", failure.error.message));

        let envelopes = read_session_file(&spawn.session_path).expect("read spawned session");
        let run_meta = envelopes
            .iter()
            .find(|env| env.kind == SessionEventKind::Lifecycle && env.event["phase"] == "run_meta")
            .expect("spawn persists run_meta");
        let actual_artifact_dir = run_meta.event["driver_config"]["dispatch_artifact_dir"].clone();

        let _ = state
            .supervisor
            .release(
                &spawn.acquire.run_id,
                "test cleanup",
                ReleaseOutcome::Completed,
            )
            .await;

        assert_eq!(
            actual_artifact_dir,
            json!(expected_artifact_dir),
            "spawn_worker_run must derive the driver artifact directory from last_path"
        );
    }

    /// The daemon half of the credential-mode escape hatch: a dispatch's
    /// override must land in the driver config the harness adapter reads, in
    /// the shape that adapter accepts (TASK-S0QRM).
    #[test]
    fn dispatch_driver_config_forwards_the_credential_mode_override() {
        let worker = StageWorker {
            id: "implementer-claude-stream-json".to_string(),
            kind: WorkerKind::Implementer,
            driver: "stdio".to_string(),
            harness: "claude".to_string(),
            linked_skills: Vec::new(),
            missing_skills: Vec::new(),
            max_iterations: None,
            context_budget_chars: None,
            applicable_states: Vec::new(),
            stall_timeout_secs: None,
            max_run_duration_secs: None,
            sandbox_permissions: None,
            harness_args: Vec::new(),
        };
        let config_for = |credential_mode: Option<&str>| {
            stage_driver_config_with_overrides(
                &worker,
                FsPath::new("/tmp/project"),
                FsPath::new("/tmp/worktree"),
                None,
                "brief",
                DriverOverrides {
                    provider: None,
                    model: None,
                    effort: None,
                    credential_mode: credential_mode.map(str::to_string),
                },
                None,
                &DriverDefaults::default(),
                None,
            )
        };

        let cfg = config_for(Some("native_login"));
        assert_eq!(cfg.0["credential_mode"], "native_login");
        // And the harness it is aimed at must accept that exact config, so the
        // override cannot be a key nothing reads.
        //
        // The question is the claude *adapter's* config contract, so ask the
        // adapter. `StdioDriver::validate` is `adapter.validate_config` and
        // nothing else, so this is the same check the dispatch would run —
        // without a test build ever holding a transport that could exec the
        // harness (TASK-3NJ9K).
        let harness = orgasmic_drivers::ClaudeAdapter::new();
        harness
            .validate_config(&cfg)
            .expect("claude must accept the override");

        // No override is a null field, not an invalid one.
        let cfg = config_for(None);
        assert!(cfg.0["credential_mode"].is_null());
        harness
            .validate_config(&cfg)
            .expect("absent override must validate");

        // A value the harness does not know is rejected before a dispatch
        // takes ownership of anything.
        let cfg = config_for(Some("bare-ish"));
        let err = harness
            .validate_config(&cfg)
            .expect_err("an unknown mode must not validate");
        assert!(format!("{err:?}").contains("bare-ish"), "{err:?}");
    }

