    // orgasmic:TASK-5HBST
    /// The one way this binary's tests may touch the process environment.
    ///
    /// `std::env::set_var` mutates state every concurrently running test in
    /// this binary shares: `PATH` decides what every subprocess spawn resolves,
    /// and `HOME` is read at daemon boot by [`pin_trusted_claude_binary`]. A
    /// test that repoints either one without excluding the others is writing
    /// into their runs, and they into its. `test_environment_lock` is the
    /// workspace-wide answer (TASK-R2HDN) and the daemon crate already uses it
    /// in `supervisor::tests`; this guard makes acquiring it and restoring the
    /// environment one indivisible step, so restoration also happens on the
    /// unwind path when an assertion between the two panics.
    ///
    /// Acquire once per test and route every key through the one guard: the
    /// lock is not reentrant, so a second guard in the same test deadlocks.
    /// Acquire it *after* `live_session_guard` where a test holds both — the
    /// lock order is flock-then-environment everywhere in this workspace.
    struct TestEnvGuard {
        _lock: tokio::sync::MutexGuard<'static, ()>,
        restore: Vec<(&'static str, Option<std::ffi::OsString>)>,
    }

    impl TestEnvGuard {
        async fn acquire() -> Self {
            Self::with_lock(test_environment_lock().lock().await)
        }

        /// For a `#[test]` body with no runtime to await on.
        fn acquire_blocking() -> Self {
            Self::with_lock(test_environment_lock().blocking_lock())
        }

        fn with_lock(lock: tokio::sync::MutexGuard<'static, ()>) -> Self {
            Self {
                _lock: lock,
                restore: Vec::new(),
            }
        }

        fn set(&mut self, key: &'static str, value: impl AsRef<std::ffi::OsStr>) -> &mut Self {
            self.restore.push((key, std::env::var_os(key)));
            std::env::set_var(key, value);
            self
        }

        #[cfg(unix)]
        fn prepend_path(&mut self, dir: &FsPath) -> &mut Self {
            let current = std::env::var("PATH").unwrap_or_default();
            self.set("PATH", format!("{}:{current}", dir.display()))
        }
    }

    impl Drop for TestEnvGuard {
        fn drop(&mut self) {
            for (key, previous) in self.restore.drain(..).rev() {
                match previous {
                    Some(value) => std::env::set_var(key, value),
                    None => std::env::remove_var(key),
                }
            }
        }
    }
    #[tokio::test]
    async fn resume_native_fork_recovery_starts_idle_without_auto_prompt_send() {
        // orgasmic:TASK-R28CP — native resume/fork must not auto-send the
        // recovery draft; ComposerSend must not land in the new session JSONL.
        let tmp = tempfile::tempdir().unwrap();
        let home = Home::at(tmp.path().join("home"));
        home.ensure().unwrap();
        let project_root = tmp.path().join("proj");
        seed_project(&home, &project_root, "orgasmic");
        write_failed_recoverable_session(
            &project_root,
            "run-native-resume-idle",
            "stall_timeout_exceeded",
            true,
        );

        let running = crate::Daemon::run(home.clone(), test_options())
            .await
            .expect("boot daemon");
        let token = read_token(&home);
        let client = reqwest::Client::new();
        let resp = client
            .post(format!(
                "http://{}/api/runs/run-native-resume-idle/recover",
                running.addr
            ))
            .bearer_auth(&token)
            .json(&json!({
                "action": "resume_native_fork",
                "project": "orgasmic",
                "force_inert": true,
                "request_id": "task-r28cp-native-idle",
            }))
            .send()
            .await
            .unwrap();
        assert!(
            resp.status().is_success(),
            "resume_native_fork recover: {}",
            resp.status()
        );
        let body: serde_json::Value = resp.json().await.unwrap();
        assert!(
            body["draft_prompt"]
                .as_str()
                .is_some_and(|draft| draft.contains("run-native-resume-idle")),
            "recovery draft is returned for manual send only: {body}"
        );
        let session_path = PathBuf::from(body["session_path"].as_str().unwrap());
        let session_raw = std::fs::read_to_string(&session_path).unwrap();
        assert!(
            !session_raw.contains("\"phase\":\"composer_send\"")
                && !session_raw.contains("\"phase\": \"composer_send\""),
            "native resume/fork must not auto-send ComposerSend: {session_raw}"
        );
        assert!(
            session_raw.contains("\"phase\":\"prompt_draft\"")
                || session_raw.contains("\"phase\": \"prompt_draft\""),
            "recovery draft must be staged unsent: {session_raw}"
        );
        assert!(
            !session_raw.contains("prompt_bundle_text"),
            "native resume/fork must not inject an initial prompt bundle"
        );

        let _ = running.shutdown.send(());
        let _ = running.join.await;
    }

    #[test]
    fn start_recovery_run_never_uses_placeholder_shell() {
        // Regression (dec_052): the old continuation path launched a placeholder
        // shell. That command, and the removed continue endpoint, must not
        // exist anywhere in the recovery surface. Needles are assembled from
        // fragments so this test does not match its own source.
        let source = include_str!("api.rs");
        let placeholder = ["echo orgasmic run", "continuation"].join(" ");
        assert!(
            !source.contains(&placeholder),
            "recovery must never launch the placeholder continuation shell"
        );
        let removed_route = ["/runs/:id/", "continue"].concat();
        assert!(
            !source.contains(&removed_route),
            "the old continue endpoint must be removed, not aliased"
        );
    }

